@pure_lazy
def _legal_bootstrap_out_ref(*parts: object) -> ServerPlanRefId:
    """Return a deterministic ServerPlan-compatible bootstrap output ref."""
    digest = hashlib.sha256("|".join(str(part) for part in parts).encode()).hexdigest()
    return ServerPlanRefId(f"out_{int(digest[:15], 16)}")


@pure_lazy
def _ordinary_required_column_facts(
    physical_contract: BootstrapPhysicalSchemaContract,
) -> frozenset[tuple[SqlTableName, SqlColumnName]]:
    """Return columns that use ordinary column-presence proof.

    Generated columns use the stronger named-artifact proof. See "Physical proof
    categories" in ``docs/design/LAZY_BOOTSTRAP_ENGINE_ARCHITECTURE.md``.
    """
    generated_columns = {
        (SqlTableName(table_name), SqlColumnName(column_name))
        for table_name, column_names in physical_contract.required_generated_columns_by_table.items()
        for column_name in column_names
    }
    required_columns = {
        (SqlTableName(table_name), SqlColumnName(column_name))
        for table_name, column_names in physical_contract.required_columns_by_table.items()
        for column_name in column_names
    }
    return frozenset(required_columns - generated_columns)


@pure_lazy
def _bootstrap_model_cache_key(
    model_classes: tuple[type[Any], ...],
) -> tuple[type[Any], ...]:
    return model_classes


@pure_lazy
def _bootstrap_contributor_cache_key(
    contributors: tuple[object, ...],
) -> tuple[tuple[str, str, str, str], ...]:
    cache_parts: list[tuple[str, str, str, str]] = []
    for contributor in contributors:
        contributor_type = type(contributor)
        type_key = f"{contributor_type.__module__}.{contributor_type.__qualname__}"
        key = getattr(contributor, "key", None)
        version = getattr(contributor, "version", None)
        fingerprint = getattr(contributor, "contract_fingerprint", None)
        if not all(isinstance(value, str) and value for value in (key, version, fingerprint)):
            raise TypeError(
                f"Bootstrap contributor {type_key} requires nonempty key, version, and contract_fingerprint strings",
            )
        assert isinstance(key, str)
        assert isinstance(version, str)
        assert isinstance(fingerprint, str)
        cache_parts.append((type_key, key, version, fingerprint))
    return tuple(sorted(cache_parts))


@pure_lazy
def _versioning_mutation_schema_dependency_refs(
    payload: BootstrapVersioningDomainPrimitivePayload | BootstrapVersionedRowsPrimitivePayload,
    *,
    domain_schema_refs: Mapping[type[VersioningDomain], ServerPlanRefId],
    versioned_family_refs: Mapping[type[VersionedObjectRow[SysId]], ServerPlanRefId],
    fts_index_refs: Mapping[type[DatabaseObjectRow[SysId]], ServerPlanRefId],
) -> tuple[ServerPlanRefId, ...]:
    """Return schema refs that must materialize before versioning bootstrap data."""
    from l3200_metadata.bootstrap_data_plan import (
        BootstrapVersionedRowsPrimitivePayload,
        BootstrapVersioningDomainPrimitivePayload,
    )

    refs: list[ServerPlanRefId] = []
    if type(payload) is BootstrapVersioningDomainPrimitivePayload:
        domain_schema_ref = domain_schema_refs.get(payload.domain_contract.domain)
        if domain_schema_ref is not None:
            refs.append(domain_schema_ref)
    elif type(payload) is BootstrapVersionedRowsPrimitivePayload:
        domain = payload.domain
        domain_schema_ref = domain_schema_refs.get(domain)
        if domain_schema_ref is not None:
            refs.append(domain_schema_ref)
        family_ref = versioned_family_refs.get(payload.model_cls)
        if family_ref is not None:
            refs.append(family_ref)
        fts_index_ref = fts_index_refs.get(payload.model_cls)
        if fts_index_ref is not None:
            refs.append(fts_index_ref)
    return tuple(dict.fromkeys(refs))


@pure_lazy
def _versioning_mutation_revision_model(
    payload: BootstrapVersioningDomainPrimitivePayload | BootstrapVersionedRowsPrimitivePayload,
) -> type[BaseRevision]:
    """Return the revision model from one closed versioning payload."""
    from l3200_metadata.bootstrap_data_plan import (
        BootstrapVersionedRowsPrimitivePayload,
        BootstrapVersioningDomainPrimitivePayload,
    )

    if type(payload) is BootstrapVersioningDomainPrimitivePayload:
        return payload.domain_contract.revision_model
    versioned_rows_payload = cast("BootstrapVersionedRowsPrimitivePayload", payload)
    domain = versioned_rows_payload.domain
    return domain.revision_model


@pure_lazy
def _shared_bootstrap_revision_id(
    group_key: tuple[object, object, object, object],
) -> RevisionId:
    """Return the stable seed revision for one domain branch."""
    from l1200_versioned_ids import RevisionId

    domain, branch_id, branch_name, workspace_id = group_key
    domain_type = cast("type[VersioningDomain]", domain)
    domain_identity = (
        domain_type.__module__,
        domain_type.__qualname__,
        domain_type.name,
    )
    revision_seed_payload = (
        "bootstrap_versioned_seed_revision",
        domain_identity,
        str(branch_id),
        str(branch_name),
        str(workspace_id),
    )
    revision_seed = hashlib.sha256(
        json.dumps(revision_seed_payload, separators=(",", ":")).encode(),
    ).hexdigest()
    from l2000_connection.schema_transaction import BootstrapRevisionSeed, deterministic_bootstrap_revision_uuid

    return RevisionId(
        deterministic_bootstrap_revision_uuid(BootstrapRevisionSeed(revision_seed)),
    )


@pure_lazy
def _bootstrap_observation_columns_by_table(
    plan: "BootstrapEnginePlan",
) -> dict[str, tuple[str, ...]]:
    """Return extra schema columns to observe without making them proof requirements."""
    from l1000_schema.large_column import large_column_pointer_name
    from l1000_schema.reflection_cache import cached_model_fields
    from l1000_schema.table_registry import has_table_config
    from l1000_schema.table_utils import get_table_name

    columns_by_table: dict[str, list[str]] = {}
    for model_cls in plan.model_classes:
        if not has_table_config(model_cls):
            continue
        table_name = get_table_name(model_cls)
        columns = columns_by_table.setdefault(table_name, [])
        for field_name in cached_model_fields(model_cls):
            columns.append(str(large_column_pointer_name(ContentColumnName(str(field_name)))))
    return {table_name: tuple(dict.fromkeys(columns)) for table_name, columns in columns_by_table.items() if columns}


@pure_lazy
