@pure_lazy
def _bootstrap_terminal_inventory_details_enabled() -> bool:
    """Return whether detailed terminal inventory counters should be emitted."""

    if os.environ.get("NERA_BOOTSTRAP_TERMINAL_INVENTORY_DETAILS", "").strip().lower() in {"1", "true", "yes"}:
        return True
    profile_module = sys.modules.get("conform.bootstrap_profile")
    if profile_module is None:
        return False
    enabled = getattr(profile_module, "bootstrap_terminal_inventory_details_enabled", None)
    return bool(enabled()) if callable(enabled) else False


@pure_lazy
def _bootstrap_profile_span(
    phase: str,
    *,
    physical_route_count: int = 1,
    owns_round_trip_budget: bool = False,
) -> AbstractContextManager[None]:
    """Return the active bootstrap profile span when test probes are installed."""

    profile_module = sys.modules.get("conform.bootstrap_profile")
    if profile_module is None:
        return nullcontext()
    span = getattr(profile_module, "bootstrap_profile_span", None)
    if not callable(span):
        return nullcontext()
    return cast(
        "AbstractContextManager[None]",
        span(
            phase,
            suite_name="bootstrap_coordinator.py",
            test="schema_bootstrap",
            physical_route_count=physical_route_count,
            owns_round_trip_budget=owns_round_trip_budget,
        ),
    )


@pure_lazy
def _bootstrap_physical_route_count(conn: object) -> int:
    """Return the number of independently budgeted physical bootstrap routes."""
    cache = getattr(conn, "_cache", None)
    upstream = getattr(conn, "_upstream", None)
    return 2 if cache is not None and upstream is not None and cache is not upstream else 1


@pure_lazy
@contextmanager
def _bootstrap_coordinator_observation(
    conn: object,
    *,
    asynchronous: bool = False,
) -> Generator[None]:
    """Own observation and transport state around a coordinator execution."""
    with (
        bootstrap_program_transport(
            enabled=getattr(conn, "backend_type", None) is BackendType.POSTGRES,
        ),
        bootstrap_driver_observation(connection=conn),
        _bootstrap_profile_span(
            "schema_bootstrap.coordinator_run_async" if asynchronous else "schema_bootstrap.coordinator_run",
            physical_route_count=_bootstrap_physical_route_count(conn),
            owns_round_trip_budget=True,
        ),
    ):
        yield


@pure_lazy
def _bootstrap_coordinator_run_budget_lazy[**P, T](fn: Callable[P, T]) -> Callable[P, T]:
    """Apply one hard bootstrap budget scope to a sync coordinator run."""

    @wraps(fn)
    def _wrapped(*args: P.args, **kwargs: P.kwargs) -> T:
        conn = args[1] if len(args) > 1 else kwargs.get("conn")
        with _bootstrap_coordinator_observation(conn):
            return fn(*args, **kwargs)

    return _wrapped


@pure_lazy
def _bootstrap_coordinator_run_awaitable_budget_lazy[**P, T](
    fn: Callable[P, Awaitable[T]],
) -> Callable[P, Awaitable[T]]:
    """Apply one hard bootstrap budget scope to an async coordinator run."""

    @wraps(fn)
    async def _wrapped(*args: P.args, **kwargs: P.kwargs) -> T:
        conn = args[1] if len(args) > 1 else kwargs.get("conn")
        with _bootstrap_coordinator_observation(conn, asynchronous=True):
            return await fn(*args, **kwargs)

    return _wrapped


@pure_lazy
def _manifest_required_indexes_by_table(
    payload_json: str,
) -> dict[SqlTableName, frozenset[SqlIndexName]]:
    """Decode the prior model-owned index surface from a manifest payload."""
    try:
        payload = json.loads(payload_json)
    except json.JSONDecodeError:
        return {}
    if not isinstance(payload, dict):
        return {}
    raw_tables = payload.get("tables")
    if not isinstance(raw_tables, list):
        return {}
    result: dict[SqlTableName, frozenset[SqlIndexName]] = {}
    for raw_table in raw_tables:
        if not isinstance(raw_table, dict):
            continue
        table_name = raw_table.get("table_name")
        raw_indexes = raw_table.get("required_indexes")
        if not isinstance(table_name, str) or not isinstance(raw_indexes, list):
            continue
        if not all(isinstance(index_name, str) for index_name in raw_indexes):
            continue
        result[SqlTableName(table_name)] = frozenset(SqlIndexName(index_name) for index_name in raw_indexes)
    return result


@pure_lazy
def _manifest_index_contracts_by_table(
    payload_json: str,
) -> dict[SqlTableName, dict[SqlIndexName, tuple[tuple[SqlColumnName, ...], bool, str | None]]]:
    """Decode hash-dense model index contracts from a manifest payload."""
    try:
        payload = json.loads(payload_json)
    except json.JSONDecodeError:
        return {}
    if not isinstance(payload, dict) or not isinstance(payload.get("tables"), list):
        return {}
    result: dict[SqlTableName, dict[SqlIndexName, tuple[tuple[SqlColumnName, ...], bool, str | None]]] = {}
    for raw_table in payload["tables"]:
        if not isinstance(raw_table, dict) or not isinstance(raw_table.get("table_name"), str):
            continue
        raw_contracts = raw_table.get("required_index_contracts")
        if not isinstance(raw_contracts, list):
            continue
        table_contracts: dict[SqlIndexName, tuple[tuple[SqlColumnName, ...], bool, str | None]] = {}
        for raw_contract in raw_contracts:
            if not isinstance(raw_contract, dict):
                continue
            name = raw_contract.get("name")
            columns = raw_contract.get("columns")
            unique = raw_contract.get("unique")
            where_sql = raw_contract.get("where_sql")
            if (
                not isinstance(name, str)
                or not isinstance(columns, list)
                or not all(isinstance(column, str) for column in columns)
                or not isinstance(unique, bool)
                or (where_sql is not None and not isinstance(where_sql, str))
            ):
                continue
            table_contracts[SqlIndexName(name)] = (
                tuple(SqlColumnName(column) for column in columns),
                unique,
                where_sql,
            )
        result[SqlTableName(raw_table["table_name"])] = table_contracts
    return result


@pure_lazy
def _stale_manifest_indexes(
    previous_payload_json: str,
    current_payload_json: str,
) -> tuple[tuple[SqlTableName, SqlIndexName], ...]:
    """Return model-owned indexes removed from the current contract."""
    previous = _manifest_required_indexes_by_table(previous_payload_json)
    current = _manifest_required_indexes_by_table(current_payload_json)
    previous_contracts = _manifest_index_contracts_by_table(previous_payload_json)
    current_contracts = _manifest_index_contracts_by_table(current_payload_json)
    table_names = set(previous) | set(previous_contracts)
    return tuple(
        (table_name, index_name)
        for table_name in sorted(table_names)
        for index_name in sorted(
            set(previous.get(table_name, frozenset())) | set(previous_contracts.get(table_name, {})),
        )
        if index_name not in current.get(table_name, frozenset()) and index_name not in current_contracts.get(table_name, {})
    )


@pure_lazy
def _complete_index_observation_requests(
    physical_contract: BootstrapPhysicalSchemaContract,
) -> tuple[tuple[SqlTableName, tuple[SqlIndexName, ...]], ...]:
    """Request every physical index once so reconciliation can prove ownership."""
    return tuple((SqlTableName(table_name), (SqlIndexName("*"),)) for table_name in physical_contract.table_names)


@pure_lazy
def _transition_artifact_covers_contract(
    artifact: BootstrapTransitionArtifactFact,
    physical_contract: BootstrapPhysicalSchemaContract,
) -> bool:
    created_tables = {str(table_name) for table_name in artifact.created_tables}
    required_tables = {str(table_name) for table_name in physical_contract.table_names}
    if not required_tables.issubset(created_tables):
        return False
    created_indexes = {str(index_name) for index_name in artifact.created_indexes}
    ddl_text = "\n".join(effect.sql for effect in artifact.ddl_effects)
    required_indexes = {
        str(index_name) for index_names in physical_contract.required_indexes_by_table.values() for index_name in index_names
    }
    return all(index_name in created_indexes or index_name in ddl_text for index_name in required_indexes)


@dataclass(slots=True)
class _SchemaPlanFetchScope:
    """Adapter that lets schema plans reuse plan-scope fetch templating."""

    schema_txn: LazySchemaTransaction
    concrete_results: dict[str, object]

    def owned_step_ref_ids(self: _SchemaPlanFetchScope) -> frozenset[ServerPlanRefId]:
        """Return step identities owned by the adapted schema plan."""
        return self.schema_txn.plan_scope_plan().owned_step_ref_ids()

    def return_result(self: _SchemaPlanFetchScope, name: str, value: object) -> None:
        from l2055_lazy_result.lazy_result import LazyResult
        from l2070_batching.server_ref import ServerRef, ServerRefs, inspect_server_value_shape_for_planning

        if isinstance(value, ServerRef):
            self.schema_txn.plan_scope_plan().return_result(name, value)
            return
        if isinstance(value, LazyResult):
            shape = inspect_server_value_shape_for_planning(
                value,
                site=f"schema plan fetch value {name!r}",
            )
            if shape.symbolic_ref_id is not None:
                self.schema_txn.plan_scope_plan().return_result(
                    name,
                    ServerRefs.from_ref_id(shape.symbolic_ref_id, variant="scalar"),
                )
                return
            if shape.has_literal_value:
                self.concrete_results[name] = shape.literal_value
                return
            msg = f"Schema plan fetch value {name!r} is neither literal nor plan-owned"
            raise TypeError(msg)
        self.concrete_results[name] = value


@dataclass(frozen=True, slots=True)
class _SchemaPlanFetchWork[T]:
    """Pure plan-scope template awaiting one terminal result map."""

    scope: _SchemaPlanFetchScope
    template: object
    plan: Any

    def materialize(self: _SchemaPlanFetchWork[T], raw_results: object | None) -> T:
        from l2000_connection.connection_plan_fetch_templates import (
            PlanScopeFetchResults,
            _resolve_plan_scope_fetch_template,
        )
        from l2000_connection.connection_lazy_return_registry import PlanScopeReturnName

        raw_mapping = getattr(raw_results, "_results", None)
        results = PlanScopeFetchResults()
        if isinstance(raw_mapping, Mapping):
            results.update((PlanScopeReturnName(str(name)), value) for name, value in raw_mapping.items())
        results.update((PlanScopeReturnName(str(name)), value) for name, value in self.scope.concrete_results.items())
        if self.scope.schema_txn._bootstrap_generation_receipt_ref is not None:
            generations = results[PlanScopeReturnName("bootstrap_generation_receipt")]
            if not isinstance(generations, Mapping):
                raise RuntimeError("Bootstrap generation receipt is not a generation map")
            from l1000_cache.schema_generation import SchemaGenerationTag
            from l2000_connection.connection_contracts import SchemaGenerationRows

            entries: list[tuple[SchemaGenerationTag, int]] = []
            for tag, generation in generations.items():
                if not isinstance(tag, str) or not isinstance(generation, int) or isinstance(generation, bool):
                    raise RuntimeError("Bootstrap generation receipt contains invalid values")
                entries.append((SchemaGenerationTag(tag), generation))
            self.scope.schema_txn.record_bootstrap_generation_receipt(SchemaGenerationRows(tuple(entries)))
        return cast("T", _resolve_plan_scope_fetch_template(self.template, results))


@pure_lazy
def _enqueue_owned_schema_generation_bumps(txn: LazySchemaTransaction) -> None:
    """Put schema-generation publication inside the application request."""
    if not txn._schema_changed or not txn._cache_generations_table_exists():
        return
    from datetime import UTC, datetime
    from impl.common.l2070_server_plan.steps.cache_steps import BootstrapSchemaGenerationBumpStep

    plan = txn.plan()
    dependencies = tuple(ServerPlanRefId(step.ref_id) for step in plan._steps)
    ref_id = ServerPlanRefId(plan._next_ref())
    txn._bootstrap_generation_receipt_ref = ref_id
    txn._bootstrap_generation_receipt_tags = txn._schema_generation_tags()
    plan.add_step(
        BootstrapSchemaGenerationBumpStep(
            ref_id,
            tags=tuple(str(tag) for tag in txn._bootstrap_generation_receipt_tags),
            timestamp=datetime.now(UTC),
            dependency_refs=dependencies,
        ),
    )


@pure_lazy
def _bootstrap_application_uses_native_commit(txn: LazySchemaTransaction) -> bool:
    """Return whether one native terminal can safely own transaction completion."""
    from l2070_batching.backend_profile import BootstrapTerminalTransport

    return txn.backend_profile.traits.bootstrap_terminal_transport is BootstrapTerminalTransport.DATA_MODIFYING_CTE


@pure_lazy
def _enqueue_owned_schema_commit(txn: LazySchemaTransaction, *, include_static_dependencies: bool = True) -> None:
    """Complete the coordinator-owned transaction in its final native request."""
    from impl.common.l2070_server_plan.steps.transaction_lifecycle_steps import DatabaseCommitAfterDepsStep

    dialect = txn.backend_profile.dialect
    if dialect is None or not dialect.bootstrap_requires_native_commit:
        return
    plan = txn.plan()
    dependencies = [
        ServerPlanRefId(step.ref_id) for step in plan._steps if include_static_dependencies or not step.is_bootstrap_static_publication()
    ]
    plan.add_step(
        DatabaseCommitAfterDepsStep(ServerPlanRefId(plan._next_ref()), source_refs=dependencies),
    )


@pure_lazy
def _schema_plan_fetch_identity(value: object) -> str:
    """Return stable ownership identity for one plan-scope fetch."""
    from l2055_lazy_result.lazy_result import LazyResult
    from l2055_lazy_result.lazy_seq import LazySeq
    from l2070_batching.server_ref import ServerRef

    if isinstance(value, ServerRef):
        return str(value.ref_id)
    if isinstance(value, LazyResult | LazySeq):
        ref_id = object.__getattribute__(value, "_step_ref_id")
        if ref_id is not None:
            return str(ref_id)
        planning_ref_id = getattr(value, "_planning_ref_id", None)
        if planning_ref_id is not None:
            return str(planning_ref_id)
    if isinstance(value, dict):
        return "map:" + "|".join(f"{key!r}={_schema_plan_fetch_identity(item)}" for key, item in value.items())
    if isinstance(value, tuple):
        return "tuple:" + "|".join(_schema_plan_fetch_identity(item) for item in value)
    if isinstance(value, list):
        return "list:" + "|".join(_schema_plan_fetch_identity(item) for item in value)
    return f"literal:{type(value).__module__}.{type(value).__qualname__}"


@external_io_boundary
def _schema_plan_fetch_work[T](
    schema_txn: LazySchemaTransaction,
    value: T,
) -> _SchemaPlanFetchWork[T]:
    """Build plan fetch templating without executing the schema plan."""
    from l2000_connection.connection_plan_fetch_templates import (
        PlanScopeFetchPathComponent,
        _plan_scope_fetch_template,
    )

    scope = _SchemaPlanFetchScope(schema_txn=schema_txn, concrete_results={})
    plan = schema_txn.plan_scope_plan()
    generation_ref = schema_txn._bootstrap_generation_receipt_ref
    if generation_ref is not None:
        from l2070_batching.server_ref import ServerRefs

        scope.return_result(
            "bootstrap_generation_receipt",
            ServerRefs.from_step(plan, generation_ref, variant="scalar"),
        )
    initial_steps = tuple(plan._steps)
    fetch_identity = _schema_plan_fetch_identity(value)
    template = _plan_scope_fetch_template(
        cast("BaseServerPlan", scope),
        value,
        (PlanScopeFetchPathComponent(f"root:{fetch_identity}"),),
    )
    if tuple(plan._steps) != initial_steps:
        added_steps = tuple((type(step).__name__, str(step.ref_id)) for step in plan._steps[len(initial_steps) :])
        msg = f"bootstrap terminal fetch mutated its closed application plan: {added_steps!r}"
        raise RuntimeError(msg)
    return _SchemaPlanFetchWork(scope=scope, template=template, plan=plan)


@pure_lazy
def _bootstrap_out_ref(*parts: object) -> ServerPlanRefId:
    digest = hashlib.sha256("|".join(str(part) for part in parts).encode()).hexdigest()[:15]
    return ServerPlanRefId(f"out_{int(digest, 16)}")


@pure_lazy
def _bootstrap_dialect_cache_key(dialect: object | None) -> str:
    if dialect is None:
        return "dialect:none"
    backend_type = getattr(dialect, "backend_type", None)
    backend_value = getattr(backend_type, "value", None) or str(backend_type)
    return f"{type(dialect).__module__}.{type(dialect).__qualname__}:{backend_value}"


def _restored_proof_source_ref(restored_proof: RestoredBootstrapProof, suffix: str) -> ServerPlanRefId:
    return _bootstrap_out_ref("restored_bootstrap_proof", restored_proof.manifest_key, restored_proof.plan_hash, suffix)


@pure_lazy
def _scope_lifecycle_metadata_for_plan(
    plan: BootstrapEnginePlan,
) -> tuple[dict[str, tuple[SqlTableName, ...]], dict[str, str]]:
    from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
    from l3200_metadata.bootstrap_manifest_builders import bootstrap_scope_facts_for_engine_plan

    scope_facts = bootstrap_scope_facts_for_engine_plan(plan)
    scope_tables_by_key: dict[str, tuple[SqlTableName, ...]] = {}
    for scope_key, fact in scope_facts.items():
        required_tables = fact.get("required_tables", ())
        if not isinstance(required_tables, list | tuple):
            raise TypeError("Bootstrap scope required_tables must be a sequence")
        scope_tables_by_key[scope_key] = tuple(SqlTableName(str(table_name)) for table_name in required_tables)
    scope_facts_by_key = {
        scope_key: str(fact["facts_hash"]) for scope_key, fact in scope_facts.items() if isinstance(fact.get("facts_hash"), str)
    }
    return scope_tables_by_key, scope_facts_by_key


@pure_lazy
def _observed_scope_lifecycle_metadata(
    observation: BootstrapObservation,
    plan: BootstrapEnginePlan,
) -> tuple[dict[str, tuple[SqlTableName, ...]], dict[str, str]]:
    expected_tables, expected_hashes = _scope_lifecycle_metadata_for_plan(plan)
    scope_tables_by_key: dict[str, tuple[SqlTableName, ...]] = {}
    scope_facts_by_key: dict[str, str] = {}
    for proof_fact in observation.proof_facts:
        scope_key = proof_fact.scope_key
        if (
            scope_key is None
            or scope_key not in expected_tables
            or proof_fact.required_tables != expected_tables[scope_key]
            or str(proof_fact.proof_hash) != expected_hashes.get(scope_key)
        ):
            continue
        scope_tables_by_key[scope_key] = proof_fact.required_tables
        scope_facts_by_key[scope_key] = str(proof_fact.proof_hash)
    return scope_tables_by_key, scope_facts_by_key


def _restored_proof_execution_facts(restored_proof: RestoredBootstrapProof) -> BootstrapExecutionFacts:
    source_ref = _restored_proof_source_ref(restored_proof, "proof")
    metadata_source_ref = _restored_proof_source_ref(restored_proof, "metadata")
    ddl_source_ref = _restored_proof_source_ref(restored_proof, "ddl_lockdown")
    return BootstrapExecutionFacts(
        status=BootstrapApplicationStatus.SKIPPED_MANIFEST_FAST_PATH,
        mutation_counts=BootstrapMutationCounts(
            schema_mutations=0,
            metadata_mutations=0,
            seed_mutations=0,
            versioning_mutations=0,
        ),
        proof_facts=tuple(
            BootstrapProofExecutionFact(
                proof_hash=BootstrapFactsHash(proof_hash),
                source_ref=source_ref,
            )
            for proof_hash in restored_proof.metadata.proof_hashes
        ),
        seed_hashes=tuple(BootstrapFactsHash(seed_hash) for seed_hash in restored_proof.metadata.seed_hashes),
        source_refs=(source_ref, metadata_source_ref, ddl_source_ref),
    )


def _restored_proof_lifecycle_effects(restored_proof: RestoredBootstrapProof) -> tuple[BootstrapLifecycleEffect, ...]:
    from impl.common.l2050_sql_types.sql_branded_types import SqlTableName

    source_ref = _restored_proof_source_ref(restored_proof, "proof")
    metadata_source_ref = _restored_proof_source_ref(restored_proof, "metadata")
    ddl_source_ref = _restored_proof_source_ref(restored_proof, "ddl_lockdown")
    table_names = tuple(SqlTableName(table.table_name) for table in restored_proof.table_contracts)
    proof_hashes = tuple(BootstrapFactsHash(proof_hash) for proof_hash in restored_proof.metadata.proof_hashes)
    seed_hashes = tuple(BootstrapFactsHash(seed_hash) for seed_hash in restored_proof.metadata.seed_hashes)
    seed_fact_hashes = {str(index): str(seed_hash) for index, seed_hash in enumerate(seed_hashes)}
    scope_tables_by_key = {
        scope_key: tuple(SqlTableName(table_name) for table_name in table_names)
        for scope_key, table_names in restored_proof.metadata.proof_scopes.items()
    }
    scope_facts_by_key = dict(restored_proof.metadata.scope_facts_by_key)
    return (
        BootstrapLifecycleEffect(
            kind=BootstrapLifecycleEffectKind.SEED_CONNECTION_PROOF,
            requirement=BootstrapLifecycleRequirement.REQUIRED,
            payload=SeedConnectionProofEffect(
                proof_hash=proof_hashes[0],
                source_ref=source_ref,
                scope_tables_by_key=scope_tables_by_key,
                existing_tables=table_names,
                seed_fact_hashes=seed_fact_hashes,
                scope_facts_by_key=scope_facts_by_key,
                bootstrap_system_session_verified=True,
            ),
        ),
        BootstrapLifecycleEffect(
            kind=BootstrapLifecycleEffectKind.MARK_SCHEMA_PROOF_SCOPES_VERIFIED,
            requirement=BootstrapLifecycleRequirement.REQUIRED,
            payload=MarkSchemaProofScopesVerifiedEffect(
                proof_hashes=proof_hashes,
                source_ref=source_ref,
                scope_tables_by_key=scope_tables_by_key,
                scope_facts_by_key=scope_facts_by_key,
            ),
        ),
        BootstrapLifecycleEffect(
            kind=BootstrapLifecycleEffectKind.MARK_SEED_FACTS_VERIFIED,
            requirement=BootstrapLifecycleRequirement.REQUIRED,
            payload=MarkSeedFactsVerifiedEffect(
                seed_hashes=seed_hashes,
                source_ref=source_ref,
                seed_fact_hashes=seed_fact_hashes,
            ),
        ),
        BootstrapLifecycleEffect(
            kind=BootstrapLifecycleEffectKind.INVALIDATE_TABLE_EXISTS_CACHE,
            requirement=BootstrapLifecycleRequirement.REQUIRED,
            payload=InvalidateTableExistsCacheEffect(
                table_names=table_names,
                source_ref=source_ref,
            ),
        ),
        BootstrapLifecycleEffect(
            kind=BootstrapLifecycleEffectKind.UPDATE_LOCAL_METADATA_CACHES,
            requirement=BootstrapLifecycleRequirement.REQUIRED,
            payload=UpdateLocalMetadataCachesEffect(
                cache_hash=BootstrapFactsHash(restored_proof.contract_fingerprint),
                source_ref=metadata_source_ref,
            ),
        ),
        BootstrapLifecycleEffect(
            kind=BootstrapLifecycleEffectKind.APPLY_DDL_LOCKDOWN,
            requirement=BootstrapLifecycleRequirement.REQUIRED,
            payload=ApplyDdlLockdownEffect(
                policy=BootstrapDdlLockdownPolicy(mode=BootstrapDdlLockdownMode.ENFORCE),
                source_ref=ddl_source_ref,
            ),
        ),
    )


@dataclass(frozen=True, slots=True)
class _BootstrapSchemaStateLazyContext:
    """Resolve the single interrogation plan into a BootstrapSchemaState."""

    schema_txn: LazySchemaTransaction
    step_ref: ServerPlanRefId
    lazy_observation: LazyResult[BootstrapObservation]
    interrogation_step: object
    engine_plan: BootstrapEnginePlan
    model_classes: tuple[type[DatabaseObjectRow[SysId]], ...]
    execute_data_primitives: bool
    require_manifest_fast_path: bool
    fuse_physical_preparation: bool

    def queue_single[T](
        self: _BootstrapSchemaStateLazyContext,
        operation: LazyOperation[T],
        pre_populated: T | None = None,
    ) -> LazyResult[T]:
        return LazyResult(operation, self, pre_populated)

    def queue_sequence[T](self: _BootstrapSchemaStateLazyContext, operation: LazyOperation[list[T]]) -> Any:
        del operation
        msg = "Bootstrap schema state interrogation does not support sequence results"
        raise NotImplementedError(msg)

    def _materialize_state(self: _BootstrapSchemaStateLazyContext, raw_result: object) -> BootstrapSchemaState:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlIndexName, SqlTableName
        from impl.common.l2070_server_plan.steps.bootstrap_interrogation import BootstrapInterrogationStep
        from l2070_batching.transition_plan_cache import transition_artifact_content_hash
        from l3200_metadata.bootstrap_observation import BootstrapFactPresence, BootstrapTransitionArtifactFact

        step = self.interrogation_step
        if not isinstance(step, BootstrapInterrogationStep):
            msg = f"Bootstrap interrogation step {self.step_ref!s} was not found in the schema plan"
            raise RuntimeError(msg)
        if isinstance(raw_result, BootstrapObservation):
            observation = raw_result
        else:
            observation = step.materialize(cast("Any", {str(self.step_ref): raw_result}))
        transition_artifact = self.schema_txn.materialized_bootstrap_transition_artifact(
            BootstrapPlanHash(self.engine_plan.plan_hash),
            observed_fingerprint=SchemaFingerprintHash(self.engine_plan.physical_contract.facts_hash()),
            desired_fingerprint=SchemaFingerprintHash(self.engine_plan.contract_fingerprint),
        )
        if not isinstance(transition_artifact, NoBootstrapTransitionArtifact):
            fact_refs = observation.interrogation_plan.fact_refs
            transition_source_ref = fact_refs.transition_ref if fact_refs is not None else self.step_ref
            observation = replace(
                observation,
                transition_artifact_facts=(
                    BootstrapTransitionArtifactFact(
                        presence=BootstrapFactPresence.PRESENT,
                        observed_hash=SchemaFingerprintHash(transition_artifact.observed_fingerprint),
                        desired_hash=SchemaFingerprintHash(transition_artifact.desired_fingerprint),
                        artifact_hash=BootstrapFactsHash(transition_artifact_content_hash(transition_artifact)),
                        backend_fingerprint=SchemaFingerprintHash(transition_artifact.backend_fingerprint),
                        source_ref=transition_source_ref,
                        ddl_effects=transition_artifact.ddl_effects,
                        created_tables=transition_artifact.created_tables,
                        created_indexes=transition_artifact.created_indexes,
                    ),
                ),
            )
        return BootstrapSchemaState(
            engine_plan=self.engine_plan,
            observation=observation,
            model_classes=self.model_classes,
            execute_data_primitives=self.execute_data_primitives,
            require_manifest_fast_path=self.require_manifest_fast_path,
        )

    def _fuse_physical_interrogation(self: _BootstrapSchemaStateLazyContext) -> None:
        if not self.fuse_physical_preparation:
            return
        LazyBootstrapCoordinator()._fuse_bootstrap_application_steps(
            self.schema_txn,
            start_index=0,
            application_tail_ref=self.step_ref,
            dynamic_tail=True,
        )

    def execute_sync(self: _BootstrapSchemaStateLazyContext, result: LazyResult[Any] | LazySeq[Any]) -> None:
        from l2055_lazy_result.purity import (
            bootstrap_lazy_terminal_boundary,
            bootstrap_phase_session,
            bootstrap_schema_write_boundary_lazy,
        )

        self._fuse_physical_interrogation()
        work = _schema_plan_fetch_work(self.schema_txn, self.lazy_observation)
        raw_results: object | None = None
        with (
            bootstrap_phase_session(),
            bootstrap_schema_write_boundary_lazy(),
            bootstrap_lazy_terminal_boundary(
                "bootstrap-interrogation",
            ),
        ):
            if not self.fuse_physical_preparation:
                _record_bootstrap_profile_counter("round_trip_boundary", "total")
                _record_bootstrap_profile_counter("round_trip_boundary", "bootstrap_interrogation")
            if getattr(work.plan, "_returns", None):
                raw_results = execute_server_plan_now(work.plan)
        raw_result = work.materialize(raw_results)
        cast("LazyResult[Any]", result)._set_resolved(cast("object", self._materialize_state(raw_result)))

    async def execute_async(self: _BootstrapSchemaStateLazyContext, result: LazyResult[Any] | LazySeq[Any]) -> None:
        from l2055_lazy_result.purity import (
            bootstrap_lazy_terminal_boundary,
            bootstrap_phase_session,
            bootstrap_schema_write_boundary_lazy,
        )

        self._fuse_physical_interrogation()
        work = _schema_plan_fetch_work(self.schema_txn, self.lazy_observation)
        raw_results: object | None = None
        with (
            bootstrap_phase_session(),
            bootstrap_schema_write_boundary_lazy(),
            bootstrap_lazy_terminal_boundary(
                "bootstrap-interrogation",
            ),
        ):
            if not self.fuse_physical_preparation:
                _record_bootstrap_profile_counter("round_trip_boundary", "total")
                _record_bootstrap_profile_counter("round_trip_boundary", "bootstrap_interrogation")
            if getattr(work.plan, "_returns", None):
                raw_results = await execute_server_plan_async(work.plan)
        raw_result = work.materialize(raw_results)
        if isinstance(result, LazySeq):
            msg = "bootstrap schema state interrogation cannot resolve a sequence"
            raise TypeError(msg)
        result._set_resolved(self._materialize_state(raw_result))


class _SchemaPlanFetchLazyContext[T]:
    """Resolve plan-scope fetch templates at a single terminal boundary."""

    def __init__(self, schema_txn: LazySchemaTransaction, value: T) -> None:
        self._schema_txn = schema_txn
        self._value = value

    def execute_sync(self: _SchemaPlanFetchLazyContext[T], result: LazyResult[T]) -> None:
        from l2055_lazy_result.purity import (
            bootstrap_lazy_terminal_boundary,
            bootstrap_phase_session,
            bootstrap_schema_write_boundary_lazy,
        )

        work = _schema_plan_fetch_work(self._schema_txn, self._value)
        raw_results: object | None = None
        if getattr(work.plan, "_returns", None):
            with (
                bootstrap_phase_session(),
                bootstrap_schema_write_boundary_lazy(),
                bootstrap_lazy_terminal_boundary(
                    "bootstrap-schema-plan-fetch",
                ),
                self._schema_txn._base_planning_catalog_scope(),
            ):
                raw_results = execute_server_plan_now(work.plan)
        result._set_resolved(work.materialize(raw_results))

    async def execute_async(self: _SchemaPlanFetchLazyContext[T], result: LazyResult[T]) -> None:
        from l2055_lazy_result.purity import (
            bootstrap_lazy_terminal_boundary,
            bootstrap_phase_session,
            bootstrap_schema_write_boundary_lazy,
        )

        work = _schema_plan_fetch_work(self._schema_txn, self._value)
        raw_results: object | None = None
        if getattr(work.plan, "_returns", None):
            with (
                bootstrap_phase_session(),
                bootstrap_schema_write_boundary_lazy(),
                bootstrap_lazy_terminal_boundary(
                    "bootstrap-schema-plan-fetch",
                ),
                self._schema_txn._base_planning_catalog_scope(),
            ):
                raw_results = await execute_server_plan_async(work.plan)
        result._set_resolved(work.materialize(raw_results))


def _materialized_bootstrap_handle_value[T](handle: LazyResult[T], *, site: str) -> T:
    from l2070_batching.server_ref import inspect_server_value_shape_for_planning

    shape = inspect_server_value_shape_for_planning(
        handle,
        site=site,
        prefer_materialized_value=True,
    )
    if shape.has_literal_value:
        return cast("T", shape.literal_value)
    raise RuntimeError(f"{site} did not produce a materialized value")


def _execute_schema_state_handle_sync(
    handle: LazyResult[BootstrapSchemaState],
) -> BootstrapSchemaState:
    """Execute one schema-state handle at its signed coordinator boundary."""
    context = handle._context
    if not isinstance(context, _BootstrapSchemaStateLazyContext):
        msg = "bootstrap interrogation handle has an unexpected execution context"
        raise TypeError(msg)
    context.execute_sync(handle)
    return _materialized_bootstrap_handle_value(handle, site="sync bootstrap schema state")


