@pure_lazy
def _planned_metadata_row_group(
    *,
    row_kind: BootstrapMetadataRowKind,
    model_path: str,
    table_name: SqlTableName,
    key_columns: tuple[str, ...],
    update_columns: tuple[str, ...],
    source_ref: ServerPlanRefId,
    row_hash_parts: tuple[object, ...],
) -> BootstrapMetadataRowGroup:
    from hashlib import sha256

    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
    from l1400_types.type_surface_contracts import BootstrapFactsHash, PythonClassPath
    from l3200_metadata.bootstrap_metadata_plan import BootstrapMetadataRowContract, BootstrapMetadataRowGroup

    row_hash = sha256("|".join(str(part) for part in row_hash_parts).encode()).hexdigest()
    produced_ref = ServerPlanRefId(
        f"out_{int(sha256(f'bootstrap-metadata:{source_ref}'.encode()).hexdigest()[:15], 16)}",
    )
    return BootstrapMetadataRowGroup(
        table_name=SqlTableName(table_name),
        key_columns=tuple(SqlColumnName(column) for column in key_columns),
        update_columns=tuple(SqlColumnName(column) for column in update_columns),
        rows=(
            BootstrapMetadataRowContract(
                row_kind=row_kind,
                model_path=PythonClassPath(model_path),
                row_hash=BootstrapFactsHash(row_hash),
                source_ref=source_ref,
            ),
        ),
        produced_ref=produced_ref,
    )


class BootstrapSchemaMigration(Protocol):
    """Queue physical preparation and activation in coordinator-owned phases."""

    def prepare_physical_for_planning(
        self: BootstrapSchemaMigration,
