    contract_fingerprint: str
    model_classes: tuple[type[DatabaseObjectRow[SysId]], ...]
    physical_contract: BootstrapPhysicalSchemaContract
    backend_type: BackendType | None = None
    physical_contract_work_products: tuple[BootstrapPhysicalContractWorkProduct, ...] = ()
    desired_primitives: tuple[Any, ...] = ()
    proof_scope_fact_hashes: tuple[str, ...] = ()
    seed_fact_hashes: tuple[str, ...] = ()
