def _publish_global_schema_hash_for_plan(plan: BootstrapEnginePlan) -> None:
    """Publish global schema authority only for an explicitly core-owned plan."""
    if plan.owns_core_schema is not True:
        return
    from l3200_metadata.canonical_hashing import set_current_schema_hash

    set_current_schema_hash(plan.schema_hash_v2)


def _bootstrap_application_planning_models(
    plan: BootstrapEnginePlan,
) -> tuple[type[DatabaseObjectRow[SysId]], ...]:
    """Bind declared application table families without exposing metadata control rows."""
    from l1000_schema.schema_def import DatabaseObjectRow
    from l3200_metadata.bootstrap_data_plan import (
        BootstrapTableFamilyPrimitivePayload,
        BootstrapVersionedRowsPrimitivePayload,
        BootstrapVersionedTableFamilyPrimitivePayload,
    )

    models: dict[type[DatabaseObjectRow[SysId]], None] = {}
    for declaration in plan.desired_primitives:
        payload = declaration.payload
        if isinstance(payload, BootstrapImmutableRowPrimitivePayload):
            models[payload.model_cls] = None
        elif isinstance(payload, (BootstrapTableFamilyPrimitivePayload, BootstrapVersionedTableFamilyPrimitivePayload)):
            for model in payload.family_models or (payload.model_cls,):
                assert issubclass(model, DatabaseObjectRow)
                models[model] = None
        elif isinstance(payload, BootstrapVersionedRowsPrimitivePayload):
            models[payload.model_cls] = None
    return tuple(models)


type _BootstrapEnginePlanCacheKey = tuple[
    str,
    tuple[type[object], ...],
    tuple[tuple[str, str, str, str], ...],
    str,
    bool,
]

_BOOTSTRAP_ENGINE_PLAN_CACHE: LocalMetadataCache[BootstrapEnginePlan] = LocalMetadataCache(
    name="bootstrap:engine_plans",
    max_entries=2048,
)
_BOOTSTRAP_ENGINE_PLAN_CACHE_LOCK = threading.RLock()


@pure_lazy
def _bootstrap_engine_plan_cache_key(
    manifest_key: str,
    model_classes: tuple[type[DatabaseObjectRow[SysId]], ...],
    contributors: tuple[object, ...],
    dialect: object | None,
    include_core: bool,
) -> _BootstrapEnginePlanCacheKey:
    return (
        manifest_key,
        cast("tuple[type[object], ...]", _bootstrap_model_cache_key(cast("tuple[type[Any], ...]", model_classes))),
        _bootstrap_contributor_cache_key(contributors),
        _bootstrap_dialect_cache_key(dialect),
        include_core,
    )


@pure_lazy
def _bootstrap_bounded_cache_key(cache_key: object) -> str:
    from l1000_schema.schema_def import DatabaseObjectRow
    from l3200_metadata.hashing import (
        compute_declared_physical_contract_fingerprint,
        compute_model_schema_contract_fingerprint,
    )

    def encode(value: object) -> object:
        if isinstance(value, type):
            type_key = f"{value.__module__}.{value.__qualname__}"
            schema_contract = compute_model_schema_contract_fingerprint(value) if issubclass(value, DatabaseObjectRow) else None
            physical_contract = compute_declared_physical_contract_fingerprint(value) if issubclass(value, DatabaseObjectRow) else None
            return {
                "type": type_key,
                "schema_contract": schema_contract,
                "physical_contract": physical_contract,
            }
        if isinstance(value, tuple):
            return [encode(item) for item in value]
        if value is None or isinstance(value, str | int | float | bool):
            return value
        raise TypeError(
            f"Bootstrap cache keys require canonical values, got {type(value).__module__}.{type(value).__qualname__}",
        )

    return json.dumps(encode(cache_key), sort_keys=True, separators=(",", ":"))


@pure_lazy
def _bootstrap_engine_plan_request_fingerprint(
    manifest_key: str,
    model_classes: tuple[type[DatabaseObjectRow[SysId]], ...],
    contributors: tuple[object, ...],
    dialect: object | None,
    include_core: bool,
) -> BootstrapFactsHash:
    request_key = _bootstrap_engine_plan_cache_key(
        manifest_key,
        model_classes,
        contributors,
        dialect,
        include_core,
    )
    canonical_request = _bootstrap_bounded_cache_key(request_key)
    return BootstrapFactsHash(hashlib.sha256(canonical_request.encode()).hexdigest())


@pure_lazy
def _validate_prebuilt_engine_plan_request(
    plan: BootstrapEnginePlan,
    *,
    manifest_key: str,
    model_classes: tuple[type[DatabaseObjectRow[SysId]], ...],
    contributors: tuple[object, ...],
    dialect: object | None,
    include_core: bool,
) -> None:
    expected = _bootstrap_engine_plan_request_fingerprint(
        manifest_key,
        model_classes,
        contributors,
        dialect,
        include_core,
    )
    if plan.request_fingerprint == expected:
        return
    raise RuntimeError(
        "prebuilt bootstrap plan request does not match the current invocation; "
        "rebuild the plan for the requested models, contributors, dialect, and core-schema ownership",
    )


@pure_lazy
def _bootstrap_logged_table_payloads(plan: BootstrapEnginePlan) -> tuple["BootstrapLoggedTablePrimitivePayload", ...]:
    """Return validated logged-table declarations for both bootstrap execution paths."""
    from l3200_metadata.bootstrap_data_plan import BootstrapLoggedTablePrimitivePayload
    from l3200_metadata.bootstrap_state import BootstrapPlanningError

    payloads: list[BootstrapLoggedTablePrimitivePayload] = []
    desired_primitives = getattr(plan, "desired_primitives", ())
    for declaration in desired_primitives:
        if declaration.identity.primitive_kind is not BootstrapDataPrimitiveKind.ENSURE_LOGGED_TABLE:
            continue
        payload = declaration.payload
        if not isinstance(payload, BootstrapLoggedTablePrimitivePayload):
            msg = (
                "ENSURE_LOGGED_TABLE requires BootstrapLoggedTablePrimitivePayload for "
                f"{declaration.identity}; rebuild the bootstrap declaration."
            )
            raise BootstrapPlanningError(msg)
        payloads.append(payload)
    return tuple(payloads)


