@contextmanager
def _bootstrap_coordinator_connection_scope(conn: object) -> Generator[None]:
    """Mark coordinator-owned schema planning without widening terminal scope."""
    prior_depth = int(getattr(conn, "_bootstrap_coordinator_run_depth", 0))
    setattr(conn, "_bootstrap_coordinator_run_depth", prior_depth + 1)
    try:
        yield
    finally:
        setattr(conn, "_bootstrap_coordinator_run_depth", prior_depth)


@dataclass(frozen=True, slots=True)
class LazyBootstrapCoordinator:
    """The only bootstrap coordinator."""

    @staticmethod
    @pure_lazy
    def _plan_declared_table_renames(
        schema_txn: LazySchemaTransaction,
        work_products: tuple[BootstrapPhysicalContractWorkProduct, ...],
    ) -> None:
        """Queue observed family renames before any target-table creation."""
        from impl.common.l7245_versioned_backends.registry import versioned_backend_registry
        from l1000_schema.table_registry import get_table_config, has_table_config
        from l1000_schema.table_utils import get_table_name
        from l3200_metadata.bootstrap_state import BootstrapPlanningError

        dialect = schema_txn._conn.get_dialect()
        snapshot = schema_txn._schema_reconciliation_snapshot
        claims: dict[SqlTableName, SqlTableName] = {}
        renamed_models: list[type[DatabaseObjectRow[SysId]]] = []
        for work_product in work_products:
            model_cls = work_product.model_cls
            if not has_table_config(model_cls):
                continue
            legacy_name = get_table_config(model_cls).renamed_from
            if not legacy_name:
                continue
            old_name = dialect.stored_table_name(SqlTableName(legacy_name))
            new_name = SqlTableName(get_table_name(model_cls))
            prior_target = claims.get(old_name)
            if prior_target is not None and prior_target != new_name and snapshot is not None and snapshot.table_exists(old_name) is True:
                raise BootstrapPlanningError(
                    f"Existing table {old_name!r} has multiple rename targets: "
                    f"{prior_target!r} and {new_name!r}. Manual reconciliation is required.",
                )
            claims[old_name] = new_name
            renamed_models.append(model_cls)
        for model_cls in renamed_models:
            backend = versioned_backend_registry.get("sparse", schema_txn)
            backend._apply_table_family_rename_lazy(schema_txn, model_cls)

    @staticmethod
    @external_io_boundary
    def _seed_schema_transaction_table_snapshot(
        schema_txn: LazySchemaTransaction,
        observation: BootstrapObservation,
    ) -> None:
        """Seed physical schema facts observed by the entry interrogation."""
        from impl.common.l2050_sql_types.sql_branded_types import SqlTypeName

        from l1400_types.type_surface_contracts import BootstrapBackendExtensionName

        for polymorphic_fact in observation.polymorphic_type_facts:
            schema_txn._polymorphic_metadata_existing_entries.setdefault(polymorphic_fact.base_table, []).append(
                (SqlTypeName(polymorphic_fact.type_name), polymorphic_fact.type_id, polymorphic_fact.python_class),
            )
        if BootstrapBackendExtensionName("pg_jsonschema") in observation.requested_backend_extensions:
            schema_txn.record_bootstrap_extension_observation(
                tuple(
                    BootstrapBackendExtensionName(fact.artifact_name)
                    for fact in observation.named_artifact_facts
                    if fact.artifact_kind == "backend_extension"
                )
            )
            schema_txn._bootstrap_json_schema_check_available = any(
                fact.artifact_kind == "backend_extension" and fact.artifact_name == "pg_jsonschema"
                for fact in observation.named_artifact_facts
            )
        from l3200_metadata.bootstrap_fts_nonce import BootstrapFtsNonceSnapshot

        for fact in observation.named_artifact_facts:
            if fact.artifact_kind == "fts_artifact" and fact.artifact_name == "database_hash_nonce":
                if fact.payload_json is None:
                    raise ValueError("Bootstrap nonce observation is missing its payload")
                schema_txn._bootstrap_fts_nonce_snapshot = BootstrapFtsNonceSnapshot.model_validate_json(fact.payload_json)
        schema_txn._schema_reconciliation_snapshot = observation.to_schema_state_snapshot()
        observed_existing_tables = frozenset(SqlTableName(str(fact.table_name)) for fact in observation.table_facts)
        schema_txn._existing_tables_snapshot_for_schema_batch = set(observed_existing_tables)
        schema_txn._bulk_table_names_snapshot = observed_existing_tables
        schema_txn._last_bulk_table_names_snapshot = observed_existing_tables
        schema_txn._schema_table_names_snapshot = observed_existing_tables
        schema_txn._seed_table_exists_cache_many(tuple((table_name, True) for table_name in observed_existing_tables))
        columns_by_table: dict[SqlTableName, set[SqlColumnName]] = {}
        for column_fact in observation.column_facts:
            columns_by_table.setdefault(SqlTableName(str(column_fact.table_name)), set()).add(
                SqlColumnName(str(column_fact.column_name)),
            )
        for table_name, columns in columns_by_table.items():
            column_snapshot = frozenset(columns)
            schema_txn._bulk_column_snapshots[table_name] = column_snapshot
            schema_txn._schema_physical_column_snapshots[table_name] = column_snapshot
        indexes_by_table: dict[SqlTableName, set[SqlIndexName]] = {}
        for index_fact in observation.index_facts:
            indexes_by_table.setdefault(SqlTableName(str(index_fact.table_name)), set()).add(
                SqlIndexName(str(index_fact.index_name)),
            )
        for table_name, indexes in indexes_by_table.items():
            index_snapshot = frozenset(indexes)
            schema_txn._bulk_index_snapshots[table_name] = index_snapshot
            schema_txn._schema_physical_index_snapshots[table_name] = index_snapshot

    def run(
        self: LazyBootstrapCoordinator,
        conn: SyncDatabaseConnection,
        *,
        manifest_key: str,
        model_classes: Sequence[type[DatabaseObjectRow[SysId]]],
        contributors: Sequence[object] = (),
        execute_data_primitives: bool = True,
        require_manifest_fast_path: bool = False,
        engine_plan: BootstrapEnginePlan | None = None,
        include_core: bool = True,
        known_empty_target: bool = False,
        schema_migration: BootstrapSchemaMigration | None = None,
    ) -> BootstrapEngineRunResult:
        """Run bootstrap and an optional migration through the two terminal boundaries."""
        if known_empty_target and schema_migration is not None:
            raise ValueError("A schema migration requires an observed source state")
        with _bootstrap_coordinator_observation(conn):
            driver_observation = current_bootstrap_observation()
            if driver_observation is None:
                raise RuntimeError("Bootstrap coordinator is missing its driver observation")
            driver_observation.require_classification = True
            # Empty PostgreSQL tables do not prove server capabilities or runtime admission.
            known_empty_target = known_empty_target and conn.backend_type is not BackendType.POSTGRES
            contributors = tuple(contributors)
            model_classes = tuple(model_classes)

            from l1300_session.session import SessionId
            from l2055_lazy_result.purity import (
                bootstrap_lazy_terminal_boundary,
                bootstrap_lifecycle_effect_boundary_lazy,
                bootstrap_plan_active,
                bootstrap_phase_session,
                bootstrap_schema_write_boundary_lazy,
            )

            if engine_plan is None:
                plan = self.build_engine_plan(
                    manifest_key=manifest_key,
                    model_classes=model_classes,
                    contributors=contributors,
                    dialect=conn.get_dialect(),
                    include_core=include_core,
                )
            else:
                plan = engine_plan
                _validate_prebuilt_engine_plan_request(
                    plan,
                    manifest_key=manifest_key,
                    model_classes=model_classes,
                    contributors=contributors,
                    dialect=conn.get_dialect(),
                    include_core=include_core,
                )
            logged_table_payloads = _bootstrap_logged_table_payloads(plan)
            conn.bind_planning_models(*model_classes, *_bootstrap_application_planning_models(plan))
            with (
                bootstrap_plan_active(),
                bootstrap_lifecycle_effect_boundary_lazy(),
                bootstrap_schema_write_boundary_lazy(),
                _bootstrap_coordinator_connection_scope(conn),
                bootstrap_observation_phase("application" if known_empty_target else "interrogation"),
                ExitStack() as observation_phases,
                conn.schema_transaction(SessionId.schema()) as schema_txn,
            ):
                if logged_table_payloads:
                    schema_txn.publish_bootstrap_logged_table_bundles_lazy(logged_table_payloads)
                if schema_migration is not None:
                    preparation_refs = schema_migration.prepare_physical_for_planning(schema_txn)
                    schema_migration.activate_lazy(
                        schema_txn,
                        dependency_refs=preparation_refs,
                    )
                with bootstrap_schema_write_boundary_lazy():
                    if known_empty_target:
                        state = _empty_bootstrap_schema_state(
                            plan,
                            execute_data_primitives=execute_data_primitives,
                            require_manifest_fast_path=require_manifest_fast_path,
                        )
                    else:
                        state_handle = self.interrogate_schema_state_lazy(
                            schema_txn,
                            plan,
                            execute_data_primitives=execute_data_primitives,
                            require_manifest_fast_path=require_manifest_fast_path,
                            fuse_physical_preparation=schema_migration is not None,
                        )
                        if require_manifest_fast_path:
                            _enqueue_owned_schema_commit(schema_txn)
                        with (
                            bootstrap_observation_phase("interrogation"),
                            bootstrap_phase_session(),
                            bootstrap_lazy_terminal_boundary("bootstrap-interrogation"),
                        ):
                            state = _execute_schema_state_handle_sync(state_handle)
                        if schema_migration is not None:
                            schema_migration.validate_interrogated_state(state)
                        observation_phases.enter_context(bootstrap_observation_phase("application"))
                        schema_txn.begin_bootstrap_application_plan()
                    self._seed_schema_transaction_table_snapshot(schema_txn, state.observation)
                    application_plan = self.plan_application(
                        state.observation,
                        state.engine_plan,
                        state.model_classes,
                        execute_data_primitives=state.execute_data_primitives,
                        require_manifest_fast_path=state.require_manifest_fast_path,
                    )
                    if application_plan.terminal_budget is BootstrapApplicationTerminalBudget.ZERO_APPLICATION_TERMINALS:
                        facts = self._fast_path_execution_facts(application_plan)
                    else:
                        execution_handle = self.build_execution_plan_lazy(
                            schema_txn,
                            state,
                            application_plan=application_plan,
                            complete_transaction=True,
                        )
                        with (
                            bootstrap_observation_phase("application"),
                            bootstrap_phase_session(),
                            bootstrap_lazy_terminal_boundary("bootstrap-application"),
                        ):
                            fetch_handle = _schema_plan_fetch_lazy(schema_txn, execution_handle)
                            facts = self._coerce_execution_facts(_execute_schema_plan_fetch_handle_sync(fetch_handle))
                        schema_txn.complete_bootstrap_application_plan(
                            transaction_committed=_bootstrap_application_uses_native_commit(schema_txn),
                        )
            self.apply_lifecycle_effects(conn, application_plan, facts)
            _publish_global_schema_hash_for_plan(plan)
            observation = state.observation
            return BootstrapEngineRunResult(
                mode=self._run_mode_for_observation(facts, observation, plan),
                plan_hash=plan.plan_hash,
                schema_hash_v2=plan.schema_hash_v2,
                schema_generation=self._schema_generation_after_application(observation, facts),
                schema_mutation_count=facts.mutation_counts.schema_mutations,
                data_mutation_count=(
                    0
                    if facts.status is BootstrapApplicationStatus.PUBLISHED_MANIFEST_ALIAS
                    else (
                        facts.mutation_counts.metadata_mutations
                        + facts.mutation_counts.seed_mutations
                        + facts.mutation_counts.versioning_mutations
                    )
                ),
                manifest_published_for_plan_hash=self._manifest_published_for_plan_hash(facts, plan),
                manifest_fast_path=facts.status is BootstrapApplicationStatus.SKIPPED_MANIFEST_FAST_PATH,
                transition_cache_replayed=bool(facts.transition_replay_facts),
                transition_replay_rejection_count=len(facts.transition_replay_rejection_facts),
            )

    def apply_lifecycle_effects(
        self: LazyBootstrapCoordinator,
        conn: SyncDatabaseConnection | AsyncDatabaseConnection,
        application_plan: BootstrapApplicationPlan,
        facts: BootstrapExecutionFacts,
    ) -> None:
        """Apply bootstrap lifecycle effects after the application terminal resolves."""
        facts = self._facts_with_lifecycle_source_refs(facts, application_plan.lifecycle_effects)
        apply_bootstrap_lifecycle_effects_boundary(conn, application_plan.lifecycle_effects, facts)

    async def run_async(
        self: LazyBootstrapCoordinator,
        conn: AsyncDatabaseConnection,
        *,
        manifest_key: str,
        model_classes: Sequence[type[DatabaseObjectRow[SysId]]],
        contributors: Sequence[object] = (),
        execute_data_primitives: bool = True,
        require_manifest_fast_path: bool = False,
        engine_plan: BootstrapEnginePlan | None = None,
        include_core: bool = True,
        known_empty_target: bool = False,
        schema_migration: BootstrapSchemaMigration | None = None,
    ) -> BootstrapEngineRunResult:
        """Run async bootstrap and an optional migration through both terminal boundaries."""
        if known_empty_target and schema_migration is not None:
            raise ValueError("A schema migration requires an observed source state")
        with _bootstrap_coordinator_observation(conn, asynchronous=True):
            driver_observation = current_bootstrap_observation()
            if driver_observation is None:
                raise RuntimeError("Bootstrap coordinator is missing its driver observation")
            driver_observation.require_classification = True
            # Empty PostgreSQL tables do not prove server capabilities or runtime admission.
            known_empty_target = known_empty_target and conn.backend_type is not BackendType.POSTGRES
            contributors = tuple(contributors)
            model_classes = tuple(model_classes)

            from l1300_session.session import SessionId
            from l2055_lazy_result.purity import (
                bootstrap_coordinator_schema_transaction_boundary,
                bootstrap_lazy_terminal_boundary,
                bootstrap_lifecycle_effect_boundary_lazy,
                bootstrap_plan_active,
                bootstrap_phase_session,
                bootstrap_schema_write_boundary_lazy,
            )

            _record_bootstrap_profile_counter(
                "schema_bootstrap_build_engine_plan_origin",
                "coordinator_manifest_fast_path" if require_manifest_fast_path else "coordinator_application",
            )
            if engine_plan is None:
                plan = self.build_engine_plan(
                    manifest_key=manifest_key,
                    model_classes=model_classes,
                    contributors=contributors,
                    dialect=conn.get_dialect(),
                    include_core=include_core,
                )
            else:
                plan = engine_plan
                _record_bootstrap_profile_counter("schema_bootstrap_build_engine_plan_origin", "coordinator_reused")
                _validate_prebuilt_engine_plan_request(
                    plan,
                    manifest_key=manifest_key,
                    model_classes=model_classes,
                    contributors=contributors,
                    dialect=conn.get_dialect(),
                    include_core=include_core,
                )
            logged_table_payloads = _bootstrap_logged_table_payloads(plan)
            conn.bind_planning_models(*model_classes, *_bootstrap_application_planning_models(plan))
            with (
                bootstrap_plan_active(),
                bootstrap_lifecycle_effect_boundary_lazy(),
                bootstrap_schema_write_boundary_lazy(),
                bootstrap_coordinator_schema_transaction_boundary(),
                _bootstrap_coordinator_connection_scope(conn),
                bootstrap_observation_phase("application" if known_empty_target else "interrogation"),
                ExitStack() as observation_phases,
            ):
                async with conn.schema_transaction_async(SessionId.schema()) as schema_txn:
                    if logged_table_payloads:
                        schema_txn.publish_bootstrap_logged_table_bundles_lazy(logged_table_payloads)
                    if schema_migration is not None:
                        preparation_refs = schema_migration.prepare_physical_for_planning(schema_txn)
                        schema_migration.activate_lazy(
                            schema_txn,
                            dependency_refs=preparation_refs,
                        )
                    if known_empty_target:
                        state = _empty_bootstrap_schema_state(
                            plan,
                            execute_data_primitives=execute_data_primitives,
                            require_manifest_fast_path=require_manifest_fast_path,
                        )
                    else:
                        state_handle = self.interrogate_schema_state_lazy(
                            schema_txn,
                            plan,
                            execute_data_primitives=execute_data_primitives,
                            require_manifest_fast_path=require_manifest_fast_path,
                            fuse_physical_preparation=schema_migration is not None,
                        )
                        if require_manifest_fast_path:
                            _enqueue_owned_schema_commit(schema_txn)
                        with (
                            bootstrap_observation_phase("interrogation"),
                            bootstrap_phase_session(),
                            bootstrap_lazy_terminal_boundary("bootstrap-interrogation"),
                        ):
                            state = await _execute_schema_state_handle_async(state_handle)
                        if schema_migration is not None:
                            schema_migration.validate_interrogated_state(state)
                        observation_phases.enter_context(bootstrap_observation_phase("application"))
                        schema_txn.begin_bootstrap_application_plan()
                    self._seed_schema_transaction_table_snapshot(schema_txn, state.observation)
                    application_plan = self.plan_application(
                        state.observation,
                        state.engine_plan,
                        state.model_classes,
                        execute_data_primitives=state.execute_data_primitives,
                        require_manifest_fast_path=state.require_manifest_fast_path,
                    )
                    if application_plan.terminal_budget is BootstrapApplicationTerminalBudget.ZERO_APPLICATION_TERMINALS:
                        facts = self._fast_path_execution_facts(application_plan)
                    else:
                        execution_handle = self.build_execution_plan_lazy(
                            schema_txn,
                            state,
                            application_plan=application_plan,
                            complete_transaction=True,
                        )
                        with (
                            bootstrap_observation_phase("application"),
                            bootstrap_phase_session(),
                            bootstrap_lazy_terminal_boundary("bootstrap-application"),
                        ):
                            fetch_handle = _schema_plan_fetch_lazy(schema_txn, execution_handle)
                            with _bootstrap_profile_span("schema_bootstrap.execute_application_terminal"):
                                resolved_facts = await _execute_schema_plan_fetch_handle_async(fetch_handle)
                                facts = self._coerce_execution_facts(resolved_facts)
                            schema_txn.complete_bootstrap_application_plan(
                                transaction_committed=_bootstrap_application_uses_native_commit(schema_txn),
                            )
            self.apply_lifecycle_effects(conn, application_plan, facts)
            _publish_global_schema_hash_for_plan(plan)
            observation = state.observation
            return BootstrapEngineRunResult(
                mode=self._run_mode_for_observation(facts, observation, plan),
                plan_hash=plan.plan_hash,
                schema_hash_v2=plan.schema_hash_v2,
                schema_generation=self._schema_generation_after_application(observation, facts),
                schema_mutation_count=facts.mutation_counts.schema_mutations,
                data_mutation_count=(
                    0
                    if facts.status is BootstrapApplicationStatus.PUBLISHED_MANIFEST_ALIAS
                    else (
                        facts.mutation_counts.metadata_mutations
                        + facts.mutation_counts.seed_mutations
                        + facts.mutation_counts.versioning_mutations
                    )
                ),
                manifest_published_for_plan_hash=self._manifest_published_for_plan_hash(facts, plan),
                manifest_fast_path=facts.status is BootstrapApplicationStatus.SKIPPED_MANIFEST_FAST_PATH,
                transition_cache_replayed=bool(facts.transition_replay_facts),
                transition_replay_rejection_count=len(facts.transition_replay_rejection_facts),
            )

    @pure_lazy
    def _manifest_published_for_plan_hash(
        self: LazyBootstrapCoordinator,
        facts: BootstrapExecutionFacts,
        plan: BootstrapEnginePlan,
    ) -> str | None:
        """Return the plan hash whose manifest was published by this application."""
        del self
        if facts.status is BootstrapApplicationStatus.SKIPPED_MANIFEST_FAST_PATH:
            return None
        if any(str(fact.plan_hash) == plan.plan_hash for fact in facts.manifest_facts):
            return plan.plan_hash
        msg = (
            "Bootstrap application completed without publishing its final plan manifest: "
            f"manifest_key={plan.manifest_key!s} plan_hash={plan.plan_hash}."
        )
        raise RuntimeError(msg)

    @pure_lazy
    def build_engine_plan(
        self: LazyBootstrapCoordinator,
        *,
        manifest_key: str,
        model_classes: Sequence[type[DatabaseObjectRow[SysId]]],
        contributors: Sequence[object] = (),
        dialect: SqlDialect | None = None,
        include_core: bool = True,
    ) -> BootstrapEnginePlan:
        contributors = tuple(contributors)
        model_classes = tuple(model_classes)
        from l3200_metadata.hashing import compute_schema_hash_lazy, expand_schema_contract_models

        from impl.common.l1000_cache.cache_generation_model import CacheGenerationRow
        from l1300_session.session import Session
        from l3200_metadata.api_name_binding_metadata import ApiNameBindingMetadata
        from l3200_metadata.bootstrap_state import (
            BootstrapManifest,
            BootstrapProofScope,
            BootstrapSeedFactRow,
        )
        from l3200_metadata.bootstrap_state import BootstrapPrimitiveState, core_bootstrap_metadata_models
        from l2000_connection.ddl_lockdown_runtime import DDLLockdownState
        from l3200_metadata.infrastructure_tables import DeploymentLeaseRecord, StartupTaskCompletion
        from l3200_metadata.polymorphic_types import PolymorphicTypeRecord
        from l3200_metadata.schema_state import SchemaState
        from l3200_metadata.schema_version import SchemaVersion
        from l3200_metadata.semantic_object_metadata import SemanticObjectMetadata

        requested_plan_cache_key = _bootstrap_engine_plan_cache_key(
            manifest_key,
            tuple(model_classes),
            tuple(contributors),
            dialect,
            include_core,
        )
        requires_fresh_binding = any(getattr(contributor, "requires_fresh_plan_binding", False) is True for contributor in contributors)
        cached_plan: BootstrapEnginePlan | None = None
        if not requires_fresh_binding:
            with _BOOTSTRAP_ENGINE_PLAN_CACHE_LOCK:
                cached_plan = _BOOTSTRAP_ENGINE_PLAN_CACHE.get(
                    _bootstrap_bounded_cache_key(requested_plan_cache_key),
                )
        if cached_plan is not None:
            _record_bootstrap_profile_counter("bootstrap_engine_plan_cache", "hit")
            return cached_plan
        _record_bootstrap_profile_counter("bootstrap_engine_plan_cache", "miss")

        with _bootstrap_profile_span("schema_bootstrap.build_engine_plan"):
            bootstrap_state = BootstrapPrimitiveState(dialect=dialect)
            with _bootstrap_profile_span("schema_bootstrap.contributor_execution"):
                for contributor in contributors:
                    contribute = getattr(contributor, "contribute", None)
                    if not callable(contribute):
                        msg = f"bootstrap contributor {type(contributor).__name__} has no contribute() method"
                        raise TypeError(msg)
                    contribute(bootstrap_state)
            if include_core:
                bootstrap_state.ensure_metadata_schema(core_bootstrap_metadata_models())
            _record_bootstrap_profile_counter("schema_bootstrap_build_engine_plan", "contributors", len(contributors))
            _record_bootstrap_profile_counter(
                "schema_bootstrap_build_engine_plan",
                "desired_primitives",
                len(bootstrap_state.desired_primitives),
            )

            core_models = (Session,) if include_core else ()

            def _normalize_declared_models() -> tuple[type[DatabaseObjectRow[SysId]], ...]:
                from l1000_schema.table_utils import get_table_name
                from l3200_metadata.bootstrap_data_plan import BootstrapVectorIndexPrimitivePayload

                vector_source_models = tuple(
                    declaration.payload.model_cls
                    for declaration in bootstrap_state.desired_primitives
                    if isinstance(declaration.payload, BootstrapVectorIndexPrimitivePayload)
                )
                physical_vector_models: list[type[DatabaseObjectRow[SysId]]] = []
                if vector_source_models and dialect is not None and dialect.backend_type in {BackendType.SQLITE, BackendType.MARIADB}:
                    from l5200_vector_index.hnsw_models import (
                        create_hnsw_content_edge_class,
                        create_hnsw_content_node_class,
                        create_hnsw_edge_class,
                        create_hnsw_metadata_class,
                        create_hnsw_node_class,
                    )

                    for model_cls in vector_source_models:
                        source_table_name = get_table_name(model_cls)
                        physical_vector_models.extend(
                            (
                                create_hnsw_node_class(source_table_name),
                                create_hnsw_edge_class(source_table_name),
                                create_hnsw_content_node_class(source_table_name),
                                create_hnsw_content_edge_class(source_table_name),
                                create_hnsw_metadata_class(source_table_name),
                            ),
                        )
                declared_product_models = tuple(
                    model_cls
                    for declaration in bootstrap_state.desired_primitives
                    for model_cls in (
                        *getattr(getattr(declaration, "payload", None), "schema_models", ()),
                        *getattr(getattr(declaration, "payload", None), "storage_models", ()),
                    )
                    if isinstance(model_cls, type)
                )
                declared_models = tuple(
                    dict.fromkeys(
                        (
                            *core_models,
                            *model_classes,
                            *physical_vector_models,
                            *bootstrap_state.model_classes,
                            *declared_product_models,
                        ),
                    ),
                )
                expanded_models = expand_schema_contract_models(declared_models)
                # Dynamic and runtime auxiliary models can resolve to a source
                # model for identity. Physical DDL still needs each actual model.
                return cast(
                    "tuple[type[DatabaseObjectRow[SysId]], ...]",
                    tuple(dict.fromkeys((*expanded_models, *declared_models))),
                )

            normalized_model_classes = _normalize_declared_models()
            graph_config_declared = any(
                declaration.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_GRAPH_CONFIG_METADATA
                for declaration in bootstrap_state.desired_primitives
            )
            graph_model_declared = any(
                any(base.__name__ in {"Graph", "GraphNode", "GraphEdge"} for base in model_cls.__mro__)
                for model_cls in normalized_model_classes
            )
            if (graph_config_declared or graph_model_declared) and not any(
                declaration.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_GRAPH_PHYSICAL_KEYS
                for declaration in bootstrap_state.desired_primitives
            ):
                # Graph config rows are per-model metadata, but graph physical
                # key tables are shared support. Deriving the support primitive
                # here keeps contributors from each emitting their own copy and
                # makes the manifest finalization step the single authority for
                # graph-support cardinality.
                bootstrap_state.ensure_graph_physical_keys(BootstrapPrimitiveContributorKey("derived.graph_physical_keys"))
                # This derived primitive carries its own ``schema_models``
                # (the graph physical key tables), so the declared-model set
                # must be recomputed before contracts are built. Building
                # contracts first leaves those models without a physical
                # contract work product, and the DDL planner later rejects the
                # closed plan with "missing a physical contract work product".
                normalized_model_classes = _normalize_declared_models()
            for _closure_pass in range(8):
                physical_contract_work_products = self._physical_contract_work_products_for_models(
                    normalized_model_classes,
                    dialect=dialect,
                )
                closed_model_classes = _normalize_declared_models()
                if closed_model_classes == normalized_model_classes:
                    break
                normalized_model_classes = closed_model_classes
            else:
                raise RuntimeError(
                    "Bootstrap physical model closure did not stabilize after 8 passes",
                )
            _record_bootstrap_profile_counter(
                "schema_bootstrap_build_engine_plan",
                "normalized_models",
                len(normalized_model_classes),
            )
            physical_contract = self._merge_physical_contract_work_products(physical_contract_work_products)
            with _bootstrap_profile_span("schema_bootstrap.compute_schema_hash"):
                schema_hash = compute_schema_hash_lazy(normalized_model_classes)
            contract_fingerprint = physical_contract.facts_hash()
            from l1000_schema.table_registry import get_table_config, has_table_config

            stored_rename_roots: dict[SqlTableName, SqlTableName] = {}
            for model_cls in normalized_model_classes:
                if not has_table_config(model_cls):
                    continue
                legacy_name = get_table_config(model_cls).renamed_from
                if legacy_name:
                    declared_name = SqlTableName(legacy_name)
                    stored_rename_roots[declared_name] = (
                        dialect.stored_table_name(declared_name) if dialect is not None else declared_name
                    )
            with _bootstrap_profile_span("schema_bootstrap.build_engine_plan_hash"):
                plan_payload = "|".join(
                    (
                        manifest_key,
                        schema_hash,
                        contract_fingerprint,
                        repr(tuple(stored_rename_roots.items())),
                        ",".join(f"{model_cls.__module__}.{model_cls.__qualname__}" for model_cls in normalized_model_classes),
                        ",".join(
                            f"{getattr(contributor, 'key', type(contributor).__qualname__)}:{getattr(contributor, 'version', '')}"
                            for contributor in contributors
                        ),
                        ",".join(sorted(str(primitive.identity.fact_hash) for primitive in bootstrap_state.desired_primitives)),
                    ),
                )
            plan = BootstrapEnginePlan(
                manifest_key=BootstrapManifestKey(manifest_key),
                plan_hash=BootstrapPlanHash(hashlib.sha256(plan_payload.encode()).hexdigest()),
                schema_hash_v2=schema_hash,
                contract_fingerprint=contract_fingerprint,
                model_classes=normalized_model_classes,
                physical_contract=physical_contract,
                backend_type=None if dialect is None else dialect.backend_type,
                physical_contract_work_products=physical_contract_work_products,
                desired_primitives=bootstrap_state.desired_primitives,
                owns_core_schema=include_core,
                request_fingerprint=_bootstrap_engine_plan_request_fingerprint(
                    manifest_key,
                    model_classes,
                    contributors,
                    dialect,
                    include_core,
                ),
                stored_rename_roots=tuple(stored_rename_roots.items()),
            )
            from l3200_metadata.bootstrap_manifest_builders import (
                _seed_fact_hashes_for_engine_plan,
                bootstrap_scope_facts_for_engine_plan,
            )

            with _bootstrap_profile_span("schema_bootstrap.build_engine_plan.derived_facts"):
                proof_scope_fact_hashes = tuple(
                    sorted(
                        str(payload["facts_hash"])
                        for payload in bootstrap_scope_facts_for_engine_plan(plan).values()
                        if isinstance(payload, dict) and isinstance(payload.get("facts_hash"), str)
                    ),
                )
                seed_fact_hashes = tuple(sorted(str(seed_hash) for seed_hash in _seed_fact_hashes_for_engine_plan(plan).values()))
            plan_with_facts = replace(
                plan,
                proof_scope_fact_hashes=proof_scope_fact_hashes,
                seed_fact_hashes=seed_fact_hashes,
            )
            normalized_plan_cache_key = _bootstrap_engine_plan_cache_key(
                manifest_key,
                normalized_model_classes,
                tuple(contributors),
                dialect,
                include_core,
            )
        if requires_fresh_binding:
            return plan_with_facts
        with _BOOTSTRAP_ENGINE_PLAN_CACHE_LOCK:
            requested_bounded_key = _bootstrap_bounded_cache_key(requested_plan_cache_key)
            normalized_bounded_key = _bootstrap_bounded_cache_key(normalized_plan_cache_key)
            cached_plan = _BOOTSTRAP_ENGINE_PLAN_CACHE.get(requested_bounded_key)
            if cached_plan is None:
                cached_plan = _BOOTSTRAP_ENGINE_PLAN_CACHE.get(normalized_bounded_key)
            if cached_plan is None:
                cached_plan = plan_with_facts
                _record_bootstrap_profile_counter("bootstrap_engine_plan_cache", "stored")
            _BOOTSTRAP_ENGINE_PLAN_CACHE.set(requested_bounded_key, cached_plan)
            _BOOTSTRAP_ENGINE_PLAN_CACHE.set(normalized_bounded_key, cached_plan)
            return cached_plan

    @pure_lazy
    def _artifact_interrogation_requirements(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> tuple[
        tuple[tuple[str, SqlTableName, str], ...],
        tuple[tuple[SqlTableName, tuple[str, ...]], ...],
        tuple[tuple[SqlTableName, tuple[str, ...]], ...],
        tuple[tuple[SqlTableName, tuple[str, ...]], ...],
    ]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlIndexName, SqlTableName
        from l3200_metadata.bootstrap_data_plan import (
            BootstrapCommitTriggersPrimitivePayload,
            BootstrapContentAddressableEmbeddingSchemaPrimitivePayload,
            BootstrapDataPrimitiveKind,
            BootstrapFtsIndexPrimitivePayload,
            BootstrapLargeColumnSchemaPrimitivePayload,
            BootstrapLoggedTablePrimitivePayload,
            BootstrapTableEventTriggerPrimitivePayload,
            BootstrapTableFamilyPrimitivePayload,
            BootstrapTriggerDdlPrimitivePayload,
            BootstrapVectorIndexPrimitivePayload,
        )

        del self
        fts_artifacts: set[tuple[str, SqlTableName, str]] = set()
        vector_artifacts: dict[SqlTableName, set[str]] = {}
        large_column_artifacts: dict[SqlTableName, set[str]] = {}
        trigger_artifacts: dict[SqlTableName, set[str]] = {}
        for declaration in cast("tuple[BootstrapDesiredPrimitiveDeclaration, ...]", plan.desired_primitives):
            payload = declaration.payload
            assert payload is not None
            if isinstance(payload, BootstrapFtsIndexPrimitivePayload):
                # Project exact requirements from the DDL-owned tuple. Do not
                # derive FTS names here. See the NER-1368 artifact contract.
                for target in payload.physical_targets:
                    fts_artifacts.update(
                        (artifact.kind.value, SqlTableName(target.table_name), artifact.name) for artifact in target.artifacts
                    )
            elif isinstance(payload, BootstrapVectorIndexPrimitivePayload):
                vector_artifacts.setdefault(payload.table_name, set()).add(str(payload.index_name))
            elif isinstance(payload, BootstrapContentAddressableEmbeddingSchemaPrimitivePayload):
                for table_name in payload.storage_tables:
                    vector_artifacts.setdefault(table_name, set()).add("content_addressable_embedding_schema")
                for index_name in payload.index_names:
                    vector_artifacts.setdefault(SqlTableName("sys_vector_index_config"), set()).add(str(index_name))
            elif isinstance(payload, BootstrapLargeColumnSchemaPrimitivePayload):
                large_column_artifacts.setdefault(payload.table_name, set()).add("large_column_metadata")
            elif isinstance(payload, BootstrapTableFamilyPrimitivePayload):
                for artifact in payload.trigger_artifacts:
                    trigger_artifacts.setdefault(artifact.table_name, set()).add(
                        str(artifact.trigger_name),
                    )
            elif isinstance(payload, BootstrapTableEventTriggerPrimitivePayload):
                trigger_artifacts.setdefault(payload.table_name, set()).add(payload.trigger_name)
            elif isinstance(payload, BootstrapLoggedTablePrimitivePayload):
                for artifact in payload.trigger_artifacts:
                    trigger_artifacts.setdefault(artifact.table_name, set()).add(
                        str(artifact.trigger_name),
                    )
            elif isinstance(payload, BootstrapTriggerDdlPrimitivePayload):
                if payload.trigger_artifacts:
                    for artifact in payload.trigger_artifacts:
                        trigger_artifacts.setdefault(artifact.table_name, set()).add(
                            str(artifact.trigger_name),
                        )
                else:
                    trigger_artifacts.setdefault(SqlTableName("__bootstrap_trigger_scope__"), set()).add(
                        payload.primitive_name,
                    )
            elif isinstance(payload, BootstrapCommitTriggersPrimitivePayload):
                for artifact in payload.trigger_artifacts:
                    trigger_artifacts.setdefault(artifact.table_name, set()).add(
                        str(artifact.trigger_name),
                    )

        def _fts_artifact_sort_key(item: tuple[str, SqlTableName, str]) -> tuple[str, str, str]:
            return item[0], str(item[1]), item[2]

        def _artifact_table_sort_key(item: tuple[SqlTableName, set[str]]) -> str:
            return str(item[0])

        def _items(values: dict[SqlTableName, set[str]]) -> tuple[tuple[SqlTableName, tuple[str, ...]], ...]:
            return tuple((table_name, tuple(sorted(names))) for table_name, names in sorted(values.items(), key=_artifact_table_sort_key))

        return (
            tuple(sorted(fts_artifacts, key=_fts_artifact_sort_key)),
            _items(vector_artifacts),
            _items(large_column_artifacts),
            _items(trigger_artifacts),
        )

    @pure_lazy
    def _physical_contract_for_models(
        self: LazyBootstrapCoordinator,
        model_classes: tuple[type[DatabaseObjectRow[SysId]], ...],
        *,
        dialect: object | None = None,
    ) -> BootstrapPhysicalSchemaContract:
        return self._merge_physical_contract_work_products(
            self._physical_contract_work_products_for_models(model_classes, dialect=dialect),
        )

    @pure_lazy
    def _physical_contract_work_products_for_models(
        self: LazyBootstrapCoordinator,
        model_classes: tuple[type[DatabaseObjectRow[SysId]], ...],
        *,
        dialect: object | None = None,
    ) -> tuple[BootstrapPhysicalContractWorkProduct, ...]:
        from l3200_metadata.bootstrap_physical_contract import physical_schema_contract_work_products_for_models

        cache_key = _bootstrap_model_cache_key(cast("tuple[type[Any], ...]", model_classes))
        bounded_key = _bootstrap_bounded_cache_key((cache_key, _bootstrap_dialect_cache_key(dialect)))
        cached = _PHYSICAL_CONTRACT_WORK_PRODUCTS_CACHE.get(bounded_key)
        if cached is not None:
            _record_bootstrap_profile_counter("bootstrap_physical_contract_work_products", "cache_hit")
            _record_bootstrap_profile_counter(
                "bootstrap_physical_contract_work_products_model_count",
                str(len(model_classes)),
            )
            return cached
        with _bootstrap_profile_span("schema_bootstrap.physical_contract_work_products_for_models"):
            work_products = physical_schema_contract_work_products_for_models(
                cast("tuple[type[ApplicationObjectRow[SysId]], ...]", model_classes),
                dialect=dialect,
            )
        _PHYSICAL_CONTRACT_WORK_PRODUCTS_CACHE.set(bounded_key, work_products)
        _record_bootstrap_profile_counter("bootstrap_physical_contract_work_products", "cache_miss")
        _record_bootstrap_profile_counter(
            "bootstrap_physical_contract_work_products_model_count",
            str(len(model_classes)),
        )
        return work_products

    @pure_lazy
    def _merge_physical_contract_work_products(
        self: LazyBootstrapCoordinator,
        work_products: tuple[BootstrapPhysicalContractWorkProduct, ...],
    ) -> BootstrapPhysicalSchemaContract:
        from l3200_metadata.bootstrap_physical_contract import (
            merge_physical_schema_contracts,
        )

        del self
        return merge_physical_schema_contracts(work_product.contract for work_product in work_products)

    @pure_lazy
    def _coerce_execution_facts(
        self: LazyBootstrapCoordinator,
        facts: object,
    ) -> BootstrapExecutionFacts:
        """Normalize the fused terminal's singleton tail wrapper."""

        del self
        if isinstance(facts, BootstrapExecutionFacts):
            return facts
        if isinstance(facts, (list, tuple)) and len(facts) == 1 and isinstance(facts[0], BootstrapExecutionFacts):
            return facts[0]
        msg = f"bootstrap application terminal returned {type(facts).__name__}, expected BootstrapExecutionFacts"
        raise TypeError(msg)

    @pure_lazy
    def _schema_generation_after_application(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        facts: BootstrapExecutionFacts,
    ) -> int:
        """Return the generation produced by the closed bootstrap application."""
        execution_generations = tuple(fact.schema_generation for fact in facts.schema_state_facts)
        if execution_generations:
            return max(execution_generations)
        observed_generations = tuple(fact.schema_generation for fact in observation.schema_state_facts)
        observed_generation = max(observed_generations, default=0)
        return max(
            1,
            observed_generation + int(facts.mutation_counts.schema_mutations > 0),
        )

    @pure_lazy
    def _run_mode_for_observation(
        self: LazyBootstrapCoordinator,
        facts: BootstrapExecutionFacts,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> BootstrapEngineRunMode:
        if facts.status is BootstrapApplicationStatus.SKIPPED_MANIFEST_FAST_PATH:
            return BootstrapEngineRunMode.MANIFEST_FAST_PATH
        if facts.status is BootstrapApplicationStatus.PUBLISHED_MANIFEST_ALIAS:
            return BootstrapEngineRunMode.MANIFEST_ALIAS
        if not self._durable_bootstrap_proof_metadata_present(observation, plan):
            if observation.manifest_facts or observation.schema_state_facts or observation.proof_facts or observation.seed_facts:
                return BootstrapEngineRunMode.SCHEMA_EVOLUTION_APPLICATION
            return BootstrapEngineRunMode.APPLICATION
        return BootstrapEngineRunMode.WARM

    @pure_lazy
    def _versioned_fk_prerequisite_table_names(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> tuple[SqlTableName, ...]:
        """Return external versioned FK tables needed for trigger planning."""

        del self
        from impl.common.l7245_versioned_backends.versioned_fk_triggers import iter_model_fks
        from l1000_schema.schema_def import get_table_name
        from l7000_versioned_schema.versioned_schema import VersionedObjectRow
        from l7000_versioned_schema.versioned_table_info import VersionedBaseTableName, derive_versioned_table_names

        prerequisite_tables: list[SqlTableName] = []
        for model_cls in plan.model_classes:
            if not issubclass(model_cls, VersionedObjectRow):
                continue
            for fk in iter_model_fks(model_cls):
                if fk.is_versioned_target and fk.target_model is not model_cls:
                    prerequisite_tables.append(
                        SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(get_table_name(fk.target_model)))).tip),
                    )
        return tuple(dict.fromkeys(prerequisite_tables))

    @pure_lazy
    def seed_fact_hashes_for_plan(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> tuple[tuple[BootstrapAuthorityKey, BootstrapFactsHash], ...]:
        """Return the expected seed authority for a closed engine plan."""
        from l3200_metadata.bootstrap_manifest_builders import _seed_fact_hashes_for_engine_plan

        return tuple(
            sorted(
                (BootstrapAuthorityKey(key), BootstrapFactsHash(facts_hash))
                for key, facts_hash in _seed_fact_hashes_for_engine_plan(plan).items()
            )
        )

    @pure_lazy
    def interrogation_request_for_plan(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> tuple[BootstrapInterrogationRequest, ServerPlanRefId]:
        """Build the closed physical observation request for an engine plan."""
        return self._interrogation_request_for_plan(plan)

    @pure_lazy
    def _interrogation_request_for_plan(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> tuple[BootstrapInterrogationRequest, ServerPlanRefId]:
        from impl.common.l2050_sql_types.sql_branded_types import (
            SqlColumnName,
            SqlConstraintName,
            SqlIndexName,
            SqlTableName,
            SqlTriggerName,
        )
        from impl.common.l2070_server_plan.steps.bootstrap_interrogation import BootstrapInterrogationRequest

        physical_contract = plan.physical_contract
        observation_columns_by_table = _bootstrap_observation_columns_by_table(plan)
        fts_artifacts, vector_artifacts, large_column_artifacts, trigger_artifacts = self._artifact_interrogation_requirements(plan)
        from l1450_index_policy_contracts.fts_physical import (
            FtsBootstrapTarget,
            FtsBootstrapTargetRole,
            FtsPhysicalArtifact,
            SqliteFtsBootstrapTarget,
        )
        from l3200_metadata.bootstrap_data_plan import (
            BootstrapFtsIndexPrimitivePayload,
            BootstrapVectorIndexPrimitivePayload,
        )

        def _fts_expected_columns(
            payload: BootstrapFtsIndexPrimitivePayload,
            target: FtsBootstrapTarget,
            artifact: FtsPhysicalArtifact,
        ) -> tuple[SqlColumnName, ...]:
            if artifact.columns:
                return tuple(SqlColumnName(str(column)) for column in artifact.columns)
            if artifact.kind.value == "table" and isinstance(target, SqliteFtsBootstrapTarget):
                revision_columns = () if target.role is FtsBootstrapTargetRole.ALL else (str(target.revision_column_name),)
                return tuple(
                    SqlColumnName(column_name) for column_name in dict.fromkeys((*payload.indexed_fields, "sys_id", *revision_columns))
                )
            return ()

        fts_artifact_columns = tuple(
            (
                BootstrapArtifactKind(artifact.kind.value),
                SqlTableName(target.table_name),
                BootstrapArtifactName(str(artifact.name)),
                _fts_expected_columns(fts_payload, target, artifact),
            )
            for declaration in plan.desired_primitives
            if isinstance((fts_payload := declaration.payload), BootstrapFtsIndexPrimitivePayload)
            for target in fts_payload.physical_targets
            for artifact in target.artifacts
            if artifact.columns or artifact.kind.value == "table"
        )
        vector_configurations = tuple(
            (
                payload.table_name,
                SqlIndexName(str(payload.index_name)),
                payload.dimensions,
                BootstrapVectorMetricName(payload.metric),
                BootstrapVectorStrategyName(payload.strategy),
            )
            for declaration in plan.desired_primitives
            if isinstance((payload := declaration.payload), BootstrapVectorIndexPrimitivePayload)
        )
        prerequisite_table_names = self._versioned_fk_prerequisite_table_names(plan)
        from l1000_schema.table_registry import get_table_config, has_table_config
        from l3250_migrations.semantic_renames import versioned_table_family_rename_pairs

        rename_tables: set[SqlTableName] = set()
        stored_rename_roots = dict(plan.stored_rename_roots)
        for work_product in plan.physical_contract_work_products:
            if not has_table_config(work_product.model_cls):
                continue
            table_config = get_table_config(work_product.model_cls)
            if table_config.renamed_from:
                rename_tables.add(SqlTableName("sys_schema_rename_history"))
                for old_name, new_name in versioned_table_family_rename_pairs(
                    stored_rename_roots.get(
                        SqlTableName(table_config.renamed_from),
                        SqlTableName(table_config.renamed_from),
                    ),
                    table_config.plural,
                ):
                    rename_tables.update((SqlTableName(old_name), SqlTableName(new_name)))
        request = BootstrapInterrogationRequest(
            manifest_key=BootstrapManifestKey(plan.manifest_key),
            plan_hash=BootstrapPlanHash(plan.plan_hash),
            table_names=tuple(
                dict.fromkeys(
                    (
                        *(SqlTableName(table_name) for table_name in physical_contract.table_names),
                        *(table_name for kind, table_name, _artifact_name in fts_artifacts if kind == "table"),
                        *prerequisite_table_names,
                        *sorted(rename_tables, key=str),
                    ),
                ),
            ),
            required_columns_by_table=tuple(
                (
                    SqlTableName(table_name),
                    tuple(
                        SqlColumnName(column_name)
                        for column_name in dict.fromkeys((*column_names, *observation_columns_by_table.get(str(table_name), ())))
                    ),
                )
                for table_name, column_names in physical_contract.required_columns_by_table.items()
            ),
            required_indexes_by_table=_complete_index_observation_requests(physical_contract),
            required_primary_key_columns_by_table=tuple(
                (
                    SqlTableName(table_name),
                    tuple(SqlColumnName(column_name) for column_name in column_names),
                )
                for table_name, column_names in physical_contract.required_primary_key_columns_by_table.items()
            ),
            required_generated_columns_by_table=tuple(
                (
                    SqlTableName(table_name),
                    tuple(SqlColumnName(column_name) for column_name in column_names),
                )
                for table_name, column_names in physical_contract.required_generated_columns_by_table.items()
            ),
            required_constraints_by_table=tuple(
                (
                    SqlTableName(table_name),
                    tuple(str(constraint_name) for constraint_name in constraint_names),
                )
                for table_name, constraint_names in physical_contract.required_check_constraints_by_table.items()
            ),
            required_triggers_by_table=trigger_artifacts,
            trigger_scan_tables=tuple(
                sorted(
                    {
                        *(SqlTableName(table_name) for table_name in physical_contract.table_names),
                        *rename_tables,
                        *(
                            table_name
                            for table_name, _trigger_names in trigger_artifacts
                            if not str(table_name).startswith("__bootstrap_")
                        ),
                    },
                    key=str,
                ),
            ),
            required_fts_artifacts_by_table=fts_artifacts,
            required_fts_artifact_columns=fts_artifact_columns,
            required_vector_artifacts_by_table=vector_artifacts,
            required_vector_configurations=vector_configurations,
            required_large_column_artifacts_by_table=large_column_artifacts,
            schema_state_hash=SchemaFingerprintHash(plan.schema_hash_v2),
            observed_fingerprint=SchemaFingerprintHash(physical_contract.facts_hash()),
            desired_fingerprint=SchemaFingerprintHash(plan.contract_fingerprint),
            expected_proof_hashes=tuple(BootstrapFactsHash(value) for value in plan.proof_scope_fact_hashes),
            expected_seed_hashes=tuple(BootstrapFactsHash(value) for value in plan.seed_fact_hashes),
        )
        interrogation_ref = ServerPlanRefId(
            f"bootstrap_interrogation:{plan.manifest_key}:{plan.plan_hash}",
        )
        request = replace(
            request,
            required_immutable_rows=tuple(
                (declaration.identity.fact_hash, declaration.payload.content_assertion(interrogation_ref))
                for declaration in plan.desired_primitives
                if isinstance(declaration.payload, BootstrapImmutableRowPrimitivePayload)
            ),
        )
        return request, interrogation_ref

    @pure_lazy
    def _build_schema_state_context(
        self: LazyBootstrapCoordinator,
        txn: LazySchemaTransaction,
        engine_plan: BootstrapEnginePlan,
        *,
        execute_data_primitives: bool = True,
        require_manifest_fast_path: bool = False,
        fuse_physical_preparation: bool = False,
    ) -> _BootstrapSchemaStateLazyContext:
        """Build the ref-backed interrogation context without executing it."""

        request, interrogation_ref = self._interrogation_request_for_plan(engine_plan)
        effective_request = txn.bootstrap_interrogation_request_no_io(request)
        lazy_observation = txn.bootstrap_interrogation_lazy(
            effective_request,
            plan_ref=interrogation_ref,
        )
        step_ref = lazy_observation.plan_owned_result_ref(txn.plan_scope_plan().owned_step_ref_ids())
        if step_ref is None:
            raise RuntimeError("Bootstrap interrogation did not publish a plan-owned result")
        interrogation_step = next(candidate for candidate in txn.plan()._steps if str(candidate.ref_id) == str(step_ref))
        return _BootstrapSchemaStateLazyContext(
            schema_txn=txn,
            step_ref=ServerPlanRefId(step_ref),
            lazy_observation=lazy_observation,
            interrogation_step=interrogation_step,
            engine_plan=engine_plan,
            model_classes=engine_plan.model_classes,
            execute_data_primitives=execute_data_primitives,
            require_manifest_fast_path=require_manifest_fast_path,
            fuse_physical_preparation=fuse_physical_preparation,
        )

    @pure_lazy
    def interrogate_schema_state_lazy(
        self: LazyBootstrapCoordinator,
        txn: LazySchemaTransaction,
        engine_plan: BootstrapEnginePlan,
        *,
        execute_data_primitives: bool = True,
        require_manifest_fast_path: bool = False,
        fuse_physical_preparation: bool = False,
    ) -> LazyResult[BootstrapSchemaState]:
        """Build the single lazy interrogation handle for the bootstrap schema state."""

        context = self._build_schema_state_context(
            txn,
            engine_plan,
            execute_data_primitives=execute_data_primitives,
            require_manifest_fast_path=require_manifest_fast_path,
            fuse_physical_preparation=fuse_physical_preparation,
        )
        step_ref = context.step_ref
        return LazyResult.published_ref(
            operation=LazyOperation(op="execute"),
            context=context,
            ref_id=step_ref,
            expected_type=BootstrapSchemaState,
            dependency_refs=frozenset({step_ref}),
        )

    @pure_lazy
    def build_execution_plan_lazy(
        self: LazyBootstrapCoordinator,
        txn: LazySchemaTransaction,
        state: BootstrapSchemaState,
        *,
        application_plan: BootstrapApplicationPlan | None = None,
        complete_transaction: bool = False,
    ) -> LazyResult[BootstrapExecutionFacts]:
        """Build and return the application execution lazy result."""

        if application_plan is None:
            application_plan = self.plan_application(
                state.observation,
                state.engine_plan,
                state.model_classes,
                execute_data_primitives=state.execute_data_primitives,
                require_manifest_fast_path=state.require_manifest_fast_path,
            )
        if application_plan.terminal_budget is BootstrapApplicationTerminalBudget.ZERO_APPLICATION_TERMINALS:
            msg = "Manifest fast-path execution facts do not require an application LazyResult."
            raise RuntimeError(msg)
        with _bootstrap_profile_span("schema_bootstrap.enqueue_application_schema"):
            return self._enqueue_application_schema_lazy(
                txn,
                application_plan,
                observation=state.observation,
                complete_transaction=complete_transaction,
            )

    @pure_lazy
    def _close_application_schema_products(
        self: LazyBootstrapCoordinator,
        schema_txn: LazySchemaTransaction,
        application_plan: BootstrapApplicationPlan,
    ) -> BootstrapApplicationPlan:
        """Produce connection-sensitive schema products once, before transaction lowering."""

        from impl.common.l7245_versioned_backends.registry import versioned_backend_registry
        from l3200_metadata.bootstrap_data_plan import BootstrapVersionedTableFamilyPrimitivePayload
        from l3200_metadata.bootstrap_state import BootstrapPlanningError

        versioned_models = [
            family_model
            for schema_contract in application_plan.data_primitive_plan.schema_mutations
            if isinstance(schema_contract.payload, BootstrapVersionedTableFamilyPrimitivePayload)
            for family_model in schema_contract.payload.family_models
        ]
        physical_contract_by_model = {
            work_product.model_cls: work_product.contract for work_product in application_plan.physical_contract_work_products
        }
        from l1000_schema.table_utils import get_table_name

        physical_contract_table_names = {get_table_name(model_cls) for model_cls in physical_contract_by_model}
        versioned_batch = application_plan.versioned_family_batch_work_product
        if versioned_models and versioned_batch is None:
            missing_versioned_physical_models = tuple(
                model_cls
                for model_cls in dict.fromkeys(versioned_models)
                if model_cls not in physical_contract_by_model and get_table_name(model_cls) not in physical_contract_table_names
            )
            if missing_versioned_physical_models:
                missing_names = ", ".join(
                    f"{model_cls.__module__}.{model_cls.__qualname__}" for model_cls in missing_versioned_physical_models
                )
                msg = f"cold bootstrap application is missing versioned-family physical contract work products for: {missing_names}"
                raise BootstrapPlanningError(msg)
            backend = versioned_backend_registry.get("sparse", schema_txn)
            versioned_batch = backend.build_bootstrap_versioned_family_work_products_for_planning(
                cast("tuple[Any, ...]", tuple(dict.fromkeys(versioned_models))),
                dialect=schema_txn._planning_dialect,
                physical_contract_work_products=application_plan.physical_contract_work_products,
            )
        return replace(
            application_plan,
            table_family_work_products=application_plan.table_family_work_products,
            versioned_family_batch_work_product=versioned_batch,
        )

