            bootstrap_phase_session,
        )

        physical_contract = plan.physical_contract
        observation_columns_by_table = _bootstrap_observation_columns_by_table(plan)
        fts_artifacts, vector_artifacts, large_column_artifacts, trigger_artifacts = self._artifact_interrogation_requirements(plan)
        table_names = tuple(
            dict.fromkeys(
