    @pure_lazy
    def plan_application(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
        model_classes: Sequence[type[DatabaseObjectRow[SysId]]],
        *,
        execute_data_primitives: bool,
        require_manifest_fast_path: bool = False,
    ) -> BootstrapApplicationPlan:
        """Build the closed application plan without executing Python callbacks."""
        model_classes = tuple(model_classes)

        if self._manifest_fast_path_available(observation, plan):
            lifecycle_effects = self._fast_path_lifecycle_effects_for_observation(observation, plan)
            return BootstrapApplicationPlan(
                kind=BootstrapApplicationPlanKind.MANIFEST_FAST_PATH,
                plan_hash=BootstrapPlanHash(plan.plan_hash),
                desired_schema_hash=SchemaFingerprintHash(plan.schema_hash_v2),
                terminal_budget=BootstrapApplicationTerminalBudget.ZERO_APPLICATION_TERMINALS,
                owns_core_schema=plan.owns_core_schema,
                lifecycle_effects=lifecycle_effects,
            )
        if require_manifest_fast_path:
            rejection = self._manifest_fast_path_rejection_details(
                observation,
                plan,
            )
            msg = f"Required bootstrap manifest fast path was rejected: {rejection}."
            raise RuntimeError(msg)
        if self._manifest_alias_available(observation, plan):
            from l3200_metadata.bootstrap_manifest_builders import (
                build_bootstrap_manifest_alias_publication_plan,
                build_bootstrap_metadata_publication_plan,
                build_bootstrap_metadata_publication_rows,
                plan_bootstrap_schema_generation,
            )
            from l3200_metadata.bootstrap_schema_plan import BootstrapSchemaDdlPlan

            matching_manifests = tuple(fact for fact in observation.manifest_facts if str(fact.manifest_key) == str(plan.manifest_key))
            repairs_global_schema_authority = (
                plan.owns_core_schema
                and len(matching_manifests) == 1
                and not self._persisted_schema_authority_matches(
                    observation,
                    plan,
                    matching_manifests[0].schema_generation,
                )
            )
            metadata_publication_plan = (
                build_bootstrap_metadata_publication_plan(plan)
                if repairs_global_schema_authority
                else build_bootstrap_manifest_alias_publication_plan(plan)
            )
            planned_generation = plan_bootstrap_schema_generation(
                observation,
                plan,
                BootstrapSchemaDdlPlan(),
            )
            if not repairs_global_schema_authority and observation.schema_state_facts:
                observed_schema_state = observation.schema_state_facts[-1]
                planned_generation = replace(
                    planned_generation,
                    schema_generation=observed_schema_state.schema_generation,
                    schema_version=observed_schema_state.schema_version,
                    changed=False,
                )
            metadata_publication_rows = build_bootstrap_metadata_publication_rows(
                plan,
                schema_generation=planned_generation.schema_generation,
                schema_version=planned_generation.schema_version,
                model_classes=cast("tuple[type[object], ...]", model_classes),
                observed_types=observation.polymorphic_type_facts,
            )
            application_tail_ref = _legal_bootstrap_out_ref(
                plan.manifest_key,
                plan.plan_hash,
                "manifest-alias-tail",
            )
            return BootstrapApplicationPlan(
                kind=BootstrapApplicationPlanKind.MANIFEST_ALIAS,
                plan_hash=BootstrapPlanHash(plan.plan_hash),
                desired_schema_hash=SchemaFingerprintHash(plan.schema_hash_v2),
                terminal_budget=BootstrapApplicationTerminalBudget.ONE_APPLICATION_TERMINAL,
                owns_core_schema=plan.owns_core_schema,
                metadata_publication_plan=metadata_publication_plan,
                metadata_publication_rows=metadata_publication_rows,
                dependency_refs=metadata_publication_plan.dependency_refs,
                metadata_refs=metadata_publication_plan.publication_refs,
                application_tail_ref=application_tail_ref,
                lifecycle_effects=self._lifecycle_effects_for_plan(
                    plan,
                    metadata_publication_plan,
                ),
            )
        # A durable proof can become stale after source, manifest, or physical
        # contract changes. Reconcile it through the same closed application
        # plan instead of treating prior authority as permanent.
        with _bootstrap_profile_span("schema_bootstrap.plan_application"):
            schema_ddl_plan = self._schema_ddl_plan_for_plan(plan)
            with _bootstrap_profile_span("schema_bootstrap.data_primitive_plan_for_plan"):
                data_primitive_plan = self._data_primitive_plan_for_plan(plan, execute_data_primitives)
            with _bootstrap_profile_span("schema_bootstrap.metadata_publication_plan_for_plan"):
                metadata_publication_plan = self._metadata_publication_plan_for_plan(plan)
            with _bootstrap_profile_span("schema_bootstrap.metadata_publication_rows_for_plan"):
                metadata_publication_rows = self._metadata_publication_rows_for_plan(
                    observation,
                    plan,
                    schema_ddl_plan,
                    tuple(model_classes),
                )
            with _bootstrap_profile_span("schema_bootstrap.lifecycle_effects_for_plan"):
                lifecycle_effects = self._lifecycle_effects_for_plan(plan, metadata_publication_plan)
            with _bootstrap_profile_span("schema_bootstrap.transition_replay_plan_for_observation"):
                transition_boundary_plan, transition_assertions = self._transition_replay_plan_for_observation(
                    observation,
                    plan,
                )
        from l3200_metadata.bootstrap_transition_boundaries import BootstrapTransitionBoundaryPlan

        transition_boundary_plan = BootstrapTransitionBoundaryPlan(
            read_boundaries=transition_boundary_plan.read_boundaries,
            assertion_boundaries=transition_boundary_plan.assertion_boundaries,
        )
        application_assertions = self._application_sql_assertions_for_plan(
            plan,
            schema_ddl_plan,
            metadata_publication_plan,
        )
        dependency_refs = tuple(
            dict.fromkeys(
                (
                    *tuple(mutation.produced_ref for mutation in data_primitive_plan.schema_mutations),
                    *schema_ddl_plan.dependency_tail_refs,
                    *tuple(mutation.produced_ref for mutation in data_primitive_plan.data_mutations),
                    *tuple(mutation.produced_ref for mutation in data_primitive_plan.versioning_mutations),
                    *metadata_publication_plan.publication_refs,
                ),
            ),
        )
        schema_refs = (
            *tuple(mutation.produced_ref for mutation in data_primitive_plan.schema_mutations),
            *schema_ddl_plan.dependency_tail_refs,
        )
        data_refs = tuple(mutation.produced_ref for mutation in data_primitive_plan.data_mutations)
        versioning_refs = tuple(mutation.produced_ref for mutation in data_primitive_plan.versioning_mutations)
        metadata_refs = tuple(metadata_publication_plan.publication_refs)
        application_tail_ref = _legal_bootstrap_out_ref(plan.manifest_key, plan.plan_hash, "tail")
        application_kind = (
            BootstrapApplicationPlanKind.TRANSITION_REPLAY
            if transition_boundary_plan.assertion_boundaries
            else BootstrapApplicationPlanKind.LAZY_PRIMITIVE_APPLICATION
        )
        return BootstrapApplicationPlan(
            kind=application_kind,
            plan_hash=BootstrapPlanHash(plan.plan_hash),
            desired_schema_hash=SchemaFingerprintHash(plan.schema_hash_v2),
            terminal_budget=BootstrapApplicationTerminalBudget.ONE_APPLICATION_TERMINAL,
            owns_core_schema=plan.owns_core_schema,
            schema_ddl_plan=schema_ddl_plan,
            metadata_publication_plan=metadata_publication_plan,
            metadata_publication_rows=metadata_publication_rows,
            data_primitive_plan=data_primitive_plan,
            physical_contract_work_products=plan.physical_contract_work_products,
            transition_boundary_plan=transition_boundary_plan,
            dependency_refs=dependency_refs,
            schema_refs=schema_refs,
            data_refs=data_refs,
            metadata_refs=metadata_refs,
            versioning_refs=versioning_refs,
            application_tail_ref=application_tail_ref,
            assertions=(*application_assertions, *transition_assertions),
            lifecycle_effects=lifecycle_effects,
        )

    @pure_lazy
    def _proof_and_seed_authority_matches(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> bool:
        """Verify proof and seed identities, not only their content hashes."""
        from l3200_metadata.bootstrap_manifest_builders import (
            _seed_fact_hashes_for_engine_plan,
            bootstrap_scope_facts_for_engine_plan,
        )

        del self
        expected_proofs: dict[str, tuple[str, tuple[SqlTableName, ...]]] = {}
        for scope_key, payload in bootstrap_scope_facts_for_engine_plan(plan).items():
            facts_hash = payload.get("facts_hash")
            if not isinstance(facts_hash, str):
                continue
            raw_required_tables = payload.get("required_tables")
            if isinstance(raw_required_tables, (tuple, list)):
                required_tables = tuple(SqlTableName(str(table_name)) for table_name in raw_required_tables)
            else:
                required_tables = ()
            expected_proofs[str(scope_key)] = (facts_hash, required_tables)
        observed_proofs = {
            fact.scope_key: (str(fact.proof_hash), fact.required_tables)
            for fact in observation.proof_facts
            if fact.manifest_key == plan.manifest_key and fact.plan_hash == plan.plan_hash and fact.scope_key is not None
        }
        if not expected_proofs or any(observed_proofs.get(scope_key) != expected for scope_key, expected in expected_proofs.items()):
            return False

        expected_seeds = {str(seed_key): str(seed_hash) for seed_key, seed_hash in _seed_fact_hashes_for_engine_plan(plan).items()}
        observed_seeds = {
            fact.seed_key: str(fact.seed_hash)
            for fact in observation.seed_facts
            if fact.manifest_key == plan.manifest_key and fact.plan_hash == plan.plan_hash and fact.seed_key is not None
        }
        return all(observed_seeds.get(seed_key) == seed_hash for seed_key, seed_hash in expected_seeds.items())

    @pure_lazy
    def _manifest_alias_available(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> bool:
        """Return whether interrogation proves a metadata-only manifest alias."""

        if not self._immutable_content_observed(observation, plan):
            return False
        from l3200_metadata.bootstrap_data_plan import BootstrapDataPrimitiveKind

        if not self._physical_contract_observed(observation, plan):
            return False
        same_key_manifests = tuple(fact for fact in observation.manifest_facts if str(fact.manifest_key) == str(plan.manifest_key))
        matching_manifests = tuple(
            fact
            for fact in same_key_manifests
            if str(fact.plan_hash) == str(plan.plan_hash) and str(fact.schema_hash) == str(plan.schema_hash_v2)
        )
        if len(matching_manifests) == 1 and self._persisted_schema_authority_matches(
            observation,
            plan,
            matching_manifests[0].schema_generation,
        ):
            return True
        schema_only_kinds = {
            BootstrapDataPrimitiveKind.ENSURE_METADATA_SCHEMA,
            BootstrapDataPrimitiveKind.ENSURE_TABLE,
        }
        requires_seed_proof = any(declaration.identity.primitive_kind not in schema_only_kinds for declaration in plan.desired_primitives)
        # Granular artifact facts prove presence, not identity: a schema-only alias therefore
        # requires the exact physical-contract fingerprint. A module seed alias is different:
        # exact durable proof and seed hashes below identify the module state while the enclosing
        # physical schema is intentionally allowed to be an additive superset.
        if not requires_seed_proof and not any(
            str(fact.contract_fingerprint) == str(plan.contract_fingerprint) for fact in observation.schema_state_facts
        ):
            return False
        if requires_seed_proof:
            if not self._proof_and_seed_authority_matches(observation, plan):
                return False
        return True

    @pure_lazy
    def _required_named_artifacts(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> set[tuple[str, str, str]]:
        physical_contract = plan.physical_contract
        required_generated_columns = {
            ("generated_column", str(table_name), str(column_name))
            for table_name, column_names in physical_contract.required_generated_columns_by_table.items()
            for column_name in column_names
        }
        required_constraints = {
            ("constraint", str(table_name), str(constraint_name))
            for table_name, constraint_names in physical_contract.required_check_constraints_by_table.items()
            for constraint_name in constraint_names
        }
        (
            required_fts_artifacts,
            required_vector_artifacts,
            required_large_column_artifacts,
            required_trigger_artifacts,
        ) = self._artifact_interrogation_requirements(plan)
        required_declared_artifacts = {
            (f"fts_{kind}", str(table_name), artifact_name) for kind, table_name, artifact_name in required_fts_artifacts
        }
        required_declared_artifacts.update(
            (artifact_kind, str(table_name), artifact_name)
            for artifact_kind, requirements in (
                ("vector_artifact", required_vector_artifacts),
                ("large_column_artifact", required_large_column_artifacts),
                ("trigger", required_trigger_artifacts),
            )
            for table_name, artifact_names in requirements
            for artifact_name in artifact_names
        )
        return {*required_generated_columns, *required_constraints, *required_declared_artifacts}

    @pure_lazy
    def _physical_contract_observed(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> bool:
        """Return whether observed physical facts cover the desired contract."""

        physical_contract = plan.physical_contract
        observed_tables = {str(fact.table_name) for fact in observation.table_facts}
        observed_columns = {(fact.table_name, fact.column_name) for fact in observation.column_facts}
        observed_indexes = {(str(fact.table_name), str(fact.index_name)) for fact in observation.index_facts}
        observed_named_artifacts = {
            (fact.artifact_kind, str(fact.table_name) if fact.table_name is not None else None, fact.artifact_name)
            for fact in observation.named_artifact_facts
        }
        required_columns = _ordinary_required_column_facts(physical_contract)
        required_indexes = {
            (str(table_name), str(index_name))
            for table_name, index_names in physical_contract.required_indexes_by_table.items()
            for index_name in index_names
        }
        if not set(physical_contract.table_names).issubset(observed_tables):
            return False
        if not required_columns.issubset(observed_columns):
            return False
        observed_types = {(str(fact.table_name), str(fact.column_name)): fact.data_type for fact in observation.column_facts}
        for table in physical_contract.tables:
            for column, expected_type in table.required_column_types:
                observed_type = observed_types.get((str(table.table_name), str(column)))
                if observed_type is None or observed_type.upper() != expected_type.upper():
                    return False
        if not required_indexes.issubset(observed_indexes):
            return False
        required_named_artifacts = self._required_named_artifacts(plan)
        if not required_named_artifacts.issubset(observed_named_artifacts):
            return False

        from l3200_metadata.managed_trigger_reconciliation import (
            expected_managed_triggers_from_primitives,
            managed_trigger_artifacts_from_manifest_payload,
            managed_trigger_surface_is_current,
        )

        expected_managed_triggers = expected_managed_triggers_from_primitives(
            plan.desired_primitives,
        )
        previously_owned_triggers = tuple(
            artifact
            for manifest_fact in observation.manifest_facts
            for artifact in managed_trigger_artifacts_from_manifest_payload(
                str(manifest_fact.manifest_payload),
            )
        )
        snapshot = observation.to_schema_state_snapshot()
        return managed_trigger_surface_is_current(
            expected_managed_triggers,
            snapshot.trigger_facts,
            observed_trigger_tables=snapshot.observed_trigger_tables,
            previously_owned_triggers=previously_owned_triggers,
        )

    @pure_lazy
    def _transition_replay_plan_for_observation(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> tuple[BootstrapTransitionBoundaryPlan, tuple[BootstrapSqlAssertion, ...]]:
        from l3200_metadata.bootstrap_assertions import (
            BootstrapAssertionKind,
            BootstrapAssertionSeverity,
            BootstrapSqlAssertion,
            BootstrapTransitionReplayAssertion,
        )
        from l3200_metadata.bootstrap_observation import BootstrapFactPresence
        from l3200_metadata.bootstrap_transition_boundaries import (
            BootstrapTransitionBoundaryPlan,
            BootstrapTransitionCacheAssertionBoundary,
            BootstrapTransitionCacheReadBoundary,
        )
        from l3200_metadata.bootstrap_execution_facts import BootstrapTransitionReplayRejectionFact

        present_artifacts = tuple(
            fact for fact in observation.transition_artifact_facts if fact.presence is BootstrapFactPresence.PRESENT
        )
        backend_fingerprints = frozenset(str(fact.backend_fingerprint) for fact in observation.backend_facts)
        observed_fingerprint = str(plan.physical_contract.facts_hash())
        desired_mismatch_rejections = tuple(
            BootstrapTransitionReplayRejectionFact(
                observed_hash=fact.observed_hash,
                desired_hash=fact.desired_hash,
                artifact_hash=fact.artifact_hash,
                reason="desired_hash_mismatch",
                source_ref=fact.source_ref,
            )
            for fact in present_artifacts
            if str(fact.desired_hash) != str(plan.contract_fingerprint)
        )
        observed_mismatch_rejections = tuple(
            BootstrapTransitionReplayRejectionFact(
                observed_hash=fact.observed_hash,
                desired_hash=fact.desired_hash,
                artifact_hash=fact.artifact_hash,
                reason="observed_hash_mismatch",
                source_ref=fact.source_ref,
            )
            for fact in present_artifacts
            if str(fact.observed_hash) != observed_fingerprint
        )
        backend_mismatch_rejections = tuple(
            BootstrapTransitionReplayRejectionFact(
                observed_hash=fact.observed_hash,
                desired_hash=fact.desired_hash,
                artifact_hash=fact.artifact_hash,
                reason="backend_fingerprint_mismatch",
                source_ref=fact.source_ref,
            )
            for fact in present_artifacts
            if str(fact.backend_fingerprint) not in backend_fingerprints
        )
        matching_artifacts = tuple(
            fact
            for fact in present_artifacts
            if str(fact.desired_hash) == str(plan.contract_fingerprint)
            and str(fact.observed_hash) == observed_fingerprint
            and str(fact.backend_fingerprint) in backend_fingerprints
        )
        if not matching_artifacts:
            return BootstrapTransitionBoundaryPlan(
                rejection_facts=(
                    *desired_mismatch_rejections,
                    *observed_mismatch_rejections,
                    *backend_mismatch_rejections,
                ),
            ), ()
        physical_contract = plan.physical_contract
        eligible_artifacts = tuple(
            artifact for artifact in matching_artifacts if _transition_artifact_covers_contract(artifact, physical_contract)
        )
        coverage_rejections = tuple(
            BootstrapTransitionReplayRejectionFact(
                observed_hash=artifact.observed_hash,
                desired_hash=artifact.desired_hash,
                artifact_hash=artifact.artifact_hash,
                reason="contract_coverage_mismatch",
                source_ref=artifact.source_ref,
            )
            for artifact in matching_artifacts
            if not _transition_artifact_covers_contract(artifact, physical_contract)
        )
        if not eligible_artifacts:
            return BootstrapTransitionBoundaryPlan(
                rejection_facts=(
                    *desired_mismatch_rejections,
                    *observed_mismatch_rejections,
                    *backend_mismatch_rejections,
                    *coverage_rejections,
                ),
            ), ()
        artifact = eligible_artifacts[-1]
        assertion_ref = artifact.source_ref
        assertion_boundary = BootstrapTransitionCacheAssertionBoundary(
            observed_hash=artifact.observed_hash,
            desired_hash=artifact.desired_hash,
            replay_hash=artifact.artifact_hash,
            source_ref=assertion_ref,
        )
        sql_assertion = BootstrapSqlAssertion(
            kind=BootstrapAssertionKind.TRANSITION_REPLAY_VALID,
            severity=BootstrapAssertionSeverity.HARD_FAILURE,
            payload=BootstrapTransitionReplayAssertion(
                observed_hash=artifact.observed_hash,
                desired_hash=artifact.desired_hash,
                source_ref=assertion_ref,
            ),
        )
        return (
            BootstrapTransitionBoundaryPlan(
                read_boundaries=(
                    BootstrapTransitionCacheReadBoundary(
                        artifact_fact=artifact,
                        boundary_ref=artifact.source_ref,
                    ),
                ),
                assertion_boundaries=(assertion_boundary,),
                rejection_facts=(
                    *desired_mismatch_rejections,
                    *observed_mismatch_rejections,
                    *backend_mismatch_rejections,
                    *coverage_rejections,
                ),
            ),
            (sql_assertion,),
        )

    @pure_lazy
    def _application_sql_assertions_for_plan(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
        schema_ddl_plan: BootstrapSchemaDdlPlan,
        metadata_publication_plan: BootstrapMetadataPublicationPlan,
    ) -> tuple[BootstrapSqlAssertion, ...]:
        with _bootstrap_profile_span("schema_bootstrap.application_sql_assertions_for_plan"):
            return self._application_sql_assertions_for_plan_inner(
                plan,
                schema_ddl_plan,
                metadata_publication_plan,
            )

    @pure_lazy
    def _application_sql_assertions_for_plan_inner(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
        schema_ddl_plan: BootstrapSchemaDdlPlan,
        metadata_publication_plan: BootstrapMetadataPublicationPlan,
    ) -> tuple[BootstrapSqlAssertion, ...]:
        from l1400_types.type_surface_contracts import BootstrapFactsHash
        from l3200_metadata.bootstrap_assertions import (
            BootstrapAssertionKind,
            BootstrapAssertionSeverity,
            BootstrapManifestAssertion,
            BootstrapProofBatchAssertion,
            BootstrapSchemaGenerationAssertion,
            BootstrapSeedBatchAssertion,
            BootstrapSqlAssertion,
        )
        from l3200_metadata.bootstrap_metadata_plan import BootstrapMetadataRowKind
        from l3200_metadata.bootstrap_state import BootstrapPlanningError
        from l3200_metadata.bootstrap_state_shapes import is_versioned_object_model
        from l1000_schema.table_utils import get_table_name

        assertions: list[BootstrapSqlAssertion] = []
        physical_contract = plan.physical_contract
        versioned_object_base_tables = frozenset(
            get_table_name(model_cls) for model_cls in plan.model_classes if is_versioned_object_model(model_cls)
        )
        table_source_refs = {
            str(table_name): family_fact.source_ref
            for family_fact in schema_ddl_plan.table_family_facts
            for table_name in family_fact.family_tables
        }
        column_fact_keys = {(str(column_fact.table_name), str(column_fact.column_name)) for column_fact in schema_ddl_plan.column_facts}
        index_fact_keys = {(str(index_fact.table_name), str(index_fact.index_name)) for index_fact in schema_ddl_plan.index_facts}
        physical_tables = getattr(physical_contract, "tables", None)
        if physical_tables is None:
            physical_tables = tuple(
                SimpleNamespace(
                    table_name=table_name,
                    required_columns=physical_contract.required_columns_by_table.get(table_name, ()),
                    required_indexes=physical_contract.required_indexes_by_table.get(table_name, ()),
                )
                for table_name in physical_contract.table_names
            )
        for table_contract in physical_tables:
            if table_contract.table_name in versioned_object_base_tables:
                continue
            source_ref = table_source_refs.get(table_contract.table_name)
            if source_ref is None:
                # Fresh deterministic DDL proof is inferred from produced facts,
                # so every required physical table must have an owning fact.
                msg = f"bootstrap table assertion missing planned source ref for {table_contract.table_name!r}"
                raise BootstrapPlanningError(msg)
            for column_name in table_contract.required_columns:
                if (table_contract.table_name, str(column_name)) not in column_fact_keys:
                    msg = f"bootstrap column fact missing planned source ref for {table_contract.table_name!r}.{column_name!r}"
                    raise BootstrapPlanningError(msg)
            for index_name in table_contract.required_indexes:
                if (table_contract.table_name, str(index_name)) not in index_fact_keys:
                    owners = tuple(
                        (
                            f"{work_product.model_cls.__module__}.{work_product.model_cls.__qualname__}",
                            candidate.required_indexes,
                        )
                        for work_product in plan.physical_contract_work_products
                        for candidate in work_product.contract.tables
                        if candidate.table_name == table_contract.table_name
                    )
                    planned_for_table = tuple(
                        sorted(
                            candidate_index
                            for candidate_table, candidate_index in index_fact_keys
                            if candidate_table == table_contract.table_name
                        ),
                    )
                    msg = (
                        "bootstrap index fact missing planned source ref for "
                        f"{table_contract.table_name!r}.{index_name!r}; "
                        f"planned={planned_for_table!r}; owners={owners!r}"
                    )
                    raise BootstrapPlanningError(msg)

        row_groups_by_kind = {
            row_group.rows[0].row_kind: row_group for row_group in metadata_publication_plan.row_groups if row_group.rows
        }
        schema_state_group = row_groups_by_kind.get(BootstrapMetadataRowKind.SCHEMA_STATE)
        if schema_state_group is not None:
            assertions.append(
                BootstrapSqlAssertion(
                    kind=BootstrapAssertionKind.SCHEMA_GENERATION_MATCHES,
                    severity=BootstrapAssertionSeverity.HARD_FAILURE,
                    payload=BootstrapSchemaGenerationAssertion(
                        schema_hash=SchemaFingerprintHash(plan.schema_hash_v2),
                        source_ref=schema_state_group.produced_ref,
                    ),
                ),
            )
        manifest_group = row_groups_by_kind.get(BootstrapMetadataRowKind.BOOTSTRAP_MANIFEST)
        if manifest_group is not None:
            for manifest_fact in metadata_publication_plan.manifest_facts:
                assertions.append(
                    BootstrapSqlAssertion(
                        kind=BootstrapAssertionKind.MANIFEST_WRITTEN,
                        severity=BootstrapAssertionSeverity.HARD_FAILURE,
                        payload=BootstrapManifestAssertion(
                            manifest_key=manifest_fact.manifest_key,
                            plan_hash=manifest_fact.plan_hash,
                            manifest_hash=manifest_fact.manifest_hash,
                            source_ref=manifest_group.produced_ref,
                        ),
                    ),
                )
        proof_group = row_groups_by_kind.get(BootstrapMetadataRowKind.PROOF_SCOPE)
        if proof_group is not None and metadata_publication_plan.proof_facts:
            assertions.append(
                BootstrapSqlAssertion(
                    kind=BootstrapAssertionKind.PROOF_FACTS_WRITTEN,
                    severity=BootstrapAssertionSeverity.HARD_FAILURE,
                    payload=BootstrapProofBatchAssertion(
                        proof_hashes=tuple(proof_fact.proof_hash for proof_fact in metadata_publication_plan.proof_facts),
                        source_ref=proof_group.produced_ref,
                    ),
                ),
            )
        seed_group = row_groups_by_kind.get(BootstrapMetadataRowKind.SEED_FACT)
        if seed_group is not None:
            from l3200_metadata.bootstrap_manifest_builders import _seed_fact_hashes_for_engine_plan

            seed_hashes = tuple(BootstrapFactsHash(seed_hash) for seed_hash in _seed_fact_hashes_for_engine_plan(plan).values())
            if seed_hashes:
                assertions.append(
                    BootstrapSqlAssertion(
                        kind=BootstrapAssertionKind.SEED_FACTS_WRITTEN,
                        severity=BootstrapAssertionSeverity.HARD_FAILURE,
                        payload=BootstrapSeedBatchAssertion(
                            seed_hashes=seed_hashes,
                            source_ref=seed_group.produced_ref,
                        ),
                    ),
                )
        return tuple(assertions)

    @pure_lazy
    def _schema_ddl_plan_for_plan(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> BootstrapSchemaDdlPlan:
        from hashlib import sha256

        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlIndexName, SqlTableName
        from l1400_types.type_surface_contracts import (
            SchemaDdlOperationName,
            SchemaDdlPhase,
            SchemaFingerprintHash,
        )
        from l1000_schema.table_utils import get_table_name
        from l3200_metadata.bootstrap_state import BootstrapPlanningError
        from l3200_metadata.bootstrap_state_shapes import is_versioned_object_model
        from l3200_metadata.bootstrap_schema_plan import (
            BootstrapSchemaColumnFact,
            BootstrapSchemaDdlKind,
            BootstrapSchemaDdlOperation,
            BootstrapSchemaDdlPlan,
            BootstrapSchemaIndexFact,
            BootstrapSchemaTableFamilyFact,
        )

        with _bootstrap_profile_span("schema_bootstrap.schema_ddl_plan_for_plan"):
            operations: list[BootstrapSchemaDdlOperation] = []
            table_facts: list[BootstrapSchemaTableFamilyFact] = []
            column_facts: list[BootstrapSchemaColumnFact] = []
            index_facts: list[BootstrapSchemaIndexFact] = []
            # ``build_engine_plan`` closes payload schema and storage products
            # into ``model_classes`` before it creates physical work products.
            # Reading payload models again here can materialize a second dynamic
            # class that was never part of the closed plan.
            schema_models = plan.model_classes
            from l1000_schema.table_registry import get_table_config

            schema_models = tuple(
                model_cls
                for is_view in (False, True)
                for model_cls in schema_models
                if (get_table_config(model_cls).view is not None) is is_view
            )
            contract_by_model = {work_product.model_cls: work_product.contract for work_product in plan.physical_contract_work_products}
            from l3200_metadata.hashing import (
                compute_declared_physical_contract_fingerprint,
            )

            contracts_by_declaration_fingerprint: dict[
                str,
                list[BootstrapPhysicalSchemaContract],
            ] = {}
            contracts_by_model_path: dict[
                str,
                list[BootstrapPhysicalSchemaContract],
            ] = {}
            for work_product in plan.physical_contract_work_products:
                declaration_fingerprint = compute_declared_physical_contract_fingerprint(
                    work_product.model_cls,
                )
                contracts_by_declaration_fingerprint.setdefault(
                    declaration_fingerprint,
                    [],
                ).append(work_product.contract)
                model_path = f"{work_product.model_cls.__module__}.{work_product.model_cls.__qualname__}"
                contracts_by_model_path.setdefault(model_path, []).append(
                    work_product.contract,
                )
            for index, model_cls in enumerate(schema_models):
                application_model_cls = cast("type[ApplicationObjectRow[Any]]", model_cls)
                contract = contract_by_model.get(application_model_cls)
                if contract is None:
                    declaration_fingerprint = compute_declared_physical_contract_fingerprint(
                        application_model_cls,
                    )
                    candidates = contracts_by_declaration_fingerprint.get(
                        declaration_fingerprint,
                        [],
                    )
                    target_table = str(get_table_name(application_model_cls))
                    target_facts = {table for candidate in candidates for table in candidate.tables if table.table_name == target_table}
                    if not target_facts:
                        model_path = f"{application_model_cls.__module__}.{application_model_cls.__qualname__}"
                        candidates = contracts_by_model_path.get(model_path, [])
                        target_facts = {
                            table for candidate in candidates for table in candidate.tables if table.table_name == target_table
                        }
                    if len(target_facts) > 1:
                        raise BootstrapPlanningError(
                            "closed bootstrap engine plan has conflicting target-table facts "
                            f"for {application_model_cls.__module__}."
                            f"{application_model_cls.__qualname__}",
                        )
                    if target_facts:
                        contract = min(candidates, key=_physical_schema_contract_facts_hash)
                if contract is None:
                    msg = (
                        "closed bootstrap engine plan is missing a physical contract work product for "
                        f"{application_model_cls.__module__}.{application_model_cls.__qualname__}"
                    )
                    raise BootstrapPlanningError(msg)
                with _bootstrap_profile_span("schema_bootstrap.schema_ddl_plan_for_model"):
                    self._append_schema_ddl_plan_for_model(
                        plan,
                        application_model_cls,
                        contract=contract,
                        index=index,
                        operations=operations,
                        table_facts=table_facts,
                        column_facts=column_facts,
                        index_facts=index_facts,
                    )
            return BootstrapSchemaDdlPlan(
                operations=tuple(operations),
                table_family_facts=tuple(table_facts),
                column_facts=tuple(column_facts),
                index_facts=tuple(index_facts),
                dependency_tail_refs=tuple(operation.produced_ref for operation in operations),
            )

    @pure_lazy
    def _append_schema_ddl_plan_for_model(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
        model_cls: type[DatabaseObjectRow[SysId]],
        *,
        contract: BootstrapPhysicalSchemaContract,
        index: int,
        operations: list[Any],
        table_facts: list[Any],
        column_facts: list[Any],
        index_facts: list[Any],
    ) -> None:
        from hashlib import sha256

        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlIndexName, SqlTableName
        from l1400_types.type_surface_contracts import (
            SchemaDdlOperationName,
            SchemaDdlPhase,
            SchemaFingerprintHash,
        )
        from l1000_schema.table_utils import get_table_name
        from l3200_metadata.bootstrap_state_shapes import is_versioned_object_model
        from l3200_metadata.bootstrap_schema_plan import (
            BootstrapSchemaColumnFact,
            BootstrapSchemaDdlKind,
            BootstrapSchemaDdlOperation,
            BootstrapSchemaIndexFact,
            BootstrapSchemaTableFamilyFact,
        )

        table_name = get_table_name(model_cls)
        produced_ref = ServerPlanRefId(
            f"out_{int(sha256(f'{plan.manifest_key}:{plan.plan_hash}:table:{index}'.encode()).hexdigest()[:15], 16)}",
        )
        for table_contract in contract.tables:
            source_ref = (
                produced_ref
                if table_contract.table_name == table_name
                else ServerPlanRefId(
                    f"{produced_ref}:{table_contract.table_name}",
                )
            )
            column_facts.extend(
                BootstrapSchemaColumnFact(
                    table_name=SqlTableName(table_contract.table_name),
                    column_name=SqlColumnName(column_name),
                    source_ref=source_ref,
                )
                for column_name in table_contract.required_columns
            )
            index_facts.extend(
                BootstrapSchemaIndexFact(
                    table_name=SqlTableName(table_contract.table_name),
                    index_name=SqlIndexName(index_name),
                    source_ref=source_ref,
                )
                for index_name in table_contract.required_indexes
            )
        if is_versioned_object_model(model_cls):
            family_tables = tuple(SqlTableName(name) for name in contract.table_names)
            if family_tables:
                table_facts.append(
                    BootstrapSchemaTableFamilyFact(
                        primary_table=SqlTableName(table_name),
                        family_tables=family_tables,
                        schema_hash=SchemaFingerprintHash(plan.schema_hash_v2),
                        source_ref=produced_ref,
                    ),
                )
            return
        operations.append(
            BootstrapSchemaDdlOperation(
                kind=BootstrapSchemaDdlKind.CREATE_TABLE,
                operation_name=SchemaDdlOperationName(f"create_table:{table_name}"),
                phase=SchemaDdlPhase("create_table"),
                dependency_refs=(operations[-1].produced_ref,) if operations else (),
                produced_ref=produced_ref,
            ),
        )
        table_facts.append(
            BootstrapSchemaTableFamilyFact(
                primary_table=SqlTableName(table_name),
                family_tables=tuple(SqlTableName(name) for name in contract.table_names),
                schema_hash=SchemaFingerprintHash(plan.schema_hash_v2),
                source_ref=produced_ref,
            ),
        )

    @pure_lazy
    def _data_primitive_plan_for_plan(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
        execute_data_primitives: bool,
    ) -> BootstrapDataPrimitivePlan:
        from dataclasses import replace
        from hashlib import sha256

        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from l1300_session.session import SystemSession
        from l1400_types.type_surface_contracts import BootstrapFactsHash, PythonClassPath
        from l1000_schema.table_utils import get_table_name
        from l7000_versioned_schema.versioned_schema import VersionedObjectRow
        from l3200_metadata.bootstrap_data_plan import (
            BootstrapDataMutationContract,
            BootstrapDesiredPrimitiveDeclaration,
            BootstrapDataPrimitiveIdentity,
            BootstrapDataPrimitiveKind,
            BootstrapDataPrimitivePlan,
            BootstrapFtsIndexPrimitivePayload,
            BootstrapLoggedTablePrimitivePayload,
            BootstrapRowPrimitivePayload,
            BootstrapScopePrimitivePayload,
            BootstrapSchemaPrimitiveContract,
            BootstrapTableFamilyPrimitivePayload,
            BootstrapTableEventTriggerPrimitivePayload,
            BootstrapVersionedTableFamilyPrimitivePayload,
            BootstrapVersioningMutationContract,
            BootstrapVersionedRowsPrimitivePayload,
            BootstrapVersioningDomainPrimitivePayload,
            BootstrapVersioningDomainSchemaPrimitivePayload,
        )

        explicitly_schema_owned_models = frozenset(
            model_cls
            for declaration in plan.desired_primitives
            for model_cls in getattr(getattr(declaration, "payload", None), "schema_models", ())
            if isinstance(model_cls, type)
        )
        explicitly_owned_tables = frozenset(
            str(declaration.target_table)
            for declaration in plan.desired_primitives
            if declaration.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_TABLE and declaration.target_table is not None
        )
        from l1000_schema.table_registry import get_table_config

        ordered_model_classes = tuple(
            model_cls
            for is_view in (False, True)
            for model_cls in plan.model_classes
            if (get_table_config(model_cls).view is not None) is is_view
        )
        table_declaration_items: list[BootstrapDesiredPrimitiveDeclaration] = []
        for index, model_cls in enumerate(ordered_model_classes):
            if issubclass(model_cls, VersionedObjectRow):
                continue
            if model_cls.__dict__.get("__nera_runtime_auxiliary_model__") is True:
                continue
            if model_cls in explicitly_schema_owned_models:
                continue
            table_name = get_table_name(model_cls)
            if table_name in explicitly_owned_tables:
                continue
            fact_hash = BootstrapFactsHash(
                sha256(
                    f"{plan.manifest_key}|{plan.plan_hash}|table|{table_name}".encode(),
                ).hexdigest(),
            )
            table_declaration_items.append(
                BootstrapDesiredPrimitiveDeclaration(
                    identity=BootstrapDataPrimitiveIdentity(
                        primitive_kind=BootstrapDataPrimitiveKind.ENSURE_TABLE,
                        model_path=PythonClassPath(f"{model_cls.__module__}.{model_cls.__qualname__}"),
                        fact_hash=fact_hash,
                    ),
                    target_table=SqlTableName(table_name),
                    lowered_ref=_legal_bootstrap_out_ref(
                        plan.manifest_key,
                        plan.plan_hash,
                        "data",
                        "table",
                        index,
                    ),
                    payload=BootstrapTableFamilyPrimitivePayload(
                        model_cls=model_cls,
                        family_models=(model_cls,),
                        family_tables=(SqlTableName(table_name),),
                        # See docs/design/data_history/ci_trueup_architecture_survey_2026_08_05/
                        # failure-ownership-and-tdd-ladders.rst: physical FK parents are
                        # closed planning dependencies, not backend error-retry hints.
                        foreign_key_tables=extract_bootstrap_foreign_key_tables(model_cls),
                        fingerprint=f"{model_cls.__module__}.{model_cls.__qualname__}",
                    ),
                ),
            )
        table_declarations = tuple(table_declaration_items)
        desired_by_identity = {
            declaration.identity: declaration
            for declaration in (
                *table_declarations,
                *cast("tuple[BootstrapDesiredPrimitiveDeclaration, ...]", plan.desired_primitives),
            )
        }
        desired_primitives = tuple(desired_by_identity.values())
        if not execute_data_primitives:
            return BootstrapDataPrimitivePlan(desired_primitives=desired_primitives)
        schema_primitive_kinds = frozenset(
            {
                BootstrapDataPrimitiveKind.ENSURE_TABLE,
                BootstrapDataPrimitiveKind.ENSURE_METADATA_SCHEMA,
                BootstrapDataPrimitiveKind.ENSURE_VERSIONED_TABLE_FAMILY,
                BootstrapDataPrimitiveKind.ENSURE_VERSIONING_DOMAIN_SCHEMA,
                BootstrapDataPrimitiveKind.ENSURE_QUEUE,
                BootstrapDataPrimitiveKind.ENSURE_FTS_INDEX,
                BootstrapDataPrimitiveKind.ENSURE_VECTOR_INDEX,
                BootstrapDataPrimitiveKind.ENSURE_LOGGED_TABLE,
                BootstrapDataPrimitiveKind.ENSURE_LOG_TABLE,
                BootstrapDataPrimitiveKind.ENSURE_TABLE_EVENT_TRIGGER,
                BootstrapDataPrimitiveKind.ENSURE_COMMIT_TRIGGERS,
                BootstrapDataPrimitiveKind.ENSURE_LARGE_COLUMN_METADATA_SCHEMA,
                BootstrapDataPrimitiveKind.ENSURE_BACKEND_SCHEMA,
                BootstrapDataPrimitiveKind.ENSURE_CONTENT_ADDRESSABLE_EMBEDDING_SCHEMA,
                BootstrapDataPrimitiveKind.ENSURE_DYNAMIC_SEARCH_SCHEMA,
                BootstrapDataPrimitiveKind.ENSURE_CONSTRAINT_METADATA,
                BootstrapDataPrimitiveKind.ENSURE_GRAPH_CONFIG_METADATA,
                BootstrapDataPrimitiveKind.ENSURE_POLYMORPHIC_REGISTRY_METADATA,
                BootstrapDataPrimitiveKind.ENSURE_STAGED_TABLE_TRIGGERS,
                BootstrapDataPrimitiveKind.ENSURE_LOG_IMMUTABILITY_TRIGGERS,
                BootstrapDataPrimitiveKind.ENSURE_RETROACTIVE_VERSIONED_FK_TRIGGERS,
                BootstrapDataPrimitiveKind.ENSURE_FTS_CONFIG_METADATA,
                BootstrapDataPrimitiveKind.ENSURE_VECTOR_CONFIG_METADATA,
                BootstrapDataPrimitiveKind.ENSURE_RIPPLE_TRIGGERS,
                BootstrapDataPrimitiveKind.ENSURE_GRAPH_PHYSICAL_KEYS,
                BootstrapDataPrimitiveKind.ENSURE_VERSION_PHYSICAL_KEYS,
            },
        )
        versioned_table_family_refs = tuple(
            declaration.lowered_ref
            for declaration in desired_primitives
            if declaration.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_VERSIONED_TABLE_FAMILY
            and declaration.lowered_ref is not None
        )
        versioned_trigger_kinds = frozenset(
            {
                BootstrapDataPrimitiveKind.ENSURE_STAGED_TABLE_TRIGGERS,
                BootstrapDataPrimitiveKind.ENSURE_LOG_IMMUTABILITY_TRIGGERS,
                BootstrapDataPrimitiveKind.ENSURE_RETROACTIVE_VERSIONED_FK_TRIGGERS,
            },
        )

        schema_refs_by_table: dict[SqlTableName, list[ServerPlanRefId]] = {}
        for declaration in desired_primitives:
            if declaration.lowered_ref is None:
                continue
            payload = declaration.payload
            if isinstance(payload, BootstrapTableFamilyPrimitivePayload | BootstrapVersionedTableFamilyPrimitivePayload):
                for table_name in payload.family_tables:
                    schema_refs_by_table.setdefault(table_name, []).append(declaration.lowered_ref)
            elif isinstance(payload, BootstrapLoggedTablePrimitivePayload):
                for table_name in payload.table_names:
                    schema_refs_by_table.setdefault(table_name, []).append(declaration.lowered_ref)

        def _schema_dependency_refs_for(declaration: BootstrapDesiredPrimitiveDeclaration) -> tuple[ServerPlanRefId, ...]:
            if declaration.identity.primitive_kind in versioned_trigger_kinds:
                return versioned_table_family_refs
            payload = declaration.payload
            if isinstance(payload, BootstrapTableEventTriggerPrimitivePayload):
                return tuple(schema_refs_by_table.get(payload.table_name, ()))
            if isinstance(payload, BootstrapTableFamilyPrimitivePayload):
                table_config = get_table_config(payload.model_cls)
                view = table_config.view
                view_dependency_tables = (
                    (
                        get_table_name(view.base_model),
                        *(get_table_name(join.model) for join in view.joins),
                    )
                    if view is not None
                    else ()
                )
                dependency_tables = (*payload.foreign_key_tables, *view_dependency_tables)
                return tuple(
                    dict.fromkeys(
                        ref for table_name in dependency_tables for ref in schema_refs_by_table.get(SqlTableName(table_name), ())
                    ),
                )
            return ()

        schema_mutations = tuple(
            BootstrapSchemaPrimitiveContract(
                identity=declaration.identity,
                target_table=declaration.target_table,
                dependency_refs=_schema_dependency_refs_for(declaration),
                produced_ref=declaration.lowered_ref,
                payload=declaration.payload,
            )
            for declaration in desired_primitives
            if declaration.identity.primitive_kind in schema_primitive_kinds and declaration.lowered_ref is not None
        )
        row_refs_by_table: dict[SqlTableName, list[ServerPlanRefId]] = {}
        for declaration in desired_primitives:
            if (
                declaration.identity.primitive_kind
                in (BootstrapDataPrimitiveKind.ENSURE_ROW, BootstrapDataPrimitiveKind.ENSURE_IMMUTABLE_ROW)
                and declaration.target_table is not None
                and declaration.lowered_ref is not None
                and isinstance(declaration.payload, BootstrapRowPrimitivePayload | BootstrapImmutableRowPrimitivePayload)
            ):
                row_refs_by_table.setdefault(declaration.target_table, []).append(declaration.lowered_ref)
        row_dependency_refs_by_table = {table_name: tuple(dict.fromkeys(refs)) for table_name, refs in row_refs_by_table.items()}
        immutable_by_table: dict[SqlTableName, list[BootstrapDesiredPrimitiveDeclaration]] = {}
        for declaration in desired_primitives:
            if isinstance(declaration.payload, BootstrapImmutableRowPrimitivePayload) and declaration.target_table is not None:
                immutable_by_table.setdefault(declaration.target_table, []).append(declaration)

        guarded_rows: dict[ServerPlanRefId, BootstrapImmutableRowPrimitivePayload] = {}

        def guarded_payload(
            declaration: BootstrapDesiredPrimitiveDeclaration,
            visiting: frozenset[ServerPlanRefId] = frozenset(),
        ) -> BootstrapImmutableRowPrimitivePayload | BootstrapRowPrimitivePayload:
            payload = declaration.payload
            assert isinstance(payload, BootstrapImmutableRowPrimitivePayload | BootstrapRowPrimitivePayload)
            if not isinstance(payload, BootstrapImmutableRowPrimitivePayload):
                return payload
            ref = declaration.lowered_ref
            assert ref is not None
            if ref in visiting:
                raise ValueError("Immutable bootstrap row dependencies contain a cycle")
            cached = guarded_rows.get(ref)
            if cached is not None:
                return cached
            requirements = list(payload.required_rows)
            for table in payload.depends_on_tables:
                for parent in immutable_by_table.get(table, ()):
                    parent_payload = guarded_payload(parent, visiting | {ref})
                    assert isinstance(parent_payload, BootstrapImmutableRowPrimitivePayload)
                    parent_ref = parent.lowered_ref
                    assert parent_ref is not None
                    requirements.append(parent_payload.content_assertion(parent_ref))
            guarded = replace(payload, required_rows=tuple(requirements))
            guarded_rows[ref] = guarded
            return guarded

        row_mutations = tuple(
            BootstrapDataMutationContract(
                identity=declaration.identity,
                target_table=declaration.target_table or SqlTableName("bootstrap_unknown_rows"),
                key_columns=tuple(SqlColumnName(field_name) for field_name in declaration.payload.key_fields),
                dependency_refs=tuple(
                    ref
                    for table_name in declaration.payload.depends_on_tables
                    for ref in row_dependency_refs_by_table.get(table_name, ())
                ),
                produced_ref=declaration.lowered_ref,
                payload=guarded_payload(declaration),
            )
            for declaration in desired_primitives
            if declaration.identity.primitive_kind
            in (BootstrapDataPrimitiveKind.ENSURE_ROW, BootstrapDataPrimitiveKind.ENSURE_IMMUTABLE_ROW)
            and declaration.lowered_ref is not None
            and isinstance(declaration.payload, BootstrapRowPrimitivePayload | BootstrapImmutableRowPrimitivePayload)
        )
        domain_schema_refs = {
            declaration.payload.domain_contract.domain: declaration.lowered_ref
            for declaration in desired_primitives
            if declaration.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_VERSIONING_DOMAIN_SCHEMA
            and declaration.lowered_ref is not None
            and isinstance(declaration.payload, BootstrapVersioningDomainSchemaPrimitivePayload)
        }
        versioned_family_refs = {
            declaration.payload.model_cls: declaration.lowered_ref
            for declaration in desired_primitives
            if declaration.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_VERSIONED_TABLE_FAMILY
            and declaration.lowered_ref is not None
            and isinstance(declaration.payload, BootstrapVersionedTableFamilyPrimitivePayload)
        }
        fts_index_refs = {
            declaration.payload.model_cls: declaration.lowered_ref
            for declaration in desired_primitives
            if declaration.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_FTS_INDEX
            and declaration.lowered_ref is not None
            and isinstance(declaration.payload, BootstrapFtsIndexPrimitivePayload)
        }
        scope_mutations = tuple(
            BootstrapDataMutationContract(
                identity=declaration.identity,
                target_table=SqlTableName("sys_bootstrap_proof_scopes"),
                key_columns=(SqlColumnName("manifest_key"), SqlColumnName("scope_key")),
                dependency_refs=(),
                produced_ref=declaration.lowered_ref,
                payload=replace(
                    declaration.payload,
                    manifest_key=str(plan.manifest_key),
                    plan_hash=str(plan.plan_hash),
                    primitive_hash=str(declaration.identity.fact_hash),
                ),
            )
            for declaration in desired_primitives
            if declaration.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_BOOTSTRAP_SCOPE
            and declaration.lowered_ref is not None
            and isinstance(declaration.payload, BootstrapScopePrimitivePayload)
        )
        versioning_mutations = tuple(
            BootstrapVersioningMutationContract(
                identity=declaration.identity,
                domain_table=get_table_name(_versioning_mutation_revision_model(declaration.payload)),
                auxiliary_tables=(),
                dependency_refs=tuple(
                    dict.fromkeys(
                        (
                            *_versioning_mutation_schema_dependency_refs(
                                declaration.payload,
                                domain_schema_refs=domain_schema_refs,
                                versioned_family_refs=versioned_family_refs,
                                fts_index_refs=fts_index_refs,
                            ),
                            *(
                                ref
                                for table_name in getattr(declaration.payload, "depends_on_tables", ())
                                for ref in row_dependency_refs_by_table.get(table_name, ())
                            ),
                        ),
                    ),
                ),
                produced_ref=declaration.lowered_ref,
                payload=declaration.payload,
            )
            for declaration in desired_primitives
            if declaration.identity.primitive_kind
            in {
                BootstrapDataPrimitiveKind.ENSURE_VERSIONING_DOMAIN,
                BootstrapDataPrimitiveKind.ENSURE_VERSIONED_ROW,
            }
            and declaration.lowered_ref is not None
            and isinstance(
                declaration.payload,
                BootstrapVersioningDomainPrimitivePayload | BootstrapVersionedRowsPrimitivePayload,
            )
        )
        if not plan.owns_core_schema:
            return BootstrapDataPrimitivePlan(
                desired_primitives=desired_primitives,
                schema_mutations=schema_mutations,
                data_mutations=(*row_mutations, *scope_mutations),
                versioning_mutations=versioning_mutations,
                assertion_refs=(),
            )
        system_session_hash = sha256(
            f"{plan.manifest_key}|{plan.plan_hash}|system-session|system".encode(),
        ).hexdigest()
        produced_ref = _legal_bootstrap_out_ref(
            plan.manifest_key,
            plan.plan_hash,
            "data",
            "system_session",
        )
        system_session_schema_ref = ServerPlanRefId(
            f"out_{int(sha256(f'{plan.manifest_key}:{plan.plan_hash}:system_session_schema'.encode()).hexdigest()[:15], 16)}",
        )
        system_session_model_path = PythonClassPath(f"{SystemSession.__module__}.{SystemSession.__qualname__}")
        system_session_schema_identity = BootstrapDataPrimitiveIdentity(
            primitive_kind=BootstrapDataPrimitiveKind.ENSURE_TABLE,
            model_path=system_session_model_path,
            fact_hash=BootstrapFactsHash(
                sha256(
                    f"{plan.manifest_key}|{plan.plan_hash}|table|sys_sessions|system-session".encode(),
                ).hexdigest(),
            ),
        )
        system_session_identity = BootstrapDataPrimitiveIdentity(
            primitive_kind=BootstrapDataPrimitiveKind.ENSURE_SYSTEM_SESSION,
            model_path=system_session_model_path,
            fact_hash=BootstrapFactsHash(system_session_hash),
        )
        return BootstrapDataPrimitivePlan(
            desired_primitives=(
                *desired_primitives,
                BootstrapDesiredPrimitiveDeclaration(
                    identity=system_session_schema_identity,
                    target_table=SqlTableName("sys_sessions"),
                    lowered_ref=system_session_schema_ref,
                    payload=BootstrapTableFamilyPrimitivePayload(
                        model_cls=SystemSession,
                        family_models=(SystemSession,),
                        family_tables=(SqlTableName("sys_sessions"),),
                        fingerprint=f"{SystemSession.__module__}.{SystemSession.__qualname__}",
                    ),
                ),
                BootstrapDesiredPrimitiveDeclaration(
                    identity=system_session_identity,
                    target_table=SqlTableName("sys_sessions"),
                    lowered_ref=produced_ref,
                ),
            ),
            schema_mutations=(
                *schema_mutations,
                BootstrapSchemaPrimitiveContract(
                    identity=system_session_schema_identity,
                    target_table=SqlTableName("sys_sessions"),
                    dependency_refs=(),
                    produced_ref=system_session_schema_ref,
                    payload=BootstrapTableFamilyPrimitivePayload(
                        model_cls=SystemSession,
                        family_models=(SystemSession,),
                        family_tables=(SqlTableName("sys_sessions"),),
                        fingerprint=f"{SystemSession.__module__}.{SystemSession.__qualname__}",
                    ),
                ),
            ),
            data_mutations=(
                BootstrapDataMutationContract(
                    identity=system_session_identity,
                    target_table=SqlTableName("sys_sessions"),
                    key_columns=(SqlColumnName("sys_id"),),
                    dependency_refs=(system_session_schema_ref,),
                    produced_ref=produced_ref,
                ),
                *row_mutations,
                *scope_mutations,
            ),
            versioning_mutations=versioning_mutations,
            assertion_refs=(produced_ref,),
        )

    @pure_lazy
    def _metadata_publication_plan_for_plan(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> BootstrapMetadataPublicationPlan:
        from l3200_metadata.bootstrap_manifest_builders import (
            build_bootstrap_additive_metadata_publication_plan,
            build_bootstrap_metadata_publication_plan,
        )

        if not plan.owns_core_schema:
            return build_bootstrap_additive_metadata_publication_plan(plan)
        return build_bootstrap_metadata_publication_plan(plan)

    @pure_lazy
    def _metadata_publication_rows_for_plan(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
        schema_ddl_plan: BootstrapSchemaDdlPlan,
        model_classes: tuple[type[DatabaseObjectRow[SysId]], ...],
    ) -> BootstrapMetadataPublicationRows:
        from l3200_metadata.bootstrap_manifest_builders import (
            build_bootstrap_metadata_publication_rows,
            plan_bootstrap_schema_generation,
        )

        planned_generation = plan_bootstrap_schema_generation(
            observation,
            plan,
            schema_ddl_plan,
        )
        return build_bootstrap_metadata_publication_rows(
            plan,
            schema_generation=planned_generation.schema_generation,
            schema_version=planned_generation.schema_version,
            model_classes=cast("tuple[type[object], ...]", model_classes),
            observed_types=observation.polymorphic_type_facts,
        )

    @pure_lazy
    def _persisted_schema_authority_matches(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
        manifest_schema_generation: int,
    ) -> bool:
        """Verify that the manifest and singleton schema state describe one commit."""
        from l3200_metadata.bootstrap_manifest_builders import (
            BOOTSTRAP_PHYSICAL_SURFACE_VERSION,
            bootstrap_physical_surface_hash,
        )

        del self
        if len(observation.schema_state_facts) != 1:
            return False
        schema_state = observation.schema_state_facts[0]
        coherent_global_state = (
            schema_state.schema_generation == manifest_schema_generation
            and schema_state.authority_schema_version == schema_state.schema_version
            and schema_state.authority_schema_hash == str(schema_state.schema_hash)
            and schema_state.authority_schema_hash_v2 == str(schema_state.schema_hash)
            and schema_state.cache_generation is not None
            and schema_state.cache_generation >= schema_state.schema_generation
        )
        if not coherent_global_state:
            return False
        if str(schema_state.schema_hash) != str(plan.schema_hash_v2):
            return True
        return (
            schema_state.contract_fingerprint == str(plan.contract_fingerprint)
            and schema_state.physical_surface_hash == bootstrap_physical_surface_hash(plan)
            and schema_state.physical_surface_version == BOOTSTRAP_PHYSICAL_SURFACE_VERSION
        )

    @pure_lazy
    def manifest_fast_path_rejection_details(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> BootstrapValidationDetail:
        """Explain why persisted authority does not match an engine plan."""
        return self._manifest_fast_path_rejection_details(observation, plan)

    @pure_lazy
    def manifest_fast_path_rejection_details_after_authority_validation(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> BootstrapValidationDetail:
        """Explain non-authority fast-path rejection after exact authority validation."""
        return self._manifest_fast_path_rejection_details(
            observation,
            plan,
            proof_and_seed_authority_prevalidated=True,
        )

    @pure_lazy
    def _manifest_fast_path_rejection_details(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
        *,
        proof_and_seed_authority_prevalidated: bool = False,
    ) -> BootstrapValidationDetail:
        from l3200_metadata.bootstrap_manifest_builders import (
            bootstrap_manifest_payload_json,
        )

        matching_manifest_keys = tuple(fact for fact in observation.manifest_facts if str(fact.manifest_key) == str(plan.manifest_key))
        if len(matching_manifest_keys) != 1:
            return BootstrapValidationDetail(f"matching_manifest_count={len(matching_manifest_keys)}")
        manifest = matching_manifest_keys[0]
        contract_mismatches: list[str] = []
        if str(manifest.plan_hash) != str(plan.plan_hash):
            contract_mismatches.append("plan_hash")
        if str(manifest.schema_hash) != str(plan.schema_hash_v2):
            contract_mismatches.append("schema_hash_v2")
        if str(manifest.manifest_payload) != bootstrap_manifest_payload_json(plan):
            contract_mismatches.append("payload_json")
        if contract_mismatches:
            return BootstrapValidationDetail(f"manifest_contract_mismatch fields={tuple(contract_mismatches)!r}")
        if not self._persisted_schema_authority_matches(
            observation,
            plan,
            manifest.schema_generation,
        ):
            return BootstrapValidationDetail("persisted_schema_authority_mismatch")
        if not self._physical_contract_observed(observation, plan):
            observed_artifacts = {
                (
                    fact.artifact_kind,
                    str(fact.table_name) if fact.table_name is not None else None,
                    fact.artifact_name,
                )
                for fact in observation.named_artifact_facts
            }
            physical_contract = plan.physical_contract
            observed_tables = {fact.table_name for fact in observation.table_facts}
            observed_columns = {(fact.table_name, fact.column_name) for fact in observation.column_facts}
            observed_indexes = {(str(fact.table_name), str(fact.index_name)) for fact in observation.index_facts}
            missing_tables = sorted(set(physical_contract.table_names) - observed_tables)
            missing_columns = sorted(_ordinary_required_column_facts(physical_contract) - observed_columns)
            required_indexes = {
                (str(table_name), str(index_name))
                for table_name, index_names in physical_contract.required_indexes_by_table.items()
                for index_name in index_names
            }
            missing_indexes = sorted(required_indexes - observed_indexes)
            required_named_artifacts = self._required_named_artifacts(plan)
            comparable_observed_artifacts: set[tuple[str, str, str]] = {
                (artifact_kind, table_name, artifact_name)
                for artifact_kind, table_name, artifact_name in observed_artifacts
                if table_name is not None
            }
            missing_named_artifacts = sorted(required_named_artifacts - comparable_observed_artifacts)
            return BootstrapValidationDetail(
                "physical_contract_mismatch "
                f"missing_tables={missing_tables!r} missing_columns={missing_columns!r} "
                f"missing_indexes={missing_indexes!r} missing_named_artifacts={missing_named_artifacts!r} "
                f"observed_artifacts={sorted(observed_artifacts)!r}"
            )
        if not proof_and_seed_authority_prevalidated and not self._proof_and_seed_authority_matches(observation, plan):
            return BootstrapValidationDetail("proof_or_seed_authority_mismatch")
        return BootstrapValidationDetail("manifest authority did not satisfy an unclassified invariant")

    @pure_lazy
    def manifest_fast_path_available(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> bool:
        """Return whether persisted authority satisfies an engine plan."""
        return self._manifest_fast_path_available(observation, plan)

    @pure_lazy
    def manifest_fast_path_available_after_authority_validation(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> bool:
        """Check the fast path without repeating exact proof and seed validation."""
        return self._manifest_fast_path_available(
            observation,
            plan,
            proof_and_seed_authority_prevalidated=True,
        )

    @pure_lazy
    def _immutable_content_observed(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> bool:
        expected = sorted(
            str(declaration.identity.fact_hash)
            for declaration in plan.desired_primitives
            if isinstance(declaration.payload, BootstrapImmutableRowPrimitivePayload)
        )
        return expected == sorted(str(value) for value in observation.verified_immutable_row_hashes)

    @pure_lazy
    def _manifest_fast_path_available(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
        *,
        proof_and_seed_authority_prevalidated: bool = False,
    ) -> bool:
        if not self._immutable_content_observed(observation, plan):
            return False
        _record_bootstrap_profile_counter(
            "bootstrap_manifest_fast_path_expected_manifest_key",
            str(plan.manifest_key),
        )
        _record_bootstrap_profile_counter(
            "bootstrap_manifest_fast_path_observed_manifest_count",
            str(len(observation.manifest_facts)),
        )
        _record_bootstrap_profile_counter(
            "bootstrap_manifest_fast_path_matching_manifest_key_count",
            str(
                sum(1 for fact in observation.manifest_facts if str(fact.manifest_key) == str(plan.manifest_key)),
            ),
        )
        from l3200_metadata.bootstrap_manifest_builders import (
            bootstrap_manifest_payload_json,
        )

        expected_manifest_payload = bootstrap_manifest_payload_json(plan)
        matching_manifests = tuple(
            fact
            for fact in observation.manifest_facts
            if str(fact.manifest_key) == str(plan.manifest_key)
            and str(fact.plan_hash) == str(plan.plan_hash)
            and str(fact.schema_hash) == str(plan.schema_hash_v2)
            and str(fact.manifest_payload) == expected_manifest_payload
        )
        if len(matching_manifests) != 1:
            _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_miss", "manifest")
            return False
        if not self._persisted_schema_authority_matches(
            observation,
            plan,
            matching_manifests[0].schema_generation,
        ):
            _record_bootstrap_profile_counter(
                "bootstrap_manifest_fast_path_miss",
                "schema_authority",
            )
            return False
        if not self._physical_contract_observed(observation, plan):
            _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_miss", "schema_contract")
            return False

        physical_contract = plan.physical_contract
        with _bootstrap_profile_span("schema_bootstrap.manifest_fast_path.proof_scope"):
            proof_and_seed_authority_matches = proof_and_seed_authority_prevalidated or self._proof_and_seed_authority_matches(
                observation,
                plan,
            )
        if not proof_and_seed_authority_matches:
            _record_bootstrap_profile_counter(
                "bootstrap_manifest_fast_path_miss",
                "proof_or_seed_authority",
            )
            return False
        with _bootstrap_profile_span("schema_bootstrap.manifest_fast_path.physical_sets"):
            observed_tables = {fact.table_name for fact in observation.table_facts}
            observed_columns = {(fact.table_name, fact.column_name) for fact in observation.column_facts}
            observed_indexes = {(str(fact.table_name), str(fact.index_name)) for fact in observation.index_facts}
            required_columns = _ordinary_required_column_facts(physical_contract)
            required_indexes = {
                (str(table_name), str(index_name))
                for table_name, index_names in physical_contract.required_indexes_by_table.items()
                for index_name in index_names
            }
        _record_bootstrap_profile_counter(
            "bootstrap_manifest_fast_path_cardinality", "required_tables", len(physical_contract.table_names)
        )
        _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_cardinality", "observed_tables", len(observed_tables))
        _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_cardinality", "required_columns", len(required_columns))
        _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_cardinality", "observed_columns", len(observed_columns))
        _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_cardinality", "required_indexes", len(required_indexes))
        _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_cardinality", "observed_indexes", len(observed_indexes))
        missing_tables = set(physical_contract.table_names) - observed_tables
        if missing_tables:
            _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_miss", "tables")
            _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_missing_table", str(len(missing_tables)))
            return False
        missing_columns = required_columns - observed_columns
        if missing_columns:
            _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_miss", "columns")
            _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_missing_column", str(len(missing_columns)))
            return False
        missing_indexes = required_indexes - observed_indexes
        if missing_indexes:
            _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_miss", "indexes")
            _record_bootstrap_profile_counter("bootstrap_manifest_fast_path_missing_index", str(len(missing_indexes)))
            return False
        return True

    @pure_lazy
    def _durable_bootstrap_proof_metadata_present(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> bool:
        if not self._immutable_content_observed(observation, plan) or not self._physical_contract_observed(observation, plan):
            return False
        matching_manifest = any(
            str(fact.manifest_key) == str(plan.manifest_key) and str(fact.plan_hash) == str(plan.plan_hash)
            for fact in observation.manifest_facts
        )
        return matching_manifest and self._proof_and_seed_authority_matches(
            observation,
            plan,
        )

    @pure_lazy
    def _fast_path_lifecycle_effects_for_observation(
        self: LazyBootstrapCoordinator,
        observation: BootstrapObservation,
        plan: BootstrapEnginePlan,
    ) -> tuple[BootstrapLifecycleEffect, ...]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
        from l1400_types.type_surface_contracts import BootstrapFactsHash

        proof_hashes = tuple(fact.proof_hash for fact in observation.proof_facts)
        seed_hashes = tuple(fact.seed_hash for fact in observation.seed_facts)
        scope_tables_by_key, scope_facts_by_key = _observed_scope_lifecycle_metadata(observation, plan)
        source_ref = (
            observation.proof_facts[0].source_ref
            if observation.proof_facts
            else _bootstrap_out_ref("bootstrap_fast_path", plan.manifest_key, plan.plan_hash, "proof")
        )
        metadata_source_ref = (
            observation.manifest_facts[0].source_ref
            if observation.manifest_facts
            else _bootstrap_out_ref("bootstrap_fast_path", plan.manifest_key, plan.plan_hash, "metadata")
        )
        proof_hash = proof_hashes[0] if proof_hashes else BootstrapFactsHash(plan.physical_contract.facts_hash())
        return (
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.SEED_CONNECTION_PROOF,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=SeedConnectionProofEffect(
                    proof_hash=proof_hash,
                    source_ref=source_ref,
                    scope_tables_by_key=scope_tables_by_key,
                    existing_tables=tuple(SqlTableName(table_name) for table_name in plan.physical_contract.table_names),
                    seed_fact_hashes={str(index): str(seed_hash) for index, seed_hash in enumerate(seed_hashes)},
                    scope_facts_by_key=scope_facts_by_key,
                    bootstrap_system_session_verified=True,
                ),
            ),
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.MARK_SCHEMA_PROOF_SCOPES_VERIFIED,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=MarkSchemaProofScopesVerifiedEffect(
                    proof_hashes=proof_hashes or (proof_hash,),
                    source_ref=source_ref,
                    scope_tables_by_key=scope_tables_by_key,
                    scope_facts_by_key=scope_facts_by_key,
                ),
            ),
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.MARK_SEED_FACTS_VERIFIED,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=MarkSeedFactsVerifiedEffect(
                    seed_hashes=seed_hashes,
                    source_ref=source_ref,
                    seed_fact_hashes={str(index): str(seed_hash) for index, seed_hash in enumerate(seed_hashes)},
                ),
            ),
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.INVALIDATE_TABLE_EXISTS_CACHE,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=InvalidateTableExistsCacheEffect(
                    table_names=tuple(SqlTableName(table_name) for table_name in plan.physical_contract.table_names),
                    source_ref=source_ref,
                ),
            ),
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.UPDATE_LOCAL_METADATA_CACHES,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=UpdateLocalMetadataCachesEffect(
                    cache_hash=BootstrapFactsHash(plan.contract_fingerprint),
                    source_ref=metadata_source_ref,
                ),
            ),
            *self._ddl_lockdown_lifecycle_effect(plan),
        )

    @pure_lazy
    def _ddl_lockdown_lifecycle_effect(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
    ) -> tuple[BootstrapLifecycleEffect, ...]:
        """Declare post-bootstrap DDL lockdown as a closed lifecycle effect."""
        return (
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.APPLY_DDL_LOCKDOWN,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=ApplyDdlLockdownEffect(
                    policy=BootstrapDdlLockdownPolicy(mode=BootstrapDdlLockdownMode.ENFORCE),
                    source_ref=ServerPlanRefId(f"bootstrap_lifecycle:{plan.manifest_key}:{plan.plan_hash}:ddl_lockdown"),
                ),
            ),
        )

    @pure_lazy
    def _lifecycle_effects_for_plan(
        self: LazyBootstrapCoordinator,
        plan: BootstrapEnginePlan,
        metadata_publication_plan: BootstrapMetadataPublicationPlan,
    ) -> tuple[BootstrapLifecycleEffect, ...]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
        from l1400_types.type_surface_contracts import BootstrapFactsHash

        proof_hashes = tuple(proof_fact.proof_hash for proof_fact in metadata_publication_plan.proof_facts)
        proof_source_ref = (
            metadata_publication_plan.proof_facts[0].source_ref
            if metadata_publication_plan.proof_facts
            else _bootstrap_out_ref("bootstrap_lifecycle", plan.manifest_key, plan.plan_hash, "proof")
        )
        proof_hash = proof_hashes[0] if proof_hashes else BootstrapFactsHash(plan.physical_contract.facts_hash())
        seed_group = next(
            (group for group in metadata_publication_plan.row_groups if group.rows and group.rows[0].row_kind.value == "seed_fact"),
            None,
        )
        seed_hashes = tuple(row.row_hash for row in seed_group.rows) if seed_group is not None else ()
        seed_source_ref = seed_group.produced_ref if seed_group is not None else proof_source_ref
        scope_tables_by_key, scope_facts_by_key = _scope_lifecycle_metadata_for_plan(plan)
        return (
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.SEED_CONNECTION_PROOF,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=SeedConnectionProofEffect(
                    proof_hash=proof_hash,
                    source_ref=proof_source_ref,
                    scope_tables_by_key=scope_tables_by_key,
                    existing_tables=tuple(SqlTableName(table_name) for table_name in plan.physical_contract.table_names),
                    seed_fact_hashes={str(index): str(seed_hash) for index, seed_hash in enumerate(seed_hashes)},
                    scope_facts_by_key=scope_facts_by_key,
                    bootstrap_system_session_verified=True,
                ),
            ),
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.MARK_SCHEMA_PROOF_SCOPES_VERIFIED,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=MarkSchemaProofScopesVerifiedEffect(
                    proof_hashes=proof_hashes or (proof_hash,),
                    source_ref=proof_source_ref,
                    scope_tables_by_key=scope_tables_by_key,
                    scope_facts_by_key=scope_facts_by_key,
                ),
            ),
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.MARK_SEED_FACTS_VERIFIED,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=MarkSeedFactsVerifiedEffect(
                    seed_hashes=seed_hashes,
                    source_ref=seed_source_ref,
                    seed_fact_hashes={str(index): str(seed_hash) for index, seed_hash in enumerate(seed_hashes)},
                ),
            ),
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.INVALIDATE_TABLE_EXISTS_CACHE,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=InvalidateTableExistsCacheEffect(
                    table_names=tuple(SqlTableName(table_name) for table_name in plan.physical_contract.table_names),
                    source_ref=proof_source_ref,
                ),
            ),
            BootstrapLifecycleEffect(
                kind=BootstrapLifecycleEffectKind.UPDATE_LOCAL_METADATA_CACHES,
                requirement=BootstrapLifecycleRequirement.REQUIRED,
                payload=UpdateLocalMetadataCachesEffect(
                    cache_hash=BootstrapFactsHash(plan.contract_fingerprint),
                    source_ref=proof_source_ref,
                ),
            ),
            *self._ddl_lockdown_lifecycle_effect(plan),
        )

    @pure_lazy
    def _fast_path_execution_facts(
        self: LazyBootstrapCoordinator,
        application_plan: BootstrapApplicationPlan,
    ) -> BootstrapExecutionFacts:
        proof_facts: list[BootstrapProofExecutionFact] = []
        seed_hashes: list[object] = []
        source_refs: list[ServerPlanRefId] = []
        for effect in application_plan.lifecycle_effects:
            source_ref = getattr(effect.payload, "source_ref", None)
            if isinstance(source_ref, ServerPlanRefId):
                source_refs.append(source_ref)
            if isinstance(effect.payload, SeedConnectionProofEffect):
                proof_facts.append(
                    BootstrapProofExecutionFact(
                        proof_hash=effect.payload.proof_hash,
                        source_ref=effect.payload.source_ref,
                    ),
                )
            if isinstance(effect.payload, MarkSchemaProofScopesVerifiedEffect):
                proof_facts.extend(
                    BootstrapProofExecutionFact(proof_hash=proof_hash, source_ref=effect.payload.source_ref)
                    for proof_hash in effect.payload.proof_hashes
                )
            if isinstance(effect.payload, MarkSeedFactsVerifiedEffect):
                seed_hashes.extend(effect.payload.seed_hashes)
        return BootstrapExecutionFacts(
            status=BootstrapApplicationStatus.SKIPPED_MANIFEST_FAST_PATH,
            mutation_counts=BootstrapMutationCounts(
                schema_mutations=0,
                metadata_mutations=0,
                seed_mutations=0,
                versioning_mutations=0,
            ),
            proof_facts=tuple(dict.fromkeys(proof_facts)),
            seed_hashes=cast("tuple[Any, ...]", tuple(dict.fromkeys(seed_hashes))),
            source_refs=tuple(dict.fromkeys(source_refs)),
        )

    def _facts_with_lifecycle_source_refs(
        self: LazyBootstrapCoordinator,
        facts: BootstrapExecutionFacts,
        lifecycle_effects: tuple[BootstrapLifecycleEffect, ...],
    ) -> BootstrapExecutionFacts:
        del self
        lifecycle_source_refs = tuple(
            source_ref
            for effect in lifecycle_effects
            if isinstance((source_ref := getattr(effect.payload, "source_ref", None)), ServerPlanRefId)
        )
        if not lifecycle_source_refs:
            return facts
        return replace(
            facts,
            source_refs=tuple(dict.fromkeys((*facts.source_refs, *lifecycle_source_refs))),
        )

    @pure_lazy
    def _enqueue_application_schema_lazy(
        self: LazyBootstrapCoordinator,
        schema_txn: LazySchemaTransaction,
        application_plan: BootstrapApplicationPlan,
        *,
        observation: BootstrapObservation,
        complete_transaction: bool = False,
    ) -> LazyResult[BootstrapExecutionFacts]:
        """Install application work and return the fused terminal tail."""

        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from l1000_schema.column_utils import get_db_column_name
        from l1000_schema.table_utils import get_table_name
        from l3200_metadata.bootstrap_data_plan import (
            BootstrapIdentityRemapKey,
            BootstrapRowMutationWorkProduct,
            BootstrapRowPrimitivePayload,
            BootstrapRuntimeIdentityRef,
            build_bootstrap_seed_lookups,
            remap_bootstrap_row_payload_identities,
        )

        from impl.common.l7100_versioned_operations.fk_field_resolver import iter_model_fks

        seed_mutations = tuple(
            mutation
            for mutation in application_plan.data_primitive_plan.data_mutations
            if isinstance(mutation.payload, BootstrapRowPrimitivePayload)
        )
        build_bootstrap_seed_lookups(seed_mutations)
        from pydantic import BaseModel

        fk_target_models: set[type[object]] = set()
        for mutation in seed_mutations:
            payload = mutation.payload
            assert isinstance(payload, BootstrapRowPrimitivePayload)
            model_cls = payload.model_cls
            if not isinstance(model_cls, type) or not issubclass(model_cls, BaseModel):
                raise TypeError("bootstrap identity planning requires a Pydantic row model")
            fk_target_models.update(
                fk.target_model for fk in iter_model_fks(model_cls, require_enforce=False) if fk.target_column == "sys_id"
            )
        identity_refs: dict[object, object] = {}
        data_mutations: list[Any] = []
        for data_mutation in application_plan.data_primitive_plan.data_mutations:
            payload = data_mutation.payload
            if isinstance(payload, BootstrapRowPrimitivePayload) and identity_refs:
                payload = remap_bootstrap_row_payload_identities(payload, identity_refs)
                data_mutation = replace(data_mutation, payload=payload)
            data_mutations.append(data_mutation)
            if not isinstance(payload, BootstrapRowPrimitivePayload) or payload.key_fields == ("sys_id",):
                continue
            model_cls = payload.model_cls
            if not isinstance(model_cls, type):
                raise TypeError("bootstrap row identity projection requires a model type")
            for source_row in payload.rows:
                row = source_row.row if isinstance(source_row, BootstrapRowMutationWorkProduct) else source_row
                source_identity = getattr(row, "sys_id", None)
                if source_identity is None:
                    continue
                effective_identity = (
                    source_row.value_for("sys_id") if isinstance(source_row, BootstrapRowMutationWorkProduct) else source_identity
                )
                if not isinstance(effective_identity, SysId):
                    raise TypeError("bootstrap identity fallback must be a SysId")
                key_values = tuple(
                    (
                        SqlColumnName(get_db_column_name(model_cls, DynamicFieldName(key_name))),
                        (
                            source_row.value_for(key_name)
                            if isinstance(source_row, BootstrapRowMutationWorkProduct)
                            else getattr(source_row, key_name)
                        ),
                    )
                    for key_name in payload.key_fields
                )
                runtime_identity = BootstrapRuntimeIdentityRef(
                    table_name=SqlTableName(get_table_name(model_cls)),
                    identity_column=SqlColumnName(get_db_column_name(model_cls, DynamicFieldName("sys_id"))),
                    key_values=key_values,
                    fallback=effective_identity,
                )
                for target_model in fk_target_models:
                    if issubclass(model_cls, target_model):
                        identity_refs[
                            BootstrapIdentityRemapKey(
                                target_model=target_model,
                                source_identity=source_identity,
                            )
                        ] = runtime_identity

        application_start_index = 0
        schema_results: list[LazyResult[Any]] = []
        data_results: list[LazyResult[BootstrapDataPrimitivePlan] | LazyResult[None]] = []
        versioning_results: list[LazyResult[BootstrapDataPrimitivePlan]] = []
        transition_replay_results: list[LazyResult[object]] = []
        transition_replay_facts: tuple[Any, ...] = ()
        runtime_assertions = application_plan.assertions

        if application_plan.kind is BootstrapApplicationPlanKind.MANIFEST_ALIAS:
            if application_plan.metadata_publication_rows is None:
                msg = "bootstrap manifest alias plan has no metadata publication rows"
                raise RuntimeError(msg)
            if application_plan.application_tail_ref is None:
                msg = "bootstrap manifest alias plan has no application tail ref"
                raise RuntimeError(msg)
            from l3200_metadata.bootstrap_metadata_plan import BootstrapMetadataRowKind

            publication_kinds = {group.rows[0].row_kind for group in application_plan.metadata_publication_plan.row_groups if group.rows}
            if BootstrapMetadataRowKind.SCHEMA_STATE in publication_kinds:
                metadata_result = schema_txn.publish_bootstrap_metadata_lazy(
                    publication_plan=application_plan.metadata_publication_plan,
                    publication_rows=application_plan.metadata_publication_rows,
                )
            else:
                metadata_result = schema_txn.publish_bootstrap_manifest_alias_lazy(
                    publication_plan=application_plan.metadata_publication_plan,
                    publication_rows=application_plan.metadata_publication_rows,
                )
            from l2055_lazy_result.commit_refs import collect_plan_ref_dependencies

            tail_result = schema_txn.bootstrap_schema_tail_lazy(
