                dependency_refs=metadata_dependency_refs,
            )
        data_mutation_dependency_refs = tuple(collect_plan_ref_dependencies(*data_results))
        versioning_mutation_dependency_refs = tuple(collect_plan_ref_dependencies(*versioning_results))
        assertion_dependency_refs = tuple(collect_plan_ref_dependencies(assertion_results))
        tail_result = schema_txn.bootstrap_schema_tail_lazy(
            produced_ref=UNSET if application_plan.application_tail_ref is None else application_plan.application_tail_ref,
            table_family_facts=application_plan.schema_ddl_plan.table_family_facts,
            column_facts=application_plan.schema_ddl_plan.column_facts,
            index_facts=application_plan.schema_ddl_plan.index_facts,
            transition_replay_facts=cast("Any", transition_replay_facts),
            transition_replay_rejection_facts=application_plan.transition_boundary_plan.rejection_facts,
            data_mutation_dependency_refs=data_mutation_dependency_refs,
            versioning_mutation_dependency_refs=versioning_mutation_dependency_refs,
            assertion_dependency_refs=assertion_dependency_refs,
            metadata_publication_dependency_refs=metadata_dependency_refs,
            metadata_mutation_count=len(data_mutations),
            versioning_mutation_count=len(application_plan.data_primitive_plan.versioning_mutations),
            metadata_publication_present=True,
            seed_mutation_count=len(application_plan.metadata_publication_rows.seed_rows),
        )
        with _bootstrap_profile_span("schema_bootstrap.fuse_application_terminal"):
            self._fuse_bootstrap_application_steps(
                schema_txn,
                start_index=application_start_index,
                application_tail_ref=application_plan.application_tail_ref,
                complete_transaction=complete_transaction,
            )
        return tail_result

    @pure_lazy
    def _fuse_bootstrap_application_steps(
        self: LazyBootstrapCoordinator,
        schema_txn: LazySchemaTransaction,
        *,
        start_index: int,
        application_tail_ref: ServerPlanRefId | None,
        dynamic_tail: bool = False,
        complete_transaction: bool = False,
    ) -> None:
        """Replace application child steps with one bootstrap terminal batch."""

        del self
        if application_tail_ref is None:
            msg = "bootstrap application plan has no application tail ref"
            raise RuntimeError(msg)
        if complete_transaction:
            _enqueue_owned_schema_generation_bumps(schema_txn)
            if _bootstrap_application_uses_native_commit(schema_txn):
                _enqueue_owned_schema_commit(schema_txn)
        schema_txn.freeze_schema_execution_plan()
        plan_builder = schema_txn.schema_plan_builder()
        plan_steps = plan_builder.steps_snapshot()
        child_steps = plan_steps[start_index:]
        if not child_steps:
            msg = "bootstrap application fusion requires at least one child step"
            raise RuntimeError(msg)
        from impl.common.l2070_server_plan.steps.bootstrap_application_terminal import (
            BootstrapApplicationTerminalStep,
            BootstrapTerminalLoweringContext,
            collapse_bootstrap_terminal_static_publications,
            lower_bootstrap_terminal_work_products,
        )

        conn = schema_txn._conn
        backend_profile = schema_txn._backend_profile
        if backend_profile is None:
            msg = "bootstrap terminal lowering requires a backend profile"
            raise RuntimeError(msg)
        flattened_child_steps: list[ServerPlanStep[Any]] = []
        pending_child_steps = list(child_steps)
        while pending_child_steps:
            child_step = pending_child_steps.pop(0)
            if type(child_step) is BootstrapApplicationTerminalStep:
                pending_child_steps[0:0] = list(child_step.children)
            else:
                flattened_child_steps.append(child_step)
        collapsed_child_steps = (
            tuple(flattened_child_steps)
            if dynamic_tail
            else collapse_bootstrap_terminal_static_publications(
                tuple(flattened_child_steps),
                application_tail_ref=application_tail_ref,
            )
        )
        terminal_children = lower_bootstrap_terminal_work_products(
            collapsed_child_steps,
            context=BootstrapTerminalLoweringContext(
                backend_type=conn.backend_type,
                dialect=conn.get_dialect(),
                supports_data_modifying_ctes=backend_profile.traits.supports_data_modifying_ctes,
                backend_profile=backend_profile,
                planning_catalog=schema_txn._planning_catalog,
            ),
        )

        terminal_ref = ServerPlanRefId(plan_builder._next_ref()) if complete_transaction else application_tail_ref
        terminal_step = BootstrapApplicationTerminalStep(
            terminal_ref,
            terminal_children,
            expose_child_results=complete_transaction,
            result_ref=application_tail_ref if dynamic_tail else None,
        )
        _record_bootstrap_profile_counter("round_trip_boundary", "total")
        _record_bootstrap_profile_counter("round_trip_boundary", "bootstrap_application_terminal")
        with _bootstrap_profile_span("schema_bootstrap.terminal_statement_inventory"):
            inventory = terminal_step.statement_inventory()
        _record_bootstrap_profile_counter(
            "bootstrap_application_terminal",
            "logical_statements",
            inventory.total_logical_statements,
        )
        _record_bootstrap_profile_counter(
            "bootstrap_application_terminal",
            "children",
            len(inventory.items),
        )
        _record_bootstrap_profile_counter(
            "bootstrap_application_terminal",
            "physical_children",
            inventory.total_physical_children,
        )
        _record_bootstrap_profile_counter(
            "bootstrap_application_terminal",
            "backend_statements",
            inventory.total_backend_statements,
        )
        _record_bootstrap_profile_counter(
            "bootstrap_application_terminal",
            "script_groups",
            inventory.total_script_groups,
        )
        if _bootstrap_terminal_inventory_details_enabled():
            pending_compile_nodes = list(terminal_step.children)
            while pending_compile_nodes:
                compile_node = pending_compile_nodes.pop()
                _record_bootstrap_profile_counter(
                    "bootstrap_application_terminal_compile_node",
                    type(compile_node).__name__,
                )
                pending_compile_nodes.extend(getattr(compile_node, "children", ()))
            for terminal_child in terminal_step.children:
                if type(terminal_child).__name__ != "PhysicalStatementGroup":
                    continue
                for nested_child in getattr(terminal_child, "children", ()):
                    nested_statement = getattr(nested_child, "_stmt", None)
                    nested_category = getattr(nested_statement, "category", None)
                    nested_category_value = getattr(nested_category, "value", nested_category)
                    nested_phase = getattr(nested_statement, "logical_phase", None)
                    _record_bootstrap_profile_counter(
                        "bootstrap_application_terminal_batched_leaf",
                        (
                            f"{type(nested_child).__name__}:"
                            f"{type(nested_statement).__name__}:"
                            f"{nested_category_value or 'none'}:"
                            f"{nested_phase or 'none'}"
                        ),
                    )
            for item in inventory.items:
                amount = item.logical_statement_count
                _record_bootstrap_profile_counter("bootstrap_application_terminal_step_type", item.step_type, amount)
                _record_bootstrap_profile_counter("bootstrap_application_terminal_kind", item.statement_kind.value, amount)
                _record_bootstrap_profile_counter("bootstrap_application_terminal_sql_family", item.sql_family, amount)
                _record_bootstrap_profile_counter(
                    "bootstrap_application_terminal_backend_statement",
                    item.sql_family,
                    item.backend_statement_count,
                )
                _record_bootstrap_profile_counter(
                    "bootstrap_application_terminal_physical_child",
                    item.sql_family,
                    item.physical_child_count,
                )
                _record_bootstrap_profile_counter("bootstrap_application_terminal_ordering_layer", item.ordering_layer, amount)
                _record_bootstrap_profile_counter(
                    "bootstrap_application_terminal_object_classification",
                    item.object_classification,
                    amount,
                )
                if item.script_group_count:
                    _record_bootstrap_profile_counter(
                        "bootstrap_application_terminal_script_group", item.sql_family, item.script_group_count
                    )
                if item.primitive_kind is not None:
                    _record_bootstrap_profile_counter("bootstrap_application_terminal_primitive_kind", item.primitive_kind, amount)
                if item.source_ref is not None:
                    _record_bootstrap_profile_counter("bootstrap_application_terminal_source_ref", item.source_ref, amount)
                for physical_object in item.physical_objects:
                    _record_bootstrap_profile_counter("bootstrap_application_terminal_physical_object", physical_object)
                for physical_object, owner in item.physical_object_owners:
                    _record_bootstrap_profile_counter(
                        "bootstrap_application_terminal_physical_object_owner",
                        f"{physical_object}:{owner}",
                    )
            for physical_object, owners in inventory.duplicate_physical_object_owners().items():
                _record_bootstrap_profile_counter(
                    "bootstrap_application_terminal_duplicate_physical_object_owner",
                    f"{physical_object}:{'|'.join(owners)}",
                )
        plan_builder.replace_steps((*plan_steps[:start_index], terminal_step))
        frozen_schema_operations = schema_txn._schema_operation_plan.freeze_for_execution()
        schema_txn._schema_operation_plan.transfer_to_terminal(frozen_schema_operations)
        fused_steps = plan_builder.steps_snapshot()
        current_steps = plan_builder.steps_snapshot()
        if current_steps != fused_steps:
            added_steps = tuple((type(step).__name__, str(step.ref_id)) for step in current_steps[len(fused_steps) :])
            msg = f"bootstrap terminal fusion left deferred application steps: {added_steps!r}"
            raise RuntimeError(msg)

    @pure_lazy
    def _install_data_mutation_contract(
        self: LazyBootstrapCoordinator,
        schema_txn: LazySchemaTransaction,
        contract: Any,
        dependency_refs: tuple[ServerPlanRefId, ...],
    ) -> LazyResult[BootstrapDataPrimitivePlan] | LazyResult[None]:
        from l3200_metadata.bootstrap_data_plan import (
            BootstrapDataPrimitiveKind,
            BootstrapRowPrimitivePayload,
            BootstrapScopePrimitivePayload,
        )

        if contract.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_SYSTEM_SESSION:
            return schema_txn.ensure_bootstrap_system_session_lazy(
                produced_ref=contract.produced_ref,
                dependency_refs=dependency_refs,
            )
        if contract.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_IMMUTABLE_ROW and isinstance(
            contract.payload, BootstrapImmutableRowPrimitivePayload
        ):
            return schema_txn.ensure_bootstrap_immutable_row_lazy(
                contract.payload,
                dependency_refs=BootstrapDependencyRefs((*dependency_refs, *contract.dependency_refs)),
                produced_ref=contract.produced_ref,
            )
        if contract.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_ROW and isinstance(
            contract.payload, BootstrapRowPrimitivePayload
        ):
            return schema_txn.upsert_bootstrap_rows_lazy(
                cast("Any", contract.payload.model_cls),
                cast("Any", contract.payload.rows),
                conflict_fields=tuple(DynamicFieldName(field_name) for field_name in contract.payload.key_fields),
                exclude_fields=tuple(DynamicFieldName(field_name) for field_name in contract.payload.exclude_fields),
                dependency_refs=(*dependency_refs, *contract.dependency_refs),
                dependency_table_reads=contract.payload.depends_on_tables,
                produced_refs=(contract.produced_ref,),
            )
        if contract.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_BOOTSTRAP_SCOPE and isinstance(
            contract.payload,
            BootstrapScopePrimitivePayload,
        ):
            return schema_txn.ensure_bootstrap_scope_lazy(
                contract.payload,
                produced_ref=contract.produced_ref,
                dependency_refs=(*dependency_refs, *contract.dependency_refs),
            )
        msg = f"no lazy data primitive installer for {contract.identity.primitive_kind!r}"
        raise RuntimeError(msg)

    @pure_lazy
    def _install_versioning_mutation_contract(
        self: LazyBootstrapCoordinator,
        schema_txn: LazySchemaTransaction,
        contract: Any,
        dependency_refs: tuple[ServerPlanRefId, ...],
        *,
        shared_revision_id: RevisionId | None = None,
        enqueue_commit_envelope: bool = True,
    ) -> LazyResult[BootstrapDataPrimitivePlan]:
        from l3200_metadata.bootstrap_data_plan import (
            BootstrapDataPrimitiveKind,
            BootstrapVersionedRowsPrimitivePayload,
            BootstrapVersioningDomainPrimitivePayload,
        )

        if contract.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_VERSIONING_DOMAIN and isinstance(
            contract.payload,
            BootstrapVersioningDomainPrimitivePayload,
        ):
            metadata = dict(contract.payload.revision_metadata)
            from l1400_types.type_surface_contracts import RevisionMessage

            message = RevisionMessage(str(metadata.get("message", "Bootstrap initial revision")))
            return schema_txn.ensure_bootstrap_versioning_domain_lazy(
                contract.payload.domain_contract.domain,
                branch_id=contract.payload.branch_id,
                branch_name=contract.payload.branch_name,
                workspace_id=contract.payload.workspace_id,
                session_id=cast("Any", contract.payload.session_id),
                message=message,
                tip_materialization=contract.payload.tip_materialization,
                branchpoint_materialization=contract.payload.branchpoint_materialization,
                produced_ref=contract.produced_ref,
                dependency_refs=(*dependency_refs, *contract.dependency_refs),
            )
        if contract.identity.primitive_kind is BootstrapDataPrimitiveKind.ENSURE_VERSIONED_ROW and isinstance(
            contract.payload,
            BootstrapVersionedRowsPrimitivePayload,
        ):
            from l1400_types.type_surface_contracts import NoRevision

            return schema_txn.ensure_bootstrap_versioned_rows_lazy(
                cast("Any", contract.payload.domain),
                cast("Any", contract.payload.model_cls),
                cast("Any", contract.payload.rows),
                conflict_fields=tuple(DynamicFieldName(field_name) for field_name in contract.payload.key_fields),
                exclude_fields=tuple(DynamicFieldName(field_name) for field_name in contract.payload.exclude_fields),
                branch_id=contract.payload.branch_id,
                branch_name=contract.payload.branch_name,
                workspace_id=contract.payload.workspace_id,
                produced_ref=contract.produced_ref,
                dependency_refs=(*dependency_refs, *contract.dependency_refs),
                shared_revision_id=NoRevision() if shared_revision_id is None else shared_revision_id,
                enqueue_commit_envelope=enqueue_commit_envelope,
            )
        msg = f"no lazy versioning primitive installer for {contract.identity.primitive_kind!r}"
        raise RuntimeError(msg)


