import contextvars
import logging
from collections.abc import Sequence, Awaitable, Mapping
from enum import Enum
from typing import TYPE_CHECKING, Any, Protocol, cast, runtime_checkable

from pydantic import AwareDatetime

from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
from l2000_connection.connection_lazy_return_registry import PlanScopeReturnName
from l2055_lazy_result.lazy_result import LazyResult
from l2055_lazy_result.purity import in_bootstrap_plan_active_context, pure_lazy
from l2055_lazy_result.transform import project_lazy_result
from l1000_schema.no_security_permissions import ExplicitNoSecurityPermissions
