if TYPE_CHECKING:
    from l2000_connection.connection import AsyncDatabaseConnection, SyncDatabaseConnection
    from l2050_transaction.transaction import AsyncReadTransaction, ReadTransaction
    from l3200_metadata.bootstrap_execution_facts import BootstrapDdlLockdownExecutionFact
    from l3200_metadata.bootstrap_lifecycle_effects import ApplyDdlLockdownEffect
    from l3200_metadata.bootstrap_observation import BootstrapDdlLockdownFact
    from l2000_connection.connection import _LazyConnectionBase

logger = logging.getLogger(__name__)
_DDL_LOCKDOWN_TABLE = "sys_ddl_lockdown"
_DDL_LOCKDOWN_TABLE_NAME = SqlTableName(_DDL_LOCKDOWN_TABLE)

_DDL_ADMIN_CONTEXT: contextvars.ContextVar[dict[str, Any] | None] = contextvars.ContextVar(
    "_DDL_ADMIN_CONTEXT",
    default=None,
)


@runtime_checkable
class _SyncTablePresenceAuthority[
    TableExistsManyTableNamesT: tuple[SqlTableName, ...] = tuple[SqlTableName, ...],
    TableExistsManyResultT: Mapping[SqlTableName, bool] = Mapping[SqlTableName, bool],
](Protocol):
    def table_exists_many(self, table_names: TableExistsManyTableNamesT) -> TableExistsManyResultT: ...


@runtime_checkable
class _AsyncTablePresenceAuthority(Protocol):
    async def table_exists_many_async(
        self,
        table_names: Sequence[SqlTableName],
    ) -> Mapping[SqlTableName, bool]: ...


@runtime_checkable
class _ProjectedTablePresenceAuthority[
    ProjectedOrCachedTableExistsTableNameT: SqlTableName = SqlTableName,
    ProjectedOrCachedTableExistsResultT: bool | None = bool | None,
](Protocol):
    def projected_or_cached_table_exists(
        self, table_name: ProjectedOrCachedTableExistsTableNameT
    ) -> ProjectedOrCachedTableExistsResultT: ...


@pure_lazy
def _get_admin_context() -> dict[str, Any] | None:
    """Return the current admin override context."""
    return _DDL_ADMIN_CONTEXT.get()


def _set_admin_context(context: dict[str, Any] | None) -> None:
    """Set the current admin override context."""
    _DDL_ADMIN_CONTEXT.set(context)


@pure_lazy
def _is_admin_session() -> bool:
    """Return whether DDL lockdown checks should be bypassed."""
    context = _get_admin_context()
    return bool(context and context.get("admin"))


@pure_lazy
def _cached_lockdown_table_exists(conn: _LazyConnectionBase) -> bool | None:
    """Return cached/projected lockdown-table existence when available."""
    if isinstance(conn, _ProjectedTablePresenceAuthority):
        projected = conn.projected_or_cached_table_exists(SqlTableName(_DDL_LOCKDOWN_TABLE))
        if isinstance(projected, bool):
            return projected
    cached_lockdown_presence = getattr(conn, "bootstrap_ddl_lockdown_table_presence", None)
    if callable(cached_lockdown_presence):
        cached = cached_lockdown_presence()
        if isinstance(cached, bool):
            return cached
    known_absent = getattr(conn, "_known_absent_schema_tables", None)
    if isinstance(known_absent, set) and _DDL_LOCKDOWN_TABLE in known_absent:
        return False
    table_exists_from_cache = getattr(conn, "_table_exists_from_cache", None)
    if callable(table_exists_from_cache):
        cached = table_exists_from_cache(_DDL_LOCKDOWN_TABLE)
        if isinstance(cached, bool):
            if not cached:
                if not isinstance(known_absent, set):
                    known_absent = set()
                    setattr(conn, "_known_absent_schema_tables", known_absent)
                known_absent.add(_DDL_LOCKDOWN_TABLE)
            return cached
    if in_bootstrap_plan_active_context():
        authoritative_existing_tables = getattr(conn, "_authoritative_template_existing_tables", None)
        if isinstance(authoritative_existing_tables, frozenset):
            exists = _DDL_LOCKDOWN_TABLE in authoritative_existing_tables
            if not exists:
                if not isinstance(known_absent, set):
                    known_absent = set()
                    setattr(conn, "_known_absent_schema_tables", known_absent)
                known_absent.add(_DDL_LOCKDOWN_TABLE)
            return exists
    return None


def _mark_lockdown_table_absent(conn: _LazyConnectionBase) -> None:
    known_absent = getattr(conn, "_known_absent_schema_tables", None)
    if not isinstance(known_absent, set):
        known_absent = set()
        setattr(conn, "_known_absent_schema_tables", known_absent)
    known_absent.add(_DDL_LOCKDOWN_TABLE)


@pure_lazy
def _publish_lockdown_value_lazy[T](conn: object, value: T) -> LazyResult[T]:
    static_after = getattr(conn, "_static_after_sql_deps_lazy", None)
    if callable(static_after):
        return cast("LazyResult[T]", static_after(value, ()))
    msg = f"{type(conn).__name__} does not expose a ServerPlan-backed lazy value publisher"
    raise TypeError(msg)


@pure_lazy
def _lockdown_table_exists_lazy(conn: AsyncDatabaseConnection) -> LazyResult[bool]:
    """Published lazy lockdown-table probes must come from bootstrap observation."""
    cached = _cached_lockdown_table_exists(conn)
    if isinstance(cached, bool):
        return _publish_lockdown_value_lazy(conn, cached)
    from l3200_metadata.bootstrap_state import BootstrapPlanningError

    msg = (
        "DDL lockdown lazy table-presence checks require cached bootstrap observation. "
        "Do not project unpublished backend lazy schema probes; collect the fact in "
        "BootstrapInterrogationStep or use the concrete get_lockdown_mode boundary."
    )
    raise BootstrapPlanningError(msg)


class LockdownMode(Enum):
    """DDL lockdown mode."""

    UNLOCKED = "unlocked"
    LOCKED = "locked"
    STRICT = "strict"


@register_table(
    plural="sys_ddl_lockdown",
    singular="sys_ddl_lockdown",
    audited=False,
    semantic_id="l2000_connection.ddl_lockdown_runtime.DDLLockdownState",
    participates_in_static_naming_metadata=True,
)
class DDLLockdownState(ApplicationObjectRow[SysId]):
    """Persistent DDL lockdown state."""

    class Permissions(ExplicitNoSecurityPermissions):
        pass

    mode: str = Column(
        semantic_id="l2000_connection.ddl_lockdown_runtime.DDLLockdownState.mode", default=LockdownMode.UNLOCKED.value, max_length=32
    )
    locked_at: AwareDatetime | None = Column(
        semantic_id="l2000_connection.ddl_lockdown_runtime.DDLLockdownState.locked_at", default=None, nullable=True
    )
    locked_by: str | None = Column(
        semantic_id="l2000_connection.ddl_lockdown_runtime.DDLLockdownState.locked_by", default=None, nullable=True, max_length=256
    )
    admin_token_hash: AdminTokenHash | None = Column(
        semantic_id="l2000_connection.ddl_lockdown_runtime.DDLLockdownState.admin_token_hash", default=None, nullable=True, max_length=128
    )
    reason: DiagnosticReason | None = Column(
        semantic_id="l2000_connection.ddl_lockdown_runtime.DDLLockdownState.reason", default=None, nullable=True, max_length=1024
    )


class DDLLockdownError(Exception):
    """Raised when schema changes are blocked by lockdown."""

    def __init__(
        self: DDLLockdownError,
        mode_or_message: LockdownMode | str,
        message: DiagnosticMessage | None = None,
    ) -> None:
        if isinstance(mode_or_message, LockdownMode):
            self.mode: LockdownMode | None = mode_or_message
            if message is None:
                message = DiagnosticMessage(self._default_message())
        else:
            self.mode = None
            message = DiagnosticMessage(mode_or_message)
        super().__init__(message)

    def _default_message(self: DDLLockdownError) -> DiagnosticMessage:
        mode_str = self.mode.value if self.mode else "strict"
        return DiagnosticMessage(f"""Schema operations are locked (mode: {mode_str}).

The database schema is locked to prevent accidental changes.
Schema modifications can only be performed using admin tools.

To apply schema migrations, use:
  nera schema migrate

To check what migrations are needed:
  nera schema diff

To unlock for development (NOT RECOMMENDED for production):
  nera schema unlock --admin-token=<token>

For more information:
  nera schema --help""")

    def format_instructions(self: DDLLockdownError) -> DiagnosticMessage:
        return DiagnosticMessage(self._default_message())


def apply_bootstrap_ddl_lockdown_effect(
    conn: SyncDatabaseConnection,
    effect: ApplyDdlLockdownEffect,
) -> None:
    """Apply post-bootstrap DDL lockdown through the connection runtime hook."""

    hook = getattr(conn, "apply_bootstrap_ddl_lockdown", None)
    if callable(hook):
        hook(effect)
        return
    setattr(conn, "_bootstrap_ddl_lockdown_policy", effect.policy)


def get_lockdown_mode(
    conn: SyncDatabaseConnection,
    *,
    session_id: SessionId | None = None,
) -> LockdownMode:
    """Get the current DDL lockdown mode."""
    from l2000_connection.connection_plan_workflows import (
        SyncReadPlanWorkflow,
        execute_read_plan_workflow,
    )

    try:
        if _is_admin_session():
            return LockdownMode.UNLOCKED
        runtime_policy = getattr(conn, "_bootstrap_ddl_lockdown_policy", None)
        if runtime_policy in LockdownMode._value2member_map_:
            return LockdownMode(str(runtime_policy))
        cached_table_exists = _cached_lockdown_table_exists(conn)
        if cached_table_exists is False:
            _mark_lockdown_table_absent(conn)
            return LockdownMode.UNLOCKED
        if cached_table_exists is None:
            if not isinstance(conn, _SyncTablePresenceAuthority):
                msg = "Connection does not expose concrete runtime table-presence authority"
                raise RuntimeError(msg)
            cached_table_exists = bool(
                conn.table_exists_many((_DDL_LOCKDOWN_TABLE_NAME,)).get(_DDL_LOCKDOWN_TABLE_NAME, False),
            )
            if not cached_table_exists:
                _mark_lockdown_table_absent(conn)
                return LockdownMode.UNLOCKED

        if session_id is None:
            return get_lockdown_mode(conn, session_id=SessionId.schema())

        states = execute_read_plan_workflow(
            conn,
            SyncReadPlanWorkflow[object](
                session_id=session_id,
                build=lambda txn: txn.query_lazy(DDLLockdownState).limit(1).execute_lazy(),
                result_name=PlanScopeReturnName("lockdown_states"),
            ),
        )
        if not isinstance(states, list) or not states:
            return LockdownMode.UNLOCKED
        state = states[0]
        if not isinstance(state, DDLLockdownState):
            raise TypeError(f"Expected DDLLockdownState, got {type(state).__name__}")
        raw_mode = state.mode
        return LockdownMode(raw_mode) if raw_mode in LockdownMode._value2member_map_ else LockdownMode.STRICT
    except Exception:
        logger.warning("Failed to read DDL lockdown mode; defaulting to LOCKED", exc_info=True)
        return LockdownMode.LOCKED


async def get_lockdown_mode_async(
    conn: AsyncDatabaseConnection,
    *,
    session_id: SessionId | None = None,
) -> LockdownMode:
    """Async variant of :func:`get_lockdown_mode`."""
    from l2000_connection.connection_plan_workflows import (
        AsyncReadPlanningWorkflow,
        run_read_planning_workflow_async,
    )

    try:
        if _is_admin_session():
            return LockdownMode.UNLOCKED
        runtime_policy = getattr(conn, "_bootstrap_ddl_lockdown_policy", None)
        if runtime_policy in LockdownMode._value2member_map_:
            return LockdownMode(str(runtime_policy))
        cached_table_exists = _cached_lockdown_table_exists(conn)
        if cached_table_exists is False:
            _mark_lockdown_table_absent(conn)
            return LockdownMode.UNLOCKED
        if cached_table_exists is None:
            if not isinstance(conn, _AsyncTablePresenceAuthority):
                msg = "Connection does not expose concrete async runtime table-presence authority"
                raise RuntimeError(msg)
            presence = await conn.table_exists_many_async((_DDL_LOCKDOWN_TABLE_NAME,))
            cached_table_exists = bool(presence.get(_DDL_LOCKDOWN_TABLE_NAME, False))
            if not cached_table_exists:
                _mark_lockdown_table_absent(conn)
                return LockdownMode.UNLOCKED

        if session_id is None:
            return await get_lockdown_mode_async(conn, session_id=SessionId.schema())

        def _build(txn: AsyncReadTransaction) -> object:
            return txn.query_lazy(DDLLockdownState).limit(1).execute_lazy()

        states = await run_read_planning_workflow_async(
            conn,
            AsyncReadPlanningWorkflow[object](
                session_id=session_id,
                build=_build,
                result_name=PlanScopeReturnName("lockdown_states"),
            ),
        )
        if not isinstance(states, list) or not states:
            return LockdownMode.UNLOCKED
        state = states[0]
        if not isinstance(state, DDLLockdownState):
            raise TypeError(f"Expected DDLLockdownState, got {type(state).__name__}")
        raw_mode = state.mode
        return LockdownMode(raw_mode) if raw_mode in LockdownMode._value2member_map_ else LockdownMode.STRICT
    except Exception:
        logger.warning("Failed to read DDL lockdown mode asynchronously; defaulting to LOCKED", exc_info=True)
        return LockdownMode.LOCKED


@pure_lazy
def get_lockdown_mode_lazy(
    conn: SyncDatabaseConnection,
    *,
    session_id: SessionId | None = None,
) -> LazyResult[BootstrapDdlLockdownFact]:
    """Get the current DDL lockdown mode through the lazy schema boundary."""
    from l3200_metadata.bootstrap_observation import BootstrapDdlLockdownFact, BootstrapFactPresence

    del session_id
    cached = _cached_lockdown_table_exists(conn)
    source_ref = ServerPlanRefId("ddl_lockdown:get_lockdown_mode")
    if cached is False:
        return _publish_lockdown_value_lazy(
            conn,
            BootstrapDdlLockdownFact(
                presence=BootstrapFactPresence.ABSENT,
                source_ref=source_ref,
            ),
        )
    if cached is True:
        return _publish_lockdown_value_lazy(
            conn,
            BootstrapDdlLockdownFact(
                presence=BootstrapFactPresence.PRESENT,
                source_ref=source_ref,
            ),
        )
    return _publish_lockdown_value_lazy(
        conn,
        BootstrapDdlLockdownFact(
            presence=BootstrapFactPresence.ABSENT,
            source_ref=source_ref,
        ),
    )


@pure_lazy
def check_ddl_lockdown_lazy(conn: AsyncDatabaseConnection) -> LazyResult[BootstrapDdlLockdownExecutionFact]:
    """Async variant of :func:`check_ddl_lockdown`."""
    from l3200_metadata.bootstrap_execution_facts import BootstrapDdlLockdownExecutionFact

    if _is_admin_session():
        return _publish_lockdown_value_lazy(
            conn,
            BootstrapDdlLockdownExecutionFact(
                lockdown_hash=BootstrapFactsHash("ddl-lockdown-admin"),
                source_ref=ServerPlanRefId("ddl_lockdown:admin"),
            ),
        )

    fact = get_lockdown_mode_lazy(cast(Any, conn))
    return cast(
        "LazyResult[BootstrapDdlLockdownExecutionFact]",
        project_lazy_result(cast("LazyResult[object]", fact), "ddl_lockdown_execution_fact"),
    )

