"""Backend-owned factories for optional shared services."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Mapping
from enum import StrEnum
from typing import TYPE_CHECKING, ClassVar

from l1350_foundational_types import BackendType

if TYPE_CHECKING:
    from l2050_transaction.transaction import ReadTransaction


class BackendBackupService(ABC):
    """Base contract for a backend-owned backup service."""


class BackendBackupFactory(ABC):
    """Construct a backend-owned backup service."""

    @abstractmethod
    def create(self, txn: ReadTransaction) -> BackendBackupService:
        """Construct the service for one transaction."""
        ...


class BackendBackupFactoryMissing(StrEnum):
    """Explicit result when a backend has no backup factory."""

    NOT_REGISTERED = "not_registered"


class BackendBackupFactoryRegistry:
    """Store process-local backup factories registered by backend implementations."""

    _factories: ClassVar[Mapping[BackendType, BackendBackupFactory]] = {}

    @classmethod
    def register(
        cls,
        backend_type: BackendType,
        factory: BackendBackupFactory,
    ) -> None:
        """Register a backend-owned backup factory."""
        cls._factories = {**cls._factories, backend_type: factory}

    @classmethod
    def get(
        cls,
        backend_type: BackendType,
    ) -> BackendBackupFactory | BackendBackupFactoryMissing:
        """Return a registered backup factory or an explicit miss."""
        return cls._factories.get(
            backend_type,
            BackendBackupFactoryMissing.NOT_REGISTERED,
        )

