"""Provider-owned notification subscription transports."""

from __future__ import annotations

import abc
import asyncio
import contextlib
import logging
import threading
from collections import deque
from collections.abc import AsyncGenerator, Generator
from dataclasses import dataclass
from datetime import UTC, datetime
from enum import StrEnum
from typing import TYPE_CHECKING, Protocol

from pydantic import AwareDatetime

from l1300_session.session import SessionId
from l1400_types.type_surface_contracts import (
    NotificationChannelName as NotificationChannelName,
    NotificationPayload as NotificationPayload,
)
logger = logging.getLogger(__name__)


def _notification_transport_failures() -> tuple[type[BaseException], ...]:
    from l2200_notification.transport_failures import transport_failures

    return transport_failures()


if TYPE_CHECKING:
    from l2000_connection.connection_pool import AsyncConnectionPool
    from l2000_connection.connection_provider import ConnectionProvider
    from l2200_notification.notification_channel import Notification, NotificationChannel


@dataclass(frozen=True, slots=True)
class NotificationDeadline:
    """Explicit finite deadline for a notification wait."""

    at: AwareDatetime


@dataclass(frozen=True, slots=True)
class NoNotificationDeadline:
    """Explicit unbounded notification wait contract."""


NO_NOTIFICATION_DEADLINE = NoNotificationDeadline()
type NotificationDeadlineSpec = NotificationDeadline | NoNotificationDeadline


class NotificationWaitReason(StrEnum):
    """Reason a provider-owned notification subscription stopped waiting."""

    NOTIFICATION = "notification"
    RESYNC_REQUIRED = "resync_required"
    DEADLINE = "deadline"
    STOPPED = "stopped"
    CLOSED = "closed"


class NotificationResyncCause(StrEnum):
    """Identify the continuity loss that requires an authoritative re-read."""

    NOT_REQUIRED = "not_required"
    SUBSCRIPTION_ESTABLISHED = "subscription_established"
    TRANSPORT_RECONNECTED = "transport_reconnected"
    TRANSPORT_ERROR = "transport_error"
    TRANSPORT_CLOSED = "transport_closed"
    NOTIFICATION_OVERFLOW = "notification_overflow"
    DURABLE_BATCH_INCOMPLETE = "durable_batch_incomplete"
    POLL_GAP_EXCEEDED_TTL = "poll_gap_exceeded_ttl"
    POLL_FAILED = "poll_failed"
    WATCH_REESTABLISHED = "watch_reestablished"


@dataclass(frozen=True, slots=True)
class NotificationWaitResult:
    """Backend-neutral result from one notification wait."""

    reason: NotificationWaitReason
    channel: NotificationChannelName = NotificationChannelName("")
    payload: NotificationPayload = NotificationPayload("")
    resync_cause: NotificationResyncCause = NotificationResyncCause.NOT_REQUIRED

    def __post_init__(self) -> None:
        is_resync = self.reason is NotificationWaitReason.RESYNC_REQUIRED
        has_cause = self.resync_cause is not NotificationResyncCause.NOT_REQUIRED
        if is_resync and not has_cause:
            raise ValueError("A RESYNC_REQUIRED result must carry a resync_cause naming what was lost")
        if not is_resync and has_cause:
            raise ValueError(f"resync_cause is only meaningful for RESYNC_REQUIRED, not {self.reason}")


def poll_gap_lost_notifications(*, last_poll_at: AwareDatetime, now: AwareDatetime) -> bool:
    """Return whether a notification can expire wholly between two polls."""
    from l2200_notification.polling_channel import NOTIFICATION_TTL_SECONDS

    return (now - last_poll_at).total_seconds() >= NOTIFICATION_TTL_SECONDS


class SyncNotificationStopSignal[TWake](Protocol):
    """Blocking stop signal used by synchronous notification waits."""

    def is_set(self) -> bool: ...

    def wait(self, timeout: float | None = None) -> TWake: ...


class AsyncNotificationStopSignal[TWake](Protocol):
    """Awaitable stop signal used by asynchronous notification waits."""

    def is_set(self) -> bool: ...

    async def wait(self) -> TWake: ...


class SyncNotificationSubscription(abc.ABC):
    """Receive-only blocking notification transport owned by a provider."""

    @abc.abstractmethod
    def wait[TWake](
        self,
        *,
        deadline: NotificationDeadlineSpec,
        stop_signal: SyncNotificationStopSignal[TWake],
    ) -> NotificationWaitResult:
        """Block until a wake, deadline, closure, or stop request."""


UNBOUNDED_NOTIFICATION_CAPACITY = -1


@dataclass(frozen=True, slots=True)
class NotificationBufferSnapshot:
    """Current bounded receive-buffer counters."""

    items: int
    payload_bytes: int
    capacity: int
    byte_capacity: int


class AsyncNotificationSubscription(abc.ABC):
    """Receive-only async notification transport owned by a provider."""

    def buffer_snapshot(self) -> NotificationBufferSnapshot:
        """Return current queue counters when the transport exposes them."""
        return NotificationBufferSnapshot(
            items=0,
            payload_bytes=0,
            capacity=UNBOUNDED_NOTIFICATION_CAPACITY,
            byte_capacity=UNBOUNDED_NOTIFICATION_CAPACITY,
        )

    @abc.abstractmethod
    async def wait_async[TWake](
        self,
        *,
        deadline: NotificationDeadlineSpec,
        stop_signal: AsyncNotificationStopSignal[TWake],
    ) -> NotificationWaitResult:
        """Wait for one notification, deadline, closure, or stop signal."""


class ChannelAsyncNotificationSubscription(AsyncNotificationSubscription):
    def __init__(self, channel: NotificationChannel) -> None:
        self._channel = channel
        self._notifications = channel.notifications()
        self._notification_task: asyncio.Task[Notification] | None = None
        self._established = False
        self._closed = False
        self._wait_lock = asyncio.Lock()

    async def wait_async[TWake](
        self,
        *,
        deadline: NotificationDeadlineSpec,
        stop_signal: AsyncNotificationStopSignal[TWake],
    ) -> NotificationWaitResult:
        async with self._wait_lock:
            return await self._wait_serialized(deadline=deadline, stop_signal=stop_signal)

    async def _wait_serialized[TWake](
        self,
        *,
        deadline: NotificationDeadlineSpec,
        stop_signal: AsyncNotificationStopSignal[TWake],
    ) -> NotificationWaitResult:
        deadline_at = deadline.at if isinstance(deadline, NotificationDeadline) else None
        if self._closed:
            return NotificationWaitResult(reason=NotificationWaitReason.CLOSED)
        if not self._established:
            self._established = True
            return NotificationWaitResult(
                reason=NotificationWaitReason.RESYNC_REQUIRED,
                resync_cause=NotificationResyncCause.SUBSCRIPTION_ESTABLISHED,
            )
        if stop_signal.is_set():
            return NotificationWaitResult(reason=NotificationWaitReason.STOPPED)
        if self._channel.consume_overflow():
            return NotificationWaitResult(
                reason=NotificationWaitReason.RESYNC_REQUIRED,
                resync_cause=NotificationResyncCause.NOTIFICATION_OVERFLOW,
            )
        if self._notification_task is None:
            self._notification_task = asyncio.create_task(anext(self._notifications))
        notification_task = self._notification_task
        stop_task = asyncio.create_task(stop_signal.wait())
        tasks: set[asyncio.Task[object]] = {notification_task, stop_task}
        deadline_task: asyncio.Task[object] | None = None
        if deadline_at is not None:
            delay = max(0.0, (deadline_at - datetime.now(UTC)).total_seconds())
            deadline_task = asyncio.create_task(asyncio.sleep(delay))
            tasks.add(deadline_task)
        done, pending = await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)
        try:
            if stop_task in done:
                return NotificationWaitResult(reason=NotificationWaitReason.STOPPED)
            if deadline_task is not None and deadline_task in done:
                return NotificationWaitResult(reason=NotificationWaitReason.DEADLINE)
            self._notification_task = None
            try:
                notification = await notification_task
            except asyncio.CancelledError:
                if self._closed:
                    return NotificationWaitResult(reason=NotificationWaitReason.CLOSED)
                raise
            except StopAsyncIteration:
                return NotificationWaitResult(
                    reason=NotificationWaitReason.RESYNC_REQUIRED,
                    resync_cause=NotificationResyncCause.TRANSPORT_CLOSED,
                )
            except _notification_transport_failures():
                logger.warning("Notification transport failed; caller must re-read", exc_info=True)
                return NotificationWaitResult(
                    reason=NotificationWaitReason.RESYNC_REQUIRED,
                    resync_cause=NotificationResyncCause.TRANSPORT_ERROR,
                )
            return NotificationWaitResult(
                reason=(NotificationWaitReason.RESYNC_REQUIRED if notification.resync_required else NotificationWaitReason.NOTIFICATION),
                channel=NotificationChannelName(notification.channel),
                payload=NotificationPayload(notification.payload),
                resync_cause=(
                    NotificationResyncCause.TRANSPORT_ERROR if notification.resync_required else NotificationResyncCause.NOT_REQUIRED
                ),
            )
        finally:
            cancellable = [task for task in pending if task is not notification_task]
            for task in cancellable:
                task.cancel()
            if cancellable:
                await asyncio.gather(*cancellable, return_exceptions=True)

    async def close(self) -> None:
        self._closed = True
        task = self._notification_task
        self._notification_task = None
        if task is not None and not task.done():
            task.cancel()
            await asyncio.gather(task, return_exceptions=True)


class _AsyncPollingNotificationSubscription(AsyncNotificationSubscription):
    def __init__(
        self,
        provider: ConnectionProvider,
        channels: frozenset[NotificationChannelName],
        session_id: SessionId,
        *,
        initial_resync_required: bool = True,
    ) -> None:
        from l2200_notification.polling_channel import register_process_notification_wake

        self._provider = provider
        self._channels = channels
        self._session_id = session_id
        self._seen_notification_ids: dict[str, AwareDatetime] = {}
        self._pending: deque[NotificationWaitResult] = deque()
        self._forward_cursor: int | None = None
        self._loop = asyncio.get_running_loop()
        self._wake_event = asyncio.Event()
        self._closed = False
        self._initial_resync_pending = initial_resync_required
        now = datetime.now(UTC)
        self._last_poll_at = now
        self._last_successful_poll_at = now

        def wake() -> None:
            self._loop.call_soon_threadsafe(self._wake_event.set)

        self._unsubscribe_wake = register_process_notification_wake(channels, wake)

    def buffer_snapshot(self) -> NotificationBufferSnapshot:
        payload_bytes = sum(len(item.payload.encode("utf-8")) for item in self._pending)
        return NotificationBufferSnapshot(
            items=len(self._pending),
            payload_bytes=payload_bytes,
            capacity=64,
            byte_capacity=8_388_608,
        )

    async def close(self) -> None:
        self._closed = True
        self._unsubscribe_wake()
        self._wake_event.set()
        await asyncio.sleep(0)

    async def establish(self) -> None:
        """Capture the durable polling boundary before the subscription is exposed."""
        await self._poll_bounded(datetime.now(UTC))

    async def _poll_bounded(self, now: AwareDatetime) -> None:
        from l2000_connection.connection_plan_workflows import AsyncReadPlanningWorkflow, run_read_planning_workflow_async
        from l2200_notification.polling_channel import (
            DEFAULT_MAX_FORWARD_PAGES,
            DEFAULT_POLL_OVERLAP_SIZE,
            DEFAULT_POLL_PAGE_SIZE,
            DEFAULT_POLL_TAIL_SIZE,
            NotificationForwardPollRequest,
            NotificationOverlapPollRequest,
            NotificationRow,
            NotificationSequence,
            NotificationTailPollRequest,
            poll_notifications_forward_lazy,
            poll_notifications_overlap_lazy,
            poll_notifications_tail_lazy,
        )

        async def _read(
            request: NotificationForwardPollRequest | NotificationOverlapPollRequest | NotificationTailPollRequest,
        ) -> tuple[NotificationRow, ...]:
            if isinstance(request, NotificationOverlapPollRequest):
                build = lambda txn: poll_notifications_overlap_lazy(txn, request)
            elif isinstance(request, NotificationTailPollRequest):
                build = lambda txn: poll_notifications_tail_lazy(txn, request)
            else:
                build = lambda txn: poll_notifications_forward_lazy(txn, request)
            async with self._provider.acquire() as conn:
                rows = await run_read_planning_workflow_async(
                    conn,
                    AsyncReadPlanningWorkflow[list[NotificationRow]](session_id=self._session_id, build=build),
                )
                return tuple(rows)

        channels = tuple(sorted(self._channels))
        rows: list[NotificationRow] = []
        resync_required = False
        if self._forward_cursor is None:
            tail = await _read(NotificationTailPollRequest(now=now, channels=channels, page_size=DEFAULT_POLL_TAIL_SIZE + 1))
            resync_required = len(tail) > DEFAULT_POLL_TAIL_SIZE
            self._forward_cursor = max((int(row.sequence_id) for row in tail), default=0)
            self._seen_notification_ids.update((str(row.sys_id), row.expires_at) for row in tail)
        else:
            page_was_full = False
            for _page_number in range(DEFAULT_MAX_FORWARD_PAGES):
                page = await _read(
                    NotificationForwardPollRequest(
                        now=now,
                        channels=channels,
                        after_sequence=NotificationSequence(self._forward_cursor),
                        page_size=DEFAULT_POLL_PAGE_SIZE,
                    )
                )
                page_was_full = len(page) == DEFAULT_POLL_PAGE_SIZE
                rows.extend(page)
                if page:
                    self._forward_cursor = max(int(row.sequence_id) for row in page)
                if not page_was_full:
                    break
            # A full page is drained before the next forward read. The cursor
            # remains at that page boundary, so later rows stay available
            # without expanding the in-memory receive buffer.
            overlap = await _read(
                NotificationOverlapPollRequest(
                    now=now,
                    channels=channels,
                    after_sequence=NotificationSequence(max(0, self._forward_cursor - DEFAULT_POLL_OVERLAP_SIZE)),
                    through_sequence=NotificationSequence(self._forward_cursor),
                    page_size=DEFAULT_POLL_OVERLAP_SIZE,
                )
            )
            rows.extend(reversed(overlap))

        self._seen_notification_ids = {row_id: expiry for row_id, expiry in self._seen_notification_ids.items() if expiry > now}
        for row in rows:
            row_id = str(row.sys_id)
            if row_id in self._seen_notification_ids:
                continue
            self._seen_notification_ids[row_id] = row.expires_at
            self._pending.append(
                NotificationWaitResult(
                    reason=NotificationWaitReason.NOTIFICATION,
                    channel=NotificationChannelName(row.channel),
                    payload=NotificationPayload(row.payload),
                )
            )
        if resync_required:
            self._pending.append(
                NotificationWaitResult(
                    reason=NotificationWaitReason.RESYNC_REQUIRED,
                    channel=min(self._channels),
                    resync_cause=NotificationResyncCause.NOTIFICATION_OVERFLOW,
                )
            )

    async def wait_async[TWake](
        self,
        *,
        deadline: NotificationDeadlineSpec,
        stop_signal: AsyncNotificationStopSignal[TWake],
    ) -> NotificationWaitResult:
        deadline_at = deadline.at if isinstance(deadline, NotificationDeadline) else None
        if self._closed:
            return NotificationWaitResult(reason=NotificationWaitReason.CLOSED)
        if self._initial_resync_pending:
            self._initial_resync_pending = False
            return NotificationWaitResult(
                reason=NotificationWaitReason.RESYNC_REQUIRED,
                resync_cause=NotificationResyncCause.SUBSCRIPTION_ESTABLISHED,
            )
        interval = 0.01
        while not stop_signal.is_set() and not self._closed:
            now = datetime.now(UTC)
            if deadline_at is not None and deadline_at <= now:
                return NotificationWaitResult(reason=NotificationWaitReason.DEADLINE)
            if self._pending:
                return self._pending.popleft()
            if poll_gap_lost_notifications(last_poll_at=self._last_successful_poll_at, now=now):
                self._last_successful_poll_at = now
                return NotificationWaitResult(
                    reason=NotificationWaitReason.RESYNC_REQUIRED,
                    resync_cause=NotificationResyncCause.POLL_GAP_EXCEEDED_TTL,
                )
            try:
                await self._poll_bounded(now)
            except _notification_transport_failures():
                await asyncio.sleep(interval)
                return NotificationWaitResult(
                    reason=NotificationWaitReason.RESYNC_REQUIRED,
                    resync_cause=NotificationResyncCause.POLL_FAILED,
                )
            self._last_successful_poll_at = now
            self._last_poll_at = now
            if self._pending:
                return self._pending.popleft()
            timeout = interval
            if deadline_at is not None:
                timeout = min(timeout, max(0.0, (deadline_at - datetime.now(UTC)).total_seconds()))
            stop_task = asyncio.create_task(stop_signal.wait())
            wake_task = asyncio.create_task(self._wake_event.wait())
            done, pending = await asyncio.wait(
                {stop_task, wake_task},
                timeout=timeout,
                return_when=asyncio.FIRST_COMPLETED,
            )
            for task in pending:
                task.cancel()
            for task in pending:
                with contextlib.suppress(asyncio.CancelledError):
                    await task
            if wake_task in done:
                self._wake_event.clear()
                interval = 0.01
            else:
                interval = min(interval * 2, 2.0)
        return NotificationWaitResult(
            reason=NotificationWaitReason.CLOSED if self._closed else NotificationWaitReason.STOPPED,
        )


class _SyncPollingNotificationSubscription(SyncNotificationSubscription):
    def __init__(
        self,
        provider: ConnectionProvider,
        channels: frozenset[NotificationChannelName],
        session_id: SessionId,
        *,
        initial_resync_required: bool = True,
    ) -> None:
        from l2200_notification.polling_channel import register_process_notification_wake

        self._provider = provider
        self._channels = channels
        self._session_id = session_id
        self._seen_notification_ids: dict[str, AwareDatetime] = {}
        self._pending: deque[NotificationWaitResult] = deque()
        self._forward_cursor: int | None = None
        self._wake_event = threading.Event()
        self._initial_resync_pending = initial_resync_required
        now = datetime.now(UTC)
        self._last_poll_at = now
        self._last_successful_poll_at = now
        self._unsubscribe_wake = register_process_notification_wake(channels, self._wake_event.set)

    def close(self) -> None:
        self._unsubscribe_wake()
        self._wake_event.set()

    def _poll_bounded(self, now: AwareDatetime) -> None:
        from l2000_connection.connection_plan_workflows import SyncReadPlanWorkflow, run_read_plan_workflow
        from l2200_notification.polling_channel import (
            DEFAULT_MAX_FORWARD_PAGES,
            DEFAULT_POLL_OVERLAP_SIZE,
            DEFAULT_POLL_PAGE_SIZE,
            DEFAULT_POLL_TAIL_SIZE,
            NotificationForwardPollRequest,
            NotificationOverlapPollRequest,
            NotificationRow,
            NotificationSequence,
            NotificationTailPollRequest,
            poll_notifications_forward_lazy,
            poll_notifications_overlap_lazy,
            poll_notifications_tail_lazy,
        )

        def _read(
            request: NotificationForwardPollRequest | NotificationOverlapPollRequest | NotificationTailPollRequest,
        ) -> tuple[NotificationRow, ...]:
            if isinstance(request, NotificationOverlapPollRequest):
                build = lambda txn: poll_notifications_overlap_lazy(txn, request)
            elif isinstance(request, NotificationTailPollRequest):
                build = lambda txn: poll_notifications_tail_lazy(txn, request)
            else:
                build = lambda txn: poll_notifications_forward_lazy(txn, request)
            with self._provider.acquire_sync_context() as conn:
                rows = run_read_plan_workflow(
                    conn,
                    SyncReadPlanWorkflow[list[NotificationRow]](session_id=self._session_id, build=build),
                )
                return tuple(rows)

        channels = tuple(sorted(self._channels))
        rows: list[NotificationRow] = []
        resync_required = False
        if self._forward_cursor is None:
            tail = _read(NotificationTailPollRequest(now=now, channels=channels, page_size=DEFAULT_POLL_TAIL_SIZE + 1))
            resync_required = len(tail) > DEFAULT_POLL_TAIL_SIZE
            rows.extend(reversed(tail[:DEFAULT_POLL_TAIL_SIZE]))
            self._forward_cursor = max((int(row.sequence_id) for row in rows), default=0)
        else:
            page_was_full = False
            for _page_number in range(DEFAULT_MAX_FORWARD_PAGES):
                page = _read(
                    NotificationForwardPollRequest(
                        now=now,
                        channels=channels,
                        after_sequence=NotificationSequence(self._forward_cursor),
                        page_size=DEFAULT_POLL_PAGE_SIZE,
                    )
                )
                page_was_full = len(page) == DEFAULT_POLL_PAGE_SIZE
                rows.extend(page)
                if page:
                    self._forward_cursor = max(int(row.sequence_id) for row in page)
                if not page_was_full:
                    break
            if page_was_full:
                overload_tail = list(_read(NotificationTailPollRequest(now=now, channels=channels, page_size=DEFAULT_POLL_TAIL_SIZE)))
                overload_tail.reverse()
                rows.extend(overload_tail)
                if overload_tail:
                    self._forward_cursor = max(
                        self._forward_cursor,
                        max(int(row.sequence_id) for row in overload_tail),
                    )
                resync_required = True
            overlap = _read(
                NotificationOverlapPollRequest(
                    now=now,
                    channels=channels,
                    after_sequence=NotificationSequence(max(0, self._forward_cursor - DEFAULT_POLL_OVERLAP_SIZE)),
                    through_sequence=NotificationSequence(self._forward_cursor),
                    page_size=DEFAULT_POLL_OVERLAP_SIZE,
                )
            )
            rows.extend(reversed(overlap))

        self._seen_notification_ids = {row_id: expiry for row_id, expiry in self._seen_notification_ids.items() if expiry > now}
        for row in rows:
            row_id = str(row.sys_id)
            if row_id in self._seen_notification_ids:
                continue
            self._seen_notification_ids[row_id] = row.expires_at
            self._pending.append(
                NotificationWaitResult(
                    reason=NotificationWaitReason.NOTIFICATION,
                    channel=NotificationChannelName(row.channel),
                    payload=NotificationPayload(row.payload),
                )
            )
        if resync_required:
            self._pending.append(
                NotificationWaitResult(
                    reason=NotificationWaitReason.RESYNC_REQUIRED,
                    channel=min(self._channels),
                    resync_cause=NotificationResyncCause.NOTIFICATION_OVERFLOW,
                )
            )

    def wait[TWake](
        self,
        *,
        deadline: NotificationDeadlineSpec,
        stop_signal: SyncNotificationStopSignal[TWake],
    ) -> NotificationWaitResult:
        deadline_at = deadline.at if isinstance(deadline, NotificationDeadline) else None
        if self._initial_resync_pending:
            self._initial_resync_pending = False
            return NotificationWaitResult(
                reason=NotificationWaitReason.RESYNC_REQUIRED,
                resync_cause=NotificationResyncCause.SUBSCRIPTION_ESTABLISHED,
            )
        interval = 0.01
        while not stop_signal.is_set():
            now = datetime.now(UTC)
            if deadline_at is not None and deadline_at <= now:
                return NotificationWaitResult(reason=NotificationWaitReason.DEADLINE)
            if self._pending:
                return self._pending.popleft()
            if poll_gap_lost_notifications(last_poll_at=self._last_successful_poll_at, now=now):
                self._last_successful_poll_at = now
                return NotificationWaitResult(
                    reason=NotificationWaitReason.RESYNC_REQUIRED,
                    resync_cause=NotificationResyncCause.POLL_GAP_EXCEEDED_TTL,
                )
            try:
                self._poll_bounded(now)
            except _notification_transport_failures():
                return NotificationWaitResult(
                    reason=NotificationWaitReason.RESYNC_REQUIRED,
                    resync_cause=NotificationResyncCause.POLL_FAILED,
                )
            self._last_successful_poll_at = now
            self._last_poll_at = now
            if self._pending:
                return self._pending.popleft()
            timeout = interval
            if deadline_at is not None:
                timeout = min(timeout, max(0.0, (deadline_at - datetime.now(UTC)).total_seconds()))
            if self._wake_event.wait(timeout):
                self._wake_event.clear()
                interval = 0.01
            else:
                interval = min(interval * 2, 0.25)
        return NotificationWaitResult(reason=NotificationWaitReason.STOPPED)


@contextlib.contextmanager
def sync_notification_subscription(
    provider: ConnectionProvider,
    channels: frozenset[NotificationChannelName],
    *,
    session_id: SessionId,
    initial_resync_required: bool = False,
) -> Generator[SyncNotificationSubscription]:
    """Open a portable synchronous polling subscription."""
    subscription = _SyncPollingNotificationSubscription(
        provider,
        channels,
        session_id,
        initial_resync_required=initial_resync_required,
    )
    try:
        yield subscription
    finally:
        subscription.close()


class _ReconnectableNativeNotificationSubscription(AsyncNotificationSubscription):
    """Keep one provider lease alive across native transport connection epochs."""

    def __init__(
        self,
        pool: AsyncConnectionPool,
        channels: frozenset[NotificationChannelName],
        session_id: SessionId,
    ) -> None:
        self._pool = pool
        self._channels = channels
        self._session_id = session_id
        self._context: contextlib.AbstractAsyncContextManager[NotificationChannel] | None = None
        self._delegate: ChannelAsyncNotificationSubscription | None = None
        self._lifecycle_lock = asyncio.Lock()

    async def open(self) -> None:
        async with self._lifecycle_lock:
            if self._delegate is not None:
                return
            context = self._pool.notification_channel_context(session_id=self._session_id)
            channel = await context.__aenter__()
            try:
                for channel_name in self._channels:
                    await channel.subscribe(channel_name)
            except BaseException:
                await context.__aexit__(None, None, None)
                raise
            self._context = context
            self._delegate = ChannelAsyncNotificationSubscription(channel)

    async def wait_async[TWake](
        self,
        *,
        deadline: NotificationDeadlineSpec,
        stop_signal: AsyncNotificationStopSignal[TWake],
    ) -> NotificationWaitResult:
        await self.open()
        delegate = self._delegate
        if delegate is None:
            return NotificationWaitResult(reason=NotificationWaitReason.CLOSED)
        result = await delegate.wait_async(deadline=deadline, stop_signal=stop_signal)
        if result.resync_cause in {
            NotificationResyncCause.TRANSPORT_ERROR,
            NotificationResyncCause.TRANSPORT_CLOSED,
        }:
            await self._close_epoch()
        return result

    async def _close_epoch(self) -> None:
        async with self._lifecycle_lock:
            delegate = self._delegate
            context = self._context
            self._delegate = None
            self._context = None
            if delegate is not None:
                await delegate.close()
            if context is not None:
                await context.__aexit__(None, None, None)

    async def close(self) -> None:
        await self._close_epoch()


@contextlib.asynccontextmanager
async def pool_notification_subscription(
    provider: ConnectionProvider,
    pool: AsyncConnectionPool,
    channels: frozenset[NotificationChannelName],
    *,
    session_id: SessionId,
) -> AsyncGenerator[AsyncNotificationSubscription]:
    """Open a native or portable asynchronous subscription."""
    from l1200_capabilities.capabilities import BackendCapability

    async with provider.acquire() as probe:
        capabilities = frozenset(probe.get_capabilities())
    if BackendCapability.REALTIME_NOTIFY not in capabilities:
        subscription = _AsyncPollingNotificationSubscription(provider, channels, session_id)
        await subscription.establish()
        try:
            yield subscription
        finally:
            await subscription.close()
        return
    native_subscription = _ReconnectableNativeNotificationSubscription(pool, channels, session_id)
    await native_subscription.open()
    try:
        yield native_subscription
    finally:
        await native_subscription.close()

