"""Bounded, same-task re-entrant connection provider wrappers."""

from __future__ import annotations

import asyncio
import threading
from collections.abc import AsyncGenerator, Generator
from contextlib import AbstractAsyncContextManager, AbstractContextManager, asynccontextmanager, contextmanager
from contextvars import ContextVar, Token
from dataclasses import dataclass

from l2000_connection.connection import AsyncDatabaseConnection, SyncDatabaseConnection
from l2000_connection.connection_provider import ConnectionProvider


class DatabaseAcquisitionTimeout(RuntimeError):
    """Raised when acquisition waits too long for connection capacity."""

    def __init__(self, timeout_seconds: float, max_concurrent: int) -> None:
        self.timeout_seconds = timeout_seconds
        self.max_concurrent = max_concurrent
        super().__init__(f"Timed out after {timeout_seconds:.2f}s waiting for database capacity (max_concurrent={max_concurrent})")


class MixedConnectionLeaseModeError(RuntimeError):
    """Raised when code tries to mix sync and async lease modes."""


class NoCurrentTaskId:
    pass


class NoSyncLease:
    pass


_NO_CURRENT_TASK_ID = NoCurrentTaskId()
_NO_SYNC_LEASE = NoSyncLease()

type CurrentTaskId = int | NoCurrentTaskId
type SyncLeaseState = _SyncLease | NoSyncLease


@dataclass(slots=True)
class _AsyncLease:
    owner_task_id: int
    conn: AsyncDatabaseConnection
    ctx: AbstractAsyncContextManager[AsyncDatabaseConnection]
    depth: int = 1


@dataclass(slots=True)
class _SyncLease:
    owner_thread_id: int
    owner_task_id: CurrentTaskId
    conn: SyncDatabaseConnection
    ctx: AbstractContextManager[SyncDatabaseConnection]
    depth: int = 1


class BoundedReentrantConnectionProvider(ConnectionProvider):
    """Wrap a provider with bounded outer acquisition and same-task reuse."""

    def __init__(
        self,
        base_provider: ConnectionProvider,
        *,
        max_concurrent: int,
        acquire_timeout_seconds: float,
    ) -> None:
        self._base_provider = base_provider
        self._max_concurrent = max(1, max_concurrent)
        self._acquire_timeout_seconds = max(0.0, acquire_timeout_seconds)
        self._capacity = threading.BoundedSemaphore(self._max_concurrent)
        self._async_lease: ContextVar[_AsyncLease | None] = ContextVar(
            "data_layer_bounded_async_lease",
            default=None,
        )
        self._sync_local = threading.local()

    @property
    def max_concurrent(self) -> int:
        return self._max_concurrent

    @property
    def acquire_timeout_seconds(self) -> float:
        return self._acquire_timeout_seconds

    @asynccontextmanager
    async def _acquire_async_context_impl(self) -> AsyncGenerator[AsyncDatabaseConnection]:
        owner_task_id = self._require_current_task_id()
        existing = self._async_lease.get()
        if existing is not None and existing.owner_task_id == owner_task_id:
            existing.depth += 1
            try:
                yield existing.conn
            finally:
                existing.depth -= 1
            return
        sync_existing = self._get_sync_lease()
        if type(sync_existing) is _SyncLease and sync_existing.owner_thread_id == threading.get_ident():
            msg = "Cannot acquire an async connection lease while a sync lease is active on this thread"
            raise MixedConnectionLeaseModeError(msg)

        acquired = await self._acquire_capacity_async()
        if not acquired:
            raise DatabaseAcquisitionTimeout(
                self._acquire_timeout_seconds,
                self._max_concurrent,
            )

        lease: _AsyncLease | None = None
        token: Token | None = None
        outer_closed = False
        try:
            ctx = self._base_provider.acquire()
            conn = await ctx.__aenter__()
            lease = _AsyncLease(owner_task_id=owner_task_id, conn=conn, ctx=ctx)
            token = self._async_lease.set(lease)
            try:
                yield conn
            except BaseException as exc:
                try:
                    suppressed = await lease.ctx.__aexit__(type(exc), exc, exc.__traceback__)
                finally:
                    if token is not None:
                        self._async_lease.reset(token)
                        token = None
                    outer_closed = True
                    self._capacity.release()
                if not suppressed:
                    raise
        finally:
            if lease is None:
                self._capacity.release()
            elif not outer_closed:
                try:
                    await lease.ctx.__aexit__(None, None, None)
                finally:
                    if token is not None:
                        self._async_lease.reset(token)
                    self._capacity.release()

    @contextmanager
    def _acquire_sync_context_impl(self) -> Generator[SyncDatabaseConnection]:
        owner_thread_id = threading.get_ident()
        existing = self._get_sync_lease()
        if type(existing) is _SyncLease and existing.owner_thread_id == owner_thread_id:
            existing.depth += 1
            try:
                yield existing.conn
            finally:
                existing.depth -= 1
            return
        async_existing = self._async_lease.get()
        if async_existing is not None:
            msg = "Cannot acquire a sync connection lease while an async lease is active in this context"
            raise MixedConnectionLeaseModeError(msg)

        acquired = self._capacity.acquire(timeout=self._acquire_timeout_seconds)
        if not acquired:
            raise DatabaseAcquisitionTimeout(
                self._acquire_timeout_seconds,
                self._max_concurrent,
            )

        lease: _SyncLease | None = None
        outer_closed = False
        try:
            ctx = self._base_provider.acquire_sync_context()
            conn = ctx.__enter__()
            lease = _SyncLease(
                owner_thread_id=owner_thread_id,
                owner_task_id=self._maybe_current_task_id(),
                conn=conn,
                ctx=ctx,
            )
            self._set_sync_lease(lease)
            try:
                yield conn
            except BaseException as exc:
                try:
                    suppressed = lease.ctx.__exit__(type(exc), exc, exc.__traceback__)
                finally:
                    self._clear_sync_lease()
                    outer_closed = True
                    self._capacity.release()
                if not suppressed:
                    raise
        finally:
            if lease is None:
                self._capacity.release()
            elif not outer_closed:
                try:
                    lease.ctx.__exit__(None, None, None)
                finally:
                    self._clear_sync_lease()
                    self._capacity.release()

    def _get_sync_lease(self) -> SyncLeaseState:
        try:
            lease = self._sync_local.lease
        except AttributeError:
            return _NO_SYNC_LEASE
        return lease if type(lease) is _SyncLease else _NO_SYNC_LEASE

    def _set_sync_lease(self, lease: _SyncLease) -> None:
        self._sync_local.lease = lease

    def _clear_sync_lease(self) -> None:
        if hasattr(self._sync_local, "lease"):
            del self._sync_local.lease

    async def _acquire_capacity_async(self) -> bool:
        deadline = asyncio.get_running_loop().time() + self._acquire_timeout_seconds
        poll_interval_seconds = 0.005
        while True:
            if self._capacity.acquire(blocking=False):
                return True
            if self._acquire_timeout_seconds == 0.0:
                return False
            remaining = deadline - asyncio.get_running_loop().time()
            if remaining <= 0:
                return False
            await asyncio.sleep(min(poll_interval_seconds, remaining))

    @staticmethod
    def _require_current_task_id() -> int:
        task = asyncio.current_task()
        if task is None:
            msg = "BoundedReentrantConnectionProvider.acquire() requires a running asyncio task"
            raise RuntimeError(msg)
        return id(task)

    @staticmethod
    def _maybe_current_task_id() -> CurrentTaskId:
        try:
            task = asyncio.current_task()
        except RuntimeError:
            return _NO_CURRENT_TASK_ID
        if task is None:
            return _NO_CURRENT_TASK_ID
        return id(task)


def maybe_wrap_bounded_connection_provider(
    base_provider: ConnectionProvider,
    *,
    enabled: bool,
    max_concurrent: int,
    acquire_timeout_seconds: float,
) -> ConnectionProvider:
    """Return the bounded provider when enabled, else the original provider."""

    if not enabled:
        return base_provider
    return BoundedReentrantConnectionProvider(
        base_provider,
        max_concurrent=max_concurrent,
        acquire_timeout_seconds=acquire_timeout_seconds,
    )


__all__ = [
    "BoundedReentrantConnectionProvider",
    "DatabaseAcquisitionTimeout",
    "MixedConnectionLeaseModeError",
    "maybe_wrap_bounded_connection_provider",
]

