"""Semantic schema-artifact dependency planning.

This module intentionally separates the *schema contract* from the eventual SQL
statements a backend emits. The split is the guardrail that was missing when
staged-log triggers and graph auxiliary maintenance depended on incidental
enqueue order: a trigger can be declared before its tables are declared in
Python, but it must never be realized before the tables and columns it names are
materialized in the database.
"""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from enum import StrEnum


class SchemaArchitectureError(RuntimeError):
    """Raised when schema planning violates an architecture invariant."""


class UnsupportedSchemaDependencyCycle(SchemaArchitectureError):
    """Raised when a backend cannot realize a hard materialization cycle."""


class SchemaArtifactSubject(str):
    """Branded semantic identity for a schema artifact."""

    __slots__ = ()


class SchemaBackendScope(str):
    """Branded backend realization scope for a schema artifact."""

    __slots__ = ()


class SchemaArtifactKind(StrEnum):
    """Backend-neutral identities for durable schema facts."""

    TABLE = "table"
    COLUMN = "column"
    CANDIDATE_KEY = "candidate_key"
    INDEX = "index"
    FOREIGN_KEY = "foreign_key"
    TRIGGER = "trigger"
    METADATA = "metadata"
    SHARED_SUPPORT = "shared_support"


@dataclass(frozen=True, order=True, slots=True)
class SchemaArtifactKey:
    """Stable semantic identity for one schema artifact.

    The key is deliberately smaller than rendered SQL. Dedupe and deterministic
    ordering use semantic identity so a backend can choose different physical
    realization shapes without reintroducing enqueue-order dependencies.
    """

    kind: SchemaArtifactKind
    subject: SchemaArtifactSubject
    backend_scope: SchemaBackendScope = SchemaBackendScope("")


@dataclass(frozen=True, slots=True)
class SchemaArtifactDeclaration:
    """Pure declaration of artifacts and their requirements.

    ``requires_declared`` means the complete schema contract must contain the
    artifact. ``requires_materialized`` is stronger: the backend must have made
    that artifact physically available before this declaration's realization can
    execute. SQLite inline foreign keys are a declared requirement without a
    target-table execution edge; trigger bodies are hard materialization edges
    because the database validates the referenced tables/columns at trigger
    creation time.
    """

    key: SchemaArtifactKey
    provides: frozenset[SchemaArtifactKey]
    requires_declared: frozenset[SchemaArtifactKey] = frozenset()
    requires_materialized: frozenset[SchemaArtifactKey] = frozenset()


@dataclass(frozen=True, slots=True)
class FrozenSchemaArtifactGraph:
    """Immutable, validated schema contract before backend realization."""

    declarations: tuple[SchemaArtifactDeclaration, ...]
    provided_artifacts: frozenset[SchemaArtifactKey]


@dataclass(frozen=True, slots=True)
class SchemaArtifactGraph:
    """Builder for a complete schema artifact contract.

    The builder is value-shaped and does not expose mutation APIs; callers create
    a graph from all declarations and then finalize it before any SQL lowering.
    """

    declarations: tuple[SchemaArtifactDeclaration, ...] = ()

    def finalize(self: SchemaArtifactGraph) -> FrozenSchemaArtifactGraph:
        provided: set[SchemaArtifactKey] = set()
        producer_by_key: dict[SchemaArtifactKey, SchemaArtifactDeclaration] = {}
        for declaration in self.declarations:
            for artifact in declaration.provides:
                existing = producer_by_key.get(artifact)
                if existing is not None and existing != declaration:
                    msg = f"conflicting schema artifact producer for {artifact.subject}"
                    raise SchemaArchitectureError(msg)
                producer_by_key[artifact] = declaration
                provided.add(artifact)

        for declaration in self.declarations:
            missing = (declaration.requires_declared | declaration.requires_materialized) - provided
            if missing:
                names = ", ".join(sorted(artifact.subject for artifact in missing))
                msg = f"missing declared schema artifact for {declaration.key.subject}: {names}"
                raise SchemaArchitectureError(msg)

        ordered = tuple(sorted(self.declarations, key=lambda declaration: declaration.key))
        return FrozenSchemaArtifactGraph(
            declarations=ordered,
            provided_artifacts=frozenset(provided),
        )


@dataclass(frozen=True, slots=True)
class BackendRealizationCapability:
    """Backend capabilities that affect hard dependency realization."""

    atomic_hard_cycles: bool = False


@dataclass(frozen=True, slots=True)
class FrozenRealizationPlan:
    """Deterministic backend realization order for a frozen artifact graph."""

    ordered_artifacts: tuple[SchemaArtifactKey, ...]
    dependency_edges: frozenset[tuple[SchemaArtifactKey, SchemaArtifactKey]] = field(default_factory=frozenset)

    @classmethod
    def from_artifact_graph(
        cls: type[FrozenRealizationPlan],
        graph: FrozenSchemaArtifactGraph,
        *,
        capability: BackendRealizationCapability = BackendRealizationCapability(),
    ) -> FrozenRealizationPlan:
        resolved_capability = capability
        provider: dict[SchemaArtifactKey, SchemaArtifactDeclaration] = {}
        for declaration in graph.declarations:
            for artifact in declaration.provides:
                provider[artifact] = declaration

        artifacts = tuple(sorted(graph.provided_artifacts))
        incoming: dict[SchemaArtifactKey, set[SchemaArtifactKey]] = {artifact: set() for artifact in artifacts}
        outgoing: dict[SchemaArtifactKey, set[SchemaArtifactKey]] = {artifact: set() for artifact in artifacts}
        edges: set[tuple[SchemaArtifactKey, SchemaArtifactKey]] = set()
        for declaration in graph.declarations:
            for required in declaration.requires_materialized:
                for provided in declaration.provides:
                    outgoing[required].add(provided)
                    incoming[provided].add(required)
                    edges.add((required, provided))

        ready = [artifact for artifact in artifacts if not incoming[artifact]]
        ordered: list[SchemaArtifactKey] = []
        while ready:
            current = ready.pop(0)
            ordered.append(current)
            for dependent in sorted(outgoing[current]):
                incoming[dependent].remove(current)
                if not incoming[dependent]:
                    ready.append(dependent)
            ready.sort()

        if len(ordered) != len(artifacts):
            cyclic = tuple(sorted(artifact for artifact in artifacts if incoming[artifact]))
            if not resolved_capability.atomic_hard_cycles:
                names = ", ".join(artifact.subject for artifact in cyclic)
                msg = f"unsupported hard schema dependency cycle: {names}"
                raise UnsupportedSchemaDependencyCycle(msg)
            ordered.extend(cyclic)

        # Keep declaration objects referenced until here so static analysis sees
        # that realization is derived from immutable data, not callback effects.
        del provider
        return cls(ordered_artifacts=tuple(ordered), dependency_edges=frozenset(edges))

