"""Shared runtime primitives for connection core mixins."""

from __future__ import annotations

import logging
import sys
import types
from collections.abc import Iterator, Mapping
from dataclasses import dataclass, field
from enum import Enum

from typing import Self


from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
from l1400_types.type_surface_contracts import (
    BootstrapFactsHash,
    ConnectionPayloadOpaqueMarker as ConnectionPayloadOpaqueMarker,
    SessionHandlePayloadOpaqueMarker as SessionHandlePayloadOpaqueMarker,
    DiagnosticMessage,
    NoBootstrapFactsHash,
)
from l2000_connection.deferred_imports import ConnectionModuleName, load_connection_module
from l2092_timing_tracking.transaction_efficiency import TransactionOwnedWork, start_transaction_owned_work
from l2000_connection.sync_async_guard import (
    MethodName,
    check_not_in_async_context as _shared_check_not_in_async_context,
)

logger = logging.getLogger(__name__)


class TransactionModeName(str):
    """Logical transaction execution mode."""


class TransactionTraceLabel(str):
    """Optional caller label attached to a transaction trace."""


class TransactionAttemptNumber(int):
    """One-based transaction retry attempt number."""


@dataclass(frozen=True, slots=True)
class NoTransactionTraceLabel:
    """Explicit absence of a transaction trace label."""

    def __bool__(self: NoTransactionTraceLabel) -> bool:
        return False


@dataclass(frozen=True, slots=True)
class NoTransactionAttempt:
    """Explicit absence of a transaction retry attempt."""

    def __bool__(self: NoTransactionAttempt) -> bool:
        return False


@dataclass(frozen=True, slots=True)
class NoTransactionMode:
    """Explicit absence of an active transaction mode."""

    def __bool__(self: NoTransactionMode) -> bool:
        return False


NO_TRANSACTION_TRACE_LABEL = NoTransactionTraceLabel()
NO_TRANSACTION_ATTEMPT = NoTransactionAttempt()
NO_TRANSACTION_MODE = NoTransactionMode()
type TransactionTraceLabelState = TransactionTraceLabel | NoTransactionTraceLabel
type TransactionAttemptState = TransactionAttemptNumber | NoTransactionAttempt
type TransactionModeState = TransactionModeName | NoTransactionMode


class DataTransactionBackendState(str, Enum):
    """Projected physical backend transaction state for a logical data transaction."""

    NOT_STARTED = "not_started"
    OPEN = "open"
    COMMITTED = "committed"
    ROLLED_BACK = "rolled_back"


@dataclass(slots=True)
class DataTransactionSidecar:
    """Transaction-local physical backend state, separate from logical scope state."""

    read_only: bool
    mode: TransactionModeName
    label: TransactionTraceLabelState = NO_TRANSACTION_TRACE_LABEL
    attempt: TransactionAttemptState = NO_TRANSACTION_ATTEMPT
    backend_state: DataTransactionBackendState = DataTransactionBackendState.NOT_STARTED
    requires_repeatable_snapshot: bool = False

    @property
    def backend_open(self: DataTransactionSidecar) -> bool:
        return self.backend_state is DataTransactionBackendState.OPEN


@dataclass(frozen=True, slots=True)
class DataTransactionExecutionFacts:
    """Immutable snapshot of backend transaction state for planning contexts."""

    logical_active: bool
    backend_state: DataTransactionBackendState
    read_only: bool
    mode: TransactionModeState = NO_TRANSACTION_MODE


@dataclass(slots=True)
class _TransactionTraceState:
    mode: TransactionModeName
    read_only: bool
    label: TransactionTraceLabelState
    attempt: TransactionAttemptState
    started_at_monotonic: float
    started_at_unix: float
    start_stack: tuple[DiagnosticMessage, ...]
    db_active_ms: float = 0.0
    db_operation_count: int = 0
    owned_work: TransactionOwnedWork = field(default_factory=start_transaction_owned_work)

    def __post_init__(self: _TransactionTraceState) -> None:
        self.start_stack = tuple(DiagnosticMessage(str(frame)) for frame in self.start_stack)


class BootstrapScopeVerificationKey(str):
    """Stable identity of one verified bootstrap scope."""


class BootstrapSeedFactKey(str):
    """Identity of one seed fact contributing to bootstrap proof."""


@dataclass(frozen=True, slots=True)
class NoBootstrapScopeVerificationKey:
    """Explicit absence of a bootstrap scope verification key."""


NO_BOOTSTRAP_SCOPE_VERIFICATION_KEY = NoBootstrapScopeVerificationKey()
type BootstrapScopeVerificationKeyState = BootstrapScopeVerificationKey | NoBootstrapScopeVerificationKey


class _ImmutableBootstrapMap[TKey, TValue](Mapping[TKey, TValue]):
    """Immutable mapping work product used by bootstrap proof state."""

    __slots__ = ("_values",)

    def __init__(self: Self, entries: tuple[tuple[TKey, TValue], ...]) -> None:
        self._values = types.MappingProxyType(dict(entries))

    def __getitem__(self: _ImmutableBootstrapMap[TKey, TValue], key: TKey) -> TValue:
        return self._values[key]

    def __iter__(self: _ImmutableBootstrapMap[TKey, TValue]) -> Iterator[TKey]:
        return iter(self._values)

    def __len__(self: _ImmutableBootstrapMap[TKey, TValue]) -> int:
        return len(self._values)


class BootstrapTableExistenceFacts(_ImmutableBootstrapMap[SqlTableName, bool]):
    """Physical table-existence facts behind a bootstrap proof."""


class BootstrapSeedFactHashes(_ImmutableBootstrapMap[BootstrapSeedFactKey, BootstrapFactsHash]):
    """Seed facts behind a bootstrap proof, keyed by producer identity."""


EMPTY_BOOTSTRAP_TABLE_EXISTENCE_FACTS = BootstrapTableExistenceFacts(())
EMPTY_BOOTSTRAP_SEED_FACT_HASHES = BootstrapSeedFactHashes(())


class BootstrapMode(str, Enum):
    """Bootstrap state for a required schema slice on one connection."""

    WARM = "warm"
    PRESEEDED = "preseeded"


@dataclass(frozen=True, slots=True)
class BootstrapScopeProof:
    """Classified bootstrap state plus the existence evidence behind it."""

    mode: BootstrapMode
    required_tables: tuple[SqlTableName, ...]
    exists_by_table: BootstrapTableExistenceFacts = field(
        default_factory=lambda: EMPTY_BOOTSTRAP_TABLE_EXISTENCE_FACTS,
    )
    verification_key: BootstrapScopeVerificationKeyState = NO_BOOTSTRAP_SCOPE_VERIFICATION_KEY
    seed_fact_hashes: BootstrapSeedFactHashes = field(
        default_factory=lambda: EMPTY_BOOTSTRAP_SEED_FACT_HASHES,
    )
    facts_hash: BootstrapFactsHash | NoBootstrapFactsHash = NoBootstrapFactsHash()

    def __post_init__(self: BootstrapScopeProof) -> None:
        normalized_required_tables = tuple(dict.fromkeys(SqlTableName(table_name) for table_name in self.required_tables))
        object.__setattr__(self, "required_tables", normalized_required_tables)

    def missing_tables(self: BootstrapScopeProof) -> tuple[SqlTableName, ...]:
        """Return required table names still absent under this proof."""
        return tuple(table_name for table_name in self.required_tables if not bool(self.exists_by_table.get(table_name, False)))

    def all_tables_exist(self: BootstrapScopeProof) -> bool:
        """Return whether every required table already exists."""
        return all(bool(self.exists_by_table.get(table_name, False)) for table_name in self.required_tables)


def _interpreter_is_shutting_down() -> bool:
    """Return whether Python finalization has started."""
    return sys.is_finalizing() or sys.meta_path is None


def _imp_api_l2050_transaction() -> types.ModuleType:
    module: types.ModuleType = load_connection_module(ConnectionModuleName("l2050_transaction.transaction"))
    return module


def _check_not_in_async_context(method_name: MethodName) -> None:
    """Raise error if sync method is called from async context."""
    _shared_check_not_in_async_context(method_name)

