from __future__ import annotations

from collections import ChainMap, deque
from collections.abc import Hashable, Mapping, Sequence
from copy import copy
from dataclasses import dataclass, fields, is_dataclass, replace
from types import MappingProxyType
from typing import TYPE_CHECKING, cast

from pydantic import BaseModel, RootModel, Secret

from l1000_schema.schema_def import DatabaseObjectRow
from l2000_connection.connection_lazy_return_registry import (
    PlanScopeReturnName,
    _is_symbolic_named_value,
    _register_named_lazy_return,
)

if TYPE_CHECKING:
    from impl.common.l2070_server_plan.base_server_plan import BaseServerPlan
    from l2080_lazy_orm.lazy_row import LazyRow

# Generated by scripts/codemods/extract_connection_core_residue.py from l2000_connection/connection.py.
# Run import hygiene and focused connection tests after applying this codemod.


class PlanScopeFetchPathComponent(str):
    """Branded component in a plan-scope fetch template path."""

    __slots__ = ()


type PlanScopeFetchPath = tuple[PlanScopeFetchPathComponent, ...]


@dataclass(frozen=True, slots=True)
class NoPlanScopeLazyRow:
    """Sentinel for fetch tokens that are not backed by a LazyRow."""


NO_PLAN_SCOPE_LAZY_ROW = NoPlanScopeLazyRow()


class PlanScopeFetchResults(dict[PlanScopeReturnName, object]):
    """Concrete result map returned by plan-scope execution."""


@dataclass(frozen=True, slots=True)
class MissingServerRefValue:
    """Sentinel for unresolved nested ServerRef values."""


MISSING_SERVER_REF_VALUE = MissingServerRefValue()


@dataclass(frozen=True, slots=True)
class ServerRefValueResolution[T]:
    """Explicit result for resolving a nested ServerRef value."""

    found: bool
    value: T | MissingServerRefValue = MISSING_SERVER_REF_VALUE


@dataclass(frozen=True, slots=True)
class _PlanScopeFetchToken:
    name: PlanScopeReturnName
    scalar_row_id: bool = False
    lazy_row: LazyRow | NoPlanScopeLazyRow = NO_PLAN_SCOPE_LAZY_ROW


@dataclass(frozen=True, slots=True)
class CallbackResultTemplate[T]:
    """Callback result template with an explicit plan-execution requirement."""

    value: T
    requires_plan_execution: bool


def _plan_scope_fetch_name(path: PlanScopeFetchPath) -> PlanScopeReturnName:
    return PlanScopeReturnName("__fetch__." + "|".join(f"{len(str(part))}:{part}" for part in path))


def _mapping_key_path_component(key: Hashable) -> PlanScopeFetchPathComponent:
    if not isinstance(key, str):
        msg = f"Named callback result fields require string keys, got {type(key).__name__}."
        raise TypeError(msg)
    return PlanScopeFetchPathComponent(f"field:{len(key)}:{key}")


def _mapping_index_path_component(index: int) -> PlanScopeFetchPathComponent:
    return PlanScopeFetchPathComponent(f"map:{index}")


def _sequence_path_component(kind: PlanScopeFetchPathComponent, index: int) -> PlanScopeFetchPathComponent:
    return PlanScopeFetchPathComponent(f"{kind}:{index}")


def _rebuild_dict_type[T: dict[object, object], TKey, TValue](
    original: T,
    items: Sequence[tuple[TKey, TValue]],
) -> T:
    rebuilt = copy(original)
    rebuilt.clear()
    rebuilt.update(items)
    return rebuilt


def _rebuild_tuple_type[T: tuple[object, ...], TItem](original: T, items: tuple[TItem, ...]) -> T:
    if type(original) is tuple:
        return cast("T", items)
    return cast("T", tuple.__new__(type(original), items))


def _rebuild_list_type[T: list[object], TItem](original: T, items: Sequence[TItem]) -> T:
    rebuilt = copy(original)
    rebuilt.clear()
    rebuilt.extend(items)
    return rebuilt


def _rebuild_deque_type[T](original: deque[T], items: Sequence[T]) -> deque[T]:
    rebuilt = copy(original)
    rebuilt.clear()
    rebuilt.extend(items)
    return rebuilt


def _plan_scope_fetch_template[T](scope: BaseServerPlan, value: T, path: PlanScopeFetchPath) -> T:
    """Register symbolic leaves and return a template for reconstruction."""
    if _is_symbolic_named_value(value).is_symbolic:
        from l1400_types import ServerPlanRefId, SysId
        from l2055_lazy_result.lazy_result import LazyResult
        from l2080_lazy_orm.lazy_row import LazyRow
        from l2070_batching.server_ref import ScalarServerRef, ServerRefs, inspect_server_value_shape_for_planning

        if isinstance(value, LazyResult) and object.__getattribute__(value, "_operation") is None:
            return cast("T", object.__getattribute__(value, "_value"))
        name = _plan_scope_fetch_name(path)
        return_result = scope.return_result
        scalar_row_id = isinstance(value, ScalarServerRef)
        if isinstance(value, LazyResult):
            expected_type = value.expected_result_type()
            scalar_row_id = isinstance(expected_type, type) and issubclass(expected_type, SysId)
        if isinstance(value, ScalarServerRef):
            ref_id = str(value.ref_id)
            if ref_id.endswith(".sys_id") and "." in ref_id:
                base_ref_id = ref_id.removesuffix(".sys_id")
                return_result(
                    name,
                    ServerRefs.from_ref_id(
                        ServerPlanRefId(base_ref_id),
                        variant="object",
                    ),
                )
                return cast("T", _PlanScopeFetchToken(name, scalar_row_id=True))
        if not _register_named_lazy_return(scope, name, value).registered:
            if isinstance(value, LazyRow):
                return value
            if isinstance(value, LazyResult):
                shape = inspect_server_value_shape_for_planning(
                    value,
                    site="_plan_scope_fetch_template",
                )
                if shape.has_literal_value:
                    return cast("T", shape.literal_value)
            msg = f"Workflow result at {path!r} is symbolic but has no plan-owned return reference"
            raise TypeError(msg)
        return cast(
            "T",
            _PlanScopeFetchToken(
                name,
                scalar_row_id=scalar_row_id,
                lazy_row=value if isinstance(value, LazyRow) else NO_PLAN_SCOPE_LAZY_ROW,
            ),
        )
    if isinstance(value, BaseModel) and not isinstance(value, DatabaseObjectRow):
        resolved_fields = {
            item_name: _plan_scope_fetch_template(
                scope,
                getattr(value, item_name),
                (*path, _mapping_key_path_component(item_name)),
            )
            for item_name in type(value).model_fields
        }
        resolved_fields.update(
            {
                item_name: _plan_scope_fetch_template(
                    scope,
                    item,
                    (*path, _mapping_key_path_component(item_name)),
                )
                for item_name, item in (value.model_extra or {}).items()
            },
        )
        template_model = value.model_copy(update=resolved_fields)
        object.__setattr__(template_model, "__pydantic_fields_set__", set(value.model_fields_set))
        return cast("T", template_model)
    if is_dataclass(value) and not isinstance(value, type):
        resolved_fields = {
            item.name: _plan_scope_fetch_template(
                scope,
                getattr(value, item.name),
                (*path, _mapping_key_path_component(item.name)),
            )
            for item in fields(value)
            if item.init
        }
        return replace(value, **resolved_fields)
    if isinstance(value, dict):
        return cast(
            "T",
            _rebuild_dict_type(
                value,
                [
                    (
                        key,
                        _plan_scope_fetch_template(
                            scope,
                            item,
                            (*path, _mapping_index_path_component(index)),
                        ),
                    )
                    for index, (key, item) in enumerate(value.items())
                ],
            ),
        )
    if isinstance(value, ChainMap):
        return cast(
            "T",
            ChainMap(
                *(
                    _plan_scope_fetch_template(
                        scope,
                        mapping,
                        (*path, PlanScopeFetchPathComponent(f"chain-map:{index}")),
                    )
                    for index, mapping in enumerate(value.maps)
                ),
            ),
        )
    if isinstance(value, MappingProxyType):
        return cast(
            "T",
            MappingProxyType(
                {
                    key: _plan_scope_fetch_template(
                        scope,
                        item,
                        (*path, _mapping_index_path_component(index)),
                    )
                    for index, (key, item) in enumerate(value.items())
                },
            ),
        )
    if isinstance(value, tuple):
        return cast(
            "T",
            _rebuild_tuple_type(
                value,
                tuple(
                    _plan_scope_fetch_template(
                        scope,
                        item,
                        (*path, _sequence_path_component(PlanScopeFetchPathComponent("tuple"), index)),
                    )
                    for index, item in enumerate(value)
                ),
            ),
        )
    if isinstance(value, list):
        return cast(
            "T",
            _rebuild_list_type(
                value,
                [
                    _plan_scope_fetch_template(
                        scope,
                        item,
                        (*path, _sequence_path_component(PlanScopeFetchPathComponent("list"), index)),
                    )
                    for index, item in enumerate(value)
                ],
            ),
        )
    if isinstance(value, deque):
        return cast(
            "T",
            _rebuild_deque_type(
                value,
                [
                    _plan_scope_fetch_template(
                        scope,
                        item,
                        (*path, _sequence_path_component(PlanScopeFetchPathComponent("deque"), index)),
                    )
                    for index, item in enumerate(value)
                ],
            ),
        )
    return value


def _callback_result_template[T](scope: BaseServerPlan, result: T) -> CallbackResultTemplate[T]:
    """Register symbolic leaves and declare whether the callback left plan work."""
    template = _plan_scope_fetch_template(
        scope,
        result,
        (PlanScopeFetchPathComponent("callback_return"),),
    )
    pending: list[object] = [template]
    requires_plan_execution = False
    while pending:
        item = pending.pop()
        if isinstance(item, _PlanScopeFetchToken):
            requires_plan_execution = True
            break
        if isinstance(item, BaseModel) and not isinstance(item, DatabaseObjectRow):
            pending.extend(getattr(item, name) for name in type(item).model_fields)
            pending.extend((item.model_extra or {}).values())
        elif is_dataclass(item) and not isinstance(item, type):
            pending.extend(getattr(item, field.name) for field in fields(item) if field.init)
        elif isinstance(item, ChainMap):
            pending.extend(item.maps)
        elif isinstance(item, (dict, MappingProxyType)):
            pending.extend(item.values())
        elif isinstance(item, (tuple, list, deque)):
            pending.extend(item)
    return CallbackResultTemplate(
        value=template,
        requires_plan_execution=requires_plan_execution,
    )


def _resolve_callback_result_template[T, TKey: str, TValue](
    template: CallbackResultTemplate[T],
    values: Mapping[TKey, TValue],
) -> T:
    """Resolve one callback template from named ServerPlan values."""
    results = PlanScopeFetchResults((PlanScopeReturnName(name), value) for name, value in values.items())
    return _resolve_plan_scope_fetch_template(template.value, results)


def _resolve_plan_scope_fetch_template[T](template: T, results: PlanScopeFetchResults) -> T:
    def _resolve_server_ref_value(ref: object) -> ServerRefValueResolution[object]:
        from l2070_batching.server_ref import ServerRef

        if not isinstance(ref, ServerRef):
            return ServerRefValueResolution(found=False)
        ref_id = str(ref.ref_id)
        if ref_id in results:
            return ServerRefValueResolution(found=True, value=results[PlanScopeReturnName(ref_id)])
        if "." not in ref_id:
            return ServerRefValueResolution(found=False)
        base_ref, field_name = ref_id.split(".", 1)
        base_key = PlanScopeReturnName(base_ref)
        if base_key not in results:
            return ServerRefValueResolution(found=False)
        base_value = results[base_key]
        if isinstance(base_value, dict):
            if field_name in base_value:
                return ServerRefValueResolution(found=True, value=base_value[field_name])
            return ServerRefValueResolution(found=False)
        value = getattr(base_value, field_name, None)
        return ServerRefValueResolution(found=value is not None, value=value)

    if isinstance(template, _PlanScopeFetchToken):
        value = results[template.name]
        if not isinstance(template.lazy_row, NoPlanScopeLazyRow):
            template.lazy_row._store_materialized(value)
            return cast("T", template.lazy_row)
        if template.scalar_row_id:
            from l2070_batching.server_ref import ServerRef

            resolved_value = _resolve_server_ref_value(value)
            if resolved_value.found:
                value = resolved_value.value
            if isinstance(value, dict) and "sys_id" in value:
                row_id = value["sys_id"]
                resolved_row_id = _resolve_server_ref_value(row_id)
                if resolved_row_id.found:
                    return cast("T", resolved_row_id.value)
                return cast("T", row_id)
            row_id = getattr(value, "sys_id", None)
            if row_id is not None:
                resolved_row_id = _resolve_server_ref_value(row_id)
                if resolved_row_id.found:
                    return cast("T", resolved_row_id.value)
                return cast("T", row_id)
        return cast("T", value)
    if isinstance(template, BaseModel) and not isinstance(template, DatabaseObjectRow):
        resolved_fields = {
            item_name: _resolve_plan_scope_fetch_template(getattr(template, item_name), results)
            for item_name in type(template).model_fields
        }
        resolved_fields.update(
            {item_name: _resolve_plan_scope_fetch_template(item, results) for item_name, item in (template.model_extra or {}).items()},
        )
        validation_fields = {
            item_name: item.get_secret_value() if isinstance(item, Secret) else item
            for item_name, item in resolved_fields.items()
        }
        rebuilt_model = (
            type(template).model_validate(validation_fields["root"])
            if isinstance(template, RootModel)
            else type(template).model_validate(validation_fields)
        )
        object.__setattr__(rebuilt_model, "__pydantic_fields_set__", set(template.model_fields_set))
        private_state = object.__getattribute__(template, "__pydantic_private__")
        if private_state is not None:
            object.__setattr__(rebuilt_model, "__pydantic_private__", copy(private_state))
        return cast("T", rebuilt_model)
    if is_dataclass(template) and not isinstance(template, type):
        resolved_fields = {
            item.name: _resolve_plan_scope_fetch_template(getattr(template, item.name), results) for item in fields(template) if item.init
        }
        return replace(template, **resolved_fields)
    if isinstance(template, dict):
        return cast(
            "T",
            _rebuild_dict_type(
                template,
                [(key, _resolve_plan_scope_fetch_template(value, results)) for key, value in template.items()],
            ),
        )
    if isinstance(template, ChainMap):
        return cast(
            "T",
            ChainMap(*(_resolve_plan_scope_fetch_template(mapping, results) for mapping in template.maps)),
        )
    if isinstance(template, MappingProxyType):
        return cast(
            "T",
            MappingProxyType(
                {key: _resolve_plan_scope_fetch_template(value, results) for key, value in template.items()},
            ),
        )
    if isinstance(template, tuple):
        return cast(
            "T",
            _rebuild_tuple_type(
                template,
                tuple(_resolve_plan_scope_fetch_template(value, results) for value in template),
            ),
        )
    if isinstance(template, list):
        return cast(
            "T",
            _rebuild_list_type(
                template,
                [_resolve_plan_scope_fetch_template(value, results) for value in template],
            ),
        )
    if isinstance(template, deque):
        return cast(
            "T",
            _rebuild_deque_type(
                template,
                [_resolve_plan_scope_fetch_template(value, results) for value in template],
            ),
        )
    return template

