"""Task-local receipts recorded only after backend transaction acknowledgements."""

from __future__ import annotations

from collections.abc import Generator
from contextlib import contextmanager
from contextvars import ContextVar
from dataclasses import dataclass
from enum import Enum


@dataclass(slots=True)
class TransactionOutcome:
    """Observed database decisions, not requested transaction actions."""

    commit_count: int = 0
    rollback_count: int = 0
    driver_requests: int = 0
    result_sets: int = 0
    transaction_controls: int = 0

    @property
    def committed(self: TransactionOutcome) -> bool:
        return self.commit_count > 0


class _UnobservedOutcome(Enum):
    UNOBSERVED = "unobserved"


_active_outcome: ContextVar[TransactionOutcome | _UnobservedOutcome] = ContextVar(
    "transaction_outcome", default=_UnobservedOutcome.UNOBSERVED,
)


@contextmanager
def observe_transaction_outcome(outcome: TransactionOutcome) -> Generator[None]:
    token = _active_outcome.set(outcome)
    try:
        yield
    finally:
        _active_outcome.reset(token)


def record_transaction_commit() -> None:
    outcome = _active_outcome.get()
    if isinstance(outcome, TransactionOutcome):
        outcome.commit_count += 1


def record_transaction_rollback() -> None:
    outcome = _active_outcome.get()
    if isinstance(outcome, TransactionOutcome):
        outcome.rollback_count += 1

