"""Helpers for formatting connection URL components."""

from __future__ import annotations

from typing import NewType

UrlHost = NewType("UrlHost", str)


def format_url_host(host: UrlHost) -> UrlHost:
    """Return a URL authority host, bracketing IPv6 literals when needed."""
