"""Validated public types for Cypher identifiers."""

from __future__ import annotations

import re
from impl.common.l2050_sql_types.sql_branded_types import SqlTypeName

type CypherIdentifierText = str
type CypherRenderedText = str
type CypherEqualityOperand = object


def _validate_label(value: CypherIdentifierText, type_name: SqlTypeName) -> None:
    if not isinstance(value, str):
        msg = f"{type_name} must be a string, got {type(value).__name__}"
        raise TypeError(msg)
    if not value:
        msg = f"{type_name} cannot be empty"
        raise ValueError(msg)
    if "`" in value or ";" in value or "\\" in value:
        msg = f"{type_name} contains invalid characters: {value!r}"
        raise ValueError(msg)


_CYPHER_PROPERTY_REGEX = re.compile(r"^[a-zA-Z_][a-zA-Z0-9_]*$")


def validate_cypher_property(value: CypherIdentifierText) -> None:
    """Validate a Cypher property name."""
    if not value:
        msg = "Cypher property name cannot be empty"
        raise ValueError(msg)
    if not _CYPHER_PROPERTY_REGEX.match(value):
        msg = f"Invalid Cypher property name: {value!r}. Must be a valid identifier (letters, digits, underscores only)."
        raise ValueError(msg)


def _validate_property(value: CypherIdentifierText, type_name: SqlTypeName) -> None:
    if not isinstance(value, str):
        msg = f"{type_name} must be a string, got {type(value).__name__}"
        raise TypeError(msg)
    try:
        validate_cypher_property(value)
    except ValueError:
        if not value:
            msg = f"{type_name} cannot be empty"
        else:
            msg = (
                f"{type_name} must be a valid identifier (letters, digits, "
                f"underscores only, starting with letter or underscore): {value!r}"
            )
        raise ValueError(msg) from None


class CypherLabel(str):
    """Cypher node or relationship label."""

    def __new__(cls: type["CypherLabel"], value: CypherIdentifierText) -> "CypherLabel":
        _validate_label(value, SqlTypeName("CypherLabel"))
        instance: CypherLabel = str.__new__(cls, value)
        return instance

    def __repr__(self: "CypherLabel") -> CypherRenderedText:
        return f"CypherLabel({str(self)!r})"


class CypherProperty(str):
    """Cypher property name."""

    def __new__(cls: type["CypherProperty"], value: CypherIdentifierText) -> "CypherProperty":
        _validate_property(value, SqlTypeName("CypherProperty"))
        instance: CypherProperty = str.__new__(cls, value)
        return instance

    def __repr__(self: "CypherProperty") -> CypherRenderedText:
        return f"CypherProperty({str(self)!r})"


class CypherLiteral:
    """Wrapper for raw Cypher fragments."""

    __slots__ = ("_value",)

    def __init__(self: "CypherLiteral", value: CypherRenderedText) -> None:
        if not isinstance(value, str):
            msg = f"CypherLiteral must be a string, got {type(value).__name__}"
            raise TypeError(msg)
        self._value = value

    @property
    def cypher(self: "CypherLiteral") -> CypherRenderedText:
        return self._value

    def __repr__(self: "CypherLiteral") -> CypherRenderedText:
        return f"CypherLiteral({self._value!r})"

    def __str__(self: "CypherLiteral") -> CypherRenderedText:
        return self._value

    def __eq__(self: "CypherLiteral", other: CypherEqualityOperand) -> bool:
        if isinstance(other, CypherLiteral):
            return self._value == other._value
        return NotImplemented

    def __hash__(self: "CypherLiteral") -> int:
        return hash(self._value)


__all__ = [
    "CypherLabel",
    "CypherLiteral",
    "CypherProperty",
    "validate_cypher_property",
]

