from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

# Generated by scripts/codemods/extract_connection_core_residue.py from l2000_connection/connection.py.
# Run import hygiene and focused connection tests after applying this codemod.

if TYPE_CHECKING:
    from l2070_batching.server_plan import ServerPlan


class PlanScopeReturnName(str):
    """Branded name for a plan-scope registered return value."""

    __slots__ = ()


@dataclass(frozen=True, slots=True)
class SymbolicNamedValueInspection[TValue]:
    """Symbolic classification that preserves the inspected value type."""

    value: TValue
    is_symbolic: bool


@dataclass(frozen=True, slots=True)
class NamedLazyReturnRegistration[TValue]:
    """Registration outcome that preserves the candidate value type."""

    value: TValue
    registered: bool


def _is_symbolic_named_value[TValue](value: TValue) -> SymbolicNamedValueInspection[TValue]:
    """Return whether a plan-scope return must be registered as a plan ref."""
    from l2055_lazy_result.lazy_result import LazyFieldRef, LazyResult
    from l2055_lazy_result.lazy_seq import LazySeq
    from l2080_lazy_orm.lazy_row import LazyRow
    from l2070_batching.server_ref import ServerRef

    return SymbolicNamedValueInspection(
        value=value,
        is_symbolic=isinstance(value, LazyFieldRef | LazyResult | LazySeq | LazyRow | ServerRef),
    )


def _register_named_lazy_return[TValue](
    plan: ServerPlan,
    name: PlanScopeReturnName,
    value: TValue,
) -> NamedLazyReturnRegistration[TValue]:
    """Register a plan-owned lazy value as a named ServerPlan return."""
    from l1000_schema.schema_def import DatabaseObjectRow
    from l2055_lazy_result.lazy_result import LazyFieldRef, LazyResult
    from l2055_lazy_result.lazy_seq import LazySeq
    from l2080_lazy_orm.lazy_row import LazyRow
    from l1400_types import ServerPlanRefId
    from l2070_batching.server_ref import ScalarServerRef, ServerRef, ServerRefs

    return_result = getattr(plan, "return_result", None)
    if not callable(return_result):
        msg = "Plan scope named lazy returns require a ServerPlan return_result() method"
        raise TypeError(msg)

    if isinstance(value, ServerRef):
        return_result(name, value)
        return NamedLazyReturnRegistration(value, True)

    owned_step_refs = plan.owned_step_ref_ids()
    if isinstance(value, LazyFieldRef):
        projection = value.plan_owned_projection(owned_step_refs)
        if projection is None:
            return NamedLazyReturnRegistration(value, False)
        projection_ref, projection_type = projection
        return_result(
            name,
            ServerRefs.from_ref_id(
                projection_ref,
                variant="scalar",
                type_hint=projection_type,
            ),
        )
        return NamedLazyReturnRegistration(value, True)

    if isinstance(value, LazyRow):
        materialized = value.get_lazy()
        materialization_context = object.__getattribute__(materialized, "_context")
        source = getattr(materialization_context, "_source", None)
        if isinstance(source, LazyResult | LazySeq | ServerRef):
            registered = _register_named_lazy_return(plan, name, source).registered
        else:
            registered = _register_named_lazy_return(plan, name, materialized).registered
        return NamedLazyReturnRegistration(value, registered)

    if not isinstance(value, LazyResult | LazySeq):
        return NamedLazyReturnRegistration(value, False)
    resolved_ref_id = value.plan_owned_result_ref(owned_step_refs)
    if resolved_ref_id is None:
        return NamedLazyReturnRegistration(value, False)
    producer_step = next(
        (step for step in getattr(plan, "_steps", ()) if str(getattr(step, "ref_id", "")) == str(resolved_ref_id)),
        None,
    )

    expected_type = value.expected_result_type()
    producer_cardinality = producer_step.result_cardinality() if producer_step is not None else None
    if isinstance(value, LazySeq) or getattr(producer_cardinality, "name", None) == "MANY":
        if isinstance(expected_type, type) and issubclass(expected_type, DatabaseObjectRow):
            return_result(
                name,
                ServerRefs.from_ref_id(
                    ServerPlanRefId(resolved_ref_id),
                    variant="object_sequence",
                    type_hint=expected_type,
                ),
            )
        else:
            return_result(
                name,
                ServerRefs.from_ref_id(
                    ServerPlanRefId(resolved_ref_id),
                    variant="scalar_sequence",
                    type_hint=expected_type if isinstance(expected_type, type) else None,
                ),
            )
        return NamedLazyReturnRegistration(value, True)
    if isinstance(expected_type, type) and issubclass(expected_type, DatabaseObjectRow):
        return_result(
            name,
            ServerRefs.from_ref_id(
                ServerPlanRefId(resolved_ref_id),
                variant="object",
                type_hint=expected_type,
            ),
        )
        return NamedLazyReturnRegistration(value, True)

    return_result(
        name,
        ScalarServerRef[object](None, ServerPlanRefId(resolved_ref_id)),
    )
    return NamedLazyReturnRegistration(value, True)

