@dataclass(frozen=True, slots=True)
class PlanScopeFetchUnset:
    """Explicit variant for an omitted plan-scope fetch value."""


PLAN_SCOPE_FETCH_UNSET: PlanScopeFetchUnset = PlanScopeFetchUnset()


class _ImmutablePlanScopeValues[K, V](dict[K, V]):
    """Dictionary-compatible immutable values crossing a plan-scope boundary."""

    def __init__(self, values: SupportsKeysAndGetItem[K, V] | tuple[tuple[K, V], ...] = ()) -> None:
        dict.__init__(self, values)

    def __setitem__(self, key: K, value: V) -> Never:
        del key, value
        raise TypeError(f"{type(self).__name__} is immutable")

    def __delitem__(self, key: K) -> Never:
        del key
        raise TypeError(f"{type(self).__name__} is immutable")

    def clear(self) -> Never:
        raise TypeError(f"{type(self).__name__} is immutable")

    @overload
    def pop(self, key: K, /) -> V: ...

    @overload
    def pop(self, key: K, default: V, /) -> V: ...

    @overload
    def pop[DefaultT](self, key: K, default: DefaultT, /) -> V | DefaultT: ...

    def pop[DefaultT](self, key: K, default: DefaultT | None = None) -> V | DefaultT | None:
        del key, default
        raise TypeError(f"{type(self).__name__} is immutable")

    def popitem(self) -> Never:
        raise TypeError(f"{type(self).__name__} is immutable")

    def setdefault(self, key: K, default: V | None = None) -> Never:
        del key, default
        raise TypeError(f"{type(self).__name__} is immutable")

    def update(
        self,
        values: SupportsKeysAndGetItem[K, V] | Iterable[tuple[K, V]] = (),
        /,
        **named_values: V,
    ) -> Never:
        del values, named_values
        raise TypeError(f"{type(self).__name__} is immutable")

    def __or__[OtherK, OtherV](
        self,
        values: dict[OtherK, OtherV],
        /,
    ) -> dict[K | OtherK, V | OtherV]:
        return dict.__or__(self, values)

    def __ior__[OtherK, OtherV](
        self,
        values: SupportsKeysAndGetItem[OtherK, OtherV] | Iterable[tuple[OtherK, OtherV]],
        /,
    ) -> Never:
        del values
        raise TypeError(f"{type(self).__name__} is immutable")


class PlanScopeRuntimeSeedValues[K, V](_ImmutablePlanScopeValues[K, V]):
    """Immutable runtime values bound to a plan before execution."""


class PlanScopeResultValues[T](_ImmutablePlanScopeValues[str, T]):
    """Immutable named values published by a plan-scope execution."""


def _assert_private_plan_execution_authority() -> None:
    if in_explicit_execution_authority():
        return
    msg = "Plan workflow materialization requires explicit ServerPlan execution authority"
    raise RuntimeError(msg)


def _workflow_materialization_plan(scope: SyncPlanScope | AsyncPlanScope) -> BaseServerPlan:
    current_plan = getattr(scope.txn, "plan_scope_plan", None)
    if callable(current_plan):
        try:
            plan = current_plan()
        except RuntimeError as exc:
            if str(exc) != "Transaction plan must be initialized before lazy plan authoring":
                raise
            plan = scope.txn.plan()
    else:
        plan = scope.plan
    if not isinstance(plan, BaseServerPlan):
        msg = f"Plan scope workflow requires BaseServerPlan, got {type(plan).__name__}"
        raise TypeError(msg)
    return plan


def _workflow_should_commit(transaction: SyncWriteTransaction | AsyncWriteTransaction) -> bool:
    return transaction.is_active


class _BorrowedPlanOwner[PlanScopePlanResultT: object = object](Protocol):
    def plan_scope_plan(self: _BorrowedPlanOwner) -> PlanScopePlanResultT: ...


def _borrowed_plan_for_transaction(
    transaction: _BorrowedPlanOwner,
) -> BaseServerPlan:
    plan = transaction.plan_scope_plan()
    if not isinstance(plan, BaseServerPlan):
        msg = f"Borrowed plan scope requires BaseServerPlan, got {type(plan).__name__}"
        raise TypeError(msg)
    return plan


class SyncBorrowedPlanScope:
    """Named-result scope over a caller-owned synchronous transaction."""

    def __init__(self, txn: ReadTransaction | WriteTransaction) -> None:
        self.txn = txn
        self.plan = _borrowed_plan_for_transaction(txn)
        self._named_returns: dict[str, object] = {}
        self._executed = False

    def bind_runtime_seed_values[K, V](self, values: PlanScopeRuntimeSeedValues[K, V]) -> None:
        self.plan.bind_runtime_seed_values(PlanScopeRuntimeSeedValues(values))

    def return_result(self, name: str, value: object) -> None:
        if name in self._named_returns:
            raise ValueError(f"Duplicate plan result name: {name}")
        self._named_returns[name] = value

    @external_io_boundary
    def execute_results(self) -> PlanScopeResultValues[PlanResultValue]:
        """Execute exactly the named products owned by this borrowed scope."""
        if self._executed:
            msg = "Borrowed plan scope has already executed"
            raise RuntimeError(msg)
        concrete_results: dict[str, object] = {}
        has_plan_returns = False
        for name, value in self._named_returns.items():
            if _register_named_lazy_return(self.plan, PlanScopeReturnName(name), value).registered:
                has_plan_returns = True
            elif _is_symbolic_named_value(value).is_symbolic:
                msg = f"Borrowed plan scope return {name!r} must be plan-owned before execution"
                raise TypeError(msg)
            else:
                concrete_results[name] = value
        if self._named_returns and not has_plan_returns:
            self._executed = True
            return PlanScopeResultValues(concrete_results)
        with _imp_impl_l2070_execution_context().explicit_plan_execution_scope():
            raw_results = execute_server_plan_now(self.plan)
        if not isinstance(raw_results, PlanResults):
            msg = f"Borrowed plan scope expected PlanResults, got {type(raw_results).__name__}"
            raise TypeError(msg)
        results = raw_results.as_dict()
        results.update(concrete_results)
        self._executed = True
        return PlanScopeResultValues(results)


class AsyncBorrowedPlanScope:
    """Named-result scope over a caller-owned asynchronous transaction."""

    def __init__(self, txn: AsyncReadTransaction | AsyncWriteTransaction) -> None:
        self.txn = txn
