    def return_result(self, name: str, value: object) -> None:
        if name in self._named_returns:
            raise ValueError(f"Duplicate plan result name: {name}")
        self._named_returns[name] = value

    @external_io_boundary
    async def execute_results(self) -> PlanScopeResultValues[PlanResultValue]:
        """Execute exactly the named products owned by this borrowed scope."""
        if self._executed:
            msg = "Borrowed plan scope has already executed"
            raise RuntimeError(msg)
        concrete_results: dict[str, object] = {}
        has_plan_returns = False
        for name, value in self._named_returns.items():
            if _register_named_lazy_return(self.plan, PlanScopeReturnName(name), value).registered:
                has_plan_returns = True
            elif _is_symbolic_named_value(value).is_symbolic:
