class AsyncPlanScope[
    ConnT: AsyncDatabaseConnection = AsyncDatabaseConnection,
]:
    """Async explicit ServerPlan-owned transaction scope with no callback ingress."""

    def __init__(
        self,
        conn: ConnT,
        session_id: SessionId,
        *,
        mode: Literal["read", "write"],
        retry_policy: RetryPolicyInput = UNSET,
        timeout_seconds: TransactionTimeoutInput = UNSET,
        session_resolve: Callable[[Any], LazyResult[SessionId]] | None = None,
        session_context_resolver: SessionContextResolverInput = SESSION_CONTEXT_RESOLVER_UNSET,
    ) -> None:
        self._conn: ConnT = conn
        self._session_id = session_id
        self._session_resolve = session_resolve
        self._session_context_resolver = session_context_resolver
        self._mode = mode
        self._retry_policy = retry_policy
        self._timeout_seconds = timeout_seconds
        self._txn: AsyncReadTransaction | AsyncWriteTransaction | None = None
        self._plan: BaseServerPlan | None = None
        self._txn_owner: _AsyncReadTransactionContext | _AsyncWriteTransactionContext | None = None
        self._started = False
        self._execution_started = False
        self._executed = False
        self._closed = False
        self._owns_transaction_state = False
        self._named_returns: dict[str, object] = {}
        self._registered_return_names: set[str] = set()
        self._async_token: contextvars.Token | None = None

    @property
    def txn(self: AsyncPlanScope) -> AsyncReadTransaction | AsyncWriteTransaction:
        if self._txn is None:
            msg = "Plan scope has not been entered"
            raise RuntimeError(msg)
        return self._txn

    @property
    def transaction(self: AsyncPlanScope) -> AsyncReadTransaction | AsyncWriteTransaction:
        """Return the transaction object exposed by this explicit plan scope."""
        return self.txn

    @property
    def read_transaction(self: AsyncPlanScope) -> AsyncReadTransaction:
        """Return the typed read transaction, failing before callbacks on mode misuse."""
        if self._mode != "read":
            msg = "Read workflow requires a read plan scope"
            raise RuntimeError(msg)
        return cast("AsyncReadTransaction", self.txn)

    @property
    def write_transaction(self: AsyncPlanScope) -> AsyncWriteTransaction:
        """Return the typed write transaction, failing before callbacks on mode misuse."""
        if self._mode != "write":
            msg = "Write workflow requires a write plan scope"
            raise RuntimeError(msg)
        return cast("AsyncWriteTransaction", self.txn)

    @property
    def plan(self: AsyncPlanScope) -> BaseServerPlan:
        if self._plan is None:
            msg = "Plan scope has not been entered"
            raise RuntimeError(msg)
        return self._plan

    @external_io_boundary
    async def __aenter__(self: AsyncPlanScope) -> AsyncPlanScope:
        try:
            if self._mode == "read":
                await self._enter_read()
            else:
                await self._enter_write()
            plan = self.txn.plan()
            if not isinstance(plan, BaseServerPlan):
                msg = f"Expected BaseServerPlan, got {type(plan).__name__}"
                raise TypeError(msg)
            self.txn._set_lazy_plan_runtime(plan)
            self._plan = plan
            await plan.__aenter__()
            from l2000_connection.connection import _register_lazy_session_source

            _register_lazy_session_source(self, self._session_resolve)
            if isinstance(self._session_context_resolver, SessionContextResolver):
                self.txn.resolve_session_context_lazy(self._session_context_resolver)
            return self
        except BaseException as exc:
            try:
                await self.close(type(exc), exc, exc.__traceback__)
            except BaseException:
                logger.exception("Plan scope cleanup failed while handling scope entry failure")
            raise

    @external_io_boundary
    async def __aexit__(
        self: AsyncPlanScope,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: TracebackType | None,
    ) -> None:
        try:
            await self.close(exc_type, exc_val, exc_tb)
        except BaseException:
            if exc_val is None:
                raise
            logger.exception("Plan scope cleanup failed while propagating transaction failure")

    def bind_runtime_seed_values[K, V](
        self: AsyncPlanScope,
        values: PlanScopeRuntimeSeedValues[K, V],
    ) -> None:
        """Bind closed terminal runtime values without exposing the live plan."""
        if self._plan is None:
            msg = "Plan scope has not been entered"
            raise RuntimeError(msg)
        self._plan.bind_runtime_seed_values(PlanScopeRuntimeSeedValues(values))

    def return_result(self: AsyncPlanScope, name: str, value: object) -> None:
        if name in self._named_returns:
            raise ValueError(f"Duplicate plan result name: {name}")
        self._named_returns[name] = value

    def seal_for_external_execution(self: AsyncPlanScope) -> None:
        """Bind symbolic returns before a generic external executor receives the plan."""
        plan = _workflow_materialization_plan(self)
        for name, value in self._named_returns.items():
            if not _register_named_lazy_return(plan, PlanScopeReturnName(name), value).registered:
                raise TypeError(f"External plan result {name!r} must be plan-owned")

    @pure_lazy
    def register_named_results_for_planning(self: AsyncPlanScope) -> None:
        plan = self.plan
        for name, value in self._named_returns.items():
            if name in self._registered_return_names:
                continue
            if _register_named_lazy_return(plan, PlanScopeReturnName(name), value).registered:
                self._registered_return_names.add(name)

    @external_io_boundary
    async def fetch[T](
        self: AsyncPlanScope,
        value: T | PlanScopeFetchUnset = PLAN_SCOPE_FETCH_UNSET,
        **values: T,
    ) -> Never:
        """Reject eager plan-scope materialization."""
        del value, values
        msg = "fetch() is an eager execution terminal; use an explicit workflow execution boundary"
        raise RuntimeError(msg)

    @external_io_boundary
    def commit(self: AsyncPlanScope) -> object:
        return self.commit_plan()

    @external_io_boundary
    def commit_plan(self: AsyncPlanScope) -> object:
        txn = cast("AsyncWriteTransaction", self.txn)
        commit_lazy = txn.commit_lazy
        if not callable(commit_lazy):
            msg = "Read plan scopes do not support commit()"
            raise RuntimeError(msg)
        result = commit_lazy()
        self.return_result("__commit__", result)
        return result

    @external_io_boundary
    def rollback(self: AsyncPlanScope) -> object:
        txn = cast("AsyncWriteTransaction", self.txn)
        rollback_lazy = txn.rollback_lazy
        if not callable(rollback_lazy):
            msg = "Read plan scopes do not support rollback()"
            raise RuntimeError(msg)
        result = rollback_lazy()
        self.return_result("__rollback__", result)
        return result

    @external_io_boundary
    async def execute_read_workflow[T](self: AsyncPlanScope, workflow: AsyncReadPlanWorkflow[T]) -> T:
        transaction = self.read_transaction
        transaction._bind_workflow_planning_models(workflow.planning_models)
        result = await workflow.build(transaction)
        template = _plan_scope_fetch_template(
            _workflow_materialization_plan(self),
            result,
            (PlanScopeFetchPathComponent(workflow.result_name),),
        )
        concrete = PlanScopeFetchResults(
            (PlanScopeReturnName(name), value) for name, value in (await self._execute_registered_returns_async()).items()
        )
        return cast("T", _resolve_plan_scope_fetch_template(template, concrete))

    @external_io_boundary
    async def execute_read_planning_workflow[T](
        self: AsyncPlanScope,
        workflow: AsyncReadPlanningWorkflow[T],
    ) -> T:
        result = workflow.build(self.read_transaction)
        template = _plan_scope_fetch_template(
            _workflow_materialization_plan(self),
            result,
            (PlanScopeFetchPathComponent(workflow.result_name),),
        )
        concrete = PlanScopeFetchResults(
            (PlanScopeReturnName(name), value) for name, value in (await self._execute_registered_returns_async()).items()
        )
        return cast("T", _resolve_plan_scope_fetch_template(template, concrete))

    @external_io_boundary
    async def execute_write_workflow[T](self: AsyncPlanScope, workflow: AsyncWritePlanWorkflow[T]) -> T:
        transaction = self.write_transaction
        result = await workflow.build(transaction)
        if not transaction.is_active:
            if isinstance(result, LazyResult):
                raise RuntimeError("Inactive workflow transaction cannot materialize a lazy result")
            return cast("T", result)
        template = _plan_scope_fetch_template(
            _workflow_materialization_plan(self),
            result,
            (PlanScopeFetchPathComponent(workflow.result_name),),
        )
        if workflow.commit and _workflow_should_commit(transaction):
            self.commit()
        concrete = PlanScopeFetchResults(
            (PlanScopeReturnName(name), value) for name, value in (await self._execute_registered_returns_async()).items()
        )
        return cast("T", _resolve_plan_scope_fetch_template(template, concrete))

    @external_io_boundary
    async def execute_write_planning_workflow[T](
        self: AsyncPlanScope,
        workflow: AsyncWritePlanningWorkflow[T],
    ) -> T:
        transaction = self.write_transaction
        result = workflow.build(transaction)
        if not transaction.is_active:
            if isinstance(result, LazyResult):
                raise RuntimeError("Inactive workflow transaction cannot materialize a lazy result")
            return cast("T", result)
        template = _plan_scope_fetch_template(
            _workflow_materialization_plan(self),
            result,
            (PlanScopeFetchPathComponent(workflow.result_name),),
        )
        if workflow.commit and _workflow_should_commit(transaction):
            self.commit()
        concrete = PlanScopeFetchResults(
            (PlanScopeReturnName(name), value) for name, value in (await self._execute_registered_returns_async()).items()
        )
        return cast("T", _resolve_plan_scope_fetch_template(template, concrete))

    @external_io_boundary
    async def execute_single_intent_workflow[T](
        self: AsyncPlanScope,
        workflow: SingleIntentPlanWorkflow[T],
    ) -> T:
        plan = self.plan
        workflow.intent.ref_id = ServerPlanRefId(plan._next_ref())
        ref = plan._add_server_step(workflow.intent)
        self.return_result(workflow.result_name, ref)
        if not workflow.intent.is_read_only():
            self.commit()
        return cast(T, (await self._execute_registered_returns_async())[workflow.result_name])

    @external_io_boundary
    async def execute(self: AsyncPlanScope) -> Mapping[str, object]:
        msg = "execute() is an eager execution terminal; use an explicit workflow execution boundary"
        raise RuntimeError(msg)

    @external_io_boundary
    async def execute_results(self: AsyncPlanScope) -> PlanScopeResultValues[PlanResultValue]:
        """Execute named results through the nominal async plan-scope owner."""
        with _imp_impl_l2070_execution_context().explicit_plan_execution_scope():
            return await self._execute_registered_returns_async()

    async def _execute_registered_returns_async(self: AsyncPlanScope) -> PlanScopeResultValues[PlanResultValue]:
        _assert_private_plan_execution_authority()
        if self._closed:
            msg = "Plan scope is closed"
            raise RuntimeError(msg)
        if self._executed:
            msg = "Plan scope has already executed"
            raise RuntimeError(msg)
        plan = _workflow_materialization_plan(self)
        concrete_results: dict[str, object] = {}
        has_plan_returns = False
        _register_async_named_results_for_planning(self)
        for name, value in self._named_returns.items():
            if name in self._registered_return_names:
                has_plan_returns = True
                continue
            if _is_symbolic_named_value(value).is_symbolic:
                msg = f"Plan scope return {name!r} must be plan-owned before execution"
                raise TypeError(msg)
            concrete_results[name] = value
        self._execution_started = True
        raw_results = await execute_server_plan_async(plan)
        if not isinstance(raw_results, PlanResults):
            msg = f"Plan scope expected PlanResults, got {type(raw_results).__name__}"
            raise TypeError(msg)
        results = raw_results.as_dict()
        results.update(concrete_results)
        self._executed = True
        return PlanScopeResultValues(results)

    @external_io_boundary
    async def close(
        self: AsyncPlanScope,
        exc_type: type[BaseException] | None = None,
        exc_val: BaseException | None = None,
        exc_tb: TracebackType | None = None,
    ) -> None:
        if self._closed:
            return
        if not self._owns_transaction_state:
            self._closed = True
            return
        txn = self._txn
        txn_owner = self._txn_owner
        conn = self._conn
        try:
            return
        finally:
            self._closed = True
            if self._plan is not None:
                try:
                    await self._plan.__aexit__(exc_type, exc_val, exc_tb)
                except Exception:
                    logger.warning("Exception during async plan-scope plan cleanup", exc_info=True)
            if txn_owner is not None:
                try:
                    await txn_owner.__aexit__(exc_type, exc_val, exc_tb)
                except Exception:
                    logger.warning("Exception during async plan-scope transaction cleanup", exc_info=True)
            if self._started or conn._data_transaction_backend_open():
                try:
                    if self._mode == "write" and (exc_type is not None or (txn is not None and txn.is_rolled_back)):
                        await conn._rollback_async()
                        conn._mark_data_transaction_backend_rolled_back()
                    else:
                        await conn._end_transaction_async()
                except Exception:
                    logger.warning("Exception during async plan-scope transaction end", exc_info=True)
            try:
                await conn._clear_statement_timeout_async()
            except Exception:
                logger.warning("Failed to clear statement timeout after async plan scope", exc_info=True)
            conn._active_transaction = False
            conn._in_data_transaction = False
            conn._clear_data_transaction_sidecar()
            if self._async_token is not None:
                _async_transaction_active.reset(self._async_token)
                self._async_token = None
            if self._mode == "write":
                conn._finish_transaction_trace_safely(context=DiagnosticLabel("write_async_plan_scope"))
                conn._data_transaction_depth = max(0, conn._data_transaction_depth - 1)
            if (
                self._mode == "write"
                and isinstance(exc_val, _SupportsAfterRollbackAsync)
                and exc_val.preserve_original_exception_after_rollback_async
            ):
                side_effect_token = _async_transaction_active.set(False)
                try:
                    try:
                        await exc_val.run_after_rollback_async(
                            conn,
                            self._session_id,
                        )
                    except Exception:
                        logger.error(
                            "After-rollback async plan-scope callback failed; preserving original exception",
                            exc_info=True,
                        )
                finally:
                    _async_transaction_active.reset(side_effect_token)

    async def _enter_read(self: AsyncPlanScope) -> None:
        conn = self._conn
        if _async_transaction_active.get():
            msg = "Nested transactions are not supported. Use the same transaction for both reads and writes."
            raise db_exc.ProgrammingError(msg)
        if conn._active_transaction:
            msg = "Cannot start async transaction while sync transaction is active."
            raise db_exc.ProgrammingError(msg)
        conn._check_not_in_schema_transaction()
        self._owns_transaction_state = True
        _effective_policy, effective_timeout, _context, start_time = conn._prepare_read_transaction(
            self._session_id,
            retry_policy_or_none(self._retry_policy),
            transaction_timeout_or_none(self._timeout_seconds),
            "read_async",
        )
        conn._check_timeout(effective_timeout, start_time)
        self._async_token = _async_transaction_active.set(True)
        conn._in_data_transaction = True
        await conn._begin_transaction_async(read_only=True)
        self._started = True
        await conn._setup_statement_timeout_async(effective_timeout, start_time)
        txn_owner = conn._create_read_transaction_async(self._session_id)
        txn = await txn_owner.__aenter__()
        txn._bind_workflow_planning_models(conn._planning_log_models())
        self._txn_owner = txn_owner
        self._txn = txn

    async def _enter_write(self: AsyncPlanScope) -> None:
        conn = self._conn
        conn._enforce_transaction_orchestration_caller("open_write_plan_async")
        if _async_transaction_active.get():
            msg = "Nested transactions are not supported. WriteTransaction provides read capabilities - use the same transaction."
            raise db_exc.ProgrammingError(msg)
        if conn._active_transaction:
            msg = "Cannot start async transaction while sync transaction is active."
            raise db_exc.ProgrammingError(msg)
        conn._check_not_in_schema_transaction()
        self._owns_transaction_state = True
        _effective_policy, effective_timeout, _context, start_time = conn._prepare_write_transaction(
            self._session_id,
            retry_policy_or_none(self._retry_policy),
            transaction_timeout_or_none(self._timeout_seconds),
            "write_async",
        )
        conn._check_timeout(effective_timeout, start_time)
        conn._data_transaction_depth += 1
        self._async_token = _async_transaction_active.set(True)
        conn._in_data_transaction = True
        conn._data_transaction_sidecar = DataTransactionSidecar(
            read_only=False,
            mode=TransactionModeName("write_async"),
            label=TransactionTraceLabel("open_write_plan_async"),
        )
        await conn._setup_statement_timeout_async(effective_timeout, start_time)
        txn_owner = conn._create_write_transaction_async(self._session_id)
        txn = await txn_owner.__aenter__()
        txn._bind_workflow_planning_models(conn._planning_log_models())
        self._txn_owner = txn_owner
        self._txn = txn


