# Run import hygiene and focused connection tests after applying this codemod.

_ORCHESTRATION_SKIP_MODULES = ("l2000_connection.connection", "asyncio", "contextlib")
_ORCHESTRATION_SKIP_MODULE_PREFIXES = ("asyncio.", "contextlib.")
_ORCHESTRATION_ALLOWED_MODULE_ROOTS = (
    "api",
    "conform",
    "impl",
    "tests",
    "services",
    "benchmarks",
    "demos",
    "fastapi_app",
    "data_layer",
    "data_layer_testing",
    "scripts",
)
_ORCHESTRATION_ALLOWED_EXACT_MODULES = ("fastapi_app", "data_layer", "data_layer_testing")
_ORCHESTRATION_ALLOWED_MODULE_PREFIXES = tuple(f"{module_root}." for module_root in _ORCHESTRATION_ALLOWED_MODULE_ROOTS)
_ORCHESTRATION_ALLOWED_PATH_ROOTS = _ORCHESTRATION_ALLOWED_MODULE_ROOTS
_ORCHESTRATION_TEST_MODULE_PREFIXES = ("_pytest",)
_ORCHESTRATION_TEST_MODULES = ("unittest", "pytest_asyncio")
_ORCHESTRATION_TEST_MODULE_WITH_CHILDREN = ("unittest.", "pytest_asyncio.")
_MIN_LAYER_MODULE_ROOT_LENGTH = 6


class OrchestrationModuleName(str):
    """Branded module name used by transaction orchestration policy checks."""

    __slots__ = ()


class OrchestrationCallerFilename(str):
    """Branded filename extracted from a call frame."""

    __slots__ = ()


@dataclass(frozen=True, slots=True)
class OrchestrationCallerPathResolution:
    """Resolved caller path, or an explicit unresolved result."""

    found: bool
    path: Path = Path("")


def _is_layer_module_root(name: OrchestrationModuleName) -> bool:
    return len(name) > _MIN_LAYER_MODULE_ROOT_LENGTH and name.startswith("l") and name[1:5].isdigit() and name[5] == "_"


def _resolve_orchestration_caller_path(caller_filename: OrchestrationCallerFilename) -> OrchestrationCallerPathResolution:
    if caller_filename.startswith("<"):
        return OrchestrationCallerPathResolution(found=True, path=Path(caller_filename))
    try:
        return OrchestrationCallerPathResolution(found=True, path=Path(caller_filename).absolute())
    except OSError:
        return OrchestrationCallerPathResolution(found=False)


def _should_skip_orchestration_frame(module_name: OrchestrationModuleName) -> bool:
    return module_name in _ORCHESTRATION_SKIP_MODULES or module_name.startswith(
        _ORCHESTRATION_SKIP_MODULE_PREFIXES,
    )


def _is_allowed_in_tree_orchestration_module(module_name: OrchestrationModuleName) -> bool:
    if module_name in _ORCHESTRATION_ALLOWED_EXACT_MODULES:
        return True
    if _is_layer_module_root(module_name):
        return True
    return any(module_name.startswith(prefix) for prefix in _ORCHESTRATION_ALLOWED_MODULE_PREFIXES)


def _is_test_orchestration_module(module_name: OrchestrationModuleName) -> bool:
    if module_name in _ORCHESTRATION_TEST_MODULES:
        return True
    if any(module_name.startswith(prefix) for prefix in _ORCHESTRATION_TEST_MODULE_PREFIXES):
        return True
    return any(module_name.startswith(prefix) for prefix in _ORCHESTRATION_TEST_MODULE_WITH_CHILDREN)


def _is_allowed_in_tree_orchestration_path(relative_path: Path) -> bool:
    if not relative_path.parts:
        return False
    top_level = relative_path.parts[0]
    if top_level in _ORCHESTRATION_ALLOWED_PATH_ROOTS:
        return True
    if _is_layer_module_root(OrchestrationModuleName(top_level)):
        return True
    if len(relative_path.parts) == 1 and relative_path.suffix == ".py":
        return relative_path.stem in _ORCHESTRATION_ALLOWED_PATH_ROOTS
    return False


def _is_virtualenv_site_packages_path(relative_path: Path) -> bool:
    if not relative_path.parts or relative_path.parts[0] not in {".venv", "venv"}:
        return False
    return "site-packages" in relative_path.parts

