"""Context-manager adapters for schema transactions."""

from __future__ import annotations

from l1400_types.type_surface_contracts import SchemaModelName

from dataclasses import dataclass
from types import TracebackType
from typing import Protocol, cast

from l1400_types.type_surface_contracts import (
    NoExceptionType,
    NoExceptionValue,
)
from l2050_transaction.external_io_boundary import external_io_boundary


@dataclass(frozen=True, slots=True)
class SchemaExitExceptionState:
    """Exception state passed through schema transaction cleanup."""

    exception_type: type[BaseException] | NoExceptionType
    exception_value: BaseException | NoExceptionValue

    def type_name(self: SchemaExitExceptionState) -> SchemaModelName:
        match self.exception_type:
            case NoExceptionType():
                return SchemaModelName("Unknown")
            case concrete_type:
                return SchemaModelName(concrete_type.__name__)


class _SyncSchemaExitOwner(Protocol):
    def _exit_sync(self, exception_state: SchemaExitExceptionState) -> None: ...


class _AsyncSchemaExitOwner(Protocol):
    async def _exit_async(self, exception_state: SchemaExitExceptionState) -> None: ...


class SyncSchemaTransactionContextMixin:
    """Standard synchronous context-manager exit adapter."""

    @external_io_boundary
    def __exit__(
        self: SyncSchemaTransactionContextMixin,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: TracebackType | None,
    ) -> None:
        del exc_tb
        owner = cast("_SyncSchemaExitOwner", self)
        owner._exit_sync(
            SchemaExitExceptionState(
                NoExceptionType() if exc_type is None else exc_type,
                NoExceptionValue() if exc_val is None else exc_val,
            )
        )


class AsyncSchemaTransactionContextMixin:
    """Standard asynchronous context-manager exit adapter."""

    @external_io_boundary
    async def __aexit__(
        self: AsyncSchemaTransactionContextMixin,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: TracebackType | None,
    ) -> None:
        del exc_tb
        owner = cast("_AsyncSchemaExitOwner", self)
        await owner._exit_async(
            SchemaExitExceptionState(
                NoExceptionType() if exc_type is None else exc_type,
                NoExceptionValue() if exc_val is None else exc_val,
            )
        )

