"""Shared authority for cached table-existence resolution."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass
from typing import Protocol

from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
from l2055_lazy_result.purity import pure_lazy


class _CachedTableExistenceAuthority[TObservation](Protocol):
    """Source-proven cache owner whose observation representation stays generic."""

    def _validate_table_exists_args(self, table_name: SqlTableName) -> None: ...

    def _table_exists_from_cache(self, table_name: SqlTableName) -> TObservation: ...


class CachedTableExistenceResults(dict[SqlTableName, bool]):
    """Known table-existence facts from the connection cache."""


@dataclass(frozen=True, slots=True)
class CachedTableExistencePartition:
    """Known cache facts and names that still require physical resolution."""

    known: CachedTableExistenceResults
    missing: tuple[SqlTableName, ...]


@pure_lazy
def _cached_table_existence[TObservation](
    conn: _CachedTableExistenceAuthority[TObservation],
    table_names: Sequence[SqlTableName],
) -> CachedTableExistencePartition:
    result = CachedTableExistenceResults()
    missing: list[SqlTableName] = []
    for table_name in table_names:
        conn._validate_table_exists_args(table_name)
        cached = conn._table_exists_from_cache(table_name)
        if isinstance(cached, bool):
            result[table_name] = cached
        else:
            missing.append(table_name)
    return CachedTableExistencePartition(result, tuple(missing))

