    return os.environ.get(_COUNTERS_ENABLED_ENV) == "1"


def _current_pytest_nodeid() -> PytestNodeIdResolution:
    raw = os.environ.get("PYTEST_CURRENT_TEST")
    if raw is None:
        return PytestNodeIdResolution(found=False)
    return PytestNodeIdResolution(found=True, nodeid=PytestNodeId(raw.split(" ", 1)[0]))


def record_profile_counter(
    name: ProfileCounterName,
    *,
    count: int = 1,
    duration_ms: float = 0.0,
    labels: ProfileCounterLabels = NO_PROFILE_COUNTER_LABELS,
) -> None:
    if not profile_counters_enabled():
        return
    path_value = os.environ.get(_COUNTERS_PATH_ENV)
    if not path_value:
        return
    path = Path(path_value)
    path.parent.mkdir(parents=True, exist_ok=True)
    payload: dict[str, object] = {
        "name": name,
        "count": count,
        "duration_ms": duration_ms,
        "pid": os.getpid(),
    }
    nodeid = _current_pytest_nodeid()
    if nodeid.found:
        payload["nodeid"] = nodeid.nodeid
    if labels:
        payload["labels"] = {label.name: label.value for label in labels}
    with _WRITE_LOCK:
        with path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, sort_keys=True))
            handle.write("\n")


@contextmanager
def profile_counter_span(
    name: ProfileCounterName,
    *,
    count: int = 1,
    labels: ProfileCounterLabels = NO_PROFILE_COUNTER_LABELS,
) -> Generator[None]:
    if not profile_counters_enabled():
        yield
        return
    started = time.perf_counter()
    try:
        yield
    finally:
        duration_ms = (time.perf_counter() - started) * 1000
        record_profile_counter(name, count=count, duration_ms=duration_ms, labels=labels)

