"""Connection provider abstraction for transaction-based APIs.

Abstracts over explicit connection pools (production) and single-connection
wrappers (internal callers, tests) so that higher-layer modules never
take a raw ``SyncDatabaseConnection`` parameter.

This module lives at layer 2000 so that both ``api/`` and ``impl/``
code at any layer can import ``ConnectionProvider`` and
``SingleConnectionProvider`` without layer violations.
"""

from __future__ import annotations

import abc
import asyncio
import contextlib
import threading
from collections.abc import AsyncGenerator, Awaitable, Generator
from enum import StrEnum
from types import TracebackType
from typing import NoReturn, cast

from l1300_session.session import SessionId
from l2000_connection.connection import AsyncDatabaseConnection, SyncDatabaseConnection
from l2000_connection.connection_pool import AsyncConnectionPool, SyncConnectionPool
from l2000_connection.notification_subscriptions import (
    AsyncNotificationStopSignal,
    AsyncNotificationSubscription,
    _AsyncPollingNotificationSubscription,
    NO_NOTIFICATION_DEADLINE,
    NotificationChannelName,
    NotificationWaitReason,
    NotificationWaitResult,
    SyncNotificationStopSignal,
    SyncNotificationSubscription,
    pool_notification_subscription,
    sync_notification_subscription,
)
from l1300_session.session import SessionId


class ConnectionProviderSource(str):
    """Branded source label for connection-provider validation errors."""

    __slots__ = ()


class ConnectionProviderErrorMessage(str):
    """Branded provider mode error message."""

    __slots__ = ()


class ConnectionProviderSubclassOption(str):
    """Branded subclass option value."""

    __slots__ = ()


type ConnectionProviderSubclassKwarg = ConnectionProviderSubclassOption | bool | int


def _raise_provider_mode_error(message: ConnectionProviderErrorMessage) -> NoReturn:
    raise TypeError(message)


def _require_sync_context_manager[T](
    *,
    value: contextlib.AbstractContextManager[T],
    source: ConnectionProviderSource,
) -> contextlib.AbstractContextManager[T]:
    if not isinstance(value, contextlib.AbstractContextManager):
        msg = (
            f"{source} must return an AbstractContextManager, got {type(value).__name__}. "
            "ConnectionProvider implementations must expose connection acquisition only "
            "through real context managers."
        )
        raise TypeError(msg)
    return value


def _require_async_context_manager[T](
    *,
    value: contextlib.AbstractAsyncContextManager[T],
    source: ConnectionProviderSource,
) -> contextlib.AbstractAsyncContextManager[T]:
    if not isinstance(value, contextlib.AbstractAsyncContextManager):
        msg = (
            f"{source} must return an AbstractAsyncContextManager, got {type(value).__name__}. "
            "ConnectionProvider implementations must expose async acquisition only "
            "through real async context managers."
        )
        raise TypeError(msg)
    return value


def _require_sync_database_connection(
    *,
    value: SyncDatabaseConnection,
    source: ConnectionProviderSource,
) -> SyncDatabaseConnection:
    if not isinstance(value, SyncDatabaseConnection):
        msg = (
            f"{source} must yield a SyncDatabaseConnection, got {type(value).__name__}. "
            "ConnectionProvider is a strict boundary; pass a real SyncDatabaseConnection "
            "or a real pool-backed provider."
        )
        raise TypeError(msg)
    return value


def _require_async_database_connection(
    *,
    value: AsyncDatabaseConnection,
    source: ConnectionProviderSource,
) -> AsyncDatabaseConnection:
    if not isinstance(value, AsyncDatabaseConnection):
        msg = (
            f"{source} must yield an AsyncDatabaseConnection, got {type(value).__name__}. "
            "ConnectionProvider is a strict boundary; pass a real AsyncDatabaseConnection "
            "or a real pool-backed provider."
        )
        raise TypeError(msg)
    return value


def require_connection_provider(
    *,
    value: ConnectionProvider,
    source: ConnectionProviderSource,
) -> ConnectionProvider:
    if not isinstance(value, ConnectionProvider):
        msg = (
            f"{source} requires a real ConnectionProvider, got {type(value).__name__}. "
            "Do not pass duck-typed pools or cast arbitrary objects through this boundary."
        )
        raise TypeError(msg)
    return value


class _AsyncRLock:
    """Small same-task reentrant async lock for single-connection wrappers."""

    __slots__ = ("_depth", "_lock", "_owner")

    def __init__(self: _AsyncRLock) -> None:
        self._lock = asyncio.Lock()
        self._owner: asyncio.Task[object] | None = None
        self._depth = 0

    async def __aenter__(self: _AsyncRLock) -> None:
        task = asyncio.current_task()
        if task is None:
            msg = "Async connection acquisition requires a running asyncio task"
            raise RuntimeError(msg)
        if self._owner is task:
            self._depth += 1
            return
        await self._lock.acquire()
        self._owner = task
        self._depth = 1

    async def __aexit__(
        self: _AsyncRLock,
        exc_type: type[BaseException],
        exc: BaseException,
        tb: TracebackType,
    ) -> None:
        del exc_type, exc, tb
        task = asyncio.current_task()
        if self._owner is not task:
            msg = "Async connection acquisition released by a non-owner task"
            raise RuntimeError(msg)
        self._depth -= 1
        if self._depth == 0:
            self._owner = None
            self._lock.release()


class NotificationSubscriptionMode(StrEnum):
    """Notification receive capabilities supplied by a connection provider."""

    NONE = "none"
    SYNC = "sync"
    ASYNC = "async"
    DUAL = "dual"

    @property
    def supports_async(self) -> bool:
        return self in {NotificationSubscriptionMode.ASYNC, NotificationSubscriptionMode.DUAL}


class ConnectionProvider(abc.ABC):
    """Strict base class for objects that can provide connections.

    Subclassed by explicit pool adapters and the lightweight
    ``SingleConnectionProvider`` wrapper.  Higher-layer functions accept
    this type rather than ``SyncDatabaseConnection``.
    """

    __slots__ = ()

    def __init_subclass__(cls, **kwargs: ConnectionProviderSubclassKwarg) -> None:
        super().__init_subclass__(**kwargs)
        forbidden_public_overrides = {
            name
            for name in (
                "acquire_sync_context",
                "acquire",
                "subscribe_notifications",
                "subscribe_notifications_async",
            )
            if name in cls.__dict__
        }
        if forbidden_public_overrides:
            forbidden = ", ".join(sorted(forbidden_public_overrides))
            msg = (
                f"{cls.__module__}.{cls.__qualname__} overrides {forbidden}. "
                "ConnectionProvider subclasses must implement only "
                "_acquire_sync_context_impl() / _acquire_async_context_impl() so the "
                "base class can enforce strict runtime validation."
            )
            raise TypeError(msg)

    @property
    def notification_subscription_mode(self) -> NotificationSubscriptionMode:
        """Return the provider-owned notification receive capability."""
        return NotificationSubscriptionMode.NONE

    @abc.abstractmethod
    def _acquire_sync_context_impl(
        self: ConnectionProvider,
    ) -> contextlib.AbstractContextManager[SyncDatabaseConnection]:
        """Implementation hook for sync acquisition."""

    @abc.abstractmethod
    def _acquire_async_context_impl(
        self: ConnectionProvider,
    ) -> contextlib.AbstractAsyncContextManager[AsyncDatabaseConnection]:
        """Implementation hook for async acquisition."""

    def _subscribe_notifications_sync_impl(
        self: ConnectionProvider,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> contextlib.AbstractContextManager[SyncNotificationSubscription]:
        del channels, session_id
        msg = "Notification subscriptions require a reconnectable connection provider"
        raise RuntimeError(msg)

    def _subscribe_notifications_impl(
        self: ConnectionProvider,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> contextlib.AbstractAsyncContextManager[AsyncNotificationSubscription]:
        del channels, session_id
        msg = "Notification subscriptions require a reconnectable connection provider"
        raise RuntimeError(msg)

    @staticmethod
    def _validate_notification_channels(channels: frozenset[NotificationChannelName]) -> None:
        if not channels:
            raise ValueError("Notification channels must not be empty")
        if any(not channel or channel.strip() != channel for channel in channels):
            raise ValueError("Each notification channel must be a non-empty trimmed string")

    @contextlib.contextmanager
    def subscribe_notifications(
        self: ConnectionProvider,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> Generator[SyncNotificationSubscription]:
        """Open one receive-only blocking notification subscription."""
        self._validate_notification_channels(channels)
        impl = _require_sync_context_manager(
            value=self._subscribe_notifications_sync_impl(channels, session_id=session_id),
            source=ConnectionProviderSource(f"{type(self).__name__}._subscribe_notifications_sync_impl()"),
        )
        with impl as subscription:
            if not isinstance(subscription, SyncNotificationSubscription):
                msg = (
                    f"{type(self).__name__}._subscribe_notifications_sync_impl() must yield a "
                    f"SyncNotificationSubscription, got {type(subscription).__name__}"
                )
                raise TypeError(msg)
            yield subscription

    @contextlib.asynccontextmanager
    async def subscribe_notifications_async(
        self: ConnectionProvider,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> AsyncGenerator[AsyncNotificationSubscription]:
        """Open one backend-neutral, provider-owned notification subscription."""
        self._validate_notification_channels(channels)
        impl = _require_async_context_manager(
            value=self._subscribe_notifications_impl(channels, session_id=session_id),
            source=ConnectionProviderSource(f"{type(self).__name__}._subscribe_notifications_impl()"),
        )
        async with impl as subscription:
            if not isinstance(subscription, AsyncNotificationSubscription):
                msg = (
                    f"{type(self).__name__}._subscribe_notifications_impl() must yield a "
                    f"AsyncNotificationSubscription, got {type(subscription).__name__}"
                )
                raise TypeError(msg)
            yield subscription

    @contextlib.contextmanager
    def acquire_sync_context(self: ConnectionProvider) -> Generator[SyncDatabaseConnection]:
        """Acquire a connection synchronously with strict runtime validation."""
        impl = _require_sync_context_manager(
            value=self._acquire_sync_context_impl(),
            source=ConnectionProviderSource(f"{type(self).__name__}._acquire_sync_context_impl()"),
        )
        with impl as conn:
            yield _require_sync_database_connection(
                value=conn,
                source=ConnectionProviderSource(f"{type(self).__name__}._acquire_sync_context_impl()"),
            )

    @contextlib.asynccontextmanager
    async def acquire(self: ConnectionProvider) -> AsyncGenerator[AsyncDatabaseConnection]:
        """Acquire a connection asynchronously with strict runtime validation."""
        impl = _require_async_context_manager(
            value=self._acquire_async_context_impl(),
            source=ConnectionProviderSource(f"{type(self).__name__}._acquire_async_context_impl()"),
        )
        async with impl as conn:
            yield _require_async_database_connection(
                value=conn,
                source=ConnectionProviderSource(f"{type(self).__name__}._acquire_async_context_impl()"),
            )


class SingleConnectionProvider(ConnectionProvider):
    """Wraps a single ``SyncDatabaseConnection`` as a ``ConnectionProvider``.

    Use this when calling functions from code that already holds
    a connection (e.g. ``impl/`` commit-branch methods, test fixtures).
    The same connection is returned from every ``acquire`` call.
    """

    __slots__ = ("_async_lock", "_conn", "_sync_lock")

    def __init__(self: SingleConnectionProvider, conn: SyncDatabaseConnection) -> None:
        self._conn = _require_sync_database_connection(
            value=conn,
            source=ConnectionProviderSource("SingleConnectionProvider(conn)"),
        )
        self._sync_lock = threading.RLock()
        self._async_lock = _AsyncRLock()

    @contextlib.contextmanager
    def _acquire_sync_context_impl(self: SingleConnectionProvider) -> Generator[SyncDatabaseConnection]:
        """Yield the wrapped connection."""
        with self._sync_lock:
            yield self._conn

    @property
    def notification_subscription_mode(self) -> NotificationSubscriptionMode:
        return NotificationSubscriptionMode.SYNC

    def _subscribe_notifications_sync_impl(
        self: SingleConnectionProvider,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> contextlib.AbstractContextManager[SyncNotificationSubscription]:
        return sync_notification_subscription(
            self,
            channels,
            session_id=session_id,
            initial_resync_required=True,
        )

    @contextlib.asynccontextmanager
    async def _acquire_async_context_impl(self: SingleConnectionProvider) -> AsyncGenerator[AsyncDatabaseConnection]:
        """Reject async acquisition from a sync-only single-connection provider."""
        msg = "SingleConnectionProvider cannot provide async connections"
        _raise_provider_mode_error(ConnectionProviderErrorMessage(msg))
        if False:
            yield cast("AsyncDatabaseConnection", self._conn)


class SingleAsyncConnectionProvider(ConnectionProvider):
    """Wraps a single ``AsyncDatabaseConnection`` as an async-only provider."""

    __slots__ = ("_async_lock", "_conn")

    def __init__(self: SingleAsyncConnectionProvider, conn: AsyncDatabaseConnection) -> None:
        self._conn = _require_async_database_connection(
            value=conn,
            source=ConnectionProviderSource("SingleAsyncConnectionProvider(conn)"),
        )
        self._async_lock = _AsyncRLock()

    def _acquire_sync_context_impl(
        self: SingleAsyncConnectionProvider,
    ) -> contextlib.AbstractContextManager[SyncDatabaseConnection]:
        """Reject sync acquisition from an async-only single-connection provider."""
        msg = "SingleAsyncConnectionProvider cannot provide sync connections"
        _raise_provider_mode_error(ConnectionProviderErrorMessage(msg))

    @contextlib.asynccontextmanager
    async def _acquire_async_context_impl(self: SingleAsyncConnectionProvider) -> AsyncGenerator[AsyncDatabaseConnection]:
        """Yield the wrapped async connection."""
        async with self._async_lock:
            yield self._conn

    @property
    def notification_subscription_mode(self) -> NotificationSubscriptionMode:
        return NotificationSubscriptionMode.ASYNC

    @contextlib.asynccontextmanager
    async def _subscribe_notifications_impl(
        self: SingleAsyncConnectionProvider,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> AsyncGenerator[AsyncNotificationSubscription]:
        async with self._async_lock:
            subscription = _AsyncPollingNotificationSubscription(
                self,
                channels,
                session_id,
                initial_resync_required=True,
            )
            await subscription.establish()
        try:
            yield subscription
        finally:
            await subscription.close()


class SyncPoolConnectionProvider(ConnectionProvider):
    """Adapts a ``SyncConnectionPool`` to sync provider acquisition."""

    __slots__ = ("_pool",)

    def __init__(self, pool: SyncConnectionPool) -> None:
        if not isinstance(pool, SyncConnectionPool):
            msg = (
                f"SyncPoolConnectionProvider(pool) requires a real SyncConnectionPool, got {type(pool).__name__}. "
                "Do not pass duck-typed objects through this boundary."
            )
            raise TypeError(msg)
        self._pool = pool

    def _acquire_sync_context_impl(
        self: SyncPoolConnectionProvider,
    ) -> contextlib.AbstractContextManager[SyncDatabaseConnection]:
        """Delegate to the sync pool and enforce its public sync facade."""

        @contextlib.contextmanager
        def _validated() -> Generator[SyncDatabaseConnection]:
            with self._pool.acquire_context() as conn:
                if not isinstance(conn, SyncDatabaseConnection):
                    msg = f"Sync pool yielded {type(conn).__name__}, expected SyncDatabaseConnection"
                    raise TypeError(msg)
                yield conn

        return _validated()

    def _acquire_async_context_impl(
        self: SyncPoolConnectionProvider,
    ) -> contextlib.AbstractAsyncContextManager[AsyncDatabaseConnection]:
        """Reject async acquisition from a sync-only pool provider."""
        msg = "SyncPoolConnectionProvider cannot provide async connections"
        _raise_provider_mode_error(ConnectionProviderErrorMessage(msg))

    @property
    def notification_subscription_mode(self) -> NotificationSubscriptionMode:
        return NotificationSubscriptionMode.SYNC

    def _subscribe_notifications_sync_impl(
        self,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> contextlib.AbstractContextManager[SyncNotificationSubscription]:
        return sync_notification_subscription(
            self,
            channels,
            session_id=session_id,
            initial_resync_required=True,
        )


class AsyncPoolConnectionProvider(ConnectionProvider):
    """Adapts an ``AsyncConnectionPool`` to async provider acquisition."""

    __slots__ = ("_pool",)

    def __init__(self, pool: AsyncConnectionPool) -> None:
        if not isinstance(pool, AsyncConnectionPool):
            msg = (
                f"AsyncPoolConnectionProvider(pool) requires a real AsyncConnectionPool, got {type(pool).__name__}. "
                "Do not pass duck-typed objects through this boundary."
            )
            raise TypeError(msg)
        self._pool = pool

    def _acquire_sync_context_impl(
        self: AsyncPoolConnectionProvider,
    ) -> contextlib.AbstractContextManager[SyncDatabaseConnection]:
        """Reject sync acquisition from an async-only pool provider."""
        msg = "AsyncPoolConnectionProvider cannot provide sync connections"
        _raise_provider_mode_error(ConnectionProviderErrorMessage(msg))

    def _acquire_async_context_impl(
        self: AsyncPoolConnectionProvider,
    ) -> contextlib.AbstractAsyncContextManager[AsyncDatabaseConnection]:
        """Delegate to the async pool and enforce its public async facade."""

        @contextlib.asynccontextmanager
        async def _validated() -> AsyncGenerator[AsyncDatabaseConnection]:
            async with self._pool.acquire() as conn:
                if not isinstance(conn, AsyncDatabaseConnection):
                    msg = f"Async pool yielded {type(conn).__name__}, expected AsyncDatabaseConnection"
                    raise TypeError(msg)
                yield conn

        return _validated()

    @property
    def notification_subscription_mode(self) -> NotificationSubscriptionMode:
        return NotificationSubscriptionMode.ASYNC

    def _subscribe_notifications_impl(
        self,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> contextlib.AbstractAsyncContextManager[AsyncNotificationSubscription]:
        return pool_notification_subscription(self, self._pool, channels, session_id=session_id)


class DualPoolConnectionProvider(ConnectionProvider):
    """Routes sync and async acquisition to distinct mode-specific pools."""

    __slots__ = ("_async_pool", "_sync_pool")

    def __init__(
        self,
        *,
        sync_pool: SyncConnectionPool,
        async_pool: AsyncConnectionPool,
    ) -> None:
        if not isinstance(sync_pool, SyncConnectionPool):
            msg = f"sync_pool must be SyncConnectionPool, got {type(sync_pool).__name__}"
            raise TypeError(msg)
        if not isinstance(async_pool, AsyncConnectionPool):
            msg = f"async_pool must be AsyncConnectionPool, got {type(async_pool).__name__}"
            raise TypeError(msg)
        self._sync_pool = sync_pool
        self._async_pool = async_pool

    def _acquire_sync_context_impl(
        self: DualPoolConnectionProvider,
    ) -> contextlib.AbstractContextManager[SyncDatabaseConnection]:
        """Delegate sync acquisition to the sync pool."""

        @contextlib.contextmanager
        def _validated() -> Generator[SyncDatabaseConnection]:
            with self._sync_pool.acquire_context() as conn:
                if not isinstance(conn, SyncDatabaseConnection):
                    msg = f"Sync pool yielded {type(conn).__name__}, expected SyncDatabaseConnection"
                    raise TypeError(msg)
                yield conn

        return _validated()

    def _acquire_async_context_impl(
        self: DualPoolConnectionProvider,
    ) -> contextlib.AbstractAsyncContextManager[AsyncDatabaseConnection]:
        """Delegate async acquisition to the async pool."""

        @contextlib.asynccontextmanager
        async def _validated() -> AsyncGenerator[AsyncDatabaseConnection]:
            async with self._async_pool.acquire() as conn:
                if not isinstance(conn, AsyncDatabaseConnection):
                    msg = f"Async pool yielded {type(conn).__name__}, expected AsyncDatabaseConnection"
                    raise TypeError(msg)
                yield conn

        return _validated()

    @property
    def notification_subscription_mode(self) -> NotificationSubscriptionMode:
        return NotificationSubscriptionMode.DUAL

    def _subscribe_notifications_sync_impl(
        self,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> contextlib.AbstractContextManager[SyncNotificationSubscription]:
        return sync_notification_subscription(
            self,
            channels,
            session_id=session_id,
            initial_resync_required=True,
        )

    def _subscribe_notifications_impl(
        self,
        channels: frozenset[NotificationChannelName],
        *,
        session_id: SessionId,
    ) -> contextlib.AbstractAsyncContextManager[AsyncNotificationSubscription]:
        return pool_notification_subscription(self, self._async_pool, channels, session_id=session_id)

