@pure_lazy
def is_versioned_model_type[ModelT](model_type: type[ModelT]) -> bool:
    from l2000_connection.deferred_imports import ConnectionModuleName, load_connection_module

    versioned_schema = load_connection_module(ConnectionModuleName("l7000_versioned_schema.versioned_schema"))
    return issubclass(model_type, versioned_schema.VersionedObjectRow)


@pure_lazy
def schema_artifact_identifier_name(value: object) -> SchemaObjectName | None:
    if value is None:
        return optional_branded_text(None, SchemaObjectName)
    if isinstance(value, str):
        return optional_branded_text(value, SchemaObjectName)
    resolved_name = getattr(value, "name", None)
    if resolved_name is not None:
        return optional_branded_text(str(resolved_name() if callable(resolved_name) else resolved_name), SchemaObjectName)
    raw_name = getattr(value, "_name", None)
    if raw_name is not None:
        return optional_branded_text(schema_artifact_identifier_name(raw_name) or str(raw_name), SchemaObjectName)
    return optional_branded_text(None, SchemaObjectName)


def validate_schema_generation_receipt(
    tags: Sequence[SchemaGenerationTag],
    entries: SchemaGenerationRows,
) -> tuple[tuple[SchemaGenerationTag, int], ...]:
    """Validate native generation rows before publishing committed cache state."""
    generations = dict(entries.entries)
    if (
        len(generations) != len(entries.entries)
        or set(generations) != set(tags)
        or any(not isinstance(value, int) or isinstance(value, bool) or value <= 0 for value in generations.values())
    ):
        raise RuntimeError("Invalid schema generation batch receipt")
    return tuple((tag, generations[tag]) for tag in tags)


@pure_lazy
def nonempty_str(value: object) -> NonEmptyTextValue | None:
    if not isinstance(value, str):
        return None
    normalized = value.strip()
    if not normalized:
        return None
    return NonEmptyTextValue(normalized)


