    names: set[SqlTableName] = set()
    candidates = [
        candidate
        for attribute in ("table_name", "_table_name", "_log_table_name", "content_table")
        if (candidate := getattr(value, attribute, None)) is not None
    ]
    table_ref = getattr(value, "_table", None)
    raw_name = getattr(table_ref, "_name", None)
    nested_name = getattr(raw_name, "name", None)
    if nested_name is not None:
        candidates.append(nested_name)
