    table_names: Sequence[SqlTableName],
) -> Mapping[SqlTableName, frozenset[SqlColumnName]]:
    table_names = tuple(table_names)
    if not isinstance(tables, dict):
        return {}
    snapshots: dict[SqlTableName, frozenset[SqlColumnName]] = {}
    for table_name in table_names:
        table_snapshot = tables.get(table_name)
        if table_snapshot is None:
            continue
        snapshot_columns = table_snapshot.columns
        if snapshot_columns is None:
            continue
        snapshots[table_name] = frozenset(SqlColumnName(column.name) for column in snapshot_columns if isinstance(column.name, str))
    return snapshots


