@pure_lazy
def _require_bootstrap_field_value(value: object) -> _BootstrapFieldValue:
    from l3200_metadata.bootstrap_data_plan import BootstrapRuntimeIdentityRef

    if isinstance(value, BootstrapRuntimeIdentityRef):
        return value
    match value:
        case None | str() | bytes() | int() | float() | Decimal() | bool() | datetime() | SysId():
            return value
        case dict():
            result: dict[str, _BootstrapFieldValue] = {}
            for key, item in value.items():
                match key:
                    case str():
                        result[key] = _require_bootstrap_field_value(item)
                    case _:
                        msg = "bootstrap row mappings require string keys"
                        raise TypeError(msg)
            return result
        case list():
            return [_require_bootstrap_field_value(item) for item in value]
        case tuple():
            return tuple(_require_bootstrap_field_value(item) for item in value)
        case _:
            msg = f"unsupported bootstrap row field value: {type(value).__name__}"
            raise TypeError(msg)


