    from impl.common.l2100_sql_grammar.ddl_effect_scope import SqlDdlEffectScope
    from impl.common.l2200_sql_dialect.sql_dialect import SqlDialect


@dataclass(frozen=True, slots=True)
class SqlDdlBundle(SqlRenderable):
    """Order-preserving renderable for deterministic DDL bundles."""

    statements: tuple[SqlRenderable, ...]
    logical_statement_count: int | Unset = UNSET
    logical_source_refs: tuple[ServerPlanRefId, ...] = ()
    logical_phase: SchemaDdlPhase | DefaultSchemaDdlPhase = field(
        default_factory=DefaultSchemaDdlPhase,
    )

    def __post_init__(self: Self) -> None:
        if self.logical_statement_count is not UNSET and self.logical_statement_count != len(self.statements):
            msg = "SqlDdlBundle.logical_statement_count must match statement count"
            raise ValueError(msg)
        if self.logical_source_refs and len(self.logical_source_refs) != len(self.statements):
            msg = "SqlDdlBundle.logical_source_refs must match statement count"
            raise ValueError(msg)

    def ddl_effect_scope(self: SqlDdlBundle, dialect: SqlDialect) -> SqlDdlEffectScope:
        """Combine the declared DDL effects in execution order."""
        from impl.common.l2100_sql_grammar.ddl_effect_scope import combined_ddl_effect_scope

        return combined_ddl_effect_scope(self.statements, dialect)

    def render(self, dialect: SqlDialect) -> SqlFragment:
        rendered = SQL_EMPTY
        for idx, statement in enumerate(self.statements):
            if idx > 0:
                rendered = rendered + SQL_SEMICOLON
            rendered = rendered + statement.render(dialect)
        return rendered

    def structural_fingerprint(self, dialect: SqlDialect) -> tuple[object, ...] | None:
        child_fingerprints: list[tuple[object, ...]] = []
        for statement in self.statements:
            fingerprint = statement.structural_fingerprint(dialect)
            if fingerprint is None:
                return None
            child_fingerprints.append(fingerprint)
        return ("SqlDdlBundle", tuple(child_fingerprints))

    def logical_statements(self: Self) -> tuple[SqlRenderable, ...]:
        """Return the ordered logical DDL statements represented by this bundle."""

        return self.statements

    def statement_grammars(self: Self, dialect: SqlDialect) -> tuple[SqlRenderable, ...]:
        """Return explicit statement children before rendering."""

        del dialect
        return self.statements

    @property
    def params_per_stmt(self: Self) -> tuple[None, ...]:
        """Expose parameter-free children to transition-cache renderers."""

        return tuple(None for _statement in self.statements)

