def _require_composed_step_tables_lazy(
    txn: SyncWriteTransaction | AsyncWriteTransaction,
    *,
    before: frozenset[ServerPlanRefId],
    accesses: tuple[AuthorityModelAccess, ...],
) -> None:
    plan = txn._get_transaction_plan_lazy()
    read_tables = {str(get_table_name(access.model_cls)) for access in accesses if AuthorityAction.READ in access.actions}
    write_tables = {
        str(get_table_name(access.model_cls))
        for access in accesses
        if any(action is not AuthorityAction.READ for action in access.actions)
    }
    for step in plan.owned_steps_snapshot():
        if ServerPlanRefId(step.ref_id) in before:
            continue
        undeclared_reads = {str(table) for table in step.tables_read()} - read_tables
        undeclared_writes = {str(table) for table in step.tables_written()} - write_tables
        if undeclared_reads or undeclared_writes:
            raise SystemAuthorityError(
                "Composed system-authority work accessed undeclared tables: "
                f"reads={sorted(undeclared_reads)!r}, writes={sorted(undeclared_writes)!r}.",
            )


