@pure_lazy
def _resource_admits_model[T: DatabaseObjectRow](
    resource: AuthorityResource,
    model_cls: type[T],
) -> bool:
    model_identity = _model_semantic_identity(model_cls)
    if model_identity in resource.allowed_model_semantic_ids:
        return True
    return resource.include_model_subtypes and not _model_semantic_identities(model_cls).isdisjoint(
        resource.allowed_model_semantic_ids,
    )


@dataclass(frozen=True, slots=True)
class _ResourceBoundQuery[T: DatabaseObjectRow]:
    """Query wrapper that enforces mutations against the resource action set."""

    _query: WriteQueryBuilder[T]
    _transaction: _ResourceBoundAuthorityTransaction | _AsyncResourceBoundAuthorityTransaction
    _model_cls: type[T]

    def filter(
        self: _ResourceBoundQuery[T],
        *expressions: Expression[bool, T] | Field[bool, T],
    ) -> _ResourceBoundQuery[T]:
        self._query.filter(*expressions)
        return self

    def update_field_lazy[ValueT](
        self: _ResourceBoundQuery[T],
        target: Field[ValueT, T],
        value: ValueT,
    ) -> LazyResult[int]:
        """Update one typed field under the resource update action."""
        self._transaction._require(self._model_cls, AuthorityAction.UPDATE)
        with _resource_bound_permission_scope(self._transaction._txn, (self._model_cls,)):
            return self._query.update_lazy(**{str(target.name): value})

    def delete_lazy(self: _ResourceBoundQuery[T]) -> LazyResult[int]:
        self._transaction._require(self._model_cls, AuthorityAction.DELETE)
        with _resource_bound_permission_scope(self._transaction._txn, (self._model_cls,)):
            return self._query.delete_lazy()

    def execute_lazy(self: _ResourceBoundQuery[T]) -> LazyResult[Sequence[T]]:
        self._transaction._require(self._model_cls, AuthorityAction.READ)
        with _resource_bound_permission_scope(self._transaction._txn, (self._model_cls,)):
            return self._query.execute_lazy()

    def count_lazy(self: _ResourceBoundQuery[T]) -> LazyResult[int]:
        """Count rows under the resource read action."""
        self._transaction._require(self._model_cls, AuthorityAction.READ)
        return self._query.count_lazy()

    def limit(self: _ResourceBoundQuery[T], count: int) -> _ResourceBoundQuery[T]:
        self._query.limit(count)
        return self


@dataclass(frozen=True, slots=True)
class _ResourceBoundAuthorityTransaction:
    """Write-plan proxy that validates every admitted model and action."""

    _txn: SyncWriteTransaction
    _resources: tuple[AuthorityResource, ...]

    @pure_lazy
    def _require_model[T: DatabaseObjectRow](
        self: _ResourceBoundAuthorityTransaction,
        model_cls: type[T],
    ) -> None:
        model_identity = _model_semantic_identity(model_cls)
