    _declared_ref_ids: frozenset[ServerPlanRefId]

    def __init__(
        self: SyncSystemAuthorityWorkScope,
        scope: SyncWritePlanScope,
        profile: SystemAuthorityProfile,
    ) -> None:
        self._scope = scope
        self._profile = profile
        self._baseline_ref_ids = frozenset(scope.plan.owned_step_ref_ids())
        self._declared_ref_ids = frozenset()

    def add(
        self: SyncSystemAuthorityWorkScope,
        resource: AuthorityResource,
        build: Callable[[SyncSystemAuthorityResourceScope], WorkResultT],
    ) -> WorkResultT:
        """Build steps through one exact resource-bound transaction view."""
        if resource not in self._profile.resources:
            raise SystemAuthorityError("System authority work declared an unadmitted resource.")
        before = set(self._scope.plan.owned_step_ref_ids())
        result = build(SyncSystemAuthorityResourceScope(self._scope, (resource,)))
        self._declared_ref_ids = self._declared_ref_ids.union(set(self._scope.plan.owned_step_ref_ids()) - before)
        return result

    def add_many(
        self: SyncSystemAuthorityWorkScope,
        resources: Sequence[AuthorityResource],
        build: Callable[[SyncSystemAuthorityResourceScope], WorkResultT],
    ) -> WorkResultT:
        """Build one plan fragment that has an exact multi-resource contract."""
        selected = tuple(resources)
        if not selected or any(resource not in self._profile.resources for resource in selected):
            raise SystemAuthorityError("System authority work declared an unadmitted resource set.")
        before = set(self._scope.plan.owned_step_ref_ids())
        result = build(SyncSystemAuthorityResourceScope(self._scope, selected))
        self._declared_ref_ids = self._declared_ref_ids.union(set(self._scope.plan.owned_step_ref_ids()) - before)
        return result

    def return_result[ResultT](
        self: SyncSystemAuthorityWorkScope,
        name: SystemAuthorityResultName,
        value: ResultT,
    ) -> ResultT:
        """Publish one named result from the resource-declared actor plan."""
        self._scope.return_result(name, value)
        return value

    def _require_all_steps_declared(self: SyncSystemAuthorityWorkScope) -> None:
        application_refs = set(self._scope.plan.owned_step_ref_ids()) - set(self._baseline_ref_ids)
        if not application_refs.issubset(self._declared_ref_ids):
            raise SystemAuthorityError("System authority work added a step without a resource declaration.")


