        self._declared_ref_ids = self._declared_ref_ids.union(
            set(self._scope.plan.owned_step_ref_ids()) - before,
        )

    def add_lazy(
        self: AsyncSystemAuthorityWorkScope,
        resource: AuthorityResource,
        build: Callable[[AsyncSystemAuthorityResourceScope], WorkResultT],
    ) -> WorkResultT:
        """Build steps attributed to one exact admitted resource."""
        selected, before = self._begin_add_lazy((resource,))
        result = build(AsyncSystemAuthorityResourceScope(self._scope, selected))
        self._finish_add_lazy(before)
        return result

    async def add_async(
        self: AsyncSystemAuthorityWorkScope,
        resource: AuthorityResource,
        build: Callable[[AsyncSystemAuthorityResourceScope], Awaitable[WorkResultT]],
    ) -> WorkResultT:
        """Build awaited plan steps through one admitted resource."""
        selected, before = self._begin_add_lazy((resource,))
        result = await build(AsyncSystemAuthorityResourceScope(self._scope, selected))
        self._finish_add_lazy(before)
        return result

    def add_many_lazy(
        self: AsyncSystemAuthorityWorkScope,
        resources: Sequence[AuthorityResource],
        build: Callable[[AsyncSystemAuthorityResourceScope], WorkResultT],
    ) -> WorkResultT:
        """Build one async plan fragment with an exact multi-resource contract."""
        selected, before = self._begin_add_lazy(resources)
        result = build(AsyncSystemAuthorityResourceScope(self._scope, selected))
        self._finish_add_lazy(before)
        return result

    async def add_many_async(
        self: AsyncSystemAuthorityWorkScope,
        resources: Sequence[AuthorityResource],
        build: Callable[[AsyncSystemAuthorityResourceScope], Awaitable[WorkResultT]],
    ) -> WorkResultT:
        """Build awaited plan steps through an exact admitted resource set."""
        selected, before = self._begin_add_lazy(resources)
        result = await build(AsyncSystemAuthorityResourceScope(self._scope, selected))
        self._finish_add_lazy(before)
        return result

    def return_result[ResultT](
        self: AsyncSystemAuthorityWorkScope,
        name: SystemAuthorityResultName,
        value: ResultT,
    ) -> ResultT:
        """Publish one named result from the resource-declared actor plan."""
        self._scope.return_result(name, value)
        return value

    def _require_all_steps_declared(self: AsyncSystemAuthorityWorkScope) -> None:
        application_refs = set(self._scope.plan.owned_step_ref_ids()) - set(self._baseline_ref_ids)
        if not application_refs.issubset(self._declared_ref_ids):
            raise SystemAuthorityError("System authority work added a step without a resource declaration.")


