@dataclass(frozen=True, slots=True)
class SyncSystemAuthorityIssuer:
    """Create short-lived tracked requests for one trusted composition root."""

    authority: SystemAuthorityService
    profile: SystemAuthorityProfile
    operation: SystemOperation
    workload_principal: WorkloadPrincipal
    purpose: SystemPurpose
    issuer: ApprovalIssuer
    operation_plan_digest: OperationPlanDigest
    capability_lifetime: timedelta = timedelta(minutes=5)
    service_session_lifetime: timedelta = timedelta(minutes=10)
    originating_authority: OriginatingActorAuthority | _UnspecifiedAuthorityBinding = (
        _UNSPECIFIED_AUTHORITY_BINDING
    )
    operation_id: LifecycleOperationId | _UnspecifiedAuthorityBinding = _UNSPECIFIED_AUTHORITY_BINDING
    approval_reference: ApprovalReference | _UnspecifiedAuthorityBinding = _UNSPECIFIED_AUTHORITY_BINDING

    def __post_init__(self: SyncSystemAuthorityIssuer) -> None:
        self.profile.require_operation(self.operation)
        if self.capability_lifetime <= timedelta(0):
            raise ValueError("System authority capability lifetime must be positive")
        if self.service_session_lifetime < self.capability_lifetime:
            raise ValueError("System authority service session cannot expire before its capability")
        if self.service_session_lifetime > timedelta(minutes=15):
            raise ValueError("System authority service sessions cannot exceed 15 minutes")

    def planned(self: SyncSystemAuthorityIssuer) -> SyncPlannedSystemAuthorityRequestIssuer:
        """Return the request issuer bound to this maintained actor operation."""
        profile = self.profile
        operation = self.operation

        def issue(
            connection: SyncDatabaseConnection,
            route: SystemAuthorityRouteBinding,
            semantic_plan_digest: SemanticPlanDigest,
        ) -> SystemAuthorityRequest:
            now = datetime.now(UTC)

            def issue_in(txn: SyncWriteTransaction) -> SystemAuthorityRequest:
                session = AuthenticatedServiceSession.issued_lazy(
                    txn,
                    workload_principal=self.workload_principal,
                    authority_domain=profile.authority_domain,
                    profile_id=profile.profile_id,
                    subsystem=profile.subsystem,
                    provider_binding_id=route.provider_binding_id,
                    route_key=route.route_key,
                    route_generation=route.route_generation,
                    schema_fingerprint=route.schema_fingerprint,
                    expires_at=now + self.service_session_lifetime,
                )
                scope = SystemAuthorityScope.for_profile(
                    profile=profile,
                    service_session=session,
                    workload_principal=self.workload_principal,
                    route=route,
                    operation_plan_digest=self.operation_plan_digest,
                    semantic_plan_digest=semantic_plan_digest,
                    purpose=self.purpose,
                    issuer=self.issuer,
                    nonce=CapabilityNonce(str(session.session_id)),
                    originating_authority=(
                        None
                        if isinstance(self.originating_authority, _UnspecifiedAuthorityBinding)
                        else self.originating_authority
                    ),
                    operation_id=(
                        None
                        if isinstance(self.operation_id, _UnspecifiedAuthorityBinding)
                        else self.operation_id
                    ),
                    approval_reference=(
                        None
                        if isinstance(self.approval_reference, _UnspecifiedAuthorityBinding)
                        else self.approval_reference
                    ),
                )
                token = self.authority.issue(
                    txn,
                    scope=scope,
                    operations=(operation,),
                    connection=connection,
                    issued_at=now,
                    expires_at=now + self.capability_lifetime,
                )
                return SystemAuthorityRequest(
                    capability_token=token,
                    scope=scope,
                    operation=operation,
                )

            return execute_write_plan_workflow(
                connection,
                SyncWritePlanWorkflow(session_id=SessionId.schema(), build=issue_in),
            )

        return SyncPlannedSystemAuthorityRequestIssuer(issue)


