def _require_request_contract(
    request: SystemAuthorityRequest,
    *,
    profile: SystemAuthorityProfile,
    operation: SystemOperation,
    route: SystemAuthorityRouteBinding,
) -> None:
    profile.require_operation(operation)
    if request.operation != operation:
        raise SystemAuthorityError("System authority request operation does not match the entrypoint operation.")
    scope = request.scope
    profile.require_resource_binding(scope.resource_binding)
    if scope.authority_domain != profile.authority_domain:
        raise SystemAuthorityError("System authority request domain does not match the entrypoint profile.")
    if scope.profile_id != profile.profile_id:
        raise SystemAuthorityError("System authority request profile identity does not match the entrypoint profile.")
    if scope.mode != profile.mode:
        raise SystemAuthorityError("System authority request mode does not match the entrypoint profile.")
    if scope.subsystem != profile.subsystem:
        raise SystemAuthorityError("System authority request subsystem does not match the entrypoint profile.")
    if scope.resources != profile.resources:
        raise SystemAuthorityError("System authority request resources do not match the entrypoint profile.")
    if (
        scope.provider_binding_id != route.provider_binding_id
        or scope.route_key != route.route_key
        or scope.route_generation != route.route_generation
        or scope.resource_binding != route.resource_binding
        or scope.schema_fingerprint != route.schema_fingerprint
        or route.lifecycle_state is not RouteLifecycleState.ACTIVE
    ):
        raise SystemAuthorityError("System authority request route does not match the provider-owned route.")
    if profile.approval_required and scope.approval_reference is None:
        raise SystemAuthorityError("System authority entrypoint requires an approval reference.")


@dataclass(frozen=True, slots=True)
class SystemActorAuthorityEntrypoint:
    """Profile-bound adapter selected by one maintained system actor."""

    profile: SystemAuthorityProfile
    operation: SystemOperation

    @pure_lazy
    def _execution_mode(self: SystemActorAuthorityEntrypoint) -> AuthorityMode:
        """Select the same profile mode for sync and async execution."""
        return self.profile.mode

    @pure_lazy
    def _planned_execution_mode(self: SystemActorAuthorityEntrypoint) -> AuthorityMode:
        """Select a data-plan mode and reject schema work before dispatch."""
        mode = self._execution_mode()
        if mode is AuthorityMode.SCHEMA:
            raise SystemAuthorityError("Schema authority does not use a data-plan entrypoint.")
        return mode

    def execute(
        self: SystemActorAuthorityEntrypoint,
        entrypoint: SyncSystemAuthorityEntrypoint,
        *,
        issue_request: SyncSystemAuthorityRequestIssuer,
        build_work: SyncActorWorkBuilder,
    ) -> PlanScopeResultValues[PlanResultValue]:
        """Invoke the mode-specific capability-aware sync composition."""
        return self._execute_by_mode(entrypoint, issue_request=issue_request, build_work=build_work)

    def _execute_by_mode(
        self: SystemActorAuthorityEntrypoint,
        entrypoint: SyncSystemAuthorityEntrypoint,
        *,
        issue_request: SyncSystemAuthorityRequestIssuer,
        build_work: SyncActorWorkBuilder,
    ) -> PlanScopeResultValues[PlanResultValue]:
        mode = self._execution_mode()
        if mode is AuthorityMode.READ:
            if not isinstance(build_work, SyncReadActorWorkBuilder):
                raise SystemAuthorityError("Read authority requires a synchronous read work builder.")
            return entrypoint.execute_read(
                profile=self.profile,
                operation=self.operation,
                issue_request=issue_request,
                build_work=build_work.build,
            )
        if mode is AuthorityMode.SCHEMA:
            if not isinstance(build_work, SyncSchemaActorWorkBuilder):
                raise SystemAuthorityError("Schema authority requires a synchronous schema work builder.")
            return entrypoint.execute_schema(
                profile=self.profile,
                operation=self.operation,
                issue_request=issue_request,
                build_work=build_work.build,
            )
        if not isinstance(build_work, SyncWriteActorWorkBuilder):
            raise SystemAuthorityError("Write authority requires a synchronous write work builder.")
        return entrypoint.execute_write(
            profile=self.profile,
            operation=self.operation,
            issue_request=issue_request,
            build_work=build_work.build,
        )

    def execute_planned(
        self: SystemActorAuthorityEntrypoint,
        entrypoint: SyncSystemAuthorityEntrypoint,
        *,
        issue_request: SyncPlannedSystemAuthorityRequestIssuer,
        build_work: SyncPlannedActorWorkBuilder,
    ) -> PlanScopeResultValues[PlanResultValue]:
        """Plan read or write actor work before authority issuance."""
        return self._execute_planned_by_mode(entrypoint, issue_request=issue_request, build_work=build_work)

    def _execute_planned_by_mode(
        self: SystemActorAuthorityEntrypoint,
        entrypoint: SyncSystemAuthorityEntrypoint,
        *,
        issue_request: SyncPlannedSystemAuthorityRequestIssuer,
        build_work: SyncPlannedActorWorkBuilder,
    ) -> PlanScopeResultValues[PlanResultValue]:
        mode = self._planned_execution_mode()
        if mode is AuthorityMode.READ:
            if not isinstance(build_work, SyncPlannedReadActorWorkBuilder):
                raise SystemAuthorityError("Planned read authority requires a synchronous read work builder.")
            return entrypoint.execute_read_planned(
                profile=self.profile,
                operation=self.operation,
                issue_request=issue_request,
                build_work=build_work.build,
            )
        if not isinstance(build_work, SyncPlannedWriteActorWorkBuilder):
            raise SystemAuthorityError("Planned write authority requires a synchronous write work builder.")
        return entrypoint.execute_planned(
            profile=self.profile,
            operation=self.operation,
            issue_request=issue_request,
            build_work=build_work.build,
        )

    async def execute_async(
        self: SystemActorAuthorityEntrypoint,
        entrypoint: AsyncSystemAuthorityEntrypoint,
        *,
        issue_request: AsyncSystemAuthorityRequestIssuer,
        build_work: AsyncActorWorkBuilder,
    ) -> PlanScopeResultValues[PlanResultValue]:
        """Invoke the mode-specific capability-aware async composition."""
        return await self._execute_by_mode_async(entrypoint, issue_request=issue_request, build_work=build_work)

    async def _execute_by_mode_async(
        self: SystemActorAuthorityEntrypoint,
        entrypoint: AsyncSystemAuthorityEntrypoint,
        *,
        issue_request: AsyncSystemAuthorityRequestIssuer,
        build_work: AsyncActorWorkBuilder,
    ) -> PlanScopeResultValues[PlanResultValue]:
        mode = self._execution_mode()
        if mode is AuthorityMode.READ:
            if not isinstance(build_work, AsyncReadActorWorkBuilder):
                raise SystemAuthorityError("Read authority requires an asynchronous read work builder.")
            return await entrypoint.execute_read_async(
                profile=self.profile,
                operation=self.operation,
                issue_request=issue_request,
                build_work=build_work.build,
            )
        if mode is AuthorityMode.SCHEMA:
            if not isinstance(build_work, AsyncSchemaActorWorkBuilder):
                raise SystemAuthorityError("Schema authority requires an asynchronous schema work builder.")
            return await entrypoint.execute_schema_async(
                profile=self.profile,
                operation=self.operation,
                issue_request=issue_request,
                build_work=build_work.build,
            )
        if not isinstance(build_work, AsyncWriteActorWorkBuilder):
            raise SystemAuthorityError("Write authority requires an asynchronous write work builder.")
        return await entrypoint.execute_write_async(
            profile=self.profile,
            operation=self.operation,
            issue_request=issue_request,
            build_work=build_work.build,
        )

    async def execute_planned_async(
        self: SystemActorAuthorityEntrypoint,
        entrypoint: AsyncSystemAuthorityEntrypoint,
        *,
        issue_request: AsyncPlannedSystemAuthorityRequestIssuer,
        build_work: AsyncPlannedActorWorkBuilder,
    ) -> PlanScopeResultValues[PlanResultValue]:
        """Plan async read or write actor work before authority issuance."""
        return await self._execute_planned_by_mode_async(
            entrypoint,
            issue_request=issue_request,
            build_work=build_work,
        )

    async def _execute_planned_by_mode_async(
        self: SystemActorAuthorityEntrypoint,
        entrypoint: AsyncSystemAuthorityEntrypoint,
        *,
        issue_request: AsyncPlannedSystemAuthorityRequestIssuer,
        build_work: AsyncPlannedActorWorkBuilder,
    ) -> PlanScopeResultValues[PlanResultValue]:
        mode = self._planned_execution_mode()
        if mode is AuthorityMode.READ:
            if not isinstance(build_work, AsyncPlannedReadActorWorkBuilder):
                raise SystemAuthorityError("Planned read authority requires an asynchronous read work builder.")
            return await entrypoint.execute_read_planned_async(
                profile=self.profile,
                operation=self.operation,
                issue_request=issue_request,
                build_work=build_work.build,
            )
        if not isinstance(build_work, AsyncPlannedWriteActorWorkBuilder):
            raise SystemAuthorityError("Planned write authority requires an asynchronous write work builder.")
        return await entrypoint.execute_planned_async(
            profile=self.profile,
            operation=self.operation,
            issue_request=issue_request,
            build_work=build_work.build,
        )


@dataclass(frozen=True, slots=True)
class SyncSystemAuthorityEntrypoint:
    """Execute one explicit system operation without invoking a legacy grant path."""

    provider: AuthorityBoundConnectionProvider
    authority: SystemAuthorityService
    approval_validator: SyncSystemApprovalValidator = SyncSystemApprovalValidator(
        _missing_sync_approval_validator,
    )

    def execute_read(
        self: SyncSystemAuthorityEntrypoint,
        *,
        profile: SystemAuthorityProfile,
        operation: SystemOperation,
        issue_request: SyncSystemAuthorityRequestIssuer,
        build_work: Callable[[SyncSystemAuthorityReadWorkScope], None],
    ) -> PlanScopeResultValues[PlanResultValue]:
        """Execute with a runtime work view that cannot construct writes."""
        if profile.mode is not AuthorityMode.READ:
            raise SystemAuthorityError("Read authority entrypoint requires a read profile.")

        def build_read_work(work: SyncSystemAuthorityWorkScope) -> None:
            build_work(SyncSystemAuthorityReadWorkScope(work))

        with self.provider.acquire_sync_context() as connection:
            request = issue_request.issue(connection, self.provider.route_binding)
            return self._execute_request(
                connection,
                request=request,
                profile=profile,
                operation=operation,
                build_work=build_read_work,
            )

    def execute_read_planned(
        self: SyncSystemAuthorityEntrypoint,
        *,
        profile: SystemAuthorityProfile,
        operation: SystemOperation,
        issue_request: SyncPlannedSystemAuthorityRequestIssuer,
        build_work: Callable[[SyncSystemAuthorityReadWorkScope], None],
