from __future__ import annotations

from collections.abc import Mapping
from typing import TYPE_CHECKING, cast

from l2070_batching.server_ref import inspect_server_value_shape_for_planning

from l2050_transaction.external_io_boundary import external_io_boundary

if TYPE_CHECKING:
    from l2050_transaction.transaction import LazyReadTransaction

# Generated by scripts/codemods/extract_connection_core_residue.py from l2000_connection/connection.py.
# Run import hygiene and focused connection tests after applying this codemod.


@external_io_boundary
def _mark_successful_auto_commit_if_needed(txn: LazyReadTransaction) -> None:
    """Repair transaction state after a successful callback-owned commit flush."""
    txn._mark_successful_auto_commit()


def _has_pending_callback_versioned_commit(txn: LazyReadTransaction) -> bool:
    callback_vtxn = txn._callback_versioned_txn
    if callback_vtxn is None:
        return False
    return bool(callback_vtxn._has_pending_lazy_commit)


def _callback_plan_owns_database_commit(txn: LazyReadTransaction) -> bool:
    """Return whether callback-owned branch publication includes the database commit."""
    plan = txn._get_transaction_plan_lazy()
    return any(step.owns_database_commit() for step in plan._steps)


@external_io_boundary
def _prepare_pending_callback_versioned_commit_flush(txn: LazyReadTransaction) -> None:
    if not _has_pending_callback_versioned_commit(txn):
        return
    plan = txn._get_transaction_plan_lazy()
    object.__setattr__(plan, "_txn", txn)


def _resolve_explicitly_committed_callback_result[T](value: T) -> T:
    """Resolve callback returns after the callback already executed its lazy plan."""
    from l2055_lazy_result.lazy_result import LazyResult
    from l2055_lazy_result.lazy_seq import LazySeq

    if isinstance(value, LazyResult | LazySeq):
        try:
            shape = inspect_server_value_shape_for_planning(
                value,
                site="explicitly committed callback result",
                prefer_materialized_value=True,
            )
        except AttributeError as exc:
            msg = "explicitly committed callback returned an unresolved lazy value"
            raise RuntimeError(msg) from exc
        if shape.has_literal_value:
            return cast("T", shape.literal_value)
        msg = "explicitly committed callback returned an unresolved lazy value"
        raise RuntimeError(msg)
    if isinstance(value, Mapping):
        return cast(
            "T",
            {key: _resolve_explicitly_committed_callback_result(item) for key, item in value.items()},
        )
    if isinstance(value, tuple):
        return cast("T", tuple(_resolve_explicitly_committed_callback_result(item) for item in value))
    if isinstance(value, list):
        return cast("T", [_resolve_explicitly_committed_callback_result(item) for item in value])
    return value

