"""Lazy helpers for schema-transaction-owned operations."""

from __future__ import annotations

from collections.abc import Sequence

from collections.abc import Awaitable, Callable
from typing import NoReturn

from l2055_lazy_result.lazy_operation import LazyOperation
from l2055_lazy_result.lazy_result import LazyResult
from l2055_lazy_result.lazy_seq import LazySeq


class SchemaOperationLazyContext[ResultT]:
    """Execution context for a single schema operation closure."""

    __slots__ = ("_async_fn", "_sync_fn")

    def __init__(
        self,
        sync_fn: Callable[[], ResultT],
        async_fn: Callable[[], Awaitable[ResultT]] | None = None,
    ) -> None:
        self._sync_fn = sync_fn
        self._async_fn = async_fn

    def queue_single[T](
        self,
        operation: LazyOperation[T],
        pre_populated: T | None = None,
    ) -> LazyResult[T]:
        return LazyResult(operation, self, pre_populated)

    def queue_sequence[T](self, operation: LazyOperation[list[T]]) -> NoReturn:
        del operation
        msg = "schema operation lazy context only supports single-result operations"
        raise NotImplementedError(msg)

    @staticmethod
    def _require_result[TerminalT](
        result: LazyResult[TerminalT] | LazySeq[TerminalT],
    ) -> LazyResult[TerminalT]:
        if isinstance(result, LazySeq):
            msg = "schema operation lazy context only supports LazyResult terminals"
            raise TypeError(msg)
        return result

    def execute_sync(
        self,
        result: LazyResult[ResultT] | LazySeq[ResultT],
    ) -> None:
        result = self._require_result(result)
        result._set_resolved(self._sync_fn())

    async def execute_async(
        self,
        result: LazyResult[ResultT] | LazySeq[ResultT],
    ) -> None:
        result = self._require_result(result)
        if self._async_fn is None:
            result._set_resolved(self._sync_fn())
            return
        result._set_resolved(await self._async_fn())


def schema_operation_lazy[T](
    sync_fn: Callable[[], T],
    async_fn: Callable[[], Awaitable[T]] | None = None,
) -> LazyResult[T]:
    """Build a pending lazy terminal for a schema-owned operation."""
    return LazyResult(
        LazyOperation(op="ddl_effect"),
        SchemaOperationLazyContext(sync_fn, async_fn),
    )

