"""Pure schema requirements used by SQL infrastructure planning."""

from __future__ import annotations

from l1000_schema.column_utils import get_db_column_name
from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
from l1000_schema.schema_def import DatabaseObjectRow
from l1400_types import DynamicFieldName, SysId
from l2055_lazy_result.purity import pure_lazy
from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName


@pure_lazy
def required_model_columns(model_cls: type[DatabaseObjectRow[SysId]]) -> frozenset[SqlColumnName]:
    """Return the physical columns required for a model-backed system table."""
    columns = {
        SqlColumnName(get_db_column_name(model_cls, DynamicFieldName(field_name)))
        for field_name in model_cls.model_fields
    }
    for config in get_large_column_configs(model_cls):
        columns.add(
            SqlColumnName(
                get_db_column_name(
                    model_cls,
                    DynamicFieldName(large_column_pointer_name(config.column)),
                ),
            ),
        )
    return frozenset(columns)

