from __future__ import annotations

from typing import Any
from collections.abc import Callable

from impl.common.l2060_query_spec.query_spec import QuerySpec
from l1000_schema.column_utils import get_db_column_name
from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
from l1400_types.type_surface_contracts import (
    QueryPrerenderSeam,
    QueryPrerenderShapeKey,
)
from impl.common.l2155_query_prerender_cache import (
    QueryPreRenderAnalysis,
    QueryPreRenderCache,
    QueryPreRenderMode,
)
from impl.common.l2160_terminal_prerender_cache import TerminalPreRenderAnalysis
from impl.common.l2190_query_prerender_contracts import (
    InstrumentationPrerenderKwargs,
    PreparedCachePrerenderKwargs,
    QueryPrerenderInfo,
    QueryPrerenderShapeMetadata,
    RenderedPrerenderSignature,
)
from impl.common.l2200_sql_dialect.sql_connection import (
    AttributedSqlRenderable,
    Sequence,
    SqlFragment,
    SqlRenderable,
    cast,
    collect_params_fast,
    compute_structural_fingerprint,
    rendered_bind_placeholder_count,
)
from collections.abc import Sequence
from impl.common.l2200_sql_dialect.sql_dialect import SqlDialect

# Generated by scripts/codemods/split_sql_connection_mixins.py from impl/common/l2200_sql_dialect/sql_connection.py.
# Run import hygiene and SQL/backend tests after applying this codemod.


def _query_spec_prerender_result_columns(
    spec: QuerySpec[Any],
    mode: QueryPreRenderMode,
) -> tuple[str, ...] | None:
    """Return the closed terminal projection carried by a prerendered QuerySpec."""
    if mode == "count":
        return ("count",)
    if mode == "exists":
        return ("exists",)
    if spec.select_columns is not None:
        return None
    return tuple(get_db_column_name(spec.model_cls, field_name) for field_name in spec.model_cls.model_fields)


class _SqlPrerenderPlanningMixin:
    """Query prerender, CTE template, and terminal cache planning."""

    _sql_maintenance_service: Any
    get_dialect: Callable[[], SqlDialect]
    _compile_query_spec_sql: Callable[..., tuple[str, tuple[object, ...]]]

    def enable_query_prerender_cache(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.enable_query_prerender_cache(*args, **kwargs)

    def enable_cte_template_cache(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.enable_cte_template_cache(*args, **kwargs)

    def enable_terminal_prerender_cache(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.enable_terminal_prerender_cache(*args, **kwargs)

    def disable_query_prerender_cache(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.disable_query_prerender_cache(*args, **kwargs)

    def disable_cte_template_cache(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.disable_cte_template_cache(*args, **kwargs)

    def disable_terminal_prerender_cache(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.disable_terminal_prerender_cache(*args, **kwargs)

    def clear_query_prerender_cache(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.clear_query_prerender_cache(*args, **kwargs)

    def clear_terminal_prerender_cache(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.clear_terminal_prerender_cache(*args, **kwargs)

    def get_query_prerender_cache_statistics(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.get_query_prerender_cache_statistics(*args, **kwargs)

    def get_query_prerender_cache_debug_report(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.get_query_prerender_cache_debug_report(*args, **kwargs)

    def get_terminal_prerender_cache_statistics(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.get_terminal_prerender_cache_statistics(*args, **kwargs)

    def get_terminal_prerender_cache_debug_report(self, *args: Any, **kwargs: Any) -> Any:
        return self._sql_maintenance_service.get_terminal_prerender_cache_debug_report(*args, **kwargs)

    def _execution_needs_terminal_prerender_info(self: Any) -> bool:
        """Return whether execution observers need terminal prerender metadata."""
        return False

    def analyze_query_prerenderability(
        self: Any,
        spec: QuerySpec[Any],
        *,
        mode: QueryPreRenderMode = "select",
    ) -> QueryPreRenderAnalysis:
        """Analyze whether a QuerySpec can be reused before grammar construction."""
        from impl.common.l2155_query_prerender_cache import analyze_query_prerenderability

        return analyze_query_prerenderability(spec, mode=mode, dialect=self.get_dialect())

    def compile_query_spec_fragment(
        self: Any,
        spec: QuerySpec[Any],
        *,
        mode: QueryPreRenderMode = "select",
    ) -> SqlFragment:
        """Compile a QuerySpec to a fragment, using cached plans when available."""
        cache: QueryPreRenderCache | None = getattr(self, "_query_prerender_cache", None)
        dialect = self.get_dialect()
        analysis = self.analyze_query_prerenderability(spec, mode=mode)
        cache_hit = False
        if cache is not None and cache.is_enabled():
            cache_hit = analysis.is_prerenderable and cache.has_plan(analysis.exact_shape_key)
            sql_str, params = cache.bind_or_compile_sql(
                spec,
                mode=mode,
                dialect=dialect,
                compile_sql=self._compile_query_spec_sql,
            )
        else:
            sql_str, params = self._compile_query_spec_sql(spec, mode, dialect)
        info = QueryPrerenderInfo.from_shape(
            QueryPrerenderShapeMetadata(
                exact_shape_key=QueryPrerenderShapeKey(analysis.exact_shape_key),
                family_shape_key=QueryPrerenderShapeKey(analysis.family_shape_key),
                mode=mode,
                seam=QueryPrerenderSeam("query_spec"),
            ),
            prerender_cache_hit=cache_hit,
            prerender_supported=analysis.is_prerenderable,
            result_columns=(
                tuple(map(SqlColumnName, result_columns))
                if (result_columns := _query_spec_prerender_result_columns(spec, mode)) is not None
                else None
            ),
        )
        fragment = SqlFragment(sql_str, params)
        fragment._query_prerender_info = info
        self._remember_rendered_query_prerender_info(sql_str, params, info)
        return fragment

    def remember_query_spec_prerender_info_for_stmt(
        self: Any,
        stmt: SqlRenderable,
        *,
        spec: QuerySpec[Any],
        mode: QueryPreRenderMode,
    ) -> SqlRenderable:
        """Remember query-spec attribution for a terminal statement object."""
        return cast("SqlRenderable", self._attach_query_spec_prerender_info(stmt, spec=spec, mode=mode))

    def _try_cte_template_cache(
        self: Any,
        stmt: SqlRenderable,
        params: tuple[object, ...],
        external_params_first: bool,
        cte_cache: dict[tuple[object, ...], tuple[str, int]],
        *,
        cte_fingerprint: tuple[object, ...] | None = None,
    ) -> tuple[str, tuple[object, ...]] | None:
        """Return cached SQL and rebound params for matching CTE grammars."""

        fingerprint = (
            cte_fingerprint
            if cte_fingerprint is not None
            else self._compute_cte_template_fingerprint(
                stmt,
                params=params,
                external_params_first=external_params_first,
                needs_returning=False,
            )
        )
        if fingerprint is None:
            return None

        entry = cte_cache.get(fingerprint)
        if entry is None:
            return None

        sql_template, expected_param_count = entry
        dialect = self.get_dialect()
        embedded_params = collect_params_fast(dialect.transform_grammar_for_execution(stmt), dialect)
        all_params = params + embedded_params if external_params_first else embedded_params + params
        if len(all_params) != expected_param_count:
            del cte_cache[fingerprint]
            return None
        if rendered_bind_placeholder_count(sql_template) != len(all_params):
            del cte_cache[fingerprint]
            return None
        return sql_template, all_params

    def _compute_cte_template_fingerprint(
        self: Any,
        stmt: SqlRenderable,
        *,
        params: tuple[object, ...] = (),
        external_params_first: bool = False,
        needs_returning: bool = False,
    ) -> tuple[object, ...] | None:
        from impl.common.l2160_terminal_prerender_cache import analyze_terminal_prerenderability

        fingerprint_target = stmt.inner if isinstance(stmt, AttributedSqlRenderable) else stmt
        if (
            type(fingerprint_target).__module__ == "impl.common.l2100_sql_grammar.domain.versioning.stmt_cte"
            and type(fingerprint_target).__name__ == "SqlSelectWithCte"
            and type(getattr(fingerprint_target, "_select", None)).__name__ != "SqlSelect"
        ):
            return None
        dialect = self.get_dialect()
        fingerprint = compute_structural_fingerprint(fingerprint_target, dialect)
        if fingerprint is None:
            return None

        exact_shape_keys = self._collect_stmt_query_prerender_exact_shape_keys(stmt)
        if exact_shape_keys is None:
            return None
        terminal_analysis = analyze_terminal_prerenderability(
            stmt,
            external_params=params,
            external_params_first=external_params_first,
            needs_returning=needs_returning,
            dialect=dialect,
        )
        if not exact_shape_keys:
            return (*fingerprint, ("terminal_exact_shape", terminal_analysis.exact_shape_key))
        return (
            *fingerprint,
            ("query_spec_exact_shapes", exact_shape_keys),
            ("terminal_exact_shape", terminal_analysis.exact_shape_key),
        )

    def _collect_stmt_query_prerender_exact_shape_keys(
        self: Any,
        stmt: object,
    ) -> tuple[str, ...] | None:
        if isinstance(stmt, tuple | list | set | frozenset) and len(stmt) > 512:
            return None
        exact_shape_keys: list[str] = []
        self._walk_stmt_query_prerender_info(stmt, exact_shape_keys, seen=set())
        return tuple(exact_shape_keys)

    def _walk_stmt_query_prerender_info(
        self: Any,
        value: object,
        exact_shape_keys: list[str],
        *,
        seen: set[int],
    ) -> None:
        if value is None or isinstance(value, str | bytes | int | float | bool):
            return

        value_id = id(value)
        if value_id in seen:
            return
        seen.add(value_id)

        if isinstance(value, AttributedSqlRenderable):
            exact_shape_key = value.prerender_info.attributed.exact_shape_key
            if exact_shape_key is not None:
                exact_shape_keys.append(exact_shape_key)
            self._walk_stmt_query_prerender_info(value.inner, exact_shape_keys, seen=seen)
            return

        if isinstance(value, SqlFragment):
            prior_info = getattr(value, "_query_prerender_info", None)
            if isinstance(prior_info, QueryPrerenderInfo):
                exact_shape_key = prior_info.attributed.exact_shape_key
                if exact_shape_key is not None:
                    exact_shape_keys.append(exact_shape_key)
            return

        if isinstance(value, dict):
            for item in value.values():
                self._walk_stmt_query_prerender_info(item, exact_shape_keys, seen=seen)
            return

        if isinstance(value, tuple | list | set | frozenset):
            for item in value:
                self._walk_stmt_query_prerender_info(item, exact_shape_keys, seen=seen)
            return

        slot_names: list[str] = []
        for cls in type(value).__mro__:
            cls_slots = cls.__dict__.get("__slots__", ())
            if isinstance(cls_slots, str):
                cls_slots = (cls_slots,)
            slot_names.extend(str(slot_name) for slot_name in cls_slots if slot_name not in {"__dict__", "__weakref__"})
        if slot_names:
            for slot_name in slot_names:
                try:
                    slot_value = object.__getattribute__(value, slot_name)
                except AttributeError:
                    continue
                self._walk_stmt_query_prerender_info(
                    slot_value,
                    exact_shape_keys,
                    seen=seen,
                )
        else:
            value_dict = getattr(value, "__dict__", None)
            if isinstance(value_dict, dict):
                for item in value_dict.values():
                    self._walk_stmt_query_prerender_info(item, exact_shape_keys, seen=seen)

    def _populate_cte_template_cache(
        self: Any,
        cte_fingerprint: tuple[object, ...] | None,
        stmt: SqlRenderable,
        sql_str: str,
        all_params: tuple[object, ...],
        cte_cache: dict[tuple[object, ...], tuple[str, int]],
    ) -> None:
        """Store the SQL template for a cacheable CTE grammar shape."""
        fingerprint = cte_fingerprint
        if fingerprint is None:
            return
        if rendered_bind_placeholder_count(sql_str) != len(all_params):
            return
        cte_cache[fingerprint] = (sql_str, len(all_params))

    def compile_query_spec_statement(
        self: Any,
        spec: QuerySpec[Any],
        *,
        mode: QueryPreRenderMode = "select",
    ) -> SqlFragment:
        """Compile a query spec into a reusable pre-rendered terminal statement."""
        statement = self.wrap_prerendered_fragment(self.compile_query_spec_fragment(spec, mode=mode))
        assert isinstance(statement, SqlFragment)
        return statement

    def wrap_prerendered_fragment(
        self: Any,
        fragment: SqlFragment,
    ) -> SqlFragment:
        """Wrap a pre-rendered fragment while preserving QuerySpec attribution."""
        stmt = fragment
        if stmt._query_prerender_info is None:
            sql_str, params = fragment.to_sql(self.get_dialect())
            stmt._query_prerender_info = self._lookup_rendered_query_prerender_info(sql_str, params)
        return stmt

    def analyze_terminal_prerenderability(
        self: Any,
        stmt: SqlRenderable,
        *,
        params: Sequence[object] = (),
        external_params_first: bool = False,
        needs_returning: bool = False,
    ) -> TerminalPreRenderAnalysis:
        """Analyze whether a terminal grammar object can skip rendering on reuse."""
        params = tuple(params)
        from impl.common.l2160_terminal_prerender_cache import analyze_terminal_prerenderability

        return analyze_terminal_prerenderability(
            stmt,
            external_params=params,
            external_params_first=external_params_first,
            needs_returning=needs_returning,
            dialect=self.get_dialect(),
        )

    def _rendered_prerender_signature(
        self: Any,
        sql_str: str,
        params: Sequence[object],
    ) -> RenderedPrerenderSignature:
        """Build a stable signature for rendered SQL attribution lookups."""
        return RenderedPrerenderSignature(sql=sql_str, param_count=len(params))

    def _remember_rendered_query_prerender_info(
        self: Any,
        sql_str: str,
        params: Sequence[object],
        info: QueryPrerenderInfo,
    ) -> None:
        """Remember QuerySpec attribution for a rendered SQL shape."""
        registry = getattr(self, "_query_prerender_origin_by_rendered_signature", None)
        if registry is None:
            registry = {}
            self._query_prerender_origin_by_rendered_signature = registry
        registry[self._rendered_prerender_signature(sql_str, params)] = info

    def _remember_rendered_terminal_prerender_analysis(
        self: Any,
        sql_str: str,
        params: Sequence[object],
        analysis: TerminalPreRenderAnalysis,
    ) -> None:
        """Remember terminal prerender analysis for a rendered SQL shape."""
        registry = getattr(self, "_terminal_prerender_analysis_by_rendered_signature", None)
        if registry is None:
            registry = {}
            self._terminal_prerender_analysis_by_rendered_signature = registry
        registry[self._rendered_prerender_signature(sql_str, params)] = analysis

    def _lookup_rendered_terminal_prerender_analysis(
        self: Any,
        sql_str: str,
        params: Sequence[object],
    ) -> TerminalPreRenderAnalysis | None:
        """Lookup terminal prerender analysis for a rendered SQL shape."""
        registry = getattr(self, "_terminal_prerender_analysis_by_rendered_signature", None)
        if registry is None:
            return None
        analysis = registry.get(self._rendered_prerender_signature(sql_str, params))
        if analysis is None:
            return None
        if isinstance(analysis, TerminalPreRenderAnalysis):
            return analysis
        return None

    def _lookup_rendered_query_prerender_info(
        self: Any,
        sql_str: str,
        params: Sequence[object],
    ) -> QueryPrerenderInfo | None:
        """Lookup prior QuerySpec attribution for a rendered SQL shape."""
        registry = getattr(self, "_query_prerender_origin_by_rendered_signature", None)
        assert registry is None or isinstance(registry, dict)
        if registry is None:
            return None
        return registry.get(self._rendered_prerender_signature(sql_str, params))

    def _attach_query_prerender_info(
        self: Any,
        stmt: SqlRenderable,
        info: QueryPrerenderInfo,
    ) -> SqlRenderable:
        """Attach prerender attribution directly to the renderable object when possible."""
        if isinstance(stmt, SqlFragment):
            stmt._query_prerender_info = info
            return stmt
        if isinstance(stmt, AttributedSqlRenderable):
            return AttributedSqlRenderable(inner=stmt.inner, prerender_info=info)
        return AttributedSqlRenderable(inner=stmt, prerender_info=info)

    def _attach_query_spec_prerender_info(
        self: Any,
        stmt: SqlRenderable,
        *,
        spec: QuerySpec[Any],
        mode: QueryPreRenderMode,
    ) -> SqlRenderable:
        """Attach QuerySpec-origin attribution to a terminal statement."""
        analysis = self.analyze_query_prerenderability(spec, mode=mode)
        return cast(
            "SqlRenderable",
            self._attach_query_prerender_info(
                stmt,
                QueryPrerenderInfo.from_shape(
                    QueryPrerenderShapeMetadata(
                        exact_shape_key=QueryPrerenderShapeKey(analysis.exact_shape_key),
                        family_shape_key=QueryPrerenderShapeKey(analysis.family_shape_key),
                        mode=mode,
                        seam=QueryPrerenderSeam("query_spec"),
                    ),
                    prerender_cache_hit=False,
                    prerender_supported=analysis.is_prerenderable,
                ),
            ),
        )

    def _extract_stmt_query_prerender_info(
        self: Any,
        stmt: SqlRenderable,
    ) -> QueryPrerenderInfo | None:
        """Return attached QuerySpec attribution for one terminal statement."""
        if isinstance(stmt, AttributedSqlRenderable):
            return stmt.prerender_info
        from impl.common.l2100_sql_grammar.domain.infra.request_scalar import SqlRequestStatement

        if isinstance(stmt, SqlRequestStatement):
            info = self._extract_stmt_query_prerender_info(stmt._inner)
            assert info is None or isinstance(info, QueryPrerenderInfo)
            return info
        if isinstance(stmt, SqlFragment):
            return stmt._query_prerender_info
        return None

    def _prepared_cache_prerender_kwargs(
        self: Any,
        info: QueryPrerenderInfo | None,
    ) -> PreparedCachePrerenderKwargs:
        """Build prepared-cache kwargs from explicit prerender metadata."""
        return {} if info is None else info.to_prepared_cache_kwargs()

    def _instrumentation_query_prerender_kwargs(
        self: Any,
