"""Collect logical results from one delimited native SQL request."""
from __future__ import annotations

from typing import Any

from l2070_batching.sql_batch import SqlBatchResult


class CompoundFrameCollector:
    """Retain the final data result for each explicitly delimited logical statement."""

    def __init__(self: CompoundFrameCollector, label: str, frame_count: int) -> None:
        self.label = label
        self.frame_count = frame_count
        self.results: list[SqlBatchResult] = []
        self.rows: list[dict[str, Any]] = []
        self.rowcount = 0

    def consume(self: CompoundFrameCollector, rows: list[dict[str, Any]], rowcount: int) -> None:
        if rows == [{self.label: len(self.results)}] and len(self.results) < self.frame_count:
            self.results.append(SqlBatchResult(rows=self.rows, rowcount=self.rowcount))
            self.rows = []
            self.rowcount = 0
            return
        if len(self.results) >= self.frame_count:
            raise RuntimeError("Unexpected result after the final ordered batch boundary")
        if any(self.label in row for row in rows):
            raise RuntimeError("Invalid ordered batch result boundary")
        if rows:
            self.rows = rows
        if rowcount >= 0:
            self.rowcount = rowcount

    def finish(self: CompoundFrameCollector) -> list[SqlBatchResult]:
        if len(self.results) != self.frame_count:
            raise RuntimeError("Missing ordered batch result boundary")
        return self.results

