    def compile(self, ctx: CompilationContext) -> CompiledStep[dict[str, object]]:
        del ctx
        runtime_ref_ids = tuple(str(entry.source_ref) for entry in self._config.entries)
        return CompiledStep(
            runtime_ref_ids=runtime_ref_ids,
        )

    def execute_runtime(self: _LargeColumnHydrationRuntimeStep, resolved: ResolvedRefs) -> dict[str, object]:
        return materialize_large_column_hydration_runtime(self._config, resolved)


def materialize_large_column_hydration_runtime(
    config: _LargeColumnHydrationRuntimeConfig,
    runtime_refs: ResolvedRefs,
) -> dict[str, object]:
    """Apply resolved manifest refs to one in-memory row payload."""
    hydrated = dict(config.row_data)
    for entry in config.entries:
        manifest = runtime_refs.require(
            entry.source_ref,
            ContentStoreManifest,
            site=f"materialize_large_column_hydration_runtime({entry.pointer})",
        )
        hydrated = _apply_large_column_manifest_by_backend(
            config.backend_type,
            hydrated,
            entry.column_config,
            entry.pointer,
            manifest,
        )
    return hydrated


def _apply_large_column_manifest_by_backend(
    backend_type: BackendType,
    row_data: dict[str, object],
    config: LargeColumnConfig,
    pointer: str,
    manifest: ContentStoreManifest[dict[str, SqlCell], dict[str, SqlCell]],
) -> dict[str, object]:
    store = found_row_or_none(manifest.store)
    if store is None:
        return row_data

    if backend_type not in {BackendType.SQLITE, BackendType.POSTGRES, BackendType.MARIADB}:
        msg = f"Unsupported large-column hydration backend {backend_type!r}."
        raise TypeError(msg)

    store_row = dict(store.row)
    total_chunks = _sql_cell_to_int(store_row.get("total_chunks", 0))
    is_binary = bool(_sql_cell_to_int(store_row.get("is_binary", 0)))
    if total_chunks > 0:
        stored_content = _reassemble_large_column_manifest_chunks(
            pointer,
            total_chunks,
            tuple(manifest.chunks),
        )
    else:
        stored_content = _sql_cell_to_bytes(store_row["payload"])
    compression_algo = _sql_cell_to_str(store_row.get("compression_algorithm", "none"))
    compression_level = _sql_cell_to_int(store_row.get("compression_level", 0))
    original_size = _sql_cell_to_int(store_row.get("original_size", 0))

    column_name = config.column
    content_type = config.content_type
    from impl.common.l2070_server_plan.steps.large_column_read import decode_large_column_payload

    decoded_value = decode_large_column_payload(
        content_hash=pointer,
        config_content_type=str(content_type),
        is_binary=is_binary,
        stored_content=stored_content,
        compression_algorithm=compression_algo,
        compression_level=compression_level,
        original_size=original_size,
    )
    row_data[column_name] = decoded_value
    return row_data


def _reassemble_large_column_manifest_chunks(
    content_hash: str,
    total_chunks: int,
    chunk_rows: tuple[object, ...],
) -> bytes:
    rows = [dict(cast("Mapping[str, SqlCell]", row)) for row in chunk_rows]
    if len(rows) != total_chunks:
        msg = f"Expected {total_chunks} chunks for {content_hash}, got {len(rows)}"
        raise ValueError(msg)
    parts: list[bytes] = []
    for expected_index, row in enumerate(sorted(rows, key=lambda item: _sql_cell_to_int(item["chunk_index"]))):
        chunk_index = _sql_cell_to_int(row["chunk_index"])
        if chunk_index != expected_index:
            msg = f"Missing chunk {expected_index} for {content_hash}"
            raise ValueError(msg)
        payload = _sql_cell_to_bytes(row["payload"])
        actual_hash = hashlib.sha256(payload).hexdigest()
        if actual_hash != _sql_cell_to_str(row["chunk_hash"]):
            msg = f"Chunk hash mismatch for {content_hash} at index {chunk_index}"
            raise ValueError(msg)
        parts.append(payload)
    return b"".join(parts)

