def sql_cell_to_int(value: SqlCell) -> int:
    if isinstance(value, SqlNull):
        msg = "Expected SQL integer cell, got NULL"
        raise TypeError(msg)
    if isinstance(value, memoryview):
        return int(bytes(value))
    if isinstance(value, str | int | float | bool | bytes | Decimal):
        return int(value)
    msg = f"Expected SQL integer cell, got {type(value).__name__}"
    raise TypeError(msg)


def sql_cell_to_str(value: SqlCell) -> RawSqlText:
    if isinstance(value, SqlNull):
        msg = "Expected SQL text cell, got NULL"
        raise TypeError(msg)
    return RawSqlText(str(value))


def sql_cell_to_bytes(value: SqlCell) -> bytes:
    if isinstance(value, SqlNull):
        msg = "Expected SQL binary cell, got NULL"
        raise TypeError(msg)
    if isinstance(value, bytes):
        return value
    if isinstance(value, memoryview):
        return bytes(value)
    if isinstance(value, str):
        if value.startswith("\\x"):
            hex_payload = value[2:]
            if len(hex_payload) % 2 == 0 and all(character in "0123456789abcdefABCDEF" for character in hex_payload):
                return bytes.fromhex(hex_payload)
        return value.encode("utf-8")
    msg = f"Expected SQL binary cell, got {type(value).__name__}"
    raise TypeError(msg)


