            BackendCapability.PARAMETER_FREE_SCHEMA_DDL_SCRIPT,
        }
        & backend_profile.capabilities
    )
    if (
        len(statements) > 1
        and backend_profile.backend_type is not BackendType.POSTGRES
        and supports_parameter_free_bundle
        and _is_parameter_free_ddl_batch(statements, schema_txn._planning_dialect)
    ):
        ddl_plan = schema_txn._bootstrap_ddl_bundle_plan_lazy(
            (SqlDdlConcatBundle(statements),),
            phase=resolved_phase,
        )
        return _schema_static_value_lazy(schema_txn, None, dependency_refs=_schema_dependency_refs_for_planning(ddl_plan))
    ddl_plan = schema_txn._bootstrap_ddl_bundle_plan_lazy(statements, phase=resolved_phase)
    dependency_refs = _schema_dependency_refs_for_planning(ddl_plan)
    return _schema_static_value_lazy(schema_txn, None, dependency_refs=dependency_refs)


@pure_lazy
def _defer_create_index_ddl_batch_lazy(
    schema_txn: LazySchemaTransaction,
    ddl_statements: tuple[SqlRenderable, ...],
) -> bool:
    statements = tuple(ddl_statements)
    if not statements:
        return True
    from impl.common.l2200_sql_dialect.sql_polymorphic_services import (
        _async_schema_transaction_type,
    )

    deferred_state = None
    if deferred_state is None or type(schema_txn) is not _async_schema_transaction_type():
        return False
    # Async schema transactions do not expose a synchronous lazy post-DDL
    # scheduler. There is intentionally no fallback callback bridge here; use
    # the normal DDL planning path for these index statements.
    return False

