"""Statement-shape helpers for cached SQL replay artifacts."""

from __future__ import annotations

from l2055_lazy_result.purity import pure_lazy

from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class _SqlToken:
    text: str
    upper: str
    quoted_identifier: bool = False


@pure_lazy
def _scan_tokens(sql: str) -> tuple[_SqlToken, ...]:
    tokens: list[_SqlToken] = []
    index = 0
    length = len(sql)
    while index < length:
        char = sql[index]
        if char.isspace():
            index += 1
            continue
        if char in {'"', "`", "["}:
            closing = "]" if char == "[" else char
            end = index + 1
            value_chars: list[str] = []
            while end < length:
                if sql[end] == closing:
                    break
                value_chars.append(sql[end])
                end += 1
            value = "".join(value_chars)
            tokens.append(_SqlToken(value, value.upper(), quoted_identifier=True))
            index = min(end + 1, length)
            continue
        if char.isalpha() or char == "_":
            end = index + 1
            while end < length and (sql[end].isalnum() or sql[end] == "_"):
                end += 1
            value = sql[index:end]
            tokens.append(_SqlToken(value, value.upper()))
            index = end
            continue
        tokens.append(_SqlToken(char, char))
        index += 1
    return tuple(tokens)


@pure_lazy
def _is_identifier(token: _SqlToken) -> bool:
    return token.quoted_identifier or bool(token.text) and (token.text[0].isalpha() or token.text[0] == "_")


@pure_lazy
def _matches(tokens: tuple[_SqlToken, ...], index: int, *keywords: str) -> bool:
    if index + len(keywords) > len(tokens):
        return False
    return all(tokens[index + offset].upper == keyword for offset, keyword in enumerate(keywords))


@pure_lazy
def _skip_if_not_exists(tokens: tuple[_SqlToken, ...], index: int) -> int:
    return index + 3 if _matches(tokens, index, "IF", "NOT", "EXISTS") else index


@pure_lazy
def _skip_if_exists(tokens: tuple[_SqlToken, ...], index: int) -> int:
    return index + 2 if _matches(tokens, index, "IF", "EXISTS") else index


@pure_lazy
def _qualified_identifier(tokens: tuple[_SqlToken, ...], index: int) -> tuple[str, int] | None:
    if index >= len(tokens) or not _is_identifier(tokens[index]):
        return None
    first = tokens[index].text
    next_index = index + 1
    if next_index + 1 < len(tokens) and tokens[next_index].text == "." and _is_identifier(tokens[next_index + 1]):
        return tokens[next_index + 1].text, next_index + 2
    return first, next_index


@pure_lazy
def create_table_name(sql: str) -> str | None:
    tokens = _scan_tokens(sql)
    index = 0
    if not _matches(tokens, index, "CREATE"):
        return None
    index += 1
    if index < len(tokens) and tokens[index].upper in {"TEMP", "TEMPORARY"}:
        index += 1
    if not _matches(tokens, index, "TABLE"):
        return None
    index = _skip_if_not_exists(tokens, index + 1)
    parsed = _qualified_identifier(tokens, index)
    return None if parsed is None else parsed[0]


@pure_lazy
def create_table_uses_if_not_exists(sql: str) -> bool:
    tokens = _scan_tokens(sql)
    index = 0
    if not _matches(tokens, index, "CREATE"):
        return False
    index += 1
    if index < len(tokens) and tokens[index].upper in {"TEMP", "TEMPORARY"}:
        index += 1
    if not _matches(tokens, index, "TABLE"):
        return False
    return _matches(tokens, index + 1, "IF", "NOT", "EXISTS")


@pure_lazy
def alter_table_name(sql: str) -> str | None:
    tokens = _scan_tokens(sql)
    if not _matches(tokens, 0, "ALTER", "TABLE"):
        return None
    parsed = _qualified_identifier(tokens, _skip_if_exists(tokens, 2))
    return None if parsed is None else parsed[0]


@pure_lazy
def alter_table_add_column(sql: str) -> tuple[str, str] | None:
    tokens = _scan_tokens(sql)
    if not _matches(tokens, 0, "ALTER", "TABLE"):
        return None
    parsed_table = _qualified_identifier(tokens, _skip_if_exists(tokens, 2))
    if parsed_table is None:
        return None
    table_name, index = parsed_table
    if not _matches(tokens, index, "ADD"):
        return None
    index += 1
    if _matches(tokens, index, "COLUMN"):
        index += 1
    index = _skip_if_not_exists(tokens, index)
    parsed_column = _qualified_identifier(tokens, index)
    if parsed_column is None:
        return None
    return table_name, parsed_column[0]


def alter_table_drop_column(sql: str) -> tuple[str, str] | None:
    """Return the table and column for one ``ALTER TABLE ... DROP COLUMN`` statement."""
    tokens = _scan_tokens(sql)
    if not _matches(tokens, 0, "ALTER", "TABLE"):
        return None
    parsed_table = _qualified_identifier(tokens, _skip_if_exists(tokens, 2))
    if parsed_table is None:
        return None
    table_name, index = parsed_table
    if not _matches(tokens, index, "DROP"):
        return None
    index += 1
    if _matches(tokens, index, "COLUMN"):
        index += 1
    parsed_column = _qualified_identifier(tokens, index)
    if parsed_column is None:
        return None
    return table_name, parsed_column[0]


@pure_lazy
def create_index_target(sql: str) -> tuple[str, str] | None:
    tokens = _scan_tokens(sql)
    index = 0
    if not _matches(tokens, index, "CREATE"):
        return None
    index += 1
    if _matches(tokens, index, "UNIQUE"):
        index += 1
    if not _matches(tokens, index, "INDEX"):
        return None
    index = _skip_if_not_exists(tokens, index + 1)
    parsed_index = _qualified_identifier(tokens, index)
    if parsed_index is None:
        return None
    index_name, index = parsed_index
    if not _matches(tokens, index, "ON"):
        return None
    parsed_table = _qualified_identifier(tokens, index + 1)
    if parsed_table is None:
        return None
    return index_name, parsed_table[0]


@pure_lazy
def trigger_table_name(sql: str) -> str | None:
    tokens = _scan_tokens(sql)
    if not tokens or tokens[0].upper not in {"CREATE", "DROP"}:
        return None
    for index, token in enumerate(tokens):
        if token.upper != "ON":
            continue
        parsed = _qualified_identifier(tokens, index + 1)
        return None if parsed is None else parsed[0]
    return None


@pure_lazy
def table_names_after_keyword(sql: str, keyword: str) -> frozenset[str]:
    tokens = _scan_tokens(sql)
    names: set[str] = set()
    target = keyword.upper()
    for index, token in enumerate(tokens):
        if token.upper != target:
            continue
        parsed = _qualified_identifier(tokens, index + 1)
        if parsed is not None:
            names.add(parsed[0])
    return frozenset(names)


def native_dml_prefix(sql: str) -> bool:
    tokens = _scan_tokens(sql)
    return bool(tokens) and tokens[0].upper in {"INSERT", "UPDATE", "DELETE", "REPLACE"}

