from __future__ import annotations

from l1400_types.type_surface_contracts import DiagnosticLabel

from collections.abc import Awaitable, Callable, Iterable, Sequence
from dataclasses import dataclass, field
from datetime import datetime
from typing import TYPE_CHECKING, Any, Literal, NoReturn, Protocol, cast
from uuid import UUID

from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
from impl.common.l2190_query_prerender_contracts import (
    InstrumentationPrerenderKwargs,
    PreparedCachePrerenderKwargs,
    RenderedPrerenderSignature,
)
from impl.common.l2100_sql_grammar.sql_fragment import SqlFragment
from impl.common.l2100_sql_grammar.tree.enums import SqlTreeKind
from impl.common.l2200_sql_dialect.sql_connection_shapes import (
    SqlLazyTerminalResult,
    reject_lazy_sql_param,
    require_lazy_result_terminal,
)
from impl.common.l2200_sql_dialect.sql_dialect import SqlDialect
from l1400_types import SqlParamTuple, SysId
from impl.common.l2100_sql_params.sql_params import SqlParamTuple as SqlExecutionParamTuple
from l2000_connection.connection_models import DatabaseRow
from impl.common.l2100_sql_grammar.protocols import SqlRenderable, SqlStatementFraming
from l2055_lazy_result.execution_context import ExecutionContext
from l2055_lazy_result.lazy_operation import LazyOperation
from l2055_lazy_result.lazy_result import LazyResult
from l2055_lazy_result.lazy_seq import LazySeq
from l2055_lazy_result.purity import pure_lazy
from l2070_batching.server_ref import ServerRef
from l2070_batching.sql_renderable import SupportsTerminalPrerenderAnalysis

if TYPE_CHECKING:
    from impl.common.l2190_query_prerender_contracts import QueryPrerenderInfo
    from impl.common.l2200_sql_dialect.sql_core_support_mixin import (
        _SqlCoreSupportMixin as _SqlConnectionCore,
    )

type _DirectFetchMode = Literal["none", "one", "all"]
type _DirectResultMode = Literal["raw", "none", "fetchone", "fetchall"]
type _DirectExecutionResult = DatabaseRow | Sequence[DatabaseRow] | None
_QuerySpecSqlCompiler = Callable[[object, object, object], tuple[str, tuple[object, ...]]]
_QUERY_SPEC_SQL_COMPILER_STATE: dict[str, _QuerySpecSqlCompiler | None] = {"compiler": None}
_LAZY_PARAM_REJECTED_TYPES: tuple[type, ...] = (LazyResult, LazySeq)
_PASSTHROUGH_TYPES: frozenset[type] = frozenset({int, float, bool, bytes, type(None)})

# Generated by scripts/codemods/extract_sql_connection_residue.py from impl/common/l2200_sql_dialect/sql_connection.py.
# Run import hygiene and SQL package tests after applying this codemod.


@dataclass(frozen=True, slots=True)
class _DirectGrammarExecutionPlan:
    """Shared lazy direct-execution plan for SQL backends."""

    sql: str
    params: SqlExecutionParamTuple
    prerender_info: QueryPrerenderInfo | None
    fetch_mode: _DirectFetchMode
    track_rtt: bool = field(default=True, kw_only=True)
    connection_local_statements: tuple[PreparedTerminalExecution, ...] = field(default=(), kw_only=True)
    requires_connection_local_schema_authority: bool = field(default=False, kw_only=True)

    @property
    def release_with_pipeline(self: _DirectGrammarExecutionPlan) -> bool:
        return self.fetch_mode == "none"


@dataclass(frozen=True, slots=True)
class _DirectGrammarExecutionRequest:
    """Lazy direct-execution request resolved through public direct entry points."""

    stmt: SqlRenderable
    params: SqlParamTuple | None = None
    external_params_first: bool = False
    fetch_mode: _DirectFetchMode = "none"
    use_savepoint_recovery: bool = True
    result_mode: _DirectResultMode = "raw"


class _SqlDirectLazyContext(ExecutionContext):
    """Resolve direct SQL execution plans on first access."""

    def __init__(self: _SqlDirectLazyContext, conn: _SqlConnectionCore) -> None:
        self._conn = conn

    def queue_single[T](
        self: _SqlDirectLazyContext,
        operation: LazyOperation[T],
        pre_populated: T | None = None,
    ) -> LazyResult[T]:
        return LazyResult(operation, self, pre_populated)

    def queue_sequence[T](self, operation: LazyOperation[list[T]]) -> NoReturn:
        del operation
        msg = "SQL direct execution context only supports LazyResult terminals"
        raise NotImplementedError(msg)

    @staticmethod
    def _require_direct_result(
        result: LazyResult[SqlLazyTerminalResult] | LazySeq[SqlLazyTerminalResult],
    ) -> LazyResult[Any]:
        return require_lazy_result_terminal(
            result,
            context=DiagnosticLabel("SQL direct execution context"),
        )

    @staticmethod
    def _require_direct_request(query_spec: object) -> _DirectGrammarExecutionRequest:
        if type(query_spec) is not _DirectGrammarExecutionRequest:
            msg = f"Expected _DirectGrammarExecutionRequest, got {type(query_spec)!r}"
            raise TypeError(msg)
        return query_spec

    def _execute_request_sync(
        self: _SqlDirectLazyContext,
        request: _DirectGrammarExecutionRequest,
    ) -> _DirectExecutionResult:
        from impl.common.l2070_server_plan.execution_guard import assert_in_plan_context

        assert_in_plan_context("_SqlDirectLazyContext.execute_sync")
        return self._conn._execute_direct_internal(
            request.stmt,
            params=request.params,
            external_params_first=request.external_params_first,
            fetch_mode=request.fetch_mode,
            use_savepoint_recovery=request.use_savepoint_recovery,
        )

    async def _execute_request_async(
        self: _SqlDirectLazyContext,
        request: _DirectGrammarExecutionRequest,
    ) -> _DirectExecutionResult:
        from impl.common.l2070_server_plan.execution_guard import assert_in_plan_context

        assert_in_plan_context("_SqlDirectLazyContext.execute_async")
        return await self._conn._execute_direct_internal_async(
            request.stmt,
            params=request.params,
            external_params_first=request.external_params_first,
            fetch_mode=request.fetch_mode,
            use_savepoint_recovery=request.use_savepoint_recovery,
        )

    def execute_sync(self, result: LazyResult[SqlLazyTerminalResult] | LazySeq[SqlLazyTerminalResult]) -> None:
        direct_result = self._require_direct_result(result)
        operation = direct_result._operation
        request = self._require_direct_request(operation.query_spec)
        raw_result = self._execute_request_sync(request)
        value = self._apply_result_mode(request, raw_result)
        direct_result._set_resolved(value)

    async def execute_async(self, result: LazyResult[SqlLazyTerminalResult] | LazySeq[SqlLazyTerminalResult]) -> None:
        direct_result = self._require_direct_result(result)
        operation = direct_result._operation
        request = self._require_direct_request(operation.query_spec)
        raw_result = await self._execute_request_async(request)
        value = self._apply_result_mode(request, raw_result)
        direct_result._set_resolved(value)

    def _apply_result_mode(
        self: _SqlDirectLazyContext,
        request: _DirectGrammarExecutionRequest,
        value: _DirectExecutionResult,
    ) -> object:
        if request.result_mode == "none":
            return None
        if request.result_mode == "fetchone":
            return type(self._conn)._transform_direct_fetchone_result(value)
        if request.result_mode == "fetchall":
            return type(self._conn)._transform_direct_fetchall_result(value)
        return value


@dataclass(frozen=True, slots=True)
class PreparedTerminalExecution:
    """Prepared terminal SQL plus explicit prerender attribution."""

    sql: str
    params: SqlExecutionParamTuple
    prerender_info: QueryPrerenderInfo | None = None
    transaction_kind: SqlTreeKind | None = None
    connection_local_statements: tuple[PreparedTerminalExecution, ...] = ()
    statement_framing: SqlStatementFraming = SqlStatementFraming.UNKNOWN


@dataclass(frozen=True, slots=True)
class AttributedSqlRenderable:
    """SqlRenderable wrapper that carries explicit prerender attribution."""

    inner: SqlRenderable
    prerender_info: QueryPrerenderInfo

    @property
    def query_plan_explainable(self: AttributedSqlRenderable) -> bool:
        """Preserve explicit explainability through prerender attribution."""
        return getattr(self.inner, "query_plan_explainable", False) is True

    def render(self, dialect: SqlDialect) -> SqlFragment:
        return self.inner.render(dialect)

    def collect_render_params(self, dialect: SqlDialect) -> SqlParamTuple:
        return cast(SqlParamTuple, self.inner.collect_render_params(dialect))

    def structural_fingerprint(self, dialect: SqlDialect) -> tuple[object, ...] | None:
        return self.inner.structural_fingerprint(dialect)

    def gated(self: AttributedSqlRenderable, gate_cte: str) -> AttributedSqlRenderable:
        """Gate the attributed statement without changing its SQL operation."""
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_conditional_gate import gate_grammar_structurally

        return AttributedSqlRenderable(
            inner=gate_grammar_structurally(self.inner, gate_cte),
            prerender_info=self.prerender_info,
        )

    def owned_cte_names(self: AttributedSqlRenderable) -> frozenset[str]:
        """Preserve statement-local CTE ownership through attribution."""
        owned_cte_names = getattr(self.inner, "owned_cte_names", None)
        if not callable(owned_cte_names):
            return frozenset()
        names = owned_cte_names()
        if not isinstance(names, Iterable):
            msg = "owned_cte_names() must return an iterable"
            raise TypeError(msg)
        return frozenset(str(name) for name in names)

    def terminal_prerender_analysis(
        self,
        *,
        dialect: SqlDialect,
        external_params: SqlParamTuple,
        external_params_first: bool,
        needs_returning: bool,
    ) -> object:
        if not isinstance(self.inner, SupportsTerminalPrerenderAnalysis):
            msg = f"{type(self.inner).__name__} does not support terminal prerender analysis"
            raise TypeError(msg)
        return self.inner.terminal_prerender_analysis(
            dialect=dialect,
            external_params=external_params,
            external_params_first=external_params_first,
            needs_returning=needs_returning,
        )

    def split_for_outer_cte(self) -> tuple[tuple[tuple[str, SqlRenderable], ...], SqlRenderable]:
        split_for_outer_cte = None
        for cls in type(self.inner).__mro__:
            method = cls.__dict__.get("split_for_outer_cte")
            if callable(method):
                split_for_outer_cte = method
                break
        if split_for_outer_cte is None:
            return (), self
        outer_ctes, inner = cast(
            "tuple[Iterable[tuple[str, SqlRenderable]], SqlRenderable]",
            split_for_outer_cte(self.inner),
        )
        return tuple(outer_ctes), inner


def _coalesce_delete_returning_id(
    object_id: SysId | None,
    kwargs: dict[str, object],
) -> SysId:
    """Support both ``object_id`` and legacy ``id=...`` callers."""
    if object_id is not None:
        return object_id
    if "id" not in kwargs:
        msg = "Missing required argument: 'id'"
        raise TypeError(msg)
    return cast(SysId, kwargs["id"])


def set_query_spec_sql_compiler(compiler: _QuerySpecSqlCompiler) -> None:
    """Register the higher-layer QuerySpec compiler used by _SqlConnectionCore."""
    _QUERY_SPEC_SQL_COMPILER_STATE["compiler"] = compiler


class _DeleteReturningConnection(Protocol):
    def delete_many_returning(
        self,
        table_name: SqlTableName,
        object_ids: list[SysId],
        returning_columns: tuple[str, ...] | None,
    ) -> list[dict[str, Any]]: ...

    async def delete_many_returning_async(
        self,
        table_name: SqlTableName,
        object_ids: list[SysId],
        returning_columns: tuple[str, ...] | None,
    ) -> list[dict[str, Any]]: ...


def _delete_returning_impl(
    self: _DeleteReturningConnection,
    table_name: SqlTableName,
    object_id: SysId | None = None,
    returning_columns: tuple[str, ...] | None = None,
    **kwargs: object,
) -> dict[str, Any] | None:
    """Delete one record and return the selected columns."""
    resolved_object_id = _coalesce_delete_returning_id(object_id, kwargs)
    result = self.delete_many_returning(table_name, [resolved_object_id], returning_columns)
    return result[0] if result else None


async def _delete_returning_impl_async(
    self: _DeleteReturningConnection,
    table_name: SqlTableName,
    object_id: SysId | None = None,
    returning_columns: tuple[str, ...] | None = None,
    **kwargs: object,
) -> dict[str, Any] | None:
    """Async delete-one wrapper over ``delete_many_returning_async``."""
    resolved_object_id = _coalesce_delete_returning_id(object_id, kwargs)
    result = await self.delete_many_returning_async(
        table_name,
        [resolved_object_id],
        returning_columns,
    )
    return result[0] if result else None


def _resolve_lazy_params(params: tuple[object, ...]) -> tuple[Any, ...]:
    """Guard params against lazy leakage; does NOT normalize bind values.

    Responsibility here is strictly to reject unresolved lazy values
    (``LazyResult``, ``LazySeq``, ``ServerRef``) that leaked past the batching
    layer. Driver-specific bind normalization (branded-type unwrap, array vs
    JSON semantics, etc.) remains the exclusive responsibility of the backend
    ``_driver_execute`` implementation.
    """
    for param in params:
        if type(param) in {str, int, float, bool, bytes, type(None)}:
            continue
        if reject_lazy_sql_param(param, _LAZY_PARAM_REJECTED_TYPES, ServerRef):
            msg = (
                "_resolve_lazy_params() rejects lazy values in direct SQL execution plans; "
                "callers must publish concrete params before reaching the SQL connection layer "
                f"(got {type(param).__name__}: {param!r})"
            )
            raise RuntimeError(msg)
    return params


@pure_lazy
def normalize_sql_params(
    params: Sequence[object],
    *,
    serialize_collections: bool = True,
) -> tuple[Any, ...]:
    """Normalize SQL parameters by unwrapping branded types.

    Branded types (BranchName, NodeId, etc.) wrap underlying values but
    database drivers don't know how to bind them. This function unwraps
    them to their underlying string/primitive values.

    When ``serialize_collections`` is True (the default), dict/list values
    are serialized to JSON strings. This is required for SQLite and MariaDB
    which cannot bind dict/list directly. PostgreSQL requires dict/list
    wrapped in ``psycopg.types.json.Jsonb()`` and should pass
    ``serialize_collections=False``.

    Args:
        params: Tuple of parameter values, possibly containing branded types
        serialize_collections: If True, serialize dict/list to JSON strings.
            Default True (needed for SQLite/MariaDB). Set False for PostgreSQL
            (dicts/lists will be wrapped in psycopg Jsonb instead).

    Returns:
        Tuple with branded types unwrapped to their underlying values
    """
    params = tuple(params)
    if not params:
        return params

    from impl.common.l2100_sql_params.sql_param_normalization import normalize_sql_bind_value

    normalized = []
    for param in params:
        param_type = type(param)
        dialect_unwrapper = getattr(type(param), "unwrap_sql_bind", None)
        if callable(dialect_unwrapper):
            if getattr(type(param), "__nera_h14_code_type__", False):
                normalized.append(param)
            else:
                normalized.append(dialect_unwrapper(param, "portable"))
            continue
        # Fast path: exact primitive types need no conversion.
        # str is handled below because str subclasses (branded types,
        # SqlTableName) need unwrapping.
        if param_type in _PASSTHROUGH_TYPES:
            normalized.append(param)
            continue
        # Fast path for exact str (not a subclass): no unwrapping needed.
        if param_type is str:
            normalized.append(param)
            continue
        if isinstance(param, datetime):
            normalized.append(param.isoformat() if serialize_collections else param)
            continue
        if isinstance(param, UUID):
            normalized.append(str(param))
            continue
        # ServerRef objects have a __getattr__ that returns a new ServerRef for
        # any attribute, which tricks hasattr() and causes failures when the
        # driver tries to bind them.  They should be rendered to SQL by the
        # grammar tree, never passed as raw parameters.
        if isinstance(param, ServerRef):
            raise TypeError(
                f"{param_type.__name__} object found in SQL params — "
                "it should have been rendered to SQL by the grammar tree, "
                "not passed as a raw parameter. Check grammar construction.",
            )
        normalized.append(
            normalize_sql_bind_value(
                param,
                serialize_collections=serialize_collections,
            ),
        )
    return tuple(normalized)


@pure_lazy
def _sql_grammar_parity_mismatch_reason(
    *,
    python_rendered: tuple[str, tuple[object, ...]],
    rust_rendered: tuple[str, tuple[object, ...]],
    normalized_python: tuple[object, ...],
    normalized_rust: tuple[object, ...],
    recipe: object,
) -> str:
    python_sql, _python_params = python_rendered
    rust_sql, _rust_params = rust_rendered
    first_diff = _first_string_diff_index(python_sql, rust_sql)
    if first_diff is None and normalized_python == normalized_rust:
        return f"unclassified parity mismatch; recipe={recipe!r}"
    if first_diff is not None:
        start = max(0, first_diff - 220)
        end = first_diff + 360
        return (
            f"sql first_diff={first_diff}; "
            f"python_context={python_sql[start:end]!r}; "
            f"rust_context={rust_sql[start:end]!r}; "
            f"python_params={python_rendered[1]!r}; rust_params={rust_rendered[1]!r}; "
            f"normalized_python={normalized_python!r}; normalized_rust={normalized_rust!r}; "
            f"recipe={recipe!r}"
        )
    return (
        f"params differ; sql={python_sql!r}; "
        f"python_params={python_rendered[1]!r}; rust_params={rust_rendered[1]!r}; "
        f"normalized_python={normalized_python!r}; normalized_rust={normalized_rust!r}; "
        f"recipe={recipe!r}"
    )


@pure_lazy
def _first_string_diff_index(left: str, right: str) -> int | None:
    for index, (left_char, right_char) in enumerate(zip(left, right)):
        if left_char != right_char:
            return index
    if len(left) != len(right):
        return min(len(left), len(right))
    return None

