MARIADB_CONCURRENT_MODIFICATION_ERROR = 1020
MARIADB_DEADLOCK_ERROR = 1213
MARIADB_CONNECTION_NAME_MAX_LENGTH = 64
MYSQL_UNKNOWN_COLUMN_ERROR = 1054


def _translate_mysql_errno(exc: Exception, errno: int) -> Exception | None:
    """Translate MySQL/MariaDB errno values when available."""
    if errno in {1317, 3024}:
        return db_exc.StatementTimeoutError(
            message=f"Statement cancelled due to timeout: {exc}",
            original_exception=exc,
        )

    if errno in {1205, 3572}:
        error_msg = str(exc).lower()
        if "lock" in error_msg:
            return db_exc.ConcurrentBranchCommitInProgressError(
                message="Commit publish is already in progress for this branch. Please retry.",
                original_exception=exc,
            )

    if errno in {MARIADB_CONCURRENT_MODIFICATION_ERROR, MARIADB_DEADLOCK_ERROR}:
        conflict_type = "deadlock" if errno == MARIADB_DEADLOCK_ERROR else "concurrent modification"
        return db_exc.ConcurrentWriteConflictError(
            f"Transaction failed because of a {conflict_type} (MariaDB error {errno}). Retry the entire operation.",
            original_exception=exc,
        )

    if errno in {1146, 1051}:
        table_name = extract_table_name_mysql(str(exc))
        return db_exc.TableNotFoundError(
            message=str(exc),
            table_name=table_name,
            original_exception=exc,
        )

    if errno == MYSQL_UNKNOWN_COLUMN_ERROR:
        column_name, table_name = extract_column_name_mysql(str(exc))
        return db_exc.ColumnNotFoundError(
            message=str(exc),
            column_name=column_name,
            table_name=table_name,
            original_exception=exc,
        )

    if errno == 30001:
        return db_exc.BranchNotFoundError("Branch not found", original_exception=exc)

    revision_identity_keys = (
        "idx_sys_revision_parents_revision_sys_id_ordinal_uniq",
        "idx_sys_revision_physical_keys_revision_sys_id_uniq",
        "for key 'revision_sys_id'",
    )
    if errno == 1062 and any(key in str(exc) for key in revision_identity_keys):
        return db_exc.ProgrammingError(
            "Revision identity already exists",
            original_exception=exc,
        )

    if errno in {1048, 1364, 1644, 1452, 1451, 1062}:
        return db_exc.IntegrityError(original_exception=exc)

    return None


def _translate_mysql_driver_exception(exc: Exception) -> Exception | None:
    """Translate connector-specific MySQL exceptions."""
    mysql_exception_map: tuple[tuple[type[BaseException], type[db_exc.Error]], ...] = (
        (mysql_driver.IntegrityError, db_exc.IntegrityError),
        (mysql_driver.OperationalError, db_exc.OperationalError),
        (mysql_driver.ProgrammingError, db_exc.ProgrammingError),
        (mysql_driver.DataError, db_exc.DataError),
        (mysql_driver.DatabaseError, db_exc.DatabaseError),
        (mysql_driver.InterfaceError, db_exc.InterfaceError),
        (MySQLError, db_exc.DatabaseError),
        (pymysql.err.IntegrityError, db_exc.IntegrityError),
        (pymysql.err.OperationalError, db_exc.OperationalError),
        (pymysql.err.ProgrammingError, db_exc.ProgrammingError),
        (pymysql.err.DataError, db_exc.DataError),
        (pymysql.err.DatabaseError, db_exc.DatabaseError),
        (pymysql.err.InterfaceError, db_exc.InterfaceError),
        (pymysql.err.MySQLError, db_exc.DatabaseError),
    )
    for driver_exc_type, translated_exc_type in mysql_exception_map:
        if isinstance(exc, driver_exc_type):
            return translated_exc_type(original_exception=exc)
    return None


def _translate_mysql_message_pattern(
    exc: Exception,
    error_msg: str,  # broad-type: accepted
) -> Exception | None:
    """Translate MySQL/MariaDB errors based on message content."""
    if ("1317" in error_msg or "3024" in error_msg) and (
        "timeout" in error_msg or "interrupted" in error_msg or "execution time exceeded" in error_msg
    ):
        return db_exc.StatementTimeoutError(
            message=f"Statement cancelled due to timeout: {exc}",
            original_exception=exc,
        )
    if ("3572" in error_msg or "1205" in error_msg) and "lock" in error_msg:
        return db_exc.ConcurrentBranchCommitInProgressError(
            message="Commit publish is already in progress for this branch. Please retry.",
            original_exception=exc,
        )
    if "1020" in error_msg and "record has changed" in error_msg:
        return db_exc.ConcurrentWriteConflictError(
            "Transaction failed due to concurrent modification (error 1020) - retry entire operation",
            original_exception=exc,
        )
    return None


def _mysql_error_number(exc: Exception) -> int | None:
    """Return an error number from either supported MySQL exception shape."""
    errno = getattr(exc, "errno", None)
    if isinstance(errno, int):
        return errno
    if exc.args and isinstance(exc.args[0], int):
        return exc.args[0]
    return None


def _translate_mysql_exception(exc: Exception) -> Exception:
    """Translate mysql_driver exceptions to our DB-API exceptions.

    This function ensures NO MySQL/MariaDB driver exception types leak through
    to application code. All exceptions are wrapped in the appropriate db_exc type.
    """

    translated: Exception | None = exc if isinstance(exc, db_exc.Error) else None
    error_msg = str(exc).lower()
    if translated is None and isinstance(exc, mysql_driver.DataError | pymysql.err.DataError):
        translated = translate_null_byte_error(exc)
    if translated is None and ("serialization failure" in error_msg or "conflicts with a committed transaction" in error_msg):
        translated = db_exc.ConcurrentWriteConflictError(
            "Transaction failed due to concurrent write conflict - retry entire operation",
            original_exception=exc,
        )

    errno = _mysql_error_number(exc) if translated is None else None
    if errno == 1644 and len(exc.args) == 2 and isinstance(exc.args[1], str):
        assertion_match = re.fullmatch(r"NERA_ASSERTION:([A-Za-z0-9_.:-]+)", exc.args[1])
        if assertion_match is not None:
            from l2070_batching.errors import NativeAssertionFailure

            return NativeAssertionFailure(ServerPlanRefId(assertion_match.group(1)))
    if errno == 4025 and translated is None:
        translated = db_exc.IntegrityError(
            f"Constraint validation rejected one or more values, including possible non-JSON values: {exc}",
            original_exception=exc,
        )
    if errno is not None and translated is None:
        translated_errno = _translate_mysql_errno(exc, errno)
        if translated_errno is not None:
            translated = translated_errno

    if translated is None:
        translated = _translate_mysql_message_pattern(
            exc,
            error_msg,
        )
    if translated is None:
        translated = _translate_mysql_driver_exception(exc)
    if translated is None:
        translated = db_exc.DatabaseError(
            message=f"Unexpected database error: {exc}",
            original_exception=exc,
        )
    return translated


def _normalize_datetime_string(value: SerializedDatetimeText) -> NormalizedParameterText:
    """Convert timezone-aware ISO datetime bind strings to MySQL UTC datetimes."""
    parameter_text = value.value if isinstance(value, Enum) and isinstance(value.value, str) else value
    year = parameter_text[:4]
    if len(year) != 4 or not year.isascii() or not year.isdecimal():
        return NormalizedParameterText(parameter_text)
    try:
        dt = datetime.fromisoformat(parameter_text)
    except (ValueError, AttributeError) as exc:
        logger.debug("Failed to parse ISO datetime from %r: %s", value, exc, exc_info=True)
        return NormalizedParameterText(parameter_text)
    if dt.tzinfo is None:
        return NormalizedParameterText(parameter_text)
    return NormalizedParameterText(dt.astimezone(UTC).replace(tzinfo=None).strftime("%Y-%m-%d %H:%M:%S.%f"))


def _normalize_param(value: object) -> object:
    """Normalize a parameter value for MySQL.

    Uses shared SQL bind normalization and converts datetime values to the
    representation expected by MySQL drivers.
    Datetime values with timezone info are converted to UTC before formatting.
    """
    if value is None:
        return None
    if isinstance(value, SqliteJsonListPayload | PostgresArrayListPayload | MariaDbJsonTableListPayload):
        return bind_native_list_payload_for_driver(value, SqlListTransport.MARIADB_JSON_TABLE)
    if isinstance(value, float) and not math.isfinite(value):
        msg = "MariaDB does not support non-finite floating-point bind values"
        raise db_exc.DataError(msg)

    value_type = type(value)
    if hasattr(value_type, "__supertype__"):
        return _normalize_param(getattr(value, "__wrapped__", value))

    if isinstance(value, SqlBindable):
        normalized_bind = normalize_sql_params((value,))[0]
        if normalized_bind is value:
            return normalized_bind
        return _normalize_param(normalized_bind)

    if isinstance(value, Decimal):
        return value

    if isinstance(value, Enum):
        return _normalize_param(value.value)

    if isinstance(value, dict | list):
        return json.dumps(value, sort_keys=True, separators=(",", ":"))

    if isinstance(value, datetime):
        if value.tzinfo is not None:
            value = value.astimezone(UTC).replace(tzinfo=None)
        return value.strftime("%Y-%m-%d %H:%M:%S.%f")

    if isinstance(value, str):
        return _normalize_datetime_string(SerializedDatetimeText(value))

    normalized = normalize_sql_params((value,))[0]
    if isinstance(normalized, str):
        return _normalize_datetime_string(SerializedDatetimeText(normalized))
    return normalized


def _normalize_params[KeyT: str](
    params: Mapping[KeyT, Any] | tuple[object, ...] | None,
) -> dict[KeyT, Any] | tuple[Any, ...] | None:
    """Normalize all parameters in a dict or tuple."""
    if params is None:
        return None
    if isinstance(params, Mapping):
        return {k: _normalize_param(v) for k, v in params.items()}
    if isinstance(params, (tuple, list)):
        return tuple(_normalize_param(v) for v in params)
    return params


def _convert_mysql_result_value(value: DatabaseValue) -> DatabaseValue:
    """Convert MySQL result values to Pydantic-compatible types.

    MySQL returns naive datetime objects, but Pydantic expects timezone-aware.
    This function adds UTC timezone to naive datetime objects.

    Args:
        value: The value from MySQL result set

    Returns:
        Converted value compatible with Pydantic models
    """
    if value is None:
        return None

    # Convert naive datetime to UTC timezone-aware datetime

    if isinstance(value, datetime) and value.tzinfo is None:
        # Add UTC timezone to naive datetime
        return value.replace(tzinfo=UTC)

    # Return other values as-is (Pydantic handles int->bool conversion)
    return value


def _convert_mysql_result_row[LabelT: str](
    row: Mapping[LabelT, DatabaseValue],
) -> dict[LabelT, DatabaseValue]:
    """Convert all values in a MySQL result row.

    Args:
        row: Dictionary of column names to values from MySQL

    Returns:
        Dictionary with converted values
    """
    return {key: _convert_mysql_result_value(value) for key, value in row.items()}


class DictRowAdapter[DataItemT: DatabaseValue]:
    """Adapts dict[str, Any] to SupportsRowInterface protocol.

    MySQL/MariaDB cursor returns dict-like rows, but DatabaseRow expects
    objects supporting both integer and string indexing. This adapter
    provides integer indexing by position in keys() order.
    """

    def __init__(self: Self, data: Mapping[str, DataItemT]) -> None:
        self._data = data
        self._keys = list(data.keys())

    def __getitem__(self: DictRowAdapter[DataItemT], key: int | str) -> DataItemT:
        """Get value by column name or position index."""
        if isinstance(key, int):
            return self._data[self._keys[key]]
        return self._data[key]

    def __len__(self: DictRowAdapter[DataItemT]) -> int:
        return len(self._data)

    def __iter__(self: DictRowAdapter[DataItemT]) -> Iterator[DataItemT]:
        return iter(self._data.values())

    def __contains__(self: DictRowAdapter[DataItemT], key: object) -> bool:
        """Check if a key exists in the row."""
        return key in self._data

    def keys(self: DictRowAdapter[DataItemT]) -> tuple[DatabaseColumnLabel, ...]:
        return tuple(DatabaseColumnLabel(str(key)) for key in self._keys)


class MariaDBDriverService:
    """MariaDB driver lifecycle service boundary."""

    def __init__(self: MariaDBDriverService, conn: _MariaDBConnectionCore) -> None:
        self._conn = conn

    def ensure_connected_sync(self: MariaDBDriverService) -> None:
        self._conn.ensure_connected_sync()

    async def ensure_connected_async(self: MariaDBDriverService) -> None:
        await self._conn.ensure_connected_async()

    def is_connected(self: MariaDBDriverService) -> bool:
        return bool(self._conn.is_connected())

    async def is_connected_async(self: MariaDBDriverService) -> bool:
        return bool(await self._conn.is_connected_async())


class _MariaDBSchemaConnection(Protocol):
    """Connection surface required by MariaDB schema services."""

    _introspector: MariaDBIntrospector | None
    _validator: MariaDBValidator | None

    _execute_direct_internal_async: _ExecuteDirectFetchAllAsync


class MariaDBSchemaService[ConnT: _MariaDBSchemaConnection]:
    """MariaDB schema/introspection service boundary."""

    def __init__(self, conn: ConnT) -> None:
        self._conn = conn

    def list_tables(self: MariaDBSchemaService) -> Sequence[SqlTableName]:
        """Physical table listing for schema transactions."""
        if self._conn._introspector is None:
            msg = "Not connected to database"
            raise db_exc.InterfaceError(msg)
        return [SqlTableName(_schema_name) for _schema_name in self._conn._introspector.list_tables()]

    def introspect_table(self: Any, table_name: SqlTableName) -> IntrospectedTable:
        if self._conn._introspector is None:
            msg = "Not connected to database"
            raise db_exc.InterfaceError(msg)
        return self._conn._introspector.introspect_table(table_name)

    def introspect_schema(
        self: Any,
        *,
        include_tables: tuple[SqlTableName, ...] | None = None,
    ) -> IntrospectedSchema[SqlTableName]:
        if self._conn._introspector is None:
            msg = "Not connected to database"
            raise db_exc.InterfaceError(msg)
        return self._conn._introspector.introspect_schema(include_tables=include_tables)

    def get_table_indexes(self: MariaDBSchemaService, table_name: SqlTableName) -> Sequence[SqlIndexName]:
        """Return all physical index names, including native FULLTEXT indexes."""
        table = self.introspect_table(table_name)
        return [
            SqlIndexName(_schema_name)
            for _schema_name in list(
                dict.fromkeys(
                    [str(index.name) for index in table.indexes] + [str(index.name) for index in table.fts_indexes],
                ),
            )
        ]

    def get_schema_validator(self: MariaDBSchemaService) -> MariaDBValidator:
        """Return the connection-owned MariaDB validator."""
        if self._conn._validator is None:
            msg = "Not connected to database"
            raise db_exc.InterfaceError(msg)
        return self._conn._validator

    def get_table_info(self: MariaDBSchemaService, table_name: SqlTableName) -> Sequence[TableInfoRow]:
        """Return normalized column information for migration validation."""
        introspector = self._conn._introspector
        if introspector is None:
            msg = "Not connected to database"
            raise db_exc.InterfaceError(msg)
        if not introspector.table_exists(table_name):
            return []
        columns = introspector._introspect_columns(table_name)
        return [
            {
                "name": column.name,
                "type": column.data_type,
                "notnull": not column.nullable,
                "dflt_value": column.default_value,
                "pk": column.is_primary_key,
            }
            for column in columns
        ]

    async def get_table_info_async(
        self: MariaDBSchemaService,
        table_name: SqlTableName,
    ) -> Sequence[TableInfoRow]:
        """Fetch column information through the async driver channel."""
        from impl.common.l2100_sql_grammar.tree.clauses import SqlItemList, SqlSystemTableRef
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlFuncCall
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        stmt = SqlSelect(
            SqlItemList(
                [
                    SqlColumnRef(SqlColumnName("COLUMN_NAME")),
                    SqlColumnRef(SqlColumnName("COLUMN_TYPE")),
                    SqlColumnRef(SqlColumnName("IS_NULLABLE")),
                    SqlColumnRef(SqlColumnName("COLUMN_DEFAULT")),
                    SqlColumnRef(SqlColumnName("COLUMN_KEY")),
                ],
            ),
            SqlSystemTableRef(SqlTableName("information_schema.columns")),
            where=sql_and(
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("TABLE_SCHEMA")),
                    BinaryOp.EQ,
                    SqlFuncCall("DATABASE"),
                ),
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("TABLE_NAME")),
                    BinaryOp.EQ,
                    SqlParam(table_name),
                ),
            ),
        )
        direct_result = await self._conn._execute_direct_internal_async(stmt, fetch_mode="all")
        rows = self._conn._transform_direct_fetchall_result(direct_result)
        return [
            {
                "name": row["COLUMN_NAME"],
                "type": row["COLUMN_TYPE"],
                "notnull": str(row["IS_NULLABLE"]).upper() == "NO",
                "dflt_value": row["COLUMN_DEFAULT"],
                "pk": str(row["COLUMN_KEY"]).upper() == "PRI",
            }
            for row in rows
        ]


class MariaDBSessionContextService:
    """MariaDB session-context service boundary."""

    def __init__(self: MariaDBSessionContextService, conn: _MariaDBConnectionCore) -> None:
        self._conn = conn

    def set_session_id(self: MariaDBSessionContextService, session_id: SessionId) -> None:
        if self._conn._cursor is None:
            msg = "Not connected"
            raise db_exc.InterfaceError(msg)

        session_id_sql = session_id.unwrap_to_sql()
        session_type: Literal["system", "user"] = "system" if session_id.is_schema_session() or session_id.is_system_session() else "user"

        if self._conn._cached_session_id != session_id_sql:
            self._conn._cursor.execute("SET @session_id = %s", (session_id_sql,))
            self._conn._cached_session_id = session_id_sql

        if self._conn._cached_session_type != session_type:
            self._conn._cursor.execute("SET @nera_session_type = %s", (session_type,))
            self._conn._cached_session_type = session_type

    async def _set_session_id_async(self: Any, session_id: SessionId) -> None:
        conn = self._conn
        """Async variant of ``_set_session_id`` with the same cache semantics."""
        await conn.ensure_connected_async()
        if conn._async_conn is None:
            msg = "Async connection not initialized"
            raise db_exc.InterfaceError(msg)

        session_id_sql = session_id.unwrap_to_sql()
        session_type: Literal["system", "user"] = "system" if session_id.is_schema_session() or session_id.is_system_session() else "user"

        cursor = await conn._async_conn.cursor()
        if conn._cached_session_id != session_id_sql:
            await cursor.execute("SET @session_id = %s", (session_id_sql,))
            conn._cached_session_id = session_id_sql

        if conn._cached_session_type != session_type:
            await cursor.execute("SET @nera_session_type = %s", (session_type,))
            conn._cached_session_type = session_type

    def _clear_cached_connection_context(self: Any) -> None:
        conn = self._conn
        """Clear connection-local session and RLS context caches."""
        conn._cached_session_id = None
        conn._cached_session_type = None
        conn._cached_rls_user_id = None

    def _set_rls_user_context(self: Any, user_id: str | None) -> None:
        conn = self._conn
        """Compatibility helper for filtered-view user context tests."""
        if conn._cursor is None:
            msg = "Not connected"
            raise db_exc.InterfaceError(msg)
        if user_id is None:
            conn._cursor.execute("SET @nera_user_id = NULL")
            conn._cached_rls_user_id = None
            return
        if conn._cached_rls_user_id != user_id:
            conn._cursor.execute("SET @nera_user_id = %s", (user_id,))
            conn._cached_rls_user_id = user_id


class MariaDBMaintenanceService:
    """MariaDB maintenance service boundary."""

    def __init__(self: MariaDBMaintenanceService, conn: _MariaDBConnectionCore) -> None:
        self._conn = conn

    def create_worker_connection(self: MariaDBMaintenanceService) -> SyncDatabaseConnection:
        return SyncMariaDBConnection(
            port=self._conn._port,
            host=self._conn._host,
            database=self._conn._database,
            user=self._conn._user,
            password=self._conn._password,
            unix_socket=self._conn._unix_socket,
            read_only=self._conn._read_only,
        )

    def health(self: Any) -> HealthCheckResult:
        conn = self._conn
        """Perform a health check on the MariaDB connection.

        Returns:
            HealthCheckResult with status and details about the connection.
        """
        conn._check_thread_safety()

        # Check basic connectivity
        if not conn.is_connected():
            return HealthCheckResult(
                status=HealthStatus.UNHEALTHY,
                backend=HealthBackendName("mariadb"),
                connected=False,
                message="Not connected to database",
            )

        # Ask the driver to verify that the server connection is alive.
        try:
            if conn._conn is None:
                return HealthCheckResult(
                    status=HealthStatus.UNHEALTHY,
                    backend=HealthBackendName("mariadb"),
                    connected=False,
                    message="Database connection not available",
                )
            conn._conn.ping(reconnect=False)
        except Exception as e:
            return HealthCheckResult(
                status=HealthStatus.UNHEALTHY,
                backend=HealthBackendName("mariadb"),
                connected=False,
                message=f"Database query failed: {e}",
            )

        # Get some basic info about the database (no sensitive details)
        details: dict[DiagnosticLabel, Any] = {}

        # Check replication status if available
        try:
            if conn._cursor is not None:
                # Check if this is a replica
                sql, params = render_to_sql(SqlMariaDbReplicaStatus(), MYSQL_DIALECT)
                conn._cursor.execute(sql, params)
                result = conn._cursor.fetchone()
                if result:
                    details[DiagnosticLabel("role")] = "replica"
                    details[DiagnosticLabel("is_replica")] = True
                else:
                    details[DiagnosticLabel("role")] = "primary"
                    details[DiagnosticLabel("is_replica")] = False
        except MySQLError as e:
            # Not all users have permission to check replication status.
            # This is an expected condition -- omit the detail rather than
            # failing the health check, which must always return a result.
            logger.debug("SHOW SLAVE STATUS failed (insufficient privileges): %s", e, exc_info=True)

        return HealthCheckResult(
            status=HealthStatus.HEALTHY,
            backend=HealthBackendName("mariadb"),
            connected=True,
            message="MariaDB connection is healthy",
            details=details,
        )

    def _invalidate_cached_context_for_sql(self: Any, sql_str: RawSqlText) -> None:
        conn = self._conn
        """Invalidate cached connection context for raw variable assignments."""
        stripped = sql_str.lstrip().lower()
        is_set_assignment = stripped.startswith("set ")
        if is_set_assignment and "@session_id" in stripped:
            conn._cached_session_id = None
        if is_set_assignment and "@nera_session_type" in stripped:
            conn._cached_session_type = None
        if "@nera_user_id" in stripped and (is_set_assignment or " into @nera_user_id" in stripped):
            conn._cached_rls_user_id = None


