class _MariaDBConnectionCore[
    ConnT: mysql_driver.MySQLConnection | None = mysql_driver.MySQLConnection | None,
    AsyncConnT: aiomysql.Connection | None = aiomysql.Connection | None,
    AsyncLoopT: asyncio.AbstractEventLoop | None = asyncio.AbstractEventLoop | None,
    CursorT: MySQLCursorDict | None = MySQLCursorDict | None,
    AsyncCursorT: aiomysql.DictCursor | None = aiomysql.DictCursor | None,
    QueryInstrumentationT: QueryInstrumentation | None = QueryInstrumentation | None,
](
    _MariaDBMetadataSchemaMixin,
    _MariaDBExecutionSupportMixin,
    _MariaDBVersioningMixin,
    _MariaDBCoreSupportMixin,
    _MariaDBLifecycleExecutionMixin,
    _SqlConnectionCore,
):
    """MariaDB/MySQL database connection.

    CRITICAL PORT REQUIREMENT:
        NO DEFAULT PORTS ANYWHERE - port parameter is REQUIRED with no default value.
        This prevents accidental connections to wrong servers (e.g., DoltDB on port 3307).
        Port must be explicitly configured in all connection instantiations.

    Supports both sync and async operations. Sync uses PyMySQL,
    async uses aiomysql for true async I/O.
    """

    _conn: ConnT
    _async_conn: AsyncConnT  # aiomysql.Connection - no type stubs available
    _async_loop: AsyncLoopT
    _cursor: CursorT
    _async_cursor: AsyncCursorT  # aiomysql.Cursor - no type stubs, stored from last execute_async
    _last_insert_id: int | None
    _query_instrumentation: QueryInstrumentationT

    # CTE template cache disabled: fast param extraction is slower than rendering.

    def __init__(self: _MariaDBConnectionCore, *args: Any, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self._backend_driver_service = MariaDBDriverService(self)
        self._backend_schema_service = MariaDBSchemaService(self)
        self._backend_session_context_service = MariaDBSessionContextService(self)
        self._backend_maintenance_service = MariaDBMaintenanceService(self)
        self._query_instrumentation = QueryInstrumentation()

    # =========================================================================
    # Async Connection Methods (aiomysql)
    # =========================================================================

    # =========================================================================
    # Async Core Execution Methods (Phase 1: Native Async I/O)
    # =========================================================================
    #
    # These methods use aiomysql for true async I/O.
    # They form the foundation for async-first transaction methods.

    # raw_execute_async is inherited from _SqlConnectionCore base class and routes through ServerPlan.

    # =========================================================================
    # AsyncExecutor Protocol Implementation (Async-First Core)
    # =========================================================================
    #
    # These methods implement the AsyncExecutor protocol from
    # l2000_connection/async_executor.py. Sync methods use sync adapters directly.

    # Legacy methods that take cursor as parameter (for backward compat)

    # =========================================================================
    # End Async Core Execution Methods
    # =========================================================================

    # raw_execute is inherited from _SqlConnectionCore base class and routes through ServerPlan.

    # _get_type_metadata, _clear_type_metadata, _insert_type_metadata, and
    # _insert_orphaned_row_for_testing are inherited from _SqlConnectionCore

    # Note: create_table_from_schema() is inherited from _SqlConnectionCore base class.
    # MariaDB-specific behavior is handled via hooks:
    # - _post_table_creation(): Post-creation actions (e.g., queue triggers)

    # Note: create_versioned_table() is inherited from _SqlConnectionCore base class.
    # MariaDB-specific behavior is handled via hooks:
    # - _get_logged_table_class(): Returns MariaDBLoggedTable
    # - _ensure_large_column_content_table(): Creates content store table

    # -------------------------------------------------------------------------
    # Large Column Support
    # -------------------------------------------------------------------------

    # Default chunk size: 4MB (safe for all backends)
    _CHUNK_SIZE_BYTES = 4 * 1024 * 1024


class SyncMariaDBConnection(_MariaDBConnectionCore, SyncSqlConnection):
    """Sync-only MariaDB connection facade."""


class AsyncMariaDBConnection(_MariaDBConnectionCore, AsyncSqlConnection):
    """Async-only MariaDB connection facade."""

    async def read_versioning_branch_tip_direct_async(
        self,
        *,
        domain: type[VersioningDomain],
        branch_name: BranchName,
        workspace_id: WorkspaceId,
    ) -> tuple[BranchId, RevisionId] | None:
        """Read the current branch tip on MariaDB's authoritative channel."""
        if self._async_conn is None:
            raise RuntimeError("MariaDB connection is not open")
        table_name = get_table_name(domain.branch_model).replace("`", "``")
        sql = (
            f"SELECT `sys_id`, `tip_revision_sys_id` FROM `{table_name}` "
            "WHERE `workspace_id` = %s AND `name` = %s AND `sys_deleted` = 0 LIMIT 1"
        )
        async with self._async_conn.cursor() as cursor:
            await cursor.execute(sql, (str(workspace_id), branch_name))
            row = await cursor.fetchone()
        if row is None or row[1] is None:
            return None
        return BranchId(str(row[0])), RevisionId(str(row[1]))

