@pure_lazy
def polyfill_index_exists_from_cache(
    conn: _DatabaseConnectionCore,
    model_type: type[DatabaseObjectRow[SysId]],
) -> bool:
    """Return sealed polyfill index existence without terminating a lazy plan."""
    table_name = SqlTableName(get_index_table_name(get_table_name(model_type)))
    cached = conn._table_exists_from_cache(table_name)
    if cached is None:
        msg = f"FTS index presence is absent from the sealed schema cache: {table_name}"
        raise LazyPurityError(msg)
    return bool(cached)


@pure_lazy
def _defer_polyfill_index_exists_execution(
    conn: _DatabaseConnectionCore,
    *,
    table_name: SqlTableName,
) -> LazyResult[bool]:
    # Index presence is startup/bootstrap-owned schema evidence. Runtime data
    # paths may consume the sealed cache but may not open schema transactions.
    cached = conn._table_exists_from_cache(table_name)
    if cached is None:
        msg = f"FTS index presence is absent from the sealed schema cache: {table_name}"
        raise LazyPurityError(msg)
