class FTSPolyfillManager:
    """Manages FTS polyfill inverted indexes.

    This class handles creation and maintenance of inverted index tables for
    full-text search. Unlike native FTS implementations (SQLite FTS5, PostgreSQL
    tsvector), the polyfill stores tokenized data in regular tables and implements
    search logic at the application level.

    Architecture:
        - Per-model inverted index tables: {table}_fts_index
        - Token → document mappings with position tracking
        - Synchronous updates (maintains index consistency)
        - Porter stemming with stop-word filtering

    Example:
        >>> from impl.common.l5150_fts_polyfill import FTSPolyfillManager
        >>> manager = FTSPolyfillManager()
        >>> with conn.schema_transaction(SessionId.schema()) as schema_txn:
        ...     manager.create_fts_index(schema_txn, Product)
        >>> conn.session(SessionId.system()).write(
        ...     fn=lambda txn: manager.rebuild_fts_index(Product, txn=txn),
        ... )
        >>>
        >>> # After updating a product
        >>> manager.update_object_index(Product, product, operation="update")

    See Also:
        - :class:`~l5100_fts.polyfill.searcher.FTSPolyfillSearcher`: Search operations
        - :class:`~l5100_fts.polyfill.index_schema.FTSInvertedIndex`: Index schema
        - :class:`~l5100_fts.polyfill.tokenizers.porter.PorterStemTokenizer`: Tokenizer
    """

    def __init__(self: FTSPolyfillManager) -> None:
        """Initialize the stateless FTS polyfill manager."""

    @legacy_sync
    def create_fts_index(
        self: FTSPolyfillManager,
        schema_owner: _SchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> bool:
        """Create inverted index table for a model.

        Creates a new table with the schema defined in FTSInvertedIndex. The table
        name follows the convention: {table_name}_fts_index

        Table Structure:
            - token: str (lowercased, stemmed)
            - content_hash: str (hash of FTS-indexed fields for deduplication)
            - field_name: str (which field)
            - position: int (token position)
            - frequency: int (term frequency)

        Args:
            model_type: Model class with @fts_indexed decorator
            session_id: Session ID for schema transaction (default: 1)

        Returns:
            True when polyfill artifacts were created; False when they already existed.

        Raises:
            ValueError: If model doesn't have FTS configuration

        Example:
            >>> @fts_indexed(fields=["name", "description"])
            >>> class Product(ApplicationObjectRow):
            ...     name: str
            ...     description: str
            >>> manager.create_fts_index(Product)
        """
        _legacy_delegate_stub()

    @legacy_async
    async def create_fts_index_async(
        self: FTSPolyfillManager,
        schema_owner: _AsyncSchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> bool:
        """Async legacy wrapper for polyfill FTS creation."""
        _legacy_delegate_stub_async()

    @pure_lazy
    def create_fts_index_lazy(
        self: FTSPolyfillManager,
        schema_owner: _PolyfillArtifactPlanOwner,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> LazyResult[bool]:
        """Record polyfill FTS schema artifacts without sync/async execution thunks."""
        config = get_fts_config(model_type)
        if config is None:
            msg = f"{model_type.__name__} not configured for FTS (missing @fts_indexed)"
            raise ValueError(msg)

        return schema_owner.create_polyfill_fts_artifacts_lazy(model_type)

    def _create_fts_index_for_schema_impl(
        self: FTSPolyfillManager,
        schema_owner: _SchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
        *,
        preserve_existing_artifacts: bool = False,
    ) -> LazyResult[bool]:
        config = get_fts_config(model_type)
        if config is None:
            msg = f"{model_type.__name__} not configured for FTS (missing @fts_indexed)"
            raise ValueError(msg)

        table_name = get_table_name(model_type)

        fts_index_class = create_fts_index_class(table_name)
        fts_metadata_class = create_fts_metadata_class(table_name)
        fts_idf_cache_class = create_fts_idf_cache_class(table_name)
        fts_stats_class = create_fts_stats_class(table_name)
        return self._create_fts_index_under_schema_authority_lazy(
            schema_owner,
            table_name=SqlTableName(table_name),
            fts_index_class=fts_index_class,
            fts_metadata_class=fts_metadata_class,
            fts_idf_cache_class=fts_idf_cache_class,
            fts_stats_class=fts_stats_class,
            preserve_existing_artifacts=preserve_existing_artifacts,
        )

    @pure_lazy
    def _create_fts_index_for_schema_lazy(
        self: FTSPolyfillManager,
        schema_owner: _AsyncSchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> LazyResult[bool]:
        config = get_fts_config(model_type)
        if config is None:
            msg = f"{model_type.__name__} not configured for FTS (missing @fts_indexed)"
            raise ValueError(msg)

        table_name = get_table_name(model_type)

        fts_index_class = create_fts_index_class(table_name)
        fts_metadata_class = create_fts_metadata_class(table_name)
        fts_idf_cache_class = create_fts_idf_cache_class(table_name)
        fts_stats_class = create_fts_stats_class(table_name)
        return self._create_fts_index_under_schema_authority_lazy(
            schema_owner,
            table_name=SqlTableName(table_name),
            fts_index_class=fts_index_class,
            fts_metadata_class=fts_metadata_class,
            fts_idf_cache_class=fts_idf_cache_class,
            fts_stats_class=fts_stats_class,
        )

    @external_io_boundary
    def _create_fts_index_under_schema_authority_impl(
        self: FTSPolyfillManager,
        schema_owner: _SchemaDdlTransaction,
        *,
        table_name: SqlTableName,
        fts_index_class: type[FTSInvertedIndex],
        fts_metadata_class: type[FTSMetadata],
        fts_idf_cache_class: type[Any],
        fts_stats_class: type[Any],
    ) -> bool:
        """Create polyfill FTS tables and indexes under one explicit schema owner."""
        artifact_table_names = _polyfill_artifact_table_names(table_name)
        (
            index_table_name,
            metadata_table_name,
            idf_cache_table_name,
            stats_table_name,
        ) = artifact_table_names

        if _schema_artifact_tables_exist_for_planning(schema_owner, artifact_table_names):
            return False

        schema_owner.drop_table(SqlTableName(index_table_name), True)
        schema_owner.drop_table(SqlTableName(metadata_table_name), True)
        schema_owner.drop_table(SqlTableName(idf_cache_table_name), True)
        schema_owner.drop_table(SqlTableName(stats_table_name), True)
        schema_owner.create_table_from_schema(fts_index_class)
        schema_owner.create_table_from_schema(fts_metadata_class)
        schema_owner.create_table_from_schema(fts_idf_cache_class)
        schema_owner.create_table_from_schema(fts_stats_class)
        self._create_fts_indexes_lazy(schema_owner, fts_index_class)
        return True

    @pure_lazy
    def _create_fts_index_under_schema_authority_lazy(
        self: FTSPolyfillManager,
        schema_owner: Any,
        *,
        table_name: SqlTableName,
        fts_index_class: type[FTSInvertedIndex],
        fts_metadata_class: type[FTSMetadata],
        fts_idf_cache_class: type[Any],
        fts_stats_class: type[Any],
        preserve_existing_artifacts: bool = False,
    ) -> LazyResult[bool]:
        """Async polyfill FTS table/index creation under one explicit schema owner."""
        artifact_table_names = _polyfill_artifact_table_names(table_name)
        (
            index_table_name,
            metadata_table_name,
            idf_cache_table_name,
            stats_table_name,
        ) = artifact_table_names

        artifacts_existed = _schema_artifact_tables_exist_for_planning(
            schema_owner,
            artifact_table_names,
        )
        if artifacts_existed:
            return LazyResult.of(False)

        drop_effects = (
            ()
            if preserve_existing_artifacts
            else (
                schema_owner.drop_table_lazy(index_table_name, if_exists=True),
                schema_owner.drop_table_lazy(metadata_table_name, if_exists=True),
                schema_owner.drop_table_lazy(idf_cache_table_name, if_exists=True),
                schema_owner.drop_table_lazy(stats_table_name, if_exists=True),
            )
        )
        artifact_models = (
            fts_index_class,
            fts_metadata_class,
            fts_idf_cache_class,
            fts_stats_class,
        )
        create_effects = (
            tuple(schema_owner.create_table_from_schema_lazy(model_cls, if_not_exists=True) for model_cls in artifact_models)
            if preserve_existing_artifacts
            else (
                schema_owner._bootstrap_table_schema_plan_lazy(
                    artifact_models,
                    produced_ref=ServerPlanRefId(schema_owner.schema_plan_builder()._next_ref()),
                ),
            )
        )
        effects = (
            *drop_effects,
            *create_effects,
            self._create_fts_indexes_lazy(schema_owner, fts_index_class),
        )
        from l2000_connection.schema_transaction import (
            _schema_dependency_refs_for_planning,
            _schema_static_value_lazy,
        )

        dependency_refs = tuple(ref_id for effect in effects for ref_id in _schema_dependency_refs_for_planning(effect))
        return _schema_static_value_lazy(
            schema_owner,
            not artifacts_existed,
            dependency_refs=tuple(dict.fromkeys(dependency_refs)),
        )

    @pure_lazy
    def _create_fts_indexes_lazy(
        self: FTSPolyfillManager,
        schema_txn: _SchemaDdlTransaction,
        fts_index_class: type[FTSInvertedIndex],
    ) -> LazyResult[Any]:
        """Enqueue FTS polyfill index grammar through the schema owner."""
        del self
        from l1000_schema.schema_def import safe_index_name

        table_name = get_table_name(fts_index_class)
        indexes = (
            SqlCreateIndex(
                name=SqlIndexIdent(SqlIndexName(safe_index_name(f"idx_{table_name}_token"))),
                table=SqlTableIdent(SqlTableName(table_name)),
                columns=[SqlColumnIdent(SqlColumnName("token"))],
                if_not_exists=True,
            ),
            SqlCreateIndex(
                name=SqlIndexIdent(SqlIndexName(safe_index_name(f"idx_{table_name}_content_hash"))),
                table=SqlTableIdent(SqlTableName(table_name)),
                columns=[SqlColumnIdent(SqlColumnName("content_hash"))],
                if_not_exists=True,
            ),
        )

        from l2000_connection.schema_transaction import (
            _schema_dependency_refs_for_planning,
            _schema_static_value_lazy,
        )

        dependencies = tuple(
            ref_id
            for index, statement in enumerate(indexes)
            for ref_id in _schema_dependency_refs_for_planning(
                schema_txn._bootstrap_ddl_bundle_plan_lazy(
                    (statement,),
                    name=SchemaDdlOperationName(f"fts_polyfill_index:{table_name}:{index}"),
                    phase=SchemaDdlPhase("fts"),
                ),
            )
        )
        return _schema_static_value_lazy(
            schema_txn,
            None,
            dependency_refs=tuple(dict.fromkeys(dependencies)),
        )

    @legacy_sync
    def drop_fts_index(
        self: FTSPolyfillManager,
        schema_owner: _SchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> None:
        """Drop inverted index table for a model.

        Removes the entire inverted index table, metadata table, and IDF cache table.
        This is a destructive operation that cannot be undone.
        Use rebuild_fts_index() to recreate the index.

        Args:
            model_type: Model class
            session_id: Session ID for schema transaction (default: 1)

        Example:
            >>> manager.drop_fts_index(Product)
        """
        _legacy_delegate_stub()

    @legacy_async
    async def drop_fts_index_async(
        self: FTSPolyfillManager,
        schema_owner: _AsyncSchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> None:
        """Async counterpart to :meth:`drop_fts_index`."""
        _legacy_delegate_stub_async()

    @pure_lazy
    def drop_fts_index_lazy(
        self: FTSPolyfillManager,
        schema_owner: _SchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> LazyResult[None]:
        """Record polyfill FTS table drops without sync/async execution thunks."""
        table_name = get_table_name(model_type)
        schema_owner.drop_table_lazy(SqlTableName(get_index_table_name(table_name)), if_exists=True)
        schema_owner.drop_table_lazy(SqlTableName(get_metadata_table_name(table_name)), if_exists=True)
        schema_owner.drop_table_lazy(SqlTableName(get_idf_cache_table_name(table_name)), if_exists=True)
        schema_owner.drop_table_lazy(SqlTableName(get_stats_table_name(table_name)), if_exists=True)
        return LazyResult.of(None)

    @external_io_boundary
    def _drop_fts_index_for_schema_impl(
        self: FTSPolyfillManager,
        schema_owner: _SchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> None:
        table_name = get_table_name(model_type)
        index_table_name = get_index_table_name(table_name)
        metadata_table_name = get_metadata_table_name(table_name)
        idf_cache_table_name = get_idf_cache_table_name(table_name)
        stats_table_name = get_stats_table_name(table_name)

        schema_owner.drop_table(SqlTableName(index_table_name), if_exists=True)
        schema_owner.drop_table(SqlTableName(metadata_table_name), if_exists=True)
        schema_owner.drop_table(SqlTableName(idf_cache_table_name), if_exists=True)
        schema_owner.drop_table(SqlTableName(stats_table_name), if_exists=True)

    @pure_lazy
    def _drop_fts_index_for_schema_lazy(
        self: FTSPolyfillManager,
        schema_owner: _AsyncSchemaDdlTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
    ) -> LazyResult[None]:
        table_name = get_table_name(model_type)
        index_table_name = get_index_table_name(table_name)
        metadata_table_name = get_metadata_table_name(table_name)
        idf_cache_table_name = get_idf_cache_table_name(table_name)
        stats_table_name = get_stats_table_name(table_name)

        schema_owner.drop_table_lazy(SqlTableName(index_table_name), if_exists=True)
        schema_owner.drop_table_lazy(SqlTableName(metadata_table_name), if_exists=True)
        schema_owner.drop_table_lazy(SqlTableName(idf_cache_table_name), if_exists=True)
        schema_owner.drop_table_lazy(SqlTableName(stats_table_name), if_exists=True)
        return LazyResult.of(None)

    def _prepare_nonversioned_rebuild_data(
        self: FTSPolyfillManager,
        objects: Sequence[DatabaseObjectRow[SysId]],
        config: FTSIndexConfig,
        fts_metadata_class: type,
    ) -> tuple[list[FTSInvertedIndex], list[Any], list[Any]]:
        """Build index entries and metadata from objects. Pure CPU logic, no I/O.

        Returns:
            Tuple of (all_entries, per_doc_metadata_entries, global_metadata_entries)
        """
        doc_lengths: dict[ContentHashValue, int] = {}
        total_doc_length = 0
        all_entries: list[FTSInvertedIndex] = []

        for obj in objects:
            entries = self._build_index_entries(obj, config)
            if entries:
                content_hash = entries[0].content_hash
                if content_hash not in doc_lengths:
                    all_entries.extend(entries)
                    doc_length = len(entries)
                    doc_lengths[content_hash] = doc_length
                    total_doc_length += doc_length

        metadata_entries: list[Any] = []
        for content_hash, doc_length in doc_lengths.items():
            meta_entry = fts_metadata_class(
                content_hash=content_hash,
                doc_length=doc_length,
            )
            metadata_entries.append(meta_entry)

        num_docs = len(doc_lengths)
        avg_doc_length = total_doc_length / num_docs if num_docs > 0 else 0.0
        global_metadata_entries = [
            fts_metadata_class(
                content_hash=GLOBAL_STATS_SENTINEL,
                doc_length=int(avg_doc_length * 1000),  # Store as int * 1000 for precision
            ),
            fts_metadata_class(
                content_hash=GLOBAL_TOTAL_DOC_LENGTH_SENTINEL,
                doc_length=total_doc_length,
            ),
            fts_metadata_class(
                content_hash=GLOBAL_DOC_COUNT_SENTINEL,
                doc_length=num_docs,
            ),
        ]

        return all_entries, metadata_entries, global_metadata_entries

    @pure_lazy
    def _materialized_versioned_rows_lazy(
        self: FTSPolyfillManager,
        txn: ReadTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
        domain: type[VersioningDomain],
    ) -> LazyResult[Sequence[DatabaseObjectRow[SysId]]]:
        from impl.common.l2060_query_spec.query_spec import QueryPermissionState, QuerySpec
        from impl.common.l2070_server_plan.steps.collect_results import FlattenResultsStep
        from impl.common.l2070_server_plan.steps.query_execute import (
            QueryExecuteStep,
            _QueryExecuteStepConfig,
        )
        from l1400_types import ServerPlanRefId
        from l2060_query_builder.query_contracts import QueryFilter

        versioned_model_type = cast(type[VersionedObjectRow[SysId]], model_type)
        registry_module = load_connection_module(ConnectionModuleName("impl.common.l7245_versioned_backends.registry"))
        materialization_module = load_connection_module(
            ConnectionModuleName("impl.common.l7500_versioned_materialization.versioned_materialization"),
        )
        versioned_backend_registry = registry_module.versioned_backend_registry
        get_materialized_revisions_lazy = materialization_module.get_materialized_revisions_lazy
        backend = versioned_backend_registry.get("sparse", txn)
        tip_model = cast(type[DatabaseObjectRow[SysId]], backend._get_or_create_tip_model(versioned_model_type))
        sparse_model = cast(type[DatabaseObjectRow[SysId]], backend._get_or_create_sparse_model(versioned_model_type))
        revisions_lazy = get_materialized_revisions_lazy(txn, domain, versioned_model_type)
        revisions_ref = getattr(revisions_lazy, "_step_ref_id", None)
        if not isinstance(revisions_ref, str):
            msg = "_materialized_versioned_rows_lazy requires symbolic materialized revision refs"
            raise RuntimeError(msg)

        from l2070_batching.server_ref import ServerRefs

        revision_ids: object = ServerRefs.from_ref_id(
            ServerPlanRefId(revisions_ref),
            variant="scalar_sequence",
        )

        tip_columns = returnable_db_columns(tip_model, include_polymorphic=False)
        sparse_columns = frozenset(returnable_db_columns(sparse_model, include_polymorphic=False))
        config = get_fts_config(model_type)
        if config is None:
            msg = f"{model_type.__name__} not configured for FTS"
            raise ValueError(msg)
        dynamic_fields = frozenset(config.fields) if "properties" in tip_columns else frozenset()
        common_columns = tuple(column for column in tip_columns if column in sparse_columns and column not in dynamic_fields)

        def _query_spec(
            query_model: type[DatabaseObjectRow[SysId]],
        ) -> QuerySpec[DatabaseObjectRow[SysId]]:
            if "revision_id" in query_model.model_fields:
                revision_column = get_db_column_name(query_model, DynamicFieldName("revision_id"))
            elif "valid_from_revision_id" in query_model.model_fields:
                revision_column = get_db_column_name(query_model, DynamicFieldName("valid_from_revision_id"))
            else:
                msg = f"_materialized_versioned_rows_lazy requires a tip or sparse model with revision fields, got {query_model.__name__}"
                raise TypeError(msg)
            filters: list[QueryFilter] = [
                QueryFilter(
                    column=revision_column,
                    operator="IN",
                    value=revision_ids,
                ),
            ]
            # Tip models by construction contain only non-deleted rows; the
            # `deleted` column only exists on sparse/staged models.
            if "deleted" in query_model.model_fields:
                filters.append(
                    QueryFilter(
                        column=get_db_column_name(query_model, DynamicFieldName("deleted")),
                        operator="=",
                        value=False,
                    ),
                )
            return QuerySpec(
                model_cls=query_model,
                select_columns=list(common_columns),
                distinct=False,
                joins=[],
                filters=filters,
                order_by=[],
                limit=None,
                offset=None,
                group_by=[],
                aggregations=[],
                having=[],
                window_functions=[],
                permission_state=QueryPermissionState.BYPASS,
                permission_grammar=None,
            )

        plan = txn._get_transaction_plan_lazy()
        tip_ref = ServerPlanRefId(plan._next_ref())
        sparse_ref = ServerPlanRefId(plan._next_ref())
        merged_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            QueryExecuteStep(
                tip_ref,
                tip_model,
                _QueryExecuteStepConfig(query_spec=_query_spec(tip_model)),
            ),
        )
        plan.add_step(
            QueryExecuteStep(
                sparse_ref,
                sparse_model,
                _QueryExecuteStepConfig(query_spec=_query_spec(sparse_model)),
            ),
        )
        plan.add_step(FlattenResultsStep(ServerPlanRefId(merged_ref), [str(tip_ref), str(sparse_ref)]))
        return cast(
            LazyResult[Sequence[DatabaseObjectRow[SysId]]],
            txn._add_intent_by_ref(ServerPlanRefId(merged_ref)),
        )

    @pure_lazy
    def _source_rows_for_rebuild_lazy(
        self: FTSPolyfillManager,
        txn: ReadTransaction,
        model_type: type[DatabaseObjectRow[SysId]],
        domain: type[VersioningDomain] | None,
    ) -> LazyResult[Sequence[DatabaseObjectRow[SysId]]]:
        from impl.common.l2060_query_spec.query_spec import QueryPermissionState, QuerySpec
        from impl.common.l2070_server_plan.steps.query_execute import (
            QueryExecuteStep,
            _QueryExecuteStepConfig,
        )
        from impl.common.l2070_server_plan.steps.row_hydration import HydrateResolvedRowsStep
        from l1400_types import ServerPlanRefId

        if domain is not None and issubclass(model_type, VersionedObjectRow):
            return self._materialized_versioned_rows_lazy(txn, model_type, domain)

        plan = txn._get_transaction_plan_lazy()
        rows_ref = ServerPlanRefId(plan._next_ref())
        hydrated_rows_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            QueryExecuteStep(
                rows_ref,
                model_type,
                _QueryExecuteStepConfig(
                    query_spec=QuerySpec(
                        model_cls=model_type,
                        select_columns=None,
                        distinct=False,
                        joins=[],
                        filters=[],
                        order_by=[],
                        limit=None,
                        offset=None,
                        group_by=[],
                        aggregations=[],
                        having=[],
                        window_functions=[],
                        permission_state=QueryPermissionState.BYPASS,
                        permission_grammar=None,
                    ),
                ),
            ),
        )
        plan.add_step(
            HydrateResolvedRowsStep(
                hydrated_rows_ref,
                source_ref=rows_ref,
                model_cls=model_type,
            ),
        )
        return cast(
            LazyResult[Sequence[DatabaseObjectRow[SysId]]],
            txn._add_intent_by_ref(ServerPlanRefId(hydrated_rows_ref)),
        )

