        obj: DatabaseObjectRow[SysId],
        operation: Literal["insert", "update", "delete"],
        txn: WriteTransaction,
        old_obj: DatabaseObjectRow[SysId] | None = None,
    ) -> None:
        """Update inverted index for a single object.

        Uses content-addressed storage: entries are keyed by content_hash, not object_id.
        This means multiple objects with identical FTS content share the same index entries.

        Operation Semantics:
            - insert: Compute content_hash, insert entries if not already indexed
            - update: Compute new content_hash, insert entries if not already indexed
                      (old entries may become orphaned, cleaned up by garbage collection)
            - delete: No immediate action (orphaned entries cleaned up by garbage collection)

        Args:
            model_type: Model class
            obj: Object instance (with id field)
            operation: Type of operation ("insert", "update", "delete")
            txn: Transaction to use. REQUIRED - no internal transactions are created.

        Example:
            >>> # After inserting a product (within a transaction)
            >>> def do_insert(txn):
            ...     product = txn.insert(Product, Product(name="Wireless Keyboard", ...))
            ...     manager.update_object_index(Product, product, operation="insert", txn=txn)
            >>> conn.session(SessionId.system()).write(fn=do_insert)
        """
        _legacy_delegate_stub()

