class _UnavailableSyncRemoteClient:
    """Sentinel used by async-only remote connections when sync I/O is hidden."""

    def call(self, method: str, params: dict[str, Any] | None = None) -> NoReturn:
        del method, params
        msg = "AsyncRemoteIntentConnection does not provide sync websocket calls"
        raise RuntimeError(msg)

    def call_batch(self, calls: list[tuple[str, dict[str, Any] | None]]) -> NoReturn:
        del calls
        msg = "AsyncRemoteIntentConnection does not provide sync websocket calls"
        raise RuntimeError(msg)


class SyncRemoteIntentTransport(Protocol):
    """Transport operations required by executor-owned remote intent runtime."""

    def call(self, method: str, params: dict[str, Any] | None = None) -> object: ...

    def call_batch(self, calls: list[tuple[str, dict[str, Any] | None]]) -> list[object]: ...

    def cancel_serverplan_request(
        self,
        *,
        request_id: str | None = None,
        batch_id: str | None = None,
    ) -> object: ...


def execute_remote_intent_plan_requests(
    client: SyncRemoteIntentTransport,
    requests: Sequence[RemoteIntentPlanRequest],
    *,
    protocol_limits: RemoteIntentProtocolLimits | None = None,
    cancellation_tracker: _RemoteRequestCancellationTracker | None = None,
) -> tuple[RemoteIntentPlanResponse, ...]:
    """Execute remote intent plans using a standard JSON-RPC batch array."""
    if not requests:
        return ()
    _validate_remote_request_batch_limits(requests, protocol_limits)
    requests = _requests_with_tracking_ids(requests)
    if cancellation_tracker is not None:
        cancellation_tracker.register(requests)
    try:
        raw_responses = client.call_batch(
            [("serverplan.execute_intent_plan", request.model_dump()) for request in requests],
        )
    except RpcError as error:
        _cancel_tracked_remote_requests(client, requests)
        if error.code == ErrorCode.AUTH_FAILED:
            raise RemoteAuthenticationRejectedError(error.message) from error
        if error.code == ErrorCode.PERMISSION_DENIED:
            raise DataLayerPermissionError(error.message) from error
        raise
    except (ConnectionClosedError, ConnectionError, OSError, TimeoutError) as error:
        _cancel_tracked_remote_requests(client, requests)
        raise RemoteTransportUnavailableError("Remote intent transport is offline or unavailable") from error
    except Exception:
        _cancel_tracked_remote_requests(client, requests)
        raise
    finally:
        if cancellation_tracker is not None:
            cancellation_tracker.unregister(requests)
    try:
        return tuple(RemoteIntentPlanResponse.model_validate(item) for item in raw_responses)
    except ValidationError as error:
        raise RemoteAuthenticationMalformedError("Remote authentication response was malformed") from error


async def execute_remote_intent_plan_requests_async(
    client: WebSocketClient,
    requests: Sequence[RemoteIntentPlanRequest],
    *,
    protocol_limits: RemoteIntentProtocolLimits | None = None,
    cancellation_tracker: _RemoteRequestCancellationTracker | None = None,
) -> tuple[RemoteIntentPlanResponse, ...]:
    """Execute remote intent plans with a native async JSON-RPC batch call."""
    if not requests:
        return ()
    _validate_remote_request_batch_limits(requests, protocol_limits)
    requests = _requests_with_tracking_ids(requests)
    if cancellation_tracker is not None:
        cancellation_tracker.register(requests)
    try:
        calls = [("serverplan.execute_intent_plan", request.model_dump()) for request in requests]
        call_batch = getattr(client, "call_batch", None)
        if callable(call_batch):
            batch_call = cast(
                "Callable[[list[tuple[str, dict[str, Any]]]], Awaitable[list[Any]]]",
                call_batch,
            )
            raw_responses = await batch_call(calls)
        else:
            raw_responses = [await client.call(method, params) for method, params in calls]
    except RpcError as error:
        await _cancel_tracked_remote_requests_async(client, requests)
        if error.code == ErrorCode.AUTH_FAILED:
            raise RemoteAuthenticationRejectedError(error.message) from error
        if error.code == ErrorCode.PERMISSION_DENIED:
            raise DataLayerPermissionError(error.message) from error
        raise
    except (ConnectionClosedError, ConnectionError, OSError, TimeoutError) as error:
        await _cancel_tracked_remote_requests_async(client, requests)
        raise RemoteTransportUnavailableError("Remote intent transport is offline or unavailable") from error
    except BaseException:
        await _cancel_tracked_remote_requests_async(client, requests)
        raise
    finally:
        if cancellation_tracker is not None:
            cancellation_tracker.unregister(requests)
    try:
        return tuple(RemoteIntentPlanResponse.model_validate(item) for item in raw_responses)
    except ValidationError as error:
        raise RemoteAuthenticationMalformedError("Remote authentication response was malformed") from error


class _RemoteRequestCancellationTracker:
    """Connection-owned registry of remote ServerPlan IDs currently in flight."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._request_ids: set[str] = set()
        self._batch_ids: set[str] = set()

    def register(self, requests: Sequence[RemoteIntentPlanRequest]) -> None:
        with self._lock:
            for request in requests:
                if request.batch_id is not None:
                    self._batch_ids.add(request.batch_id)
                elif request.request_id is not None:
                    self._request_ids.add(request.request_id)

    def unregister(self, requests: Sequence[RemoteIntentPlanRequest]) -> None:
        with self._lock:
            for request in requests:
                if request.batch_id is not None:
                    self._batch_ids.discard(request.batch_id)
                if request.request_id is not None:
                    self._request_ids.discard(request.request_id)

    def snapshot(self) -> tuple[tuple[str, ...], tuple[str, ...]]:
        with self._lock:
            return tuple(sorted(self._request_ids)), tuple(sorted(self._batch_ids))


def _cancel_tracked_remote_requests(
    client: SyncRemoteIntentTransport,
    requests: Sequence[RemoteIntentPlanRequest],
) -> None:
    seen_batches: set[str] = set()
    for request in requests:
        if request.batch_id is not None:
            if request.batch_id in seen_batches:
                continue
            seen_batches.add(request.batch_id)
            with log_on_cleanup_failure("cancel remote batch request", Exception):
                client.cancel_serverplan_request(batch_id=request.batch_id)
            continue
        if request.request_id is not None:
            with log_on_cleanup_failure("cancel remote request", Exception):
                client.cancel_serverplan_request(request_id=request.request_id)


async def _cancel_tracked_remote_requests_async(
    client: WebSocketClient,
    requests: Sequence[RemoteIntentPlanRequest],
) -> None:
    seen_batches: set[str] = set()
    for request in requests:
        if request.batch_id is not None:
            if request.batch_id in seen_batches:
                continue
            seen_batches.add(request.batch_id)
            with log_on_cleanup_failure("cancel async remote batch request", Exception):
                await client.cancel_serverplan_request(batch_id=request.batch_id)
            continue
        if request.request_id is not None:
            with log_on_cleanup_failure("cancel async remote request", Exception):
                await client.cancel_serverplan_request(request_id=request.request_id)


def _requests_with_tracking_ids(
    requests: Sequence[RemoteIntentPlanRequest],
) -> tuple[RemoteIntentPlanRequest, ...]:
    batch_id = f"remote-batch-{uuid4()}" if len(requests) > 1 else None
    tracked_requests: list[RemoteIntentPlanRequest] = []
    for request in requests:
        updates: dict[str, str] = {}
        if request.request_id is None:
            updates["request_id"] = f"remote-{uuid4()}"
        if request.batch_id is None and batch_id is not None:
            updates["batch_id"] = batch_id
        tracked_requests.append(request.model_copy(update=updates) if updates else request)
    return tuple(tracked_requests)


def _validate_remote_request_batch_limits(
    requests: Sequence[RemoteIntentPlanRequest],
    protocol_limits: RemoteIntentProtocolLimits | None,
) -> None:
    if protocol_limits is None:
        return
    if len(requests) > protocol_limits.max_jsonrpc_batch_size:
        msg = (
            f"Remote intent JSON-RPC batch size {len(requests)} exceeds server-advertised limit {protocol_limits.max_jsonrpc_batch_size}"
        )
        raise ValueError(msg)
    for request in requests:
        request_bytes = len(request.model_dump_json().encode("utf-8"))
        if request_bytes > protocol_limits.max_request_bytes:
            msg = f"Remote intent request size {request_bytes} exceeds server-advertised limit {protocol_limits.max_request_bytes}"
            raise ValueError(msg)
        intent_count = len(request.intent_graph.intents)
        if intent_count > protocol_limits.max_intents_per_plan:
            msg = (
                "Remote intent plan contains "
                f"{intent_count} intents, exceeding server-advertised limit "
                f"{protocol_limits.max_intents_per_plan}"
            )
            raise ValueError(msg)
    total_request_bytes = sum(len(request.model_dump_json().encode("utf-8")) for request in requests)
    if total_request_bytes > protocol_limits.max_in_flight_decompressed_bytes:
        msg = (
            "Remote intent JSON-RPC batch decompressed size "
            f"{total_request_bytes} exceeds server-advertised in-flight limit "
            f"{protocol_limits.max_in_flight_decompressed_bytes}"
        )
        raise ValueError(msg)


def _introspected_table_from_remote_description(
    table_name: SqlTableName,
    table_info: Mapping[str, Any],
) -> IntrospectedTable:
    fields = table_info.get("fields")
    columns: list[IntrospectedColumn] = []
    if isinstance(fields, Mapping):
        for name, field_info in fields.items():
            field_mapping = dict(field_info) if isinstance(field_info, Mapping) else {}
            data_type = str(field_mapping.get("type", "Any"))
            required = bool(field_mapping.get("required", False))
            columns.append(
                IntrospectedColumn(
                    name=SqlColumnName(str(name)),
                    data_type=SqlTypeName(data_type),
                    nullable=not required,
                    is_primary_key=str(name) == "sys_id",
                    is_uuid=data_type in {"SysId", "UUID"} or data_type.endswith("Id"),
                    extra_metadata=field_mapping,
                ),
            )
    return IntrospectedTable(
        name=SqlTableName(str(table_info.get("table", table_name))),
        columns=tuple(columns),
        extra_metadata={"remote_description": dict(table_info)},
    )


def _remote_return_model_type(
    plan: BaseServerPlan,
    name: str,
) -> type[DatabaseObjectRow] | None:
    declared = plan._return_type_hints.get(name)
    if isinstance(declared, type) and issubclass(declared, DatabaseObjectRow):
        return declared
    returned_ref = plan._returns.get(name)
    if returned_ref is None:
        return None
    producer_ref = returned_ref.partition(".")[0]
    producer = next(
        (step for step in plan._steps if str(step.ref_id) == producer_ref),
        None,
    )
    if producer is None or producer.returns_raw_rows_terminal():
        return None
    model_cls = getattr(producer, "model_cls", None)
    if model_cls is None:
        model_cls = getattr(producer, "_model_cls", None)
    if not isinstance(model_cls, type) or not issubclass(model_cls, DatabaseObjectRow):
        return None
    return model_cls


class RemoteIntentPlan(BaseServerPlan):
    """ServerPlan whose execution boundary is a remote generic-intent RPC."""

    def __init__(
        self,
        target: PlanTarget,
        *,
        client: SyncWebSocketClient,
        connection: SyncRemoteIntentConnection,
        session_id: SessionId,
        backend_profile: ServerPlanBackendProfile,
        catalog_fingerprint: RemoteIntentCatalogFingerprint | None = None,
        protocol_limits: RemoteIntentProtocolLimits | None = None,
        cancellation_tracker: _RemoteRequestCancellationTracker | None = None,
        transaction_mode: Literal["read", "write"] = "read",
    ) -> None:
        super().__init__(target, session_id=session_id, backend_profile=backend_profile)
        self._remote_client = client
        self._connection = connection
        self._authentication_generation = connection.authentication_generation
        self._remote_session_id = session_id
        self._catalog_fingerprint = catalog_fingerprint
        self._protocol_limits = protocol_limits
        self._cancellation_tracker = cancellation_tracker
        self._transaction_mode: Literal["read", "write"] = transaction_mode

    def _execute_now(self) -> PlanResults:
        """Execute queued L4 intents on the remote server."""
        if not self._steps:
            return PlanResults({})
        request = RemoteIntentPlanRequest(
            transaction_mode=self._transaction_mode,
            client_catalog_fingerprint=self._catalog_fingerprint,
            intent_graph=RemoteIntentGraph(
                intents=[serialize_intent_step(step) for step in self._steps],
                returns=dict(self._returns),
            ),
        )
        (response,) = execute_remote_intent_plan_requests(
            self._remote_client,
            [request],
            protocol_limits=self._protocol_limits,
            cancellation_tracker=self._cancellation_tracker,
        )
        self._connection._accept_data_plan_response(
            response,
            expected_generation=self._authentication_generation,
        )
        return PlanResults(
            {name: self._hydrate_result(name, value) for name, value in response.results.items()},
        )

    def _hydrate_result(self, name: str, value: object) -> object:
        type_hint = _remote_return_model_type(self, name)
        if type_hint is None:
            return value
        if isinstance(value, list):
            return [convert_row_to_model(type_hint, dict(item)) if isinstance(item, Mapping) else item for item in value]
        if isinstance(value, Mapping):
            return convert_row_to_model(type_hint, dict(value))
        return value


class AsyncRemoteIntentPlan(BaseServerPlan):
    """Async ServerPlan whose execution boundary is a remote generic-intent RPC."""

    def __init__(
        self,
        target: PlanTarget,
        *,
        client: WebSocketClient,
        connection: SyncRemoteIntentConnection,
        session_id: SessionId,
        backend_profile: ServerPlanBackendProfile,
        catalog_fingerprint: RemoteIntentCatalogFingerprint | None = None,
        protocol_limits: RemoteIntentProtocolLimits | None = None,
        cancellation_tracker: _RemoteRequestCancellationTracker | None = None,
        transaction_mode: Literal["read", "write"] = "read",
    ) -> None:
        super().__init__(target, session_id=session_id, backend_profile=backend_profile)
        self._remote_client = client
        self._connection = connection
        self._authentication_generation = connection.authentication_generation
        self._remote_session_id = session_id
        self._catalog_fingerprint = catalog_fingerprint
        self._protocol_limits = protocol_limits
        self._cancellation_tracker = cancellation_tracker
        self._transaction_mode: Literal["read", "write"] = transaction_mode

    async def _execute_impl_async(self) -> PlanResults:
        """Execute queued L4 intents on the remote server without sync I/O."""
        if not self._steps:
            return PlanResults({})
        request = RemoteIntentPlanRequest(
            transaction_mode=self._transaction_mode,
            client_catalog_fingerprint=self._catalog_fingerprint,
            intent_graph=RemoteIntentGraph(
                intents=[serialize_intent_step(step) for step in self._steps],
                returns=dict(self._returns),
            ),
        )
        (response,) = await execute_remote_intent_plan_requests_async(
            self._remote_client,
            [request],
            protocol_limits=self._protocol_limits,
            cancellation_tracker=self._cancellation_tracker,
        )
        self._connection._accept_data_plan_response(
            response,
            expected_generation=self._authentication_generation,
        )
        return PlanResults(
            {name: self._hydrate_result(name, value) for name, value in response.results.items()},
        )

    def _execute_now(self) -> NoReturn:
        msg = "AsyncRemoteIntentPlan must be executed through execute_async()"
        raise RuntimeError(msg)

    def _hydrate_result(self, name: str, value: object) -> object:
        type_hint = _remote_return_model_type(self, name)
        if type_hint is None:
            return value
        if isinstance(value, list):
            return [convert_row_to_model(type_hint, dict(item)) if isinstance(item, Mapping) else item for item in value]
        if isinstance(value, Mapping):
            return convert_row_to_model(type_hint, dict(value))
        return value


class SyncRemoteIntentReadTransaction(SyncReadTransaction):
    """Read transaction that ships generic ServerPlan intents to a remote server."""

    _conn: SyncRemoteIntentConnection

    def __init__(self, conn: SyncRemoteIntentConnection, session_id: SessionId) -> None:
        super().__init__(session_id)
        self._conn = conn
        self._lazy_plan = None
        self._session_id_source = session_id

    def __enter__(self) -> SyncRemoteIntentReadTransaction:
        self._check_thread()
        self._check_active()
        self._conn._authenticate_session(self._session_id)
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: object | None,
    ) -> None:
        del exc_type, exc_val, exc_tb
        self._state = TransactionState.CLOSED

    def _create_server_plan(self) -> BaseServerPlan:
        return RemoteIntentPlan(
            self,
            client=self._conn._client,
            connection=self._conn,
            session_id=self._session_id,
            backend_profile=self.backend_profile,
            catalog_fingerprint=self._conn.catalog_fingerprint,
            protocol_limits=self._conn.protocol_limits,
            cancellation_tracker=self._conn._cancellation_tracker,
            transaction_mode="read",
        )

    @property
    def backend_profile(self) -> ServerPlanBackendProfile:
        return self._conn.backend_profile

    @property
    def backend_type(self) -> BackendType:
        return self._conn.backend_type


class SyncRemoteIntentWriteTransaction(SyncWriteTransaction):
    """Write transaction that ships generic ServerPlan intents to a remote server."""

    _conn: SyncRemoteIntentConnection

    def __init__(self, conn: SyncRemoteIntentConnection, session_id: SessionId) -> None:
        super().__init__(session_id)
        self._conn = conn
        self._lazy_plan = None
        self._session_id_source = session_id

    def __enter__(self) -> SyncRemoteIntentWriteTransaction:
        self._check_thread()
        self._check_active()
        self._conn._authenticate_session(self._session_id)
        return self

    def _create_server_plan(self) -> BaseServerPlan:
        return RemoteIntentPlan(
            self,
            client=self._conn._client,
            connection=self._conn,
            session_id=self._session_id,
            backend_profile=self.backend_profile,
            catalog_fingerprint=self._conn.catalog_fingerprint,
            protocol_limits=self._conn.protocol_limits,
            cancellation_tracker=self._conn._cancellation_tracker,
            transaction_mode="write",
        )

    @property
    def backend_profile(self) -> ServerPlanBackendProfile:
        return self._conn.backend_profile

    @property
    def backend_type(self) -> BackendType:
        return self._conn.backend_type

    def commit(self) -> None:
        if self.is_committed:
            return
        self._flush_pending_ops()
        self._get_transaction_plan_lazy()._execute_now()
        self._state = TransactionState.COMMITTED

    def rollback(self) -> None:
        self._conn._cancel_active_remote_requests()
        self._cancel_pending_ops()
        self._state = TransactionState.ROLLED_BACK


