        return AsyncRemoteIntentReadTransaction(self, session_id)

    def _execute_authenticated_write_intent_graph(
        self: SyncRemoteIntentConnection,
        *,
        session_id: SessionId,
        intent_graph: RemoteIntentGraph,
    ) -> RemoteIntentPlanResponse:
        """Execute one explicitly assembled generic write graph with normal authority."""
        self._authenticate_session(session_id)
        request = RemoteIntentPlanRequest(
            transaction_mode="write",
            client_catalog_fingerprint=self.catalog_fingerprint,
            intent_graph=intent_graph,
        )
        try:
            (response,) = execute_remote_intent_plan_requests(
                self._client,
                (request,),
                protocol_limits=self.protocol_limits,
                cancellation_tracker=self._cancellation_tracker,
            )
        except RpcError as exc:
            if exc.code == ErrorCode.PERMISSION_DENIED:
                raise DataLayerPermissionError(exc.message) from exc
            raise
        return response

    async def _execute_authenticated_write_intent_graph_native(
        self: SyncRemoteIntentConnection,
        *,
        session_id: SessionId,
        intent_graph: RemoteIntentGraph,
    ) -> RemoteIntentPlanResponse:
        """Execute one generic write graph through the native async transport."""
        await self._authenticate_session_native(session_id)
        request = RemoteIntentPlanRequest(
            transaction_mode="write",
            client_catalog_fingerprint=self.catalog_fingerprint,
            intent_graph=intent_graph,
        )
        try:
            (response,) = await execute_remote_intent_plan_requests_async(
                self.async_client,
                (request,),
                protocol_limits=self.protocol_limits,
                cancellation_tracker=self._cancellation_tracker,
            )
        except RpcError as exc:
            if exc.code == ErrorCode.PERMISSION_DENIED:
                raise DataLayerPermissionError(exc.message) from exc
            raise
        return response

