    def write_transaction(
        self,
        *,
        session_id: SessionId,
        timeout_seconds: float | None = None,
        enable_logging: bool = False,
    ) -> SyncRemoteIntentWriteTransaction:
        del timeout_seconds, enable_logging
        return self._create_write_transaction(session_id)

    def _run_read_callback[T](
        self,
        session_id: SessionId,
        fn: Callable[[SyncReadTransaction], T],
        *,
        retry_policy: object | None = None,
        timeout_seconds: float | None = None,
    ) -> T:
        del retry_policy
        with self.read_transaction(session_id=session_id, timeout_seconds=timeout_seconds) as txn:
            result = fn(txn)
        if result is txn:
            msg = "Transaction callbacks must not return the transaction object."
            raise ValueError(msg)
        return result

    def _run_write_callback[T](
        self,
        session_id: SessionId,
        fn: Callable[[SyncWriteTransaction], T],
        *,
        retry_policy: object | None = None,
        timeout_seconds: float | None = None,
    ) -> T:
        del retry_policy
        with self.write_transaction(session_id=session_id, timeout_seconds=timeout_seconds) as txn:
            result = fn(txn)
            if not txn.is_committed and not txn.is_rolled_back:
                txn.commit()
        if result is txn:
            msg = "Transaction callbacks must not return the transaction object."
            raise ValueError(msg)
        return result

