        raw_response = self._client.call("describe_table", {"table": table_name})
        if not isinstance(raw_response, Mapping):
            msg = "describe_table returned a non-mapping response"
            raise TypeError(msg)
        return dict(raw_response)

    def _legacy_column_exists(self, table_name: SqlTableName, column_name: SqlColumnName) -> bool:
        table_info = self._describe_table(table_name)
        fields = table_info.get("fields")
        return isinstance(fields, Mapping) and column_name in fields

    def _legacy_get_table_info(self, table_name: SqlTableName) -> list[dict[str, Any]]:
        table_info = self._describe_table(table_name)
        fields = table_info.get("fields")
        if not isinstance(fields, Mapping):
            return []
        rows: list[dict[str, Any]] = []
        for name, field_info in fields.items():
            field_mapping = dict(field_info) if isinstance(field_info, Mapping) else {}
            rows.append({"name": str(name), **field_mapping})
        return rows

    def _legacy_introspect_table(self, table_name: SqlTableName) -> IntrospectedTable:
        return _introspected_table_from_remote_description(table_name, self._describe_table(table_name))

    async def _describe_table_async(self, table_name: SqlTableName) -> dict[str, Any]:
        self._require_legacy_schema_rpc()
        if self._async_client is None:
            return self._describe_table(table_name)
        raw_response = await self._async_client.describe_table(table_name)
        if not isinstance(raw_response, Mapping):
            msg = "describe_table returned a non-mapping response"
            raise TypeError(msg)
        return dict(raw_response)

