class AsyncRemoteIntentConnection(SyncRemoteIntentConnection):
    """Async-only remote connection backed by generic intent JSON-RPC."""

    _forbidden_public_methods = AsyncDatabaseConnection._forbidden_public_methods
    session = AsyncDatabaseConnection.session  # type: ignore[assignment]
    version = AsyncDatabaseConnection.version  # type: ignore[assignment]

    def __init__(
        self,
        client: WebSocketClient,
        *,
        enable_llm_delegation: bool = False,
        sync_client: SyncWebSocketClient | None = None,
        backend_type: BackendType = BackendType.SQLITE,
        capabilities: set[BackendCapability] | None = None,
        mode: RemoteConnectionMode = RemoteConnectionMode.DIRECT_REMOTE,
        backend_profile: ServerPlanBackendProfile | None = None,
        authorization: str | None = None,
        allow_legacy_schema_rpc: bool = False,
    ) -> None:
        super().__init__(
            sync_client or cast("SyncWebSocketClient", _UnavailableSyncRemoteClient()),
            async_client=client,
            enable_llm_delegation=enable_llm_delegation,
            backend_type=backend_type,
            capabilities=capabilities,
            mode=mode,
            backend_profile=backend_profile,
            authorization=authorization,
            allow_legacy_schema_rpc=allow_legacy_schema_rpc,
        )

    @legacy_async(lazy_name="replace_authorization_lazy")
    async def replace_authorization_async(self, authorization: str) -> int:
        """Replace the installed credential through the native async transport."""
        _legacy_delegate_stub()

    async def connect_async(self) -> None:
        await self._connect_async_impl()

    async def verify_remote_compatibility_async(self, model_symbols: Sequence[str]) -> dict[str, Any]:
        """Fetch compatibility proofs through the native async transport."""
        symbols = list(model_symbols)
        client = self._async_client
        assert client is not None
        try:
            raw_proof = await client.call(
                "serverplan.compatibility_proof",
                {"protocol_version": 1, "model_symbols": symbols},
            )
        except (ConnectionClosedError, ConnectionError, OSError, TimeoutError) as error:
            raise RemoteTransportUnavailableError("Remote compatibility transport is unavailable") from error
        if not isinstance(raw_proof, dict):
            msg = "Remote compatibility proof response must be an object"
            raise RuntimeError(msg)
        return raw_proof

    async def close_async(self) -> None:
        await self._close_async_impl()

    async def is_connected_async(self) -> bool:
        return await self._is_connected_async_impl()

    async def delete_returning_async(
        self,
        table_name: SqlTableName,
        row_id: SysId,
        returning_columns: Sequence[str] | None = None,
    ) -> NoReturn:
        return await self._delete_returning_async_impl(table_name, row_id, returning_columns)

    async def delete_many_returning_async(
        self,
        table_name: SqlTableName,
        ids: Sequence[SysId],
        returning_columns: Sequence[str] | None = None,
    ) -> NoReturn:
        return await self._delete_many_returning_async_impl(table_name, ids, returning_columns)

